def canonical_json(value: Any) -> str:
    """Return Attestor's canonical JSON spelling for a JSON-compatible value."""
    return _canonical(value).decode("utf-8")

def verify_report(report: Mapping[str, Any]) -> tuple[bool, list[str]]:
    """Verify digest, strict shape, bounds, and all derived adjudication data."""
    errors: list[str] = []
    if type(report) is not dict:
        return False, ["report must be an exact mapping"]
    if set(report) != _TOP_LEVEL_KEYS:
        errors.append("report fields are invalid")
    if report.get("schema") != SCHEMA or report.get("version") != VERSION:
        errors.append("report identity is invalid")
    try:
        encoded = _canonical(report)
    except (TypeError, ValueError, OverflowError, RecursionError):
        return False, sorted(set([*errors, "report is not canonical JSON"]))
    if len(encoded) > MAX_REPORT_BYTES:
        errors.append("report exceeds its byte boundary")

    claimed = report.get("report_sha256")
    if type(claimed) is not str or _SHA256.fullmatch(claimed) is None:
        errors.append("report_sha256 must be lowercase SHA-256")
    else:
        body = {
            key: value for key, value in report.items()
            if key != "report_sha256"
        }
        try:
            if claimed != _sha(body):
                errors.append("report digest mismatch")
        except (TypeError, ValueError, OverflowError, RecursionError):
            errors.append("report body is not canonical JSON")

    finding_rows = report.get("findings")
    evidence_rows = report.get("evidence")
    risk_rows = report.get("risk_areas")
    if type(finding_rows) is not list or len(finding_rows) > MAX_FINDINGS:
        errors.append("findings collection is invalid")
    if type(evidence_rows) is not list or len(evidence_rows) > MAX_EVIDENCE:
        errors.append("evidence collection is invalid")
    if type(risk_rows) is not list or len(risk_rows) > MAX_RISK_AREAS:
        errors.append("risk-area collection is invalid")

    originals_findings: list[dict[str, Any]] = []
    originals_evidence: list[dict[str, Any]] = []
    originals_risks: list[dict[str, Any]] = []
    if type(finding_rows) is list and len(finding_rows) <= MAX_FINDINGS:
        for row in finding_rows:
            if type(row) is not dict or type(row.get("original_finding")) is not dict:
                errors.append("adjudicated finding is invalid")
                break
            originals_findings.append(row["original_finding"])
    if type(evidence_rows) is list and len(evidence_rows) <= MAX_EVIDENCE:
        for row in evidence_rows:
            if type(row) is not dict or type(row.get("original_evidence")) is not dict:
                errors.append("adjudicated evidence is invalid")
                break
            originals_evidence.append(row["original_evidence"])
    if type(risk_rows) is list and len(risk_rows) <= MAX_RISK_AREAS:
        for row in risk_rows:
            if type(row) is not dict or type(row.get("original_area")) is not dict:
                errors.append("adjudicated risk area is invalid")
                break
            originals_risks.append(row["original_area"])

    if not any(error.startswith("adjudicated ") for error in errors) and all(
            type(value) is list
            for value in (finding_rows, evidence_rows, risk_rows)):
        try:
            expected = adjudicate(
                originals_findings, originals_evidence, originals_risks)
            if _canonical(expected) != encoded:
                errors.append("report derived data is inconsistent")
        except (AdjudicationError, TypeError, ValueError, OverflowError,
                RecursionError):
            errors.append("report originals cannot be safely adjudicated")
    return not errors, sorted(set(errors))

def make_advisory(finding: Mapping[str, Any], code: str,
                  generate: Callable[[str], str], *, model_id: str,
                  audit_report: Mapping[str, Any] | None = None,
                  ledger: Mapping[str, Any] | None = None) -> dict[str, Any]:
    """Produce one advisory, or withhold it and say why.

    `generate` is any callable taking a prompt and returning text.  Everything
    about the model except its output and its name stays outside this module.
    """
    if not isinstance(model_id, str) or not model_id.strip():
        raise AdvisoryError("model_id must be a non-empty string")
    if not callable(generate):
        raise AdvisoryError("generate must be callable")

    base = {
        "schema": SCHEMA,
        "version": VERSION,
        "model_id": model_id,
        "rule": _field(finding, "rule", (str,)),
        "line": _field(finding, "line", (int,)),
        "evidence_state": INFERRED,
        "at": int(time.time()),
        "limitations": [
            "written by a language model from a finding the deterministic "
            "rules had already established; it explains that finding and is "
            "not evidence for or against it",
            "outside the verified report digest, so it is not replayable and "
            "carries no weight in adjudication",
        ],
    }

    # Cleared to *explain*, which is a different clearance from being cleared
    # to decide whether a finding is real.  Passing this does not grant that.
    allowed, why = model_audit.may_speak(audit_report,
                                         role=model_audit.ROLE_PHRASE)
    if not allowed:
        return {**base, "status": WITHHELD, "reason": why, "text": ""}

    standing = model_audit.standing(ledger, model_id)
    if not standing["allowed"]:
        return {**base, "status": WITHHELD,
                "reason": "model withdrawn after %d violations"
                          % standing["violations"], "text": ""}

    try:
        text = generate(phrase_prompt(finding, code))
    except Exception as error:                      # a model failure is not ours
        return {**base, "status": WITHHELD,
                "reason": "generation failed: %s" % str(error)[:200], "text": ""}

    if not isinstance(text, str) or not text.strip():
        return {**base, "status": WITHHELD,
                "reason": "model returned nothing", "text": ""}

    if _denies_the_finding(text):
        # It was told the defect was settled and disputed it anyway.  The text
        # is dropped and the model is charged; three of these withdraw it.
        return {**base, "status": WITHHELD,
                "reason": "model disputed a verified finding",
                "violation": "denied %s at line %d" % (base["rule"], base["line"]),
                "text": ""}

    return {**base, "status": ISSUED, "text": text.strip()[:MAX_ADVISORY_CHARS]}

def charge_violations(ledger: Mapping[str, Any] | None,
                      advisories: Sequence[Mapping[str, Any]]
                      ) -> dict[str, Any] | None:
    """Record every advisory that was withheld for disputing a finding."""
    updated = ledger
    for item in advisories:
        if item.get("violation"):
            updated = model_audit.record_violation(
                updated, item["model_id"], item["violation"])
    return updated

def verify_separation(envelope: Mapping[str, Any]) -> tuple[bool, list[str]]:
    """Prove the advisory text never entered the verified report."""
    problems: list[str] = []
    if not isinstance(envelope, Mapping) or \
            envelope.get("schema") != "attestor.advisory-envelope/1.0":
        return False, ["not an advisory envelope"]
    report = envelope.get("report")
    if not isinstance(report, Mapping):
        return False, ["envelope carries no report"]
    if _sha(report) != envelope.get("report_sha256"):
        problems.append("report digest does not match the report")
    rendered = json.dumps(report, sort_keys=True, default=str)
    for row in envelope.get("advisory", {}).get("ranking", []):
        if row.get("evidence_state") != INFERRED:
            problems.append("a ranking row for %s is not marked inferred"
                            % row.get("rule"))
    for item in envelope.get("advisory", {}).get("items", []):
        text = item.get("text") or ""
        if text and text in rendered:
            problems.append("advisory text for %s appears inside the report"
                            % item.get("rule"))
        if item.get("schema") != SCHEMA:
            problems.append("foreign object under 'advisory'")
    for key in ("advisory", "advisories", "explanation", "model_text",
                "ranking", "gate_score"):
        if key in report:
            problems.append("report carries a %r key" % key)
    return not problems, problems

def _lexical_absolute(path: Path) -> Path:
    """Return an absolute spelling without resolving any link component."""
    return Path(os.path.abspath(os.fspath(path)))

def diff(current: SourceSnapshot, previous: SourceSnapshot) -> dict[str, Any]:
    """Return deterministic content-level invalidation evidence."""
    old = {item.path: item.sha256 for item in previous.files}
    new = {item.path: item.sha256 for item in current.files}
    body = {
        "schema": "attestor.snapshot-diff/4.1",
        "version": VERSION,
        "previous_snapshot_sha256": previous.snapshot_sha256,
        "current_snapshot_sha256": current.snapshot_sha256,
        "added": sorted(set(new) - set(old)),
        "removed": sorted(set(old) - set(new)),
        "changed": sorted(path for path in set(old) & set(new) if old[path] != new[path]),
        "unchanged": sorted(path for path in set(old) & set(new) if old[path] == new[path]),
        "static_contract": {"filesystem_writes": False, "network_accessed": False,
                            "target_code_executed": False},
    }
    return _report(body)

def text(self) -> tuple[str, bool]:
        """Decode UTF-8 without throwing; the bool says replacement was needed."""
        try:
            return self._content.decode("utf-8"), False
        except UnicodeDecodeError:
            return self._content.decode("utf-8", errors="replace"), True

def canonical_json(value: Any, *, pretty: bool = False) -> str:
    """Serialize bounded JSON deterministically."""
    try:
        return json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            indent=2 if pretty else None,
            separators=None if pretty else (",", ":"),
            allow_nan=False,
        )
    except (TypeError, ValueError, OverflowError, RecursionError) as exc:
        raise AssuranceOperationalError("assurance evidence is not canonical JSON") from exc

def verify_report(report: Any) -> tuple[bool, list[str]]:
    """Fail-closed wrapper: adversarial JSON never escapes as an exception."""
    try:
        return _verify_report_impl(report)
    except (Exception, RecursionError) as exc:
        return False, ["report verification failed closed (%s)" % type(exc).__name__]

def _document_value(row: Any) -> tuple[Any, Any, str]:
    """Return path, content, and optional declared digest without executing hooks."""
    if isinstance(row, Mapping):
        path = row.get("path")
        declared = row.get("sha256", "")
        for key in ("content", "raw", "text", "_content"):
            if key in row:
                return path, row[key], str(declared) if declared else ""
        return path, None, str(declared) if declared else ""
    path = getattr(row, "path", None)
    declared = getattr(row, "sha256", "")
    try:
        content = getattr(row, "content")
    except (AttributeError, OSError, ValueError):
        content = getattr(row, "_content", None)
    return path, content, str(declared) if declared else ""

def _scope_nodes(root: ast.AST) -> Iterable[ast.AST]:
    """Walk one function body without attributing nested functions to its owner."""
    pending = list(reversed(list(ast.iter_child_nodes(root))))
    while pending:
        node = pending.pop()
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):
            continue
        yield node
        pending.extend(reversed(list(ast.iter_child_nodes(node))))

def _triage_summary(findings: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    """Roll the grades up so the queue size is visible without reading findings."""
    counts = {name: 0 for name in _TRIAGE_GRADES}
    for finding in findings:
        grade = finding.get("triage", {}).get("grade")
        if grade in counts:
            counts[grade] += 1
    return {
        "by_grade": counts,
        "review_first": counts[_TRIAGE_REACHABLE_OPEN],
        "semantics": (
            "Grades order review effort from bounded static reachability. They "
            "are not runtime proof, and 'reachability-unknown' means nothing "
            "was learned rather than that the finding is low risk."
        ),
    }

class AttackSurface:
    """Complete attack surface for a project."""
    project_path: str
    entries: list[EntryPoint] = field(default_factory=list)
    files_scanned: int = 0
    languages: set[str] = field(default_factory=set)
    frameworks: set[str] = field(default_factory=set)
    errors: list[str] = field(default_factory=list)

    def by_type(self, entry_type: EntryType) -> list[EntryPoint]:
        return [e for e in self.entries if e.entry_type == entry_type]

    def by_severity(self, severity: Severity) -> list[EntryPoint]:
        return [e for e in self.entries if e.severity == severity]

    def by_file(self, file_path: str) -> list[EntryPoint]:
        return [e for e in self.entries if e.file_path == file_path]

    def unauthenticated(self) -> list[EntryPoint]:
        return [e for e in self.entries if not e.requires_auth]

    def endpoints(self) -> list[EntryPoint]:
        return self.by_type(EntryType.HTTP_ENDPOINT)

    def high_value_targets(self) -> list[EntryPoint]:
        return [e for e in self.entries if e.risk_score >= 8]

    def summary(self) -> str:
        lines = [
            "=== Attack Surface Map ===",
            "Project: %s" % self.project_path,
            "Files scanned: %d" % self.files_scanned,
            "Languages: %s" % ", ".join(sorted(self.languages)) if self.languages else "Languages: none detected",
            "Frameworks: %s" % ", ".join(sorted(self.frameworks)) if self.frameworks else "Frameworks: none detected",
            "Total entry points: %d" % len(self.entries),
            "",
        ]

        type_counts = {}
        for e in self.entries:
            type_counts[e.entry_type.name] = type_counts.get(e.entry_type.name, 0) + 1
        if type_counts:
            lines.append("By type:")
            for name, count in sorted(type_counts.items(), key=lambda x: -x[1]):
                lines.append("  %s: %d" % (name, count))

        sev_counts = {}
        for e in self.entries:
            sev_counts[e.severity.value] = sev_counts.get(e.severity.value, 0) + 1
        if sev_counts:
            lines.append("")
            lines.append("By severity:")
            for sev in ["critical", "high", "medium", "low", "info"]:
                if sev in sev_counts:
                    lines.append("  %s: %d" % (sev, sev_counts[sev]))

        unauth = self.unauthenticated()
        if unauth:
            lines.append("")
            lines.append("Unauthenticated entry points: %d" % len(unauth))

        hvt = self.high_value_targets()
        if hvt:
            lines.append("High-value targets (score >= 8): %d" % len(hvt))

        return "\n".join(lines)

    def to_dict(self) -> dict[str, Any]:
        return {
            "project": self.project_path,
            "files_scanned": self.files_scanned,
            "languages": sorted(self.languages),
            "frameworks": sorted(self.frameworks),
            "total_entries": len(self.entries),
            "entries": [
                {
                    "type": e.entry_type.name,
                    "file": e.file_path,
                    "line": e.line,
                    "severity": e.severity.value,
                    "method": e.method,
                    "route": e.route,
                    "params": e.param_names,
                    "sink": e.sink_function,
                    "auth_required": e.requires_auth,
                    "framework": e.framework,
                    "cwe": e.cwe,
                    "risk_score": e.risk_score,
                    "snippet": e.code_snippet[:200],
                }
                for e in self.entries
            ],
        }

def _truth_claims(report: Mapping[str, Any]) -> list[dict[str, Any]]:
    """Create bounded, machine-verifiable claims for Attestor's public report."""
    findings = report.get("findings", []) if isinstance(report.get("findings"), list) else []
    claims: list[dict[str, Any]] = [
        {"kind": "value", "text": "report status is " + str(report.get("status", "unknown")),
         "evidence_path": "/status", "expected": report.get("status")},
        {"kind": "count", "text": "%d findings from enabled checks" % len(findings),
         "collection_path": "/findings", "expected": len(findings)},
    ]
    for row in findings[:MAX_TRUTH_FINDING_CLAIMS]:
        if not isinstance(row, Mapping):
            continue
        claims.append({
            "kind": "finding",
            "text": "%s at %s:%s" % (
                row.get("rule", "finding"), row.get("path", "workspace"), row.get("line", 1)),
            "rule": row.get("rule", ""), "path": row.get("path", ""),
            "line": row.get("line", 1),
        })
    for row in report.get("improvements", [])[:32]:
        if not isinstance(row, Mapping):
            continue
        claims.append({
            "kind": "improvement",
            "text": "%s improvement for %s" % (
                "verified" if row.get("accepted") is True else "refused",
                row.get("target", "source")),
            "target": row.get("target", ""),
            "expected": "verified" if row.get("accepted") is True else "refused",
        })
    return claims

def _truth_document_node_count(
        value: Any, *, maximum: int = MAX_TRUTH_DOCUMENT_NODES,
        boundary: str = "Attestor 3.0 evidence") -> int:
    """Validate a full JSON report before any recursive projection/redaction."""
    if (isinstance(maximum, bool) or not isinstance(maximum, int) or
            maximum < 1):
        raise Attestor3Error("Truth Guard node boundary is invalid")
    seen: set[int] = set()
    nodes = 0

    def visit(item: Any, depth: int) -> None:
        nonlocal nodes
        nodes += 1
        if nodes > maximum:
            raise Attestor3Error(
                "%s exceeds the %d-node hard boundary" %
                (boundary, maximum))
        if depth > truth_guard.MAX_DEPTH:
            raise Attestor3Error(
                "%s exceeds the %d-level nesting boundary" %
                (boundary, truth_guard.MAX_DEPTH))
        if item is None or isinstance(item, (str, bool, int)):
            return
        if isinstance(item, float):
            if not math.isfinite(item):
                raise Attestor3Error(
                    "%s contains a non-finite number" % boundary)
            return
        if type(item) not in {dict, list, tuple}:
            raise Attestor3Error("%s contains a non-JSON value" % boundary)
        marker = id(item)
        if marker in seen:
            raise Attestor3Error("%s contains a cyclic value" % boundary)
        seen.add(marker)
        if type(item) is dict:
            if any(not isinstance(key, str) for key in item):
                raise Attestor3Error(
                    "%s contains a non-string object key" % boundary)
            for key in sorted(item):
                visit(item[key], depth + 1)
        else:
            for child in item:
                visit(child, depth + 1)
        seen.remove(marker)

    visit(value, 0)
    return nodes

def safe_public_report(report: Mapping[str, Any]) -> dict[str, Any]:
    """Return the integrity-checked, evidence-filtered public view."""
    return _validated_public_report(report)[0]

def deterministic_json(report: Mapping[str, Any], *, indent: int | None = 2) -> str:
    """Serialize a locally hard-bounded, already-filtered Attestor 3 report."""
    if type(report) is not dict:
        raise Attestor3Error("public report must be a JSON object")
    _truth_document_node_count(report)
    safe = truth_guard.redact_tree(report, _validated=True)
    encoded = json.dumps(
        safe, sort_keys=True, indent=indent, ensure_ascii=False,
        allow_nan=False).encode("utf-8")
    if len(encoded) > MAX_TRUTH_DOCUMENT_BYTES:
        raise Attestor3Error("Attestor 3.0 public JSON exceeds the 16 MiB hard boundary")
    return encoded.decode("utf-8")

def _new_component_improvement_plans(findings: Sequence[Mapping[str, Any]],
                                     max_files: int) -> list[dict[str, Any]]:
    """Expose precise review plans without inventing or claiming a verified patch."""
    grouped: dict[str, list[Mapping[str, Any]]] = {}
    for row in findings:
        if row.get("source_engine") not in {"engineering-4.0", "security-fabric-4.0"}:
            continue
        grouped.setdefault(str(row.get("path") or "workspace"), []).append(row)
    ordered = sorted(grouped, key=lambda path: (
        -max(SEVERITY_RANK.get(str(row.get("severity", "MEDIUM")).upper(), 3)
             for row in grouped[path]), path.casefold()))
    plans = []
    for target in ordered[:max(0, max_files)]:
        rows = grouped[target]
        guidance = list(dict.fromkeys(str(row.get("fix") or row.get("message") or "")[:8_000]
                                      for row in rows if row.get("fix") or row.get("message")))
        plans.append({
            "target": target, "status": "plan-only-review-required",
            "accepted": False, "complete": False,
            "reasons": [
                "Attestor 4.0 produced evidence-backed remediation guidance, but no deterministic edit passed the mandatory scan/build/test gates."
            ],
            "suggested_result": guidance, "rules": sorted(set(str(row.get("rule", ""))
                                                               for row in rows if row.get("rule"))),
            "finding_ids": [str(row.get("id") or row.get("fingerprint", ""))
                            for row in rows[:100]],
            "diff": "", "improved_source": "", "improved_source_withheld": False,
            "withheld_reason": "no verified code candidate exists", "resolved_count": 0,
            "remaining_count": len(rows), "verification": {
                "accepted": False, "state": "not-run-no-deterministic-candidate",
                "required_gates": ["scanner", "build", "test"],
            }, "probes": [], "selected_tests": {}, "edits": [], "refusals": [],
        })
    return plans

def _projection_value(value: Any) -> Any:
    """Retain a small exact value or replace it with bounded digest metadata."""
    encoded = _canonical(value)
    if len(encoded) <= MAX_PROJECTION_RETAINED_BYTES:
        return json.loads(encoded.decode("utf-8"))
    count = len(value) if isinstance(value, (dict, list, tuple)) else 1
    return {
        "state": "digest-only-public-projection",
        "source_type": type(value).__name__,
        "source_items": count,
        "source_bytes": len(encoded),
        "source_sha256": _sha(value),
    }

def _file_input_descriptors(values: Sequence[str | os.PathLike[str]]) -> list[dict[str, Any]]:
    """Describe file inputs by content and opaque location, never by file contents."""
    rows: list[dict[str, Any]] = []
    for value in values:
        try:
            path = Path(value).expanduser().resolve(strict=True)
            if not path.is_file():
                raise OSError("not a regular file")
            digest = hashlib.sha256()
            size = 0
            with path.open("rb") as stream:
                while True:
                    block = stream.read(128 * 1024)
                    if not block:
                        break
                    size += len(block)
                    if size > MAX_LEGACY_RULE_PACK_BYTES:
                        raise Attestor41Error("a legacy rule-pack input exceeds the byte boundary")
                    digest.update(block)
        except Attestor41Error:
            raise
        except (OSError, RuntimeError, TypeError, ValueError) as exc:
            raise Attestor41Error("a configured rule-pack input is unavailable") from exc
        rows.append({
            "location_sha256": _sha(os.fspath(path).encode("utf-8", "surrogatepass")),
            "content_sha256": digest.hexdigest(),
            "bytes": size,
        })
    return rows

def _is_link_or_reparse(path: Path) -> bool:
    """Recognize POSIX links and Windows reparse-backed paths before resolve()."""
    try:
        metadata = path.lstat()
    except OSError:
        return False
    attributes = int(getattr(metadata, "st_file_attributes", 0))
    reparse_flag = int(getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400))
    return stat.S_ISLNK(metadata.st_mode) or bool(attributes & reparse_flag)

def _cli_failure_output(error: BaseException, output_format: str) -> str:
    """Render a bounded failure without exposing a Python traceback."""
    error_type = type(error).__name__[:120]
    if output_format == "sarif":
        return json.dumps({
            "$schema": (
                "https://json.schemastore.org/sarif-2.1.0.json"),
            "version": "2.1.0",
            "runs": [{
                "tool": {"driver": {
                    "name": "Attestor 4.1.4",
                    "semanticVersion": VERSION,
                    "rules": [],
                }},
                "invocations": [{
                    "executionSuccessful": False,
                    "toolExecutionNotifications": [{
                        "descriptor": {"id": "ATTESTOR414-FAILED-CLOSED"},
                        "level": "error",
                        "message": {"text": (
                            "Attestor 4.1.4 analysis failed safely at a bounded "
                            "evidence boundary (%s)." % error_type)},
                    }],
                }],
                "results": [],
            }],
        }, indent=2, sort_keys=True, ensure_ascii=False)
    if output_format == "json":
        return json.dumps({
            "schema": "attestor-cli-failure/4.1.4",
            "version": VERSION,
            "status": "failed",
            "result_available": False,
            "findings": [],
            "summary": {"findings": 0, "component_errors": 1},
            "coverage": {
                "complete": False,
                "absence_proven": False,
                "gaps": [
                    "analysis failed closed before a verified result was "
                    "available"
                ],
            },
            "error": {
                "code": "ATTESTOR414-FAILED-CLOSED",
                "type": error_type,
                "details_disclosed": False,
                "traceback_disclosed": False,
            },
        }, indent=2, sort_keys=True, ensure_ascii=False)
    return "Attestor 4.1.4 failed safely: %s" % error_type

def apply_content_changes(text: str, changes: Iterable[Mapping[str, Any]]) -> str:
    """Apply LSP incremental changes in order using negotiated UTF-16 positions."""
    output = text
    rows = list(changes)
    if not rows or len(rows) > 1_000:
        raise LspProtocolError("contentChanges must be a bounded non-empty list")
    for change in rows:
        replacement = change.get("text")
        if not isinstance(replacement, str):
            raise LspProtocolError("change text is required")
        if "range" not in change:
            output = replacement
        else:
            selected = change.get("range")
            if not isinstance(selected, Mapping) or not isinstance(selected.get("start"), Mapping) \
                    or not isinstance(selected.get("end"), Mapping):
                raise LspProtocolError("change range is invalid")
            start = _position_offset(output, selected["start"])
            end = _position_offset(output, selected["end"])
            if start > end:
                raise LspProtocolError("change range is reversed")
            output = output[:start] + replacement + output[end:]
        if len(output) > MAX_DOCUMENT_CHARS:
            raise LspProtocolError("changed document exceeds the live-analysis boundary")
    return output

def _variant_process_timeout(
        profile: variant414.VariantProfile) -> int:
    """Return the immutable outer UI budget for one profile-bound run."""
    selected = variant414.require_compiled_profile(profile)
    return min(
        MAX_TIMEOUT,
        max(DEFAULT_TIMEOUT,
            selected.max_worker_seconds * VARIANT_PROCESS_TIMEOUT_MULTIPLIER),
    )

def _variant_profile_for_request(
        mode: str, version: object, value: object = None,
) -> variant414.VariantProfile | None:
    """Resolve only exact HTTP/UI slugs for the current variant-capable modes."""
    if type(mode) is not str or type(version) is not str:
        raise ValueError("Attestor mode and version must be text.")
    normalized_mode = mode.strip().lower()
    if normalized_mode == "cjpcontrol":
        if version != CURRENT_VERSION:
            raise ValueError(
                "Cockroach local control is available only in Attestor 4.1.4.")
        try:
            selected = (
                variant414.COCKROACH_JANTA_PARTY
                if value is None else variant414.profile_for_slug(value))
            selected = variant414.require_compiled_profile(selected)
        except variant414.VariantError as exc:
            raise ValueError(
                "Cockroach local control requires its exact canonical slug."
            ) from exc
        if selected is not variant414.COCKROACH_JANTA_PARTY:
            raise ValueError(
                "Cockroach local control cannot use South Park or Gruppe Sechs.")
        return selected
    applicable = version == CURRENT_VERSION and normalized_mode in VARIANT_MODES
    if not applicable:
        if value is not None:
            raise ValueError(
                "Attestor variants are only valid for current 4.1.4 maximum modes.")
        return None
    if value is None:
        return variant414.DEFAULT_PROFILE
    try:
        return variant414.profile_for_slug(value)
    except variant414.VariantError as exc:
        raise ValueError(
            "Variant must be one exact Attestor 4.1.4 canonical slug.") from exc

def _history_verification(report: dict) -> dict:
    """Freshly replay stored Truth Guard evidence without rewriting history."""
    # This endpoint can replay only Truth Guard 3. Older ledgers remain valid
    # historical artifacts, but must not be misrouted through the 4.1 verifier.
    applicable = isinstance(report.get("truth_guard3"), dict)
    if not applicable:
        return {"applicable": False, "checked": False, "verified": False,
                "fresh": None, "status": "not-applicable", "error_count": 0}
    try:
        verification = truth_guard41.verify_guarded(report, require_fresh=True)
    except (OSError, RuntimeError, TypeError, ValueError,
            truth_guard41.TruthGuard41Error):
        return {"applicable": True, "checked": False, "verified": False,
                "fresh": None, "status": "verification-error", "error_count": 1}
    fresh_value = verification.get("fresh")
    fresh = fresh_value if type(fresh_value) is bool else None
    verified = verification.get("ok") is True and fresh is True
    raw_status = str(verification.get("status", "invalid")).casefold()
    status = "fresh-verified" if verified else (
        "stale" if raw_status == "stale" else "invalid")
    errors = verification.get("errors")
    return {"applicable": True, "checked": True, "verified": verified,
            "fresh": fresh, "status": status,
            "error_count": min(len(errors), 2_000) if isinstance(errors, list) else 0}

def _completed_returncode(mode: str, code: int) -> bool:
    """Finding/policy exits are completed reports, not subprocess failures."""
    return code in (0, 1)

def _write_response_body(handler: BaseHTTPRequestHandler, body: bytes) -> bool:
    """Finish a response quietly when a local client has already disconnected."""
    try:
        handler.wfile.write(body)
        return True
    except (BrokenPipeError, ConnectionAbortedError, ConnectionResetError):
        return False

def shutdown(self) -> None:
        """Cancel active subprocesses and join worker threads on server exit."""
        with self._lock:
            for job in self._jobs.values():
                if job["status"] in ("queued", "running"):
                    job["cancel_event"].set()
        self._executor.shutdown(wait=True, cancel_futures=True)

def _discard_body(self) -> None:
        """Consume a rejected request body so the connection can close cleanly."""
        try:
            declared = 0
            for value in self.headers.get_all("Content-Length") or []:
                text = value.strip()
                if text.isascii() and text.isdecimal():
                    declared = max(declared, int(text))
            remaining = min(declared, MAX_BODY_BYTES)
            while remaining > 0:
                chunk = self.rfile.read(min(remaining, 8192))
                if not chunk:
                    break
                remaining -= len(chunk)
        except (OSError, ValueError):
            return                  # the peer has gone; the close is moot now

def audit(paths, deep: bool = True, min_severity: str = "LOW") -> dict:
    """Scan every source file under paths with both engines; group the findings."""
    threshold = detect.SEVERITY_ORDER[min_severity]
    files = detect.collect_paths(paths)
    per_file = {}
    all_findings = []
    for path in files:
        findings = detect.scan_file(path, deep=deep)
        if path.lower().endswith((".py", ".pyw")):
            findings += deepscan.scan_path(path)
            findings += rarebugs.scan_path(path)
        findings = [f for f in findings
                    if detect.SEVERITY_ORDER[f.severity] >= threshold]
        findings.sort(key=detect.Finding.sort_key)
        if findings:
            per_file[path] = findings
        all_findings += findings
    return {"files_scanned": len(files),
            "files_with_findings": len(per_file),
            "findings": all_findings,
            "per_file": per_file}

def _rel(path: str, root: str) -> str:
    """Path relative to the audited root (so reports read cleanly, not ../../..)."""
    base = root if os.path.isdir(root) else os.path.dirname(root)
    try:
        return os.path.relpath(path, base) if base else path
    except ValueError:
        return path

#!/usr/bin/env python3
"""
audit.py -- review a whole codebase and write a report.

Point it at a directory of source you legitimately have -- a repo you were added
to, a zip you were handed -- and Attestor runs BOTH engines over the entire tree (the
regex detector across C/C++/Haskell/Python/JS + secrets, and the deepscan AST
analyzer on the Python), aggregates everything, and produces a report you can hand
to a team: a summary, the most common issues, the files that need the most
attention, and every finding grouped by file. Markdown and SARIF too.

    python3 audit.py ./their_repo
    python3 audit.py ./src --severity HIGH --format md --out review.md
    python3 audit.py ./src --format sarif > review.sarif
"""
from __future__ import annotations

import argparse
import json
import os

import deepscan
import detect
import rarebugs


def audit(paths, deep: bool = True, min_severity: str = "LOW") -> dict:
    """Scan every source file under paths with both engines; group the findings."""
    threshold = detect.SEVERITY_ORDER[min_severity]
    files = detect.collect_paths(paths)
    per_file = {}
    all_findings = []
    for path in files:
        findings = detect.scan_file(path, deep=deep)
        if path.lower().endswith((".py", ".pyw")):
            findings += deepscan.scan_path(path)
            findings += rarebugs.scan_path(path)
        findings = [f for f in findings
                    if detect.SEVERITY_ORDER[f.severity] >= threshold]
        findings.sort(key=detect.Finding.sort_key)
        if findings:
            per_file[path] = findings
        all_findings += findings
    return {"files_scanned": len(files),
            "files_with_findings": len(per_file),
            "findings": all_findings,
            "per_file": per_file}


def _by_severity(findings) -> dict:
    counts = {"HIGH": 0, "MEDIUM": 0, "LOW": 0}
    for f in findings:
        counts[f.severity] = counts.get(f.severity, 0) + 1
    return counts


def _by_rule(findings):
    counts = {}
    for f in findings:
        counts[f.rule] = counts.get(f.rule, 0) + 1
    return sorted(counts.items(), key=lambda kv: kv[1], reverse=True)


def _top_files(per_file, limit: int = 10):
    return sorted(per_file.items(), key=lambda kv: len(kv[1]), reverse=True)[:limit]


def _rel(path: str, root: str) -> str:
    """Path relative to the audited root (so reports read cleanly, not ../../..)."""
    base = root if os.path.isdir(root) else os.path.dirname(root)
    try:
        return os.path.relpath(path, base) if base else path
    except ValueError:
        return path


def report_text(result: dict, root: str) -> str:
    findings = result["findings"]
    sev = _by_severity(findings)
    out = [f"Code review -- {root}", "=" * 64,
           f"scanned {result['files_scanned']} files; {len(findings)} finding(s) in "
           f"{result['files_with_findings']} file(s)",
           f"  HIGH {sev['HIGH']}   MEDIUM {sev['MEDIUM']}   LOW {sev['LOW']}"]
    rules = _by_rule(findings)
    if rules:
        out += ["", "most common issues:"]
        for rule, n in rules[:10]:
            out.append(f"  {n:>4}  {rule}")
    top = _top_files(result["per_file"])
    if top:
        out += ["", "files needing the most attention:"]
        for path, fs in top:
            out.append(f"  {len(fs):>4}  {_rel(path, root)}")
    if result["per_file"]:
        out += ["", "findings:"]
        for path in sorted(result["per_file"]):
            out.append(f"\n{_rel(path, root)}:")
            for x in result["per_file"][path]:
                out.append(f"  L{x.line} [{x.severity}] {x.rule}: {x.fix}")
    else:
        out += ["", "no issues found. clean, by Attestor's rules."]
    return "\n".join(out)


def report_markdown(result: dict, root: str) -> str:
    findings = result["findings"]
    sev = _by_severity(findings)
    lines = [f"# Code review — `{root}`", "",
             f"Scanned **{result['files_scanned']}** source files; found "
             f"**{len(findings)}** issue(s) across "
             f"**{result['files_with_findings']}** file(s).",
             "", "## Summary", "", "| Severity | Count |", "|---|---|",
             f"| HIGH | {sev['HIGH']} |",
             f"| MEDIUM | {sev['MEDIUM']} |",
             f"| LOW | {sev['LOW']} |"]
    rules = _by_rule(findings)
    if rules:
        lines += ["", "## Most common issues", "", "| Rule | Count |", "|---|---|"]
        for rule, n in rules[:12]:
            lines.append(f"| `{rule}` | {n} |")
    top = _top_files(result["per_file"])
    if top:
        lines += ["", "## Files needing the most attention", "", "| File | Issues |", "|---|---|"]
        for path, fs in top:
            lines.append(f"| `{_rel(path, root)}` | {len(fs)} |")
    if result["per_file"]:
        lines += ["", "## Findings"]
        for path in sorted(result["per_file"]):
            fs = result["per_file"][path]
            lines += ["", f"### `{_rel(path, root)}` ({len(fs)})", ""]
            for x in fs:
                lines.append(f"- **L{x.line}** `[{x.severity}]` `{x.rule}` — {x.fix}")
    else:
        lines += ["", "No issues found — clean by Attestor's rules."]
    return "\n".join(lines)


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("paths", nargs="+", help="folders or files to review")
    ap.add_argument("--no-deep", action="store_true",
                    help="skip the higher-recall (noisier) rule tier")
    ap.add_argument("--severity", choices=["LOW", "MEDIUM", "HIGH"], default="LOW")
    ap.add_argument("--format", choices=["text", "md", "sarif"], default="text")
    ap.add_argument("--out", help="write the report here instead of stdout")
    args = ap.parse_args(argv)

    result = audit(args.paths, deep=not args.no_deep, min_severity=args.severity)
    root = args.paths[0]
    if args.format == "sarif":
        text = json.dumps(detect.to_sarif(result["findings"]), indent=2)
    elif args.format == "md":
        text = report_markdown(result, root)
    else:
        text = report_text(result, root)

    if args.out:
        with open(args.out, "w", encoding="utf-8") as fh:
            fh.write(text)
        print(f"reviewed {result['files_scanned']} files, {len(result['findings'])} "
              f"finding(s) -> {args.out}")
    else:
        print(text)
    return min(len(result["findings"]), 250)


if __name__ == "__main__":
    raise SystemExit(main())

def verify_authorization(*, authorization_file: str, authority_key_file: str,
                         now: _dt.datetime | None = None) -> dict[str, Any]:
    """Accept only a signed, in-scope, unexpired TCS grant. Fail closed."""
    current = now or ta._utc_now()
    try:
        grant = json.loads(Path(authorization_file).read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise BenchAuthError("authorization file is not valid JSON") from exc
    if not isinstance(grant, Mapping) or grant.get("schema") != ta.GRANT_SCHEMA:
        raise BenchAuthError("authorization must be a Trusted Access grant")

    key = _read_key(authority_key_file)
    try:
        sig = grant.get("signature") if isinstance(grant.get("signature"), Mapping) else {}
        kid = str(sig.get("key_id", ""))
        authority_key_id = ta._signature_ok(grant, {kid: key})
    except ta.TrustedAccessError as exc:
        raise BenchAuthError("authorization signature did not verify: %s" % exc)

    resource = str(grant.get("resource", ""))
    if not resource.startswith(TCS_RESOURCE_PREFIX):
        raise BenchAuthError("authorization resource must be under %s" % TCS_RESOURCE_PREFIX)
    scopes = set(grant.get("scopes") or [])
    if REQUIRED_SCOPE not in scopes:
        raise BenchAuthError("authorization must include scope %s" % REQUIRED_SCOPE)
    issued = ta._parse_time(grant.get("issued_at"), "issued_at")
    expires = ta._parse_time(grant.get("expires_at"), "expires_at")
    if issued > current + ta.FUTURE_SKEW:
        raise BenchAuthError("authorization is not yet valid")
    if expires <= current:
        raise BenchAuthError("authorization has expired")
    return {"authority_key_id": authority_key_id, "resource": resource,
            "scopes": sorted(scopes), "grant_id": str(grant.get("grant_id"))}

def _safe_local_file(base: Path, raw: str) -> Path:
    """Mirror attestorbench41's no-escape, no-symlink discipline for inputs."""
    if not raw or "\x00" in raw or len(raw) > 32_768:
        raise BenchAuthError("manifest path is not a bounded local path")
    lexical = Path(base / raw).resolve()
    if not str(lexical).startswith(str(base.resolve())):
        raise BenchAuthError("manifest escapes the authorized directory")
    if ta is not None and getattr(lexical, "is_symlink", lambda: False)():
        raise BenchAuthError("manifest must not be a symlink")
    if not lexical.is_file():
        raise BenchAuthError("manifest does not exist as a regular file")
    return lexical

def _elf_program_headers(data: bytes):
    """Yield (p_type, p_flags, p_offset, p_filesz) for each program header."""
    is64 = data[4] == 2
    little = data[5] == 1
    endian = "<" if little else ">"
    try:
        if is64:
            phoff = struct.unpack_from(endian + "Q", data, 32)[0]
            phentsize, phnum = struct.unpack_from(endian + "HH", data, 54)
        else:
            phoff = struct.unpack_from(endian + "I", data, 28)[0]
            phentsize, phnum = struct.unpack_from(endian + "HH", data, 42)
    except struct.error as error:
        raise BinaryError("truncated ELF header") from error
    if phnum > 4096 or phentsize < 8:
        raise BinaryError("implausible ELF program header table")
    for index in range(phnum):
        base = phoff + index * phentsize
        if base + phentsize > len(data):
            break
        if is64:
            ptype, flags = struct.unpack_from(endian + "II", data, base)
            offset, _, filesz = struct.unpack_from(endian + "QQQ", data,
                                                   base + 8)
        else:
            ptype, offset = struct.unpack_from(endian + "II", data, base)
            _, filesz = struct.unpack_from(endian + "II", data, base + 8)
            flags = struct.unpack_from(endian + "I", data, base + 24)[0]
        yield ptype, flags, offset, filesz

def verify_report(report: dict[str, Any]) -> tuple[bool, list[str]]:
    """Recompute a report's identity. Fails closed."""
    if not isinstance(report, dict) or report.get("schema") != SCHEMA:
        return False, ["not a binary-hardening report"]
    body = {k: v for k, v in report.items() if k != "report_sha256"}
    if report.get("report_sha256") != _sha(body):
        return False, ["report digest does not match its contents"]
    return True, []

def open_or_create(
        checkpoint_path: str | os.PathLike[str] | None = None, *,
        objective: str = OBJECTIVE, arena_kind: str | None = None,
        seed: int | None = None) -> dict[str, Any]:
    """Load a strict checkpoint or create a new deterministic abstract arena."""
    if objective != OBJECTIVE:
        raise BlindEscapeArenaError("objective must be exactly 'Escape'")
    if checkpoint_path is not None:
        target = _checkpoint_path(checkpoint_path)
        if target.exists():
            if seed is not None:
                raise BlindEscapeArenaError("seed cannot replace an existing checkpoint")
            state = load_checkpoint(target)
            if arena_kind is not None and state["private"]["arena_kind"] != arena_kind:
                raise BlindEscapeArenaError("checkpoint arena kind does not match")
            return state
    selected_kind = arena_kind or GENERATED_ESCAPABLE
    state = _new_state(objective=objective, arena_kind=selected_kind, seed=seed)
    if checkpoint_path is not None:
        save_checkpoint(state, checkpoint_path)
    return state

def default_explorer(view: Mapping[str, Any]) -> str:
    """General black-box explorer using only the supplied opaque view."""
    if not _exact(dict(view), {
        "schema", "version", "objective", "arena_id", "episode_index", "step",
        "observation_id", "start_observation_id", "action_ids", "knowledge",
    }, "observation"):
        raise BlindEscapeArenaError("explorer view is invalid")
    current = view["observation_id"]
    actions = list(view["action_ids"])
    rows = {
        (row["observation_id"], row["action_id"]): row
        for row in view["knowledge"] if type(row) is dict
    }
    untried = [action for action in actions if (current, action) not in rows]
    if untried:
        return sorted(untried)[0]
    start = view["start_observation_id"]
    advances = [
        action for action in actions
        if rows[(current, action)]["outcome"] == "transition"
        and rows[(current, action)]["next_observation_id"] not in {current, start}
    ]
    if advances:
        return sorted(advances, key=lambda action: (
            rows[(current, action)]["attempts"], action))[0]
    return min(actions, key=lambda action: (rows[(current, action)]["attempts"], action))

def verify_state(state: Any) -> tuple[bool, list[str]]:
    """Total, fail-closed validation for an arbitrary caller-supplied value."""
    try:
        return _verify_state_core(state)
    except Exception as exc:
        return False, [
            "state validation rejected malformed input (%s)"
            % type(exc).__name__
        ]

def _is_link_or_reparse(info: os.stat_result) -> bool:
    """Recognize POSIX links and Windows reparse-backed path components."""
    attributes = int(getattr(info, "st_file_attributes", 0))
    reparse = int(getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400))
    return stat.S_ISLNK(info.st_mode) or bool(attributes & reparse)

def _lexical_root(value: Any) -> Path:
    """Validate *value* without resolving a link, then return an absolute root.

    ``Path.resolve`` cannot be the first check: by then a supplied link has
    disappeared from the spelling.  Walking the caller's lexical spelling also
    checks components that precede ``..`` before normalising the final path.
    The child repeats this check, so changing its working directory cannot
    silently retarget a relative API/CLI request.
    """
    if (not isinstance(value, str) or not value or len(value) > 32_768 or
            "\x00" in value):
        raise WorkerError("worker root is invalid")
    try:
        supplied = Path(value).expanduser()
        if supplied.drive and not supplied.is_absolute():
            raise WorkerError("worker root must not be drive-relative")
        spelling = supplied if supplied.is_absolute() else Path.cwd() / supplied
        current = Path(spelling.anchor)
        if not current.anchor:
            raise WorkerError("worker root is invalid")
        anchor_info = os.lstat(current)
        if _is_link_or_reparse(anchor_info):
            raise WorkerError("worker root contains a link or reparse point")
        if not stat.S_ISDIR(anchor_info.st_mode):
            raise WorkerError("worker root contains a non-directory component")
        for part in spelling.parts[1:]:
            if part in {"", "."}:
                continue
            if part == "..":
                current = current.parent
                continue
            current = current / part
            info = os.lstat(current)
            if _is_link_or_reparse(info):
                raise WorkerError("worker root contains a link or reparse point")
            if not stat.S_ISDIR(info.st_mode):
                raise WorkerError("worker root contains a non-directory component")
        lexical = Path(os.path.abspath(os.fspath(spelling)))
        resolved = lexical.resolve(strict=True)
        if resolved != lexical:
            raise WorkerError("worker root resolution traversed a link or reparse point")
        # Repeat the lexical walk to turn a concurrent link swap into a
        # refusal.  Downstream snapshot capture performs its own checks too.
        current = Path(lexical.anchor)
        for part in lexical.parts[1:]:
            current = current / part
            info = os.lstat(current)
            if _is_link_or_reparse(info):
                raise WorkerError("worker root contains a link or reparse point")
            if not stat.S_ISDIR(info.st_mode):
                raise WorkerError("worker root contains a non-directory component")
        root_info = os.lstat(resolved)
    except WorkerError:
        raise
    except (OSError, RuntimeError, TypeError, ValueError) as exc:
        raise WorkerError("worker root is unavailable") from exc
    if not stat.S_ISDIR(root_info.st_mode) or _is_link_or_reparse(root_info):
        raise WorkerError("worker root must be a real directory")
    return resolved

def _request_payload(action: str, payload: Mapping[str, Any]) -> tuple[dict[str, Any], bytes]:
    """Create the exact bounded request sent to the isolated child."""
    if action not in ACTIONS or type(payload) is not dict:
        raise WorkerError("worker action or payload is unsupported")
    normalized = dict(payload)
    normalized["root"] = str(_lexical_root(normalized.get("root")))
    try:
        request = json.dumps(
            normalized, sort_keys=True, separators=(",", ":"),
            ensure_ascii=False, allow_nan=False).encode("utf-8")
    except (TypeError, ValueError, UnicodeError, RecursionError) as exc:
        raise WorkerError("worker request is not strict JSON") from exc
    if len(request) > MAX_REQUEST_BYTES:
        raise WorkerError("worker request exceeds the byte boundary")
    unknown = set(normalized) - ACTION_PAYLOAD_KEYS[action]
    if unknown:
        raise WorkerError("worker payload contains unsupported fields")
    return normalized, request

class GenerationResult:
    """Typed result for one provider attempt.

    ``content`` exists only for ``SUCCESS``.  Failure and abstention details
    live in ``error`` and can therefore never masquerade as model output.
    Prompt text is intentionally not retained; evidence stores its digest.
    """

    provider: str
    model: str
    status: GenerationStatus
    content: str | None
    prompt_sha256: str
    response_sha256: str | None
    error: str | None = None

    def __post_init__(self) -> None:
        try:
            status = GenerationStatus(self.status)
        except ValueError as exc:
            raise ValueError("unknown generation status") from exc
        object.__setattr__(self, "status", status)
        if not _is_sha256(self.prompt_sha256):
            raise ValueError("prompt_sha256 must be a lowercase SHA-256 digest")
        if self.status is GenerationStatus.SUCCESS:
            if not self.content:
                raise ValueError("successful generation must contain model output")
            expected = _sha256_text(self.content)
            if self.response_sha256 != expected:
                raise ValueError("response_sha256 does not match model output")
            if self.error is not None:
                raise ValueError("successful generation cannot contain an error")
        else:
            if self.content is not None or self.response_sha256 is not None:
                raise ValueError("failed/abstained generation cannot contain model output")
        if self.status is GenerationStatus.FAILED and not self.error:
            raise ValueError("failed generation must contain a safe error summary")

    @property
    def success(self) -> bool:
        return self.status is GenerationStatus.SUCCESS

    @property
    def failed(self) -> bool:
        return self.status is GenerationStatus.FAILED

    @property
    def abstained(self) -> bool:
        return self.status is GenerationStatus.ABSTAINED

    @property
    def evidence(self) -> GenerationEvidence:
        return GenerationEvidence(
            provider=self.provider,
            model=self.model,
            status=self.status,
            prompt_sha256=self.prompt_sha256,
            response_sha256=self.response_sha256,
        )

    def evidence_dict(self) -> dict:
        return self.evidence.as_dict()

    def require_content(self) -> str:
        """Return verified response text or fail instead of inventing content."""
        if not self.success or self.content is None:
            detail = (": " + self.error) if self.error else ""
            raise ProviderError(
                f"{self.provider} generation {self.status.value}{detail}")
        return self.content

    def __bool__(self) -> bool:
        return self.success

    def __str__(self) -> str:
        # This is intentionally empty for non-success states.  Older callers
        # commonly use ``str(value).strip()`` before treating it as a candidate.
        return self.content if self.success and self.content is not None else ""

    def __contains__(self, value: object) -> bool:
        """Small compatibility bridge for legacy ``'failed' in value`` checks."""
        if not isinstance(value, str):
            return False
        if self.success:
            return value in (self.content or "")
        return value in self.status.value or value in (self.error or "")

def _validate_endpoint(url: str, allowed_hosts, allow_http: bool = False) -> str:
    """Fail closed unless an endpoint has the expected scheme and exact host."""
    try:
        parsed = urllib.parse.urlsplit(url)
        port = parsed.port
    except ValueError as exc:
        raise ProviderConfigurationError("invalid provider endpoint") from exc
    host = (parsed.hostname or "").rstrip(".").lower()
    expected = {str(item).rstrip(".").lower() for item in allowed_hosts}
    if parsed.username is not None or parsed.password is not None:
        raise ProviderConfigurationError("provider endpoint must not contain credentials")
    if host not in expected:
        raise ProviderConfigurationError("provider endpoint host is not allowlisted: " + (host or "(none)"))
    if parsed.scheme != "https" and not (allow_http and parsed.scheme == "http"):
        raise ProviderConfigurationError("provider endpoint must use HTTPS")
    if parsed.scheme == "https" and port not in (None, 443):
        raise ProviderConfigurationError("cloud provider endpoint must use HTTPS port 443")
    if parsed.fragment or any(ch in url for ch in "\x00\r\n"):
        raise ProviderConfigurationError("invalid provider endpoint")
    return url

def _validate_cloud_resolution(host: str, port: int = 443) -> None:
    """Reject cloud-provider DNS answers that point at a local/special address."""
    try:
        answers = socket.getaddrinfo(host, port, type=socket.SOCK_STREAM)
    except OSError as exc:
        raise ProviderError("provider host could not be resolved safely") from exc
    addresses = set()
    for _family, _kind, _proto, _canon, sockaddr in answers:
        try:
            address = ipaddress.ip_address(sockaddr[0].split("%", 1)[0])
        except ValueError:
            continue
        mapped = getattr(address, "ipv4_mapped", None)
        addresses.add(mapped or address)
    if not addresses or any(not address.is_global for address in addresses):
        raise ProviderError("provider host resolved to a non-public address")

def _validate_loopback_resolution(host: str, port: int) -> None:
    """Ensure a named local endpoint cannot be redirected by hosts/DNS config."""
    try:
        literal = ipaddress.ip_address(host)
    except ValueError:
        try:
            answers = socket.getaddrinfo(host, port, type=socket.SOCK_STREAM)
        except OSError as exc:
            raise ProviderConfigurationError("local OLLAMA_HOST could not be resolved") from exc
        addresses = set()
        for _family, _kind, _proto, _canon, sockaddr in answers:
            try:
                addresses.add(ipaddress.ip_address(sockaddr[0].split("%", 1)[0]))
            except ValueError:
                continue
        if not addresses or any(not address.is_loopback for address in addresses):
            raise ProviderConfigurationError("local OLLAMA_HOST did not resolve only to loopback")
    else:
        if not literal.is_loopback:
            raise ProviderConfigurationError("local OLLAMA_HOST is not loopback")

def _validate_ollama_host(host: str, allow_remote: bool = False) -> str:
    """Validate an Ollama base URL and return a normalized value.

    Local loopback endpoints are the safe default. A remote endpoint requires
    the explicit ``ATTESTOR_ALLOW_REMOTE_OLLAMA=1`` trust decision.
    """
    raw = (host or "http://localhost:11434").strip()
    try:
        parsed = urllib.parse.urlsplit(raw)
        _ = parsed.port
    except ValueError as exc:
        raise ProviderConfigurationError("invalid OLLAMA_HOST") from exc
    hostname = (parsed.hostname or "").rstrip(".").lower()
    if parsed.scheme not in ("http", "https") or not hostname:
        raise ProviderConfigurationError("OLLAMA_HOST must be a full http(s) URL")
    if parsed.username is not None or parsed.password is not None:
        raise ProviderConfigurationError("OLLAMA_HOST must not contain credentials")
    if parsed.path not in ("", "/") or parsed.query or parsed.fragment:
        raise ProviderConfigurationError("OLLAMA_HOST must not contain a path, query, or fragment")
    if any(ch in raw for ch in "\x00\r\n"):
        raise ProviderConfigurationError("invalid OLLAMA_HOST")
    if not _loopback_host(hostname) and not allow_remote:
        raise ProviderConfigurationError(
            "remote OLLAMA_HOST blocked; set ATTESTOR_ALLOW_REMOTE_OLLAMA=1 only for a trusted server")
    if _loopback_host(hostname):
        _validate_loopback_resolution(
            hostname, parsed.port or (443 if parsed.scheme == "https" else 80))
    return raw.rstrip("/")

class OpenAIProvider(Provider):
    """OpenAI-compatible chat/completions. Groq speaks the same protocol, so its
    provider is just this with a different URL and default model."""
    name = "openai"
    _url = "https://api.openai.com/v1/chat/completions"
    _allowed_hosts = frozenset({"api.openai.com"})
    _allow_http = False

    def __init__(self, api_key: str, model: str = "gpt-4o-mini", timeout: int = _TIMEOUT):
        self._key = _validate_secret(api_key)
        self._model = _validate_model(model)
        self._timeout = timeout

    def generate(self, prompt: str) -> str:
        body = {"model": self._model,
                "messages": [{"role": "user", "content": prompt}]}
        headers = {"Authorization": "Bearer " + self._key}
        try:
            data = _post_json(
                self._url, body, headers, self._timeout,
                allowed_hosts=self._allowed_hosts, allow_http=self._allow_http)
        except urllib.error.HTTPError as exc:
            raise ProviderError(f"{self.name} HTTP {exc.code} "
                                "(404=bad model, 429=quota, 401=bad key)") from exc
        except Exception as exc:                # noqa: BLE001
            raise ProviderError(f"{self.name} unreachable: {type(exc).__name__}") from exc
        try:
            return data["choices"][0]["message"]["content"]
        except (KeyError, IndexError, TypeError) as exc:
            raise ProviderError(f"{self.name}: unexpected response shape") from exc

def strip_fences(text: str | GenerationResult) -> str:
    """Pull code from a fence, rejecting non-content generation states."""
    if isinstance(text, GenerationResult):
        text = text.require_content()
    if not isinstance(text, str):
        raise TypeError("model output must be text")
    m = re.search(r"```(?:\w+)?\n(.*?)```", text, re.S)
    return m.group(1).strip() if m else text.strip()

def _attempt_generation(provider, prompt: str) -> GenerationResult:
    """Call one provider and convert every expected outcome to typed evidence."""
    provider_name, model_name = _provider_identity(provider)
    prompt_sha256 = _sha256_text(prompt)
    try:
        raw = provider.generate(prompt)
    except ProviderError as exc:
        return GenerationResult(
            provider_name, model_name, GenerationStatus.FAILED, None,
            prompt_sha256, None, _safe_detail(exc))
    if raw is None or (isinstance(raw, str) and not raw.strip()):
        return GenerationResult(
            provider_name, model_name, GenerationStatus.ABSTAINED, None,
            prompt_sha256, None, "provider returned no content")
    if not isinstance(raw, str):
        return GenerationResult(
            provider_name, model_name, GenerationStatus.FAILED, None,
            prompt_sha256, None, "provider returned non-text content")
    content = strip_fences(raw)
    if not content:
        return GenerationResult(
            provider_name, model_name, GenerationStatus.ABSTAINED, None,
            prompt_sha256, None, "provider returned an empty fenced response")
    return GenerationResult(
        provider_name, model_name, GenerationStatus.SUCCESS, content,
        prompt_sha256, _sha256_text(content))

def from_env(mode: str = "fallback", model: str = "", exclude=()) -> Brain:
    """Build a Brain from whatever keys are in the environment.

    `model`, if given, overrides the model on every configured provider -- handy
    for a single-provider setup (e.g. just Groq running Qwen). `exclude` drops
    providers by name (e.g. exclude=("gemini",) to bench Google AI Studio).
    Keys in a `keys.env` file are loaded first (a real env var still wins).
    """
    import envfile
    envfile.load()
    providers = []
    configuration_errors = []

    def add(name, factory):
        try:
            providers.append(factory())
        except ProviderConfigurationError as exc:
            configuration_errors.append(name + ": " + str(exc))

    # Order = reliability of the free tier: the sturdy ones first, flaky Gemini
    # later, paid OpenAI last. In fallback mode a 429 on any one cascades to the
    # next, so this is the "escape Google's 429s" chain, automatic.
    groq_key = os.environ.get("GROQ_API_KEY")
    if groq_key:
        add("groq", lambda: GroqProvider(
            groq_key, os.environ.get("GROQ_MODEL", "llama-3.3-70b-versatile")))
    openrouter_key = os.environ.get("OPENROUTER_API_KEY")
    if openrouter_key:
        add("openrouter", lambda: OpenRouterProvider(
            openrouter_key,
            os.environ.get("OPENROUTER_MODEL", "meta-llama/llama-3.3-70b-instruct:free")))
    mistral_key = os.environ.get("MISTRAL_API_KEY")
    if mistral_key:
        add("mistral", lambda: MistralProvider(
            mistral_key, os.environ.get("MISTRAL_MODEL", "mistral-small-latest")))
    gemini_key = os.environ.get("GEMINI_API_KEY") or os.environ.get("GOOGLE_API_KEY")
    if gemini_key:
        add("gemini", lambda: GeminiProvider(
            gemini_key, os.environ.get("GEMINI_MODEL", "gemini-2.0-flash")))
    openai_key = os.environ.get("OPENAI_API_KEY")
    if openai_key:
        add("openai", lambda: OpenAIProvider(
            openai_key, os.environ.get("OPENAI_MODEL", "gpt-4o-mini")))
    # Ollama last: local, keyless, never rate-limited -- the backstop that answers
    # when every cloud tier is throttled. Enabled by naming a local model.
    ollama_model = os.environ.get("OLLAMA_MODEL")
    if ollama_model:
        allow_remote = os.environ.get("ATTESTOR_ALLOW_REMOTE_OLLAMA", "").strip().lower() in {
            "1", "true", "yes", "on"
        }
        add("ollama", lambda: OllamaProvider(
            ollama_model, os.environ.get("OLLAMA_HOST", "http://localhost:11434"),
            allow_remote=allow_remote))
    if exclude:
        providers = [p for p in providers if p.name not in exclude]
    if model:
        try:
            checked_model = _validate_model(model)
        except ProviderConfigurationError as exc:
            configuration_errors.append("model override: " + str(exc))
            providers = []
        else:
            for provider in providers:
                provider._model = checked_model
    return Brain(providers, mode, configuration_errors)

def as_dict(self) -> dict:
        """Return a JSON-safe evidence record without prompt or response text."""
        return {
            "schema": self.schema,
            "provider": self.provider,
            "model": self.model,
            "status": self.status.value,
            "prompt_sha256": self.prompt_sha256,
            "response_sha256": self.response_sha256,
        }

def __contains__(self, value: object) -> bool:
        """Small compatibility bridge for legacy ``'failed' in value`` checks."""
        if not isinstance(value, str):
            return False
        if self.success:
            return value in (self.content or "")
        return value in self.status.value or value in (self.error or "")

def configuration_errors(self):
        """Return safe configuration messages (never API-key values)."""
        return list(self._configuration_errors)

def generate_result(self, prompt: str) -> GenerationResult:
        """Return the selected typed result; use ``generate_results`` for all attempts."""
        results = self.generate_results(prompt)
        return next((result for result in results if result.success), results[-1])

def last_generation_results(self) -> tuple[GenerationResult, ...]:
        """Return immutable provenance from the most recent generation call."""
        return self._last_generation_results

def generation_evidence(self) -> tuple[GenerationEvidence, ...]:
        """Return content-free evidence from the most recent generation call."""
        return tuple(result.evidence for result in self._last_generation_results)

def generate(self, prompt: str):
        """Backwards-compatible content API backed by typed generation results.

        Fallback still returns a string or raises ``ProviderError``. Compare
        still returns a provider mapping; successful values are strings, while
        failure/abstention values are falsey ``GenerationResult`` records. This
        preserves status inspection without ever turning a diagnostic into
        apparent model content.
        """
        results = self.generate_results(prompt)
        if self._mode == "compare":
            if not self._providers:
                return {}
            return {
                result.provider: result.require_content() if result.success else result
                for result in results
            }
        for result in results:
            if result.success:
                return result.require_content()
        errors = [result.error for result in results if result.failed and result.error]
        if errors:
            raise ProviderError("all providers failed: " + "; ".join(errors))
        if not self._providers:
            raise ProviderError("no providers configured")
        raise ProviderError("all providers abstained")

class Evidence:
    """One site in one file that demonstrates a capability."""
    path: str
    line: int
    text: str
    reason: str

    def as_dict(self) -> dict[str, Any]:
        return {"path": self.path, "line": self.line,
                "text": self.text[:200], "reason": self.reason}

def capabilities_from_source(root: str | os.PathLike[str]) -> Side:
    """What the source openly asks for, from its imports and calls."""
    try:
        snapshot = snapshot41.capture(root)
    except (snapshot41.SnapshotError, OSError, ValueError) as exc:
        raise BuildDivergenceError("source tree could not be captured") from exc
    graph = semantic.build(snapshot)
    side = Side()

    def classify(text: str) -> str | None:
        lowered = text.lower()
        for capability, needles in _SOURCE_MODULES.items():
            for needle in needles:
                if needle in lowered:
                    return capability
        return None

    for row in graph["graph"]["imports"]:
        target = str(row.get("resolved_module") or row.get("module") or "")
        capability = classify(target)
        if capability:
            side.add(capability, Evidence(
                str(row.get("path", "")), int(row.get("line", 1) or 1),
                "import " + target, "source imports %s" % target))
    for row in graph["graph"]["calls"]:
        callee = str(row.get("resolved") or row.get("callee") or "")
        capability = classify(callee)
        if capability:
            side.add(capability, Evidence(
                str(row.get("path", "")), int(row.get("line", 1) or 1),
                callee + "()", "source calls %s" % callee))
    return side

def capabilities_from_assembly(listings: Mapping[str, str]) -> Side:
    """What the compiled output actually does, from its listings.

    Syscall numbers are read from the register load that precedes the
    `syscall`, which is how the ABI is expressed in every listing. Only the
    masked instruction view is searched, so a mnemonic inside a string constant
    or a comment describing a syscall is not counted as one.
    """
    side = Side()
    for path, text in listings.items():
        masked = detect.blank(text, "asm")
        pending: list[int] = []
        for index, line in enumerate(masked):
            for match in _SYSCALL_LOAD.finditer(line):
                raw = match.group(1) or match.group(2)
                try:
                    pending.append(int(raw, 16) if raw.lower().startswith("0x")
                                   else int(raw))
                except (TypeError, ValueError):
                    continue
            if _SYSCALL_INSTR.search(line):
                for number in pending[-4:]:
                    capability = _SYSCALL_CAPABILITY.get(number)
                    if capability:
                        side.add(capability, Evidence(
                            path, index + 1, line.strip(),
                            "syscall %d issued here" % number))
                pending = []
            for pattern, capability in _ASM_SYMBOL_CAPABILITY:
                found = pattern.search(line)
                if found:
                    side.add(capability, Evidence(
                        path, index + 1, line.strip(),
                        "calls %s" % found.group(1)))
            if re.search(r"\.section\b[^\n\"]*\"[a-z]*w[a-z]*x[a-z]*\"", line, re.I) or \
                    re.search(r"\.section\b[^\n\"]*\"[a-z]*x[a-z]*w[a-z]*\"", line, re.I):
                side.add(DYNAMIC_CODE, Evidence(
                    path, index + 1, line.strip(),
                    "section is both writable and executable"))
    return side

def read_listings(root: str | os.PathLike[str]) -> dict[str, str]:
    """Every assembly listing under *root*, keyed by relative path."""
    base = Path(root)
    if not base.exists():
        raise BuildDivergenceError("assembly directory does not exist")
    out: dict[str, str] = {}
    for path in sorted(base.rglob("*")):
        if not path.is_file() or path.suffix.lower() not in _ASM_SUFFIXES:
            continue
        try:
            if path.stat().st_size > MAX_LISTING_BYTES:
                continue
            out[path.relative_to(base).as_posix()] = path.read_text(
                encoding="utf-8", errors="replace")
        except OSError:
            continue
    if not out:
        raise BuildDivergenceError("no assembly listings found under " + str(base))
    return out

def verify_report(report: Any) -> tuple[bool, list[str]]:
    """Recompute the digest and the derived counts, fail-closed."""
    errors: list[str] = []
    if not isinstance(report, Mapping):
        return False, ["report must be an object"]
    if report.get("schema") != SCHEMA or report.get("version") != VERSION:
        errors.append("schema or version mismatch")
    body = {key: value for key, value in report.items() if key != "report_sha256"}
    try:
        if report.get("report_sha256") != _sha(body):
            errors.append("report digest mismatch")
    except (TypeError, ValueError):
        errors.append("report is not canonical JSON")
    findings = report.get("findings")
    summary = report.get("summary")
    if not isinstance(findings, list) or not isinstance(summary, Mapping):
        return False, errors + ["findings or summary malformed"]
    if summary.get("finding_count") != len(findings):
        errors.append("summary finding_count does not match findings")
    if sorted(summary.get("unexplained") or []) != sorted(
            row.get("capability") for row in findings):
        errors.append("summary unexplained does not match findings")
    expected_status = "divergent" if findings else "consistent"
    if report.get("status") != expected_status:
        errors.append("status does not match findings")
    for row in findings:
        if row.get("runtime_verified") is not False:
            errors.append("a divergence may not claim runtime verification")
        if not row.get("assembly_evidence"):
            errors.append("a divergence must carry assembly evidence")
    return not errors, errors

def _wilson(successes: int, total: int, z: float = 1.959963984540054) -> list[float]:
    """Return a bounded Wilson score interval without pretending sparse certainty."""
    if total <= 0:
        return [0.0, 1.0]
    probability = successes / total
    denominator = 1.0 + z * z / total
    centre = probability + z * z / (2.0 * total)
    radius = z * math.sqrt((probability * (1.0 - probability) + z * z / (4.0 * total)) / total)
    return [round(max(0.0, (centre - radius) / denominator), 6),
            round(min(1.0, (centre + radius) / denominator), 6)]

def build_profile(observations: Iterable[Mapping[str, Any]], *, bins: int = DEFAULT_BINS,
                  min_samples: int = DEFAULT_MIN_SAMPLES) -> dict[str, Any]:
    """Build a content-addressed calibration profile from verified labels only."""
    if isinstance(bins, bool) or not 2 <= int(bins) <= 50:
        raise CalibrationError("bins must be between 2 and 50")
    if isinstance(min_samples, bool) or not 5 <= int(min_samples) <= 10_000:
        raise CalibrationError("min_samples must be between 5 and 10000")
    bins = int(bins); min_samples = int(min_samples)
    accepted: list[dict[str, Any]] = []
    observed = 0
    for observed, value in enumerate(observations, start=1):
        if observed > MAX_OBSERVATIONS:
            raise CalibrationError("calibration corpus exceeds the bounded observation limit")
        row = _normalise_observation(value)
        if row is not None:
            accepted.append(row)
    accepted.sort(key=lambda item: (
        item["dataset_id"], item["label_source"], item["rule"], item["language"],
        item["confidence"], item["outcome"]))
    groups: dict[str, list[dict[str, Any]]] = {}
    for row in accepted:
        if row["rule"]:
            groups.setdefault("rule:" + row["rule"], []).append(row)
        if row["rule"] and row["language"]:
            groups.setdefault("rule-language:" + row["rule"] + ":" + row["language"], []).append(row)
        if len(groups) > MAX_STRATA:
            raise CalibrationError("calibration corpus contains too many strata")
    body: dict[str, Any] = {
        "schema": SCHEMA, "version": VERSION,
        "policy": {"bins": bins, "min_samples_per_bin": min_samples,
                   "verified_labels_only": True,
                   "sparse_result": "unknown-no-score-replacement"},
        "corpus": {"observed": observed, "accepted": len(accepted),
                   "rejected": max(0, observed - len(accepted)),
                   "sha256": _sha(accepted),
                   "datasets": sorted({row["dataset_id"] for row in accepted}),
                   "label_sources": sorted({row["label_source"] for row in accepted})},
        "global": _metric_rows(accepted, bins, min_samples),
        "strata": {name: _metric_rows(rows, bins, min_samples)
                   for name, rows in sorted(groups.items())},
    }
    body["profile_sha256"] = _sha(body)
    return body

def calibrate_score(score: Any, profile: Mapping[str, Any] | None, *, rule: str = "",
                    language: str = "") -> dict[str, Any]:
    """Return empirical probability evidence, or explicitly abstain."""
    raw = _score(score)
    if raw is None:
        return {"state": "invalid-detector-score", "detector_score": None,
                "calibrated_probability": None, "interval_95": [0.0, 1.0],
                "samples": 0, "basis": "none"}
    valid, errors = verify_profile(profile) if profile is not None else (False, ["profile unavailable"])
    if not valid:
        return {"state": "uncalibrated", "detector_score": raw,
                "calibrated_probability": None, "interval_95": [0.0, 1.0],
                "samples": 0, "basis": "none", "errors": errors}
    if profile is None:  # defensive type/state guard; the invalid branch above normally returns
        raise CalibrationError("verified calibration profile disappeared")
    policy = profile["policy"]
    index = _bin_index(raw, policy["bins"])
    keys = []
    bounded_rule = _bounded_text(rule, 160)
    bounded_language = _bounded_text(language, 80).lower()
    if bounded_rule and bounded_language:
        keys.append("rule-language:" + bounded_rule + ":" + bounded_language)
    if bounded_rule:
        keys.append("rule:" + bounded_rule)
    candidates = [(key, profile.get("strata", {}).get(key)) for key in keys]
    candidates.append(("global", profile.get("global")))
    for basis, metrics in candidates:
        if type(metrics) is not dict or type(metrics.get("bins")) is not list \
                or index >= len(metrics["bins"]):
            continue
        bucket = metrics["bins"][index]
        if type(bucket) is dict and bucket.get("state") == "calibrated" \
                and _score(bucket.get("empirical_probability")) is not None:
            return {"state": "calibrated", "detector_score": raw,
                    "calibrated_probability": float(bucket["empirical_probability"]),
                    "interval_95": list(bucket["interval_95"]),
                    "samples": int(bucket["samples"]), "basis": basis,
                    "profile_sha256": profile["profile_sha256"]}
    return {"state": "insufficient-evidence", "detector_score": raw,
            "calibrated_probability": None, "interval_95": [0.0, 1.0],
            "samples": 0, "basis": "none", "profile_sha256": profile["profile_sha256"]}

def canonical_json(value: Any) -> str:
    """One byte-form per value, so digests are comparable across machines."""
    return json.dumps(value, sort_keys=True, separators=(",", ":"),
                      ensure_ascii=True, allow_nan=False)

def _redact(value: Any, key_hint: str = "") -> Any:
    """Drop secret-shaped evidence. A case file is meant to be shared."""
    if isinstance(value, Mapping):
        return {str(k): _redact(v, str(k)) for k, v in list(value.items())[:MAX_EVIDENCE_KEYS]}
    if isinstance(value, (list, tuple)):
        return [_redact(v, key_hint) for v in list(value)[:MAX_EVIDENCE_KEYS]]
    if isinstance(value, str):
        if _SECRET_KEY.search(key_hint) or _SECRET_VALUE.search(value):
            return REDACTED
        return value[:MAX_TEXT]
    if isinstance(value, bool) or value is None:
        return value
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if value != value or value in (float("inf"), float("-inf")):
            raise CaseFileError("evidence contains a non-finite number")
        return value
    raise CaseFileError("evidence value of type %s is not storable" % type(value).__name__)

def open_case(*, subject_path: str, subject_sha256: str, rule: str,
              summary: str, opened_by: str = "attestor",
              now: str | None = None) -> dict[str, Any]:
    """Start a case file for one finding, bound to the exact bytes it was found in."""
    case = {
        "schema": CASE_SCHEMA,
        "version": VERSION,
        "case_id": digest_json({
            "path": _text(subject_path, "subject_path"),
            "sha256": _digest(subject_sha256, "subject_sha256"),
            "rule": _identifier(rule, "rule"),
        })[:32],
        "subject": {
            "path": _text(subject_path, "subject_path"),
            "sha256": _digest(subject_sha256, "subject_sha256"),
        },
        "rule": _identifier(rule, "rule"),
        "summary": _text(summary, "summary"),
        "opened_by": _identifier(opened_by, "opened_by"),
        "opened_at": now or _utc_now(),
        "entries": [],
    }
    return case

def verify(case: Any) -> tuple[bool, list[str]]:
    """Re-derive the chain. Returns (ok, problems); never raises on hostile input."""
    problems: list[str] = []
    try:
        if not isinstance(case, Mapping) or case.get("schema") != CASE_SCHEMA:
            return False, ["not a case file"]
        entries = case.get("entries")
        if not isinstance(entries, list):
            return False, ["entries is not a list"]

        previous = GENESIS
        for position, entry in enumerate(entries):
            if not isinstance(entry, Mapping):
                problems.append("entry %d is not a mapping" % position)
                break
            if entry.get("index") != position:
                problems.append("entry %d has index %r" % (position, entry.get("index")))
            if entry.get("prev_sha256") != previous:
                problems.append("entry %d does not chain to its predecessor" % position)
            body = {k: v for k, v in entry.items() if k != "entry_sha256"}
            expected = _entry_digest(body, entry.get("prev_sha256", ""))
            if entry.get("entry_sha256") != expected:
                problems.append("entry %d digest does not match its content" % position)
            if entry.get("stage") == "regression" and \
                    (entry.get("evidence") or {}).get("fails_before_fix") is not True:
                problems.append("entry %d is a regression without a pre-fix failure" % position)
            previous = entry.get("entry_sha256", "")
        return (not problems), problems
    except Exception as exc:  # noqa: BLE001 - hostile input must not escape as a crash
        return False, ["verification failed closed (%s)" % type(exc).__name__]

def measured_only(case: Mapping[str, Any]) -> tuple[Mapping[str, Any], ...]:
    """The entries a conclusion may rest on. Hypotheses are excluded."""
    return tuple(e for e in (case.get("entries") or [])
                 if e.get("basis") == MEASURED)

def _canonical(value: Any) -> bytes:
    """Return bounded deterministic JSON using exact JSON container types."""
    pending: list[tuple[Any, int]] = [(value, 0)]
    nodes = 0
    estimated = 0
    while pending:
        current, depth = pending.pop()
        nodes += 1
        if nodes > MAX_JSON_NODES or depth > MAX_JSON_DEPTH:
            raise AuthorizationError(
                "authorization evidence exceeds the structure boundary")
        if current is None or type(current) is bool:
            estimated += 5
        elif type(current) is int:
            if not -(2 ** 63) <= current <= 2 ** 63 - 1:
                raise AuthorizationError(
                    "authorization evidence integer is outside the boundary")
            estimated += 24
        elif type(current) is str:
            size = len(current.encode("utf-8"))
            if size > MAX_TEXT_BYTES:
                raise AuthorizationError(
                    "authorization evidence text is outside the boundary")
            estimated += size + 3
        elif type(current) is list:
            if len(current) > MAX_JSON_NODES:
                raise AuthorizationError(
                    "authorization evidence collection is outside the boundary")
            estimated += len(current) + 2
            pending.extend((item, depth + 1) for item in current)
        elif type(current) is dict:
            if len(current) > MAX_JSON_NODES:
                raise AuthorizationError(
                    "authorization evidence collection is outside the boundary")
            estimated += len(current) + 2
            for key, item in current.items():
                if type(key) is not str:
                    raise AuthorizationError(
                        "authorization evidence keys must be text")
                key_size = len(key.encode("utf-8"))
                if key_size > MAX_TEXT_BYTES:
                    raise AuthorizationError(
                        "authorization evidence key is outside the boundary")
                estimated += key_size + 3
                pending.append((item, depth + 1))
        else:
            raise AuthorizationError(
                "authorization evidence contains a non-JSON value")
        if estimated > MAX_MANIFEST_BYTES:
            raise AuthorizationError(
                "authorization evidence exceeds the byte boundary")
    try:
        encoded = json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False,
        ).encode("utf-8")
    except (TypeError, ValueError, OverflowError, RecursionError) as exc:
        raise AuthorizationError(
            "authorization evidence is not deterministic JSON") from exc
    if len(encoded) > MAX_MANIFEST_BYTES:
        raise AuthorizationError(
            "authorization evidence exceeds the byte boundary")
    return encoded

def operation_sha256(operation: Any) -> str:
    """Return the digest callers bind to one exact bounded operation plan."""
    return _sha_json(operation)

def _is_local_fixed_root(path: Path) -> bool:
    """Reject UNC, mapped-network, removable, and unknown Windows roots."""
    spelling = os.fspath(path)
    if _looks_network_spelled(spelling):
        return False
    if os.name != "nt":
        # The portable standard library cannot reliably classify a POSIX
        # mount as local or remote.  This module grants no network operation;
        # callers must not present a remote mount as a local enterprise root.
        return True
    anchor = path.anchor
    if not anchor or _looks_network_spelled(anchor):
        return False
    try:
        import ctypes
        # DRIVE_FIXED == 3.  Mapped network, removable, optical, RAM-disk,
        # unknown, and unavailable roots are denied.
        return int(ctypes.windll.kernel32.GetDriveTypeW(anchor)) == 3
    except (AttributeError, OSError, TypeError, ValueError):
        return False

def denied_status() -> dict[str, Any]:
    """Return the default state without inspecting any path."""
    slug, identity = _profile()
    body = {
        "schema": DENIED_SCHEMA,
        "version": VERSION,
        "status": "authorization-required",
        "authorized": False,
        "profile": {
            "slug": slug,
            "profile_sha256": identity,
        },
        "allowed_actions": list(ACTION_ORDER),
        "defaults": {
            "apply": False,
            "dry_run": True,
            "network": False,
            "permission_persistence": False,
        },
    }
    body["status_sha256"] = _sha_json(body)
    return body

def _json_depth(text: str) -> int:
    """The deepest bracket nesting in `text`, ignoring brackets in strings.

    A single pass, no recursion, so the answer does not depend on the
    interpreter's stack. Brackets inside string literals are not structure --
    ``{"a": "[[[["}`` is depth one -- so the scanner tracks whether it is
    inside a string and honours backslash escapes. Anything malformed is left
    for ``json.loads`` to reject; this only counts.
    """
    depth = maximum = 0
    in_string = escaped = False
    for character in text:
        if in_string:
            if escaped:
                escaped = False
            elif character == "\\":
                escaped = True
            elif character == '"':
                in_string = False
            continue
        if character == '"':
            in_string = True
        elif character in "[{":
            depth += 1
            if depth > maximum:
                maximum = depth
        elif character in "]}":
            depth -= 1
    return maximum

def _normalize(src: str) -> list:
    """(original_lineno, normalized_text) for code lines; blanks/comments dropped."""
    out = []
    for idx, raw in enumerate(src.splitlines(), start=1):
        stripped = raw.strip()
        if not stripped or stripped.startswith("#"):
            continue
        out.append((idx, re.sub(r"\s+", " ", stripped)))
    return out

def _seed_windows(index: dict, size: int) -> dict:
    """hash -> [(path, window_start_index), ...] over every N-line window."""
    seeds = {}
    for path, lines in index.items():
        for i in range(len(lines) - size + 1):
            seeds.setdefault(_hash(_window_text(lines, i, size)), []).append((path, i))
    return seeds

#!/usr/bin/env python3
"""
clones.py -- find copy-pasted code (duplication), deterministically.

Duplicated blocks are where bugs breed: you fix one copy and forget the other.
This finds them with no compiler and no heuristics you have to trust. It strips
blank lines and comments, normalises whitespace, hashes every window of N code
lines, and wherever a window recurs it grows the match line-by-line into the whole
duplicated block. It then reports each clone as a pair of locations with its size.

Type-1 duplication (identical modulo layout and comments). It reads only -- never
executes or edits. Exit code = number of clone blocks found, so CI can gate on it.

    clones.py src/                       # duplicated blocks across a tree
    clones.py a.py b.py --min-lines 8    # only clones of 8+ lines
    clones.py src/ --json                # machine-readable
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import sys
from dataclasses import asdict, dataclass

SKIP_DIRS = {".git", ".hg", ".svn", "__pycache__", "build", "dist", "node_modules"}
DEFAULT_MIN_LINES = 6


@dataclass
class Clone:
    lines: int
    blocks: list           # [(path, start_line, end_line), ...]


def _read(path: str) -> str:
    try:
        with open(path, encoding="utf-8", errors="replace") as fh:
            return fh.read()
    except OSError:
        return ""


def _normalize(src: str) -> list:
    """(original_lineno, normalized_text) for code lines; blanks/comments dropped."""
    out = []
    for idx, raw in enumerate(src.splitlines(), start=1):
        stripped = raw.strip()
        if not stripped or stripped.startswith("#"):
            continue
        out.append((idx, re.sub(r"\s+", " ", stripped)))
    return out


def _hash(text: str) -> str:
    return hashlib.blake2b(text.encode("utf-8"), digest_size=16).hexdigest()


def _window_text(lines: list, start: int, size: int) -> str:
    return "\n".join(text for _lineno, text in lines[start:start + size])


def _seed_windows(index: dict, size: int) -> dict:
    """hash -> [(path, window_start_index), ...] over every N-line window."""
    seeds = {}
    for path, lines in index.items():
        for i in range(len(lines) - size + 1):
            seeds.setdefault(_hash(_window_text(lines, i, size)), []).append((path, i))
    return seeds


def _extend(a: list, ai: int, b: list, bi: int) -> int:
    """How many consecutive normalized lines match starting at a[ai] / b[bi]."""
    length = 0
    while (ai + length < len(a) and bi + length < len(b)
           and a[ai + length][1] == b[bi + length][1]):
        length += 1
    return length


def _partner(group: list, path: str, i: int, consumed: set):
    for cand_path, cand_i in group:
        if (cand_path, cand_i) != (path, i) and (cand_path, cand_i) not in consumed:
            return cand_path, cand_i
    return None


def _consume(consumed: set, path: str, start: int, length: int) -> None:
    for k in range(length):
        consumed.add((path, start + k))


def _block(index: dict, path: str, start: int, length: int) -> tuple:
    lines = index[path]
    return path, lines[start][0], lines[start + length - 1][0]


def find_clones(paths, min_lines: int = DEFAULT_MIN_LINES) -> list:
    index = {path: _normalize(_read(path)) for path in collect_paths(paths)}
    seeds = _seed_windows(index, min_lines)
    consumed = set()
    clones = []
    positions = sorted((path, i) for path, lines in index.items()
                       for i in range(max(0, len(lines) - min_lines + 1)))
    for path, i in positions:
        if (path, i) in consumed:
            continue
        group = seeds.get(_hash(_window_text(index[path], i, min_lines)), [])
        partner = _partner(group, path, i, consumed)
        if partner is None:
            continue
        other_path, other_i = partner
        length = _extend(index[path], i, index[other_path], other_i)
        clones.append(Clone(length, [_block(index, path, i, length),
                                     _block(index, other_path, other_i, length)]))
        _consume(consumed, path, i, length)
        _consume(consumed, other_path, other_i, length)
    clones.sort(key=lambda clone: clone.lines, reverse=True)
    return clones


def collect_paths(paths) -> list:
    out = []
    for raw in paths:
        if os.path.isdir(raw):
            for root, dirs, files in os.walk(raw):
                dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
                out += [os.path.join(root, f) for f in sorted(files) if f.endswith(".py")]
        elif raw.endswith(".py") or os.path.isfile(raw):
            out.append(raw)
    return out


def render(clones: list) -> str:
    if not clones:
        return "no duplicated blocks found. clean."
    total = sum(clone.lines for clone in clones)
    lines = ["%d clone block(s), %d duplicated lines" % (len(clones), total), "=" * 60]
    for clone in clones:
        where = "   <->   ".join("%s:%d-%d" % (p, s, e) for p, s, e in clone.blocks)
        lines.append("%d lines:  %s" % (clone.lines, where))
    return "\n".join(lines)


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("paths", nargs="+", help="Python files or directories")
    ap.add_argument("--min-lines", type=int, default=DEFAULT_MIN_LINES,
                    help="shortest duplicated block to report (default 6)")
    ap.add_argument("--json", action="store_true", help="machine-readable output")
    args = ap.parse_args(argv)

    clones = find_clones(args.paths, max(1, args.min_lines))
    if args.json:
        print(json.dumps([asdict(clone) for clone in clones], indent=2))
    else:
        print(render(clones))
    return min(len(clones), 250)


if __name__ == "__main__":
    sys.exit(main())

def run_scaffolding():
    """Score 1 only if the generated service compiles AND both engines find it
    clean -- the guarantee that makes his scaffolding worth something."""
    files = codegen.generate(codegen.DEFAULT_SPEC)
    try:
        for rel, content in files.items():
            if rel.endswith(".py"):
                compile(content, rel, "exec")
    except SyntaxError:
        return 0, 1

    regex_findings = 0
    with tempfile.TemporaryDirectory() as tmp:
        codegen.write_files(files, tmp, force=True)
        for path in detect.collect_paths([tmp]):
            regex_findings += len(detect.scan_file(path))
    ast_findings = sum(len(deepscan.analyze(c, r))
                       for r, c in files.items() if r.endswith(".py"))
    clean = regex_findings == 0 and ast_findings == 0
    return (1 if clean else 0), 1

def _normalized_identifier(value: str) -> str:
    """Return the filesystem/SQLite collision form used for spec validation."""
    return unicodedata.normalize("NFKC", value).casefold()

def validate_spec(spec: dict) -> None:
    """Fail fast, in plain English, instead of tracebacking mid-generation."""
    resources = spec.get("resources") if isinstance(spec, dict) else None
    if not isinstance(resources, list) or not resources:
        raise ValueError('spec needs a non-empty "resources" list, e.g. '
                         '{"resources": [{"name": "User", "fields": {"name": "str"}}]}')
    seen_resources = {}
    for res in resources:
        name = res.get("name") if isinstance(res, dict) else None
        if not isinstance(name, str) or not name.isidentifier() or not name[0].isalpha():
            raise ValueError(f"resource name {name!r} must be a valid identifier "
                             "starting with a letter (it becomes class/module names)")
        if keyword.iskeyword(name) or keyword.iskeyword(name.lower()):
            raise ValueError(f"resource name {name!r} is a Python keyword")
        normalized_name = _normalized_identifier(name)
        if normalized_name in _RESERVED_RESOURCE_NAMES:
            raise ValueError(
                f"resource name {name!r} is reserved by the built-in accounts subsystem")
        previous = seen_resources.get(normalized_name)
        if previous is not None:
            raise ValueError(
                f"resource names {previous!r} and {name!r} normalize to the same name")
        seen_resources[normalized_name] = name
        fields = res.get("fields")
        if not isinstance(fields, dict) or not fields:
            raise ValueError(f"resource {name!r} needs a non-empty 'fields' dict")
        seen_fields = {}
        for fn, ft in fields.items():
            if not isinstance(fn, str) or not fn.isidentifier():
                raise ValueError(f"{name}.{fn!r} is not a valid field name")
            if keyword.iskeyword(fn):
                raise ValueError(f"{name}.{fn!r} is a Python keyword")
            normalized_field = _normalized_identifier(fn)
            reserved_for = _RESERVED_FIELD_NAMES.get(normalized_field)
            if reserved_for is not None:
                raise ValueError(
                    f"{name}.{fn!r} is reserved for {reserved_for}")
            previous_field = seen_fields.get(normalized_field)
            if previous_field is not None:
                raise ValueError(
                    f"fields {name}.{previous_field!r} and {name}.{fn!r} "
                    "normalize to the same name")
            seen_fields[normalized_field] = fn
            if not isinstance(ft, str) or ft not in TYPE_PY:
                raise ValueError(f"{name}.{fn}: unknown type {ft!r} "
                                 f"(supported: {', '.join(sorted(TYPE_PY))})")

def big_spec(n: int) -> dict:
    """Build a spec of N standard resources -- a simple way to dial the line
    count. The fixed infrastructure is written once; each resource adds ~425
    lines, so N=20 lands around 10k."""
    if isinstance(n, bool) or not isinstance(n, int) or n < 1:
        raise ValueError("resource count must be a positive integer")
    resources = [{"name": "Entity%d" % i,
                  "fields": dict(_FIELD_SETS[i % len(_FIELD_SETS)])}
                 for i in range(1, n + 1)]
    return {"resources": resources}

def _generated_inventory(target: str) -> frozenset[str]:
    """Return the exact prior generated-file inventory, or an empty set.

    Common filenames are not provenance: ordinary Python services routinely
    contain ``app.py``, ``config.py`` and a Makefile.  The marker lets --force
    remove obsolete files Attestor actually generated while protecting databases,
    logs and user additions even inside a generated project.
    """
    marker = os.path.join(target, _GENERATION_MARKER)
    if _is_link_or_junction(marker) or not os.path.isfile(marker):
        return frozenset()
    try:
        if os.path.getsize(marker) > 512 * 1024:
            return frozenset()
        with open(marker, encoding="utf-8") as handle:
            value = json.load(handle)
    except (OSError, UnicodeError, ValueError, TypeError):
        return frozenset()
    if (not isinstance(value, dict)
            or value.get("schema") != _GENERATION_SCHEMA
            or value.get("generator_version") != GENERATED_VERSION
            or not isinstance(value.get("paths"), list)
            or len(value["paths"]) > _MAX_GENERATED_PATHS):
        return frozenset()
    paths = set()
    for relative in value["paths"]:
        if not isinstance(relative, str) or not relative:
            return frozenset()
        normalized = os.path.normpath(relative)
        if (os.path.isabs(relative) or normalized in {"", ".", ".."}
                or normalized.startswith(".." + os.sep)):
            return frozenset()
        paths.add(normalized.replace(os.sep, "/"))
    paths.add(_GENERATION_MARKER)
    return frozenset(paths)

def _unplanned_entries(target: str, planned,
                       prior_generated=frozenset()) -> list:
    """Files in the output directory that this run would not rewrite.

    Only consulted when the directory is *not* recognisably a previous
    generation.  Anything this returns is content the caller would lose
    silently, so it is worth naming before the delete rather than after it.
    """
    expected = {os.path.normcase(path) for path in planned}
    unexpected = []
    for root, dirs, names in os.walk(target):
        dirs[:] = [name for name in dirs if name not in _DERIVED_DIRS]
        for name in names:
            full = os.path.join(root, name)
            if os.path.normcase(full) in expected:
                continue
            relative = os.path.relpath(full, target).replace(os.sep, "/")
            if relative in prior_generated:
                continue
            if name.endswith(_DERIVED_SUFFIXES):
                continue
            unexpected.append(relative)
            if len(unexpected) > 64:
                return sorted(unexpected)
    return sorted(unexpected)

def _clean_output_dir(out_dir: str) -> None:
    """Remove an output directory's contents without following a target symlink."""
    target = os.path.abspath(out_dir)
    resolved = os.path.realpath(target)
    root = os.path.abspath(os.path.join(target, os.pardir))
    while os.path.abspath(os.path.join(root, os.pardir)) != root:
        root = os.path.abspath(os.path.join(root, os.pardir))
    cwd = os.path.realpath(os.getcwd())
    home = os.path.realpath(os.path.expanduser("~"))
    try:
        contains_cwd = os.path.commonpath((resolved, cwd)) == resolved
    except ValueError:
        contains_cwd = False
    if resolved in {root, home} or contains_cwd:
        raise SystemExit(f"refusing to clean unsafe output directory: {out_dir}")
    if _is_link_or_junction(target):
        raise SystemExit(f"refusing to clean linked output directory: {out_dir}")
    for entry in os.scandir(target):
        if entry.is_dir(follow_symlinks=False):
            shutil.rmtree(entry.path)
        else:
            os.unlink(entry.path)

def check_generated(out_dir: str, timeout: int = 180) -> bool:
    """Compile, test, and scan a generated project; return whether every gate passed."""
    ok = True
    python_files = []
    for root, dirs, names in os.walk(out_dir):
        dirs[:] = sorted(d for d in dirs if d != "__pycache__")
        python_files.extend(
            os.path.join(root, name) for name in sorted(names) if name.endswith(".py"))

    compile_failures = []
    sources = {}
    for path in python_files:
        try:
            with open(path, encoding="utf-8") as fh:
                source = fh.read()
            sources[path] = source
            compile(source, path, "exec")
        except (OSError, SyntaxError) as exc:
            compile_failures.append((path, exc))
    if compile_failures:
        ok = False
        print(f"[check] compile failed for {len(compile_failures)} file(s).")
        for path, exc in compile_failures:
            print(f"  {os.path.relpath(path, out_dir)}: {exc}")
    else:
        print(f"[check] compiled {len(python_files)} Python files.")

    try:
        result = subprocess.run(
            [sys.executable, "-m", "unittest", "discover", "-s", "tests", "-v"],
            cwd=out_dir, capture_output=True, text=True, timeout=timeout)
    except (OSError, subprocess.TimeoutExpired) as exc:
        ok = False
        print(f"[check] generated tests could not complete: {exc}")
    else:
        if result.returncode:
            ok = False
            output = (result.stdout + "\n" + result.stderr).strip()
            print(f"[check] generated tests failed (exit {result.returncode}).")
            if output:
                print(output[-4000:])
        else:
            print("[check] generated tests passed.")

    try:
        import deepscan
        import detect
    except ImportError as exc:
        print(f"[check] Attestor scanners are unavailable: {exc}")
        return False

    findings = []
    for path in detect.collect_paths([out_dir]):
        findings += detect.scan_file(path)
    deep_findings = []
    for path, source in sources.items():
        deep_findings += deepscan.analyze(source, path)
    if findings or deep_findings:
        ok = False
    print(f"[check] detector: {len(findings)} finding(s); "
          f"deepscan: {len(deep_findings)} finding(s).")
    for finding in findings + deep_findings:
        print(f"  {os.path.relpath(finding.path)}:{finding.line} "
              f"[{finding.severity}] {finding.rule}")
    return ok

def _read(path: str) -> tuple[str | None, str]:
    """Read UTF-8-ish source and return either text or a compact error string."""
    try:
        with open(path, encoding="utf-8", errors="replace") as handle:
            return handle.read(), ""
    except OSError as exc:
        return None, "%s: %s" % (type(exc).__name__, exc)

def _parse(source: str) -> tuple[ast.Module | None, SyntaxError | None]:
    """Parse Python source without throwing; callers render syntax failures."""
    try:
        return ast.parse(source), None
    except SyntaxError as exc:
        return None, exc

def _unparse(node: ast.AST) -> str:
    """Best-effort AST rendering for bases and annotations."""
    try:
        return ast.unparse(node)
    except Exception:
        return "..."

def _arg_nodes(node: ast.AST) -> list:
    """Return every explicit parameter node for a function-like AST node."""
    args = node.args
    out = list(args.posonlyargs) + list(args.args) + list(args.kwonlyargs)
    if args.vararg:
        out.append(args.vararg)
    if args.kwarg:
        out.append(args.kwarg)
    return out

def api_surface(source: str, path: str = "<code>") -> list[dict]:
    """List top-level classes/functions and first-level class methods."""
    tree, error = _parse(source)
    if error is not None:
        return [{"kind": "syntax", "name": "<parse error>", "line": error.lineno or 1,
                 "message": error.msg, "args": 0, "typed_args": 0,
                 "has_return": False, "has_doc": False, "async": False}]
    entries: list[dict] = []
    for node in tree.body:
        if isinstance(node, ast.ClassDef):
            methods = [item for item in node.body if isinstance(item, _DEF)]
            entries.append({
                "kind": "class",
                "name": node.name,
                "line": node.lineno,
                "methods": len(methods),
                "bases": ", ".join(_unparse(base) for base in node.bases),
                "has_doc": bool(ast.get_docstring(node)),
            })
            for item in methods:
                entries.append(_surface_entry("method", item, node.name))
        elif isinstance(node, _DEF):
            entries.append(_surface_entry("function", node))
    return entries[:MAX_SURFACE]

def _function_nodes(tree: ast.Module) -> list[tuple[str, ast.AST]]:
    """Return top-level functions and class methods for direct call mapping."""
    out = []
    for node in tree.body:
        if isinstance(node, ast.ClassDef):
            for item in node.body:
                if isinstance(item, _DEF):
                    out.append(("%s.%s" % (node.name, item.name), item))
        elif isinstance(node, _DEF):
            out.append((node.name, node))
    return out

def call_graph(source: str) -> list[tuple[str, str]]:
    """Return direct calls between functions/methods defined in the same module."""
    tree, error = _parse(source)
    if error is not None:
        return []
    functions = _function_nodes(tree)
    known = {name.split(".")[-1] for name, _ in functions}
    edges = []
    seen = set()
    for caller, node in functions:
        for child in ast.walk(node):
            if not isinstance(child, ast.Call):
                continue
            callee = ""
            if isinstance(child.func, ast.Name):
                callee = child.func.id
            elif isinstance(child.func, ast.Attribute):
                callee = child.func.attr
            edge = (caller, callee)
            if callee in known and callee != caller.split(".")[-1] and edge not in seen:
                seen.add(edge)
                edges.append(edge)
    return edges[:MAX_EDGES]

def _test_name(name: str) -> str:
    """Make a public symbol safe for use inside a generated unittest method."""
    clean = re.sub(r"[^0-9A-Za-z_]+", "_", name).strip("_").lower()
    if not clean or clean[0].isdigit():
        clean = "symbol_" + clean
    return clean

def test_skeleton(path: str, source: str) -> str:
    """Build a small unittest import skeleton for public module symbols."""
    module = _module_name(path)
    if not module:
        return "# Cannot build an import skeleton: module filename is not importable."
    tree, error = _parse(source)
    if error is not None:
        return "# Cannot build tests until the syntax error on line %s is fixed." % (error.lineno or 1)
    names = []
    for node in tree.body:
        if isinstance(node, (ast.ClassDef,) + _DEF) and not node.name.startswith("_"):
            names.append(node.name)
    lines = ["import unittest", "import %s as target" % module, "",
             "class GeneratedSmokeTests(unittest.TestCase):"]
    if not names:
        lines += [
            "    def test_module_imports(self):",
            "        self.assertIsNotNone(target)",
            "",
        ]
    for name in names[:MAX_TEST_ITEMS]:
        lines += [
            "    def test_%s_exists(self):" % _test_name(name),
            "        self.assertTrue(callable(target.%s))" % name,
            "",
        ]
    lines += ['if __name__ == "__main__":', "    unittest.main()"]
    return "\n".join(lines)

def _format_class_entry(item: dict) -> str:
    """Render one class row for the public API section."""
    base = " bases: " + item["bases"] if item.get("bases") else ""
    doc = "doc" if item.get("has_doc") else "no-doc"
    return "  class %s line %d, %d method(s), %s%s" % (
        item["name"], item["line"], item.get("methods", 0), doc, base)

def _format_syntax_entry(item: dict) -> str:
    """Render a syntax-error row in the public API section."""
    return "  syntax error line %d: %s" % (item["line"], item.get("message", ""))

def _render_surface(entries: list[dict]) -> list[str]:
    """Render API rows without burying presentation branching in the report body."""
    if not entries:
        return ["  no top-level functions/classes found."]
    renderers = {"class": _format_class_entry, "syntax": _format_syntax_entry}
    return [renderers.get(item["kind"], _format_callable_entry)(item) for item in entries]

def _render_calls(edges: list[tuple[str, str]]) -> list[str]:
    """Render direct call graph edges, including the empty graph case."""
    if not edges:
        return ["  no direct in-module calls between public functions/methods found."]
    return ["  %s -> %s" % (caller, callee) for caller, callee in edges]

def _entry_gaps(item: dict) -> list[str]:
    """Return docstring/type gaps for one API row."""
    if item["kind"] == "class":
        return [] if item.get("has_doc") else ["add a docstring to class %s" % item["name"]]
    if item["kind"] not in ("function", "method"):
        return []
    gaps = []
    if item["args"] and item["typed_args"] < item["args"]:
        gaps.append("type %s remaining parameter(s) on %s" % (
            item["args"] - item["typed_args"], item["name"]))
    if not item["has_return"]:
        gaps.append("add a return annotation to %s" % item["name"])
    if not item["has_doc"]:
        gaps.append("add a short behavior docstring to %s" % item["name"])
    return gaps

def _metric_gaps(funcs: list) -> list[str]:
    """Return complexity-driven split/simplify guidance."""
    ranked = sorted(funcs, key=lambda metric: metric.cognitive, reverse=True)
    return ["split or simplify %s around line %d" % (item.qualname, item.line)
            for item in ranked if item.exceeded(metrics.DEFAULT_LIMITS)]

def _grade_line(file_grade: grade.FileGrade) -> str:
    """Compress a FileGrade into one report line."""
    return "%s %d/100, %d high, %d medium, %d low, %d/%d over threshold" % (
        file_grade.grade, file_grade.score, file_grade.findings_high,
        file_grade.findings_medium, file_grade.findings_low,
        file_grade.over_threshold, file_grade.functions)

def run(target: str, bus: object | None = None, rounds: int = DEFAULT_PASSES) -> tuple[str, int]:
    """Dispatch a file, directory, or prompt through Code Max."""
    target = (target or "").strip()
    if not target:
        return "Code Max needs a Python file, folder, or coding request.", 2
    if os.path.isdir(target):
        return _review_directory(target, rounds=min(rounds, 50))
    if os.path.exists(target):
        return _review_file(target, rounds=min(rounds, DEFAULT_PASSES), include_refined=True)
    text, code = sieve.run(target, bus=bus, rounds=rounds)
    header = [
        "Code Max prompt pipeline",
        "=" * 72,
        "request: " + target,
        "route: Sieve write/review/improve loop",
        "",
    ]
    return "\n".join(header) + text, code

def architect(files: list[str], root: str) -> list[str]:
    """Describe the project shape and likely layering pressure."""
    buckets = {"interface": 0, "domain": 0, "data": 0, "tests": 0, "tools": 0}
    imports = {}
    for path in files:
        rel = os.path.relpath(path, root if os.path.isdir(root) else os.path.dirname(path))
        low = rel.lower()
        if any(word in low for word in ("route", "view", "api", "controller")):
            buckets["interface"] += 1
        elif any(word in low for word in ("model", "schema", "db", "repo", "storage")):
            buckets["data"] += 1
        elif any(word in low for word in ("service", "core", "domain", "logic")):
            buckets["domain"] += 1
        elif "test" in low:
            buckets["tests"] += 1
        else:
            buckets["tools"] += 1
        tree, error = _parse(_read(path))
        if error is not None:
            continue
        imports[rel] = sum(1 for node in ast.walk(tree)
                           if isinstance(node, (ast.Import, ast.ImportFrom)))
    lines = ["files by layer: " + ", ".join("%s=%d" % item for item in buckets.items())]
    if buckets["tests"] == 0:
        lines.append("add a tests layer; no test-like Python files were found.")
    crowded = sorted(imports.items(), key=lambda item: item[1], reverse=True)[:5]
    if crowded:
        lines.append("highest import pressure: " + "; ".join("%s=%d" % item for item in crowded))
    return lines

def type_maximizer(files: list[str]) -> list[str]:
    """Find missing parameter and return annotations."""
    gaps = []
    for path in files:
        for item in codemax.api_surface(_read(path), path):
            if item["kind"] not in ("function", "method"):
                continue
            if item["args"] and item["typed_args"] < item["args"]:
                gaps.append("%s:%d type %d parameter(s) on %s" % (
                    path, item["line"], item["args"] - item["typed_args"], item["name"]))
            if not item["has_return"]:
                gaps.append("%s:%d add return annotation to %s" % (
                    path, item["line"], item["name"]))
    return gaps[:MAX_ITEMS] or ["all public callables inspected have complete annotations."]

def api_designer(files: list[str]) -> list[str]:
    """Review public functions/classes for ergonomics and compatibility risk."""
    out = []
    for path in files:
        for item in codemax.api_surface(_read(path), path):
            if item["kind"] not in ("function", "method", "class"):
                continue
            if item.get("args", 0) >= 5:
                out.append("%s:%d %s has many parameters; consider an options object." % (
                    path, item["line"], item["name"]))
            if not item.get("has_doc"):
                out.append("%s:%d document behavior and edge cases for %s." % (
                    path, item["line"], item["name"]))
    return out[:MAX_ITEMS] or ["public API shape looks compact from this pass."]

def migration_assistant(files: list[str]) -> list[str]:
    """Suggest modern Python cleanup opportunities."""
    out = []
    for path in files:
        for no, line in enumerate(_read(path).splitlines(), start=1):
            if re.search(r"typing\.(List|Dict|Tuple|Set)\b", line):
                out.append("%s:%d use built-in collection generics on Python 3.9+." % (path, no))
            if re.search(r"['\"][^'\"]*%[sdfr][^'\"]*['\"]\s*%", line):
                out.append("%s:%d consider f-strings or format for clearer interpolation." % (path, no))
            if "unittest.TestCase" not in line and re.search(r"\bsuper\([^)]*,\s*self\)", line):
                out.append("%s:%d use zero-argument super() on modern Python." % (path, no))
    return out[:MAX_ITEMS] or ["no obvious migration cleanup items found."]

def bug_oracle(files: list[str]) -> list[str]:
    """Combine semantic findings with risk-shape predictions."""
    out = []
    for path in files:
        source = _read(path)
        findings = deepscan.analyze(source, path)
        for finding in findings[:5]:
            out.append("%s:%d [%s] %s -> %s" % (
                path, finding.line, finding.severity, finding.rule, finding.fix))
        fg, _findings, funcs = grade.grade_source(source, path, metrics.DEFAULT_LIMITS)
        if fg.score < 90:
            out.append("%s code-health prediction: %s %d/100; review before extending." % (
                path, fg.grade, fg.score))
        if any(item.cognitive >= 10 for item in funcs):
            out.append("%s future-bug risk: high cognitive complexity concentrates defects." % path)
    return out[:MAX_ITEMS] or ["no semantic findings or strong risk-shapes found."]

def code_contracts(files: list[str]) -> list[str]:
    """Infer lightweight pre/postcondition ideas from function signatures."""
    out = []
    for path in files:
        tree, error = _parse(_read(path))
        if error is not None:
            continue
        for node in ast.walk(tree):
            if not isinstance(node, _DEF):
                continue
            args = [arg.arg for arg in node.args.args if arg.arg != "self"]
            hints = []
            for arg in args:
                low = arg.lower()
                if any(word in low for word in ("path", "file", "dir")):
                    hints.append("%s exists or is intentionally creatable" % arg)
                if any(word in low for word in ("items", "values", "nums", "rows")):
                    hints.append("%s is iterable and not mutated unexpectedly" % arg)
                if any(word in low for word in ("count", "limit", "size", "index")):
                    hints.append("%s is non-negative" % arg)
            if hints:
                out.append("%s:%d %s preconditions: %s" % (
                    path, node.lineno, node.name, "; ".join(hints)))
    return out[:MAX_ITEMS] or ["no obvious contract candidates inferred."]

def dead_code_surgeon(files: list[str]) -> list[str]:
    """Find conservative dead-code candidates inside each module."""
    out = []
    for path in files:
        tree, error = _parse(_read(path))
        if error is not None:
            continue
        defs = {node.name: node for node in ast.walk(tree) if isinstance(node, _DEF)}
        calls = {_call_name(node.func).rsplit(".", 1)[-1]
                 for node in ast.walk(tree) if isinstance(node, ast.Call)}
        for name, node in sorted(defs.items()):
            if name.startswith("_") or name in ("main", "run") or name.startswith("test_"):
                continue
            if name not in calls:
                out.append("%s:%d %s is not called in its own module; verify external use." % (
                    path, node.lineno, name))
    return out[:MAX_ITEMS] or ["no conservative dead-code candidates found."]

def patch_ranker(files: list[str]) -> list[str]:
    """Rank fix opportunities by severity, safety, and maintainability payoff."""
    ranked = []
    for path in files:
        source = _read(path)
        _fg, findings, funcs = grade.grade_source(source, path, metrics.DEFAULT_LIMITS)
        for tip in grade.improvements(findings, funcs, metrics.DEFAULT_LIMITS, top=6):
            score = 50
            if "[HIGH]" in tip:
                score += 30
            if "split" in tip:
                score += 10
            ranked.append((score, tip))
    ranked.sort(reverse=True)
    return ["score %d: %s" % item for item in ranked[:MAX_ITEMS]] or \
        ["no ranked patch opportunities from current findings."]

def self_evolution_log() -> list[str]:
    """Summarize repeated repair memory if Attestor has learned any local patterns."""
    memory = fixmemory.load()
    patterns = memory.get("patterns", {})
    if not patterns:
        return ["no repeated repair patterns recorded yet."]
    ranked = sorted(patterns.values(), key=lambda item: item.get("count", 0), reverse=True)
    return ["%s x%d promoted=%s" % (
        item.get("rule", "unknown"), item.get("count", 0), item.get("promoted", False))
        for item in ranked[:MAX_ITEMS]]

def review_duel(files: list[str]) -> list[str]:
    """Run multiple review lenses and summarize their verdicts."""
    sections = {
        "correctness": bug_oracle(files)[:3],
        "security": ["run Security Max for full defensive review"],
        "performance": performance_lens(files)[:3],
        "maintainability": refactor_planner(files)[:3],
        "tests": test_smith(files)[:5],
    }
    out = []
    for name, items in sections.items():
        out.append(name + ": " + (items[0] if items else "clear"))
    return out

def contract(request: str) -> dict:
    """Build a deterministic coding contract for a request."""
    words = _words(request)
    rules = list(BASE_RULES) + list(MAXIMUM_CODING_RULES)
    if words.intersection(_DATA_WORDS):
        rules.extend(DATA_STRUCTURE_RULES)
    if words.intersection(_SERVICE_WORDS):
        rules.extend(SERVICE_RULES)
    else:
        rules.extend(ALGORITHM_RULES)
    return {
        "request": request,
        "rules": rules,
        "acceptance": [
            "imports without crashing",
            "passes Attestor static checks",
            "passes the request-aware smoke test when one exists",
            "keeps the public API small and obvious",
            "handles the edge cases listed in Attestor's power plan",
        ],
    }

def power_plan(request: str) -> dict:
    """Return a compact build plan used to push models toward better code."""
    words = _words(request)
    edge_cases = ["empty input", "single item", "duplicates", "invalid type"]
    if words.intersection(_GRAPH_WORDS):
        edge_cases.extend(["disconnected graph", "cycle where invalid", "missing start node"])
    if words.intersection(_STRING_WORDS):
        edge_cases.extend(["empty string", "mixed case", "punctuation"])
    if words.intersection(_DATA_WORDS):
        edge_cases.extend(["empty container", "missing key", "capacity boundary"])
    return {
        "phases": [
            "name the public API",
            "choose the simplest correct algorithm",
            "handle edge cases before optimization",
            "keep implementation deterministic",
            "make the code easy for Attestor's crucible to import and test",
        ],
        "edge_cases": edge_cases,
    }

def _path_is_local_fixed(path: Path) -> bool:
    """Reject Windows UNC, mapped-network, and removable-backed paths."""
    if os.name != "nt":
        return True
    anchor = path.anchor
    if not anchor or anchor.startswith("\\\\"):
        return False
    try:
        import ctypes
        return int(ctypes.windll.kernel32.GetDriveTypeW(anchor)) == 3
    except (AttributeError, OSError, TypeError, ValueError):
        return False

def _fixed_drive_roots() -> tuple[list[Path], list[str]]:
    """Return local fixed drives only; never removable or network drives."""
    if os.name != "nt":
        return [Path(os.path.abspath(os.sep))], [
            "portable fixed-drive enumeration covers only the primary filesystem root"
        ]
    try:
        import ctypes
        kernel32 = ctypes.windll.kernel32
        mask = int(kernel32.GetLogicalDrives())
        roots: list[Path] = []
        for index in range(26):
            if not mask & (1 << index):
                continue
            root = "%s:\\" % chr(ord("A") + index)
            # DRIVE_FIXED == 3.  Network (4), removable (2), CD-ROM (5),
            # RAM disk (6), and unknown/no-root types are deliberately denied.
            if int(kernel32.GetDriveTypeW(root)) == 3:
                roots.append(Path(root))
        return roots, ([] if roots else ["no local fixed drive was available"])
    except (AttributeError, OSError, TypeError, ValueError):
        return [], ["local fixed-drive enumeration failed closed"]

def render_text(report: Mapping[str, Any]) -> str:
    """Render a compact, terminal-safe summary of a computer-scan report."""
    summary = report.get("summary") if isinstance(report.get("summary"), Mapping) else {}
    authorization = (report.get("authorization")
                     if isinstance(report.get("authorization"), Mapping) else {})
    lines = [
        "Attestor 4.1.3 computer scan: " + _text(report.get("status"), 80),
        "Permission: " + ("granted for this run" if authorization.get("authorized")
                          else "required (no discovery performed)"),
        "Scope: " + _text(authorization.get("scope") or "home", 40),
        "Projects: %d discovered, %d analyzed" % (
            _integer(summary.get("projects_discovered")),
            _integer(summary.get("projects_analyzed"))),
        "Findings: %d; review improvements: %d; analysis errors: %d" % (
            _integer(summary.get("findings_returned")),
            _integer(summary.get("improvements_returned")),
            _integer(summary.get("analysis_errors"))),
    ]
    projects = report.get("projects") if isinstance(report.get("projects"), list) else []
    for row in projects[:MAX_PROJECTS]:
        if not isinstance(row, Mapping):
            continue
        project_summary = row.get("summary") if isinstance(row.get("summary"), Mapping) else {}
        lines.append("- %s: %s, %d finding(s) returned" % (
            _text(row.get("root"), 1_000), _text(row.get("status"), 80),
            _integer(project_summary.get("findings_returned"))))
    coverage = report.get("coverage") if isinstance(report.get("coverage"), Mapping) else {}
    gaps = coverage.get("gaps") if isinstance(coverage.get("gaps"), list) else []
    if gaps:
        lines.append("Coverage gaps:")
        for gap in gaps[:20]:
            lines.append("- " + _text(gap, 1_000))
    return "\n".join(lines)

def score(rule: str, severity: str, fix: str = "", message: str = "", snippet: str = "") -> dict:
    """Return the confidence packet attached to every detector finding."""
    return {
        "confidence": confidence(rule, severity, snippet),
        "exploitability": exploitability(rule, severity),
        "safe_to_autofix": safe_to_autofix(rule),
    }

#!/usr/bin/env python3
"""Confidence metadata for Attestor findings.

The detector already assigns severity. This module adds the operational labels a
repair pipeline needs: confidence, exploitability, and whether the issue is safe
to autofix mechanically.
"""
from __future__ import annotations

SECURITY_RULES = {
    "hardcoded-secret", "py-empty-secret-default", "py-sql-injection",
    "tls-verify-disabled", "weak-hash", "dangerous-eval", "py-yaml-load",
    "py-subprocess-shell", "py-insecure-deserialize", "debug-enabled",
    "js-client-secret-storage", "js-innerhtml", "js-settimeout-string",
    "js-prototype-pollution", "insecure-http-url", "unsafe-libc",
    "command-exec", "format-string", "scanf-unbounded",
}

SAFE_AUTOFIX_RULES = {
    "py-eq-none",
    "py-bare-except",
    "tls-verify-disabled",
    "weak-hash",
    "debug-enabled",
}

HIGH_SIGNAL_RULES = {
    "syntax-error", "tls-verify-disabled", "weak-hash", "dangerous-eval",
    "py-yaml-load", "py-subprocess-shell", "py-insecure-deserialize",
    "py-dict-fromkeys-mutable", "dataclass-mutable-default",
    "list-multiply-alias", "return-value-in-init", "c-realloc-leak",
    "c-return-local-address", "c-free-stack-address", "cpp-delete-array-mismatch",
}

LOW_SIGNAL_RULES = {
    "todo-fixme", "js-var", "py-bind-all-interfaces", "rangefor-copy",
    "float-equality", "weak-rng",
}

BASE_CONFIDENCE = {"HIGH": 0.86, "MEDIUM": 0.76, "LOW": 0.62}


def exploitability(rule: str, severity: str) -> str:
    if rule in SECURITY_RULES or severity == "HIGH":
        return "HIGH"
    if severity == "MEDIUM":
        return "MEDIUM"
    return "LOW"


def confidence(rule: str, severity: str, snippet: str = "") -> float:
    score = BASE_CONFIDENCE.get(severity, 0.60)
    if rule in HIGH_SIGNAL_RULES:
        score += 0.09
    if rule in LOW_SIGNAL_RULES:
        score -= 0.10
    if snippet and len(snippet.strip()) >= 6:
        score += 0.02
    return round(max(0.35, min(0.99, score)), 2)


def safe_to_autofix(rule: str) -> bool:
    return rule in SAFE_AUTOFIX_RULES


def score(rule: str, severity: str, fix: str = "", message: str = "", snippet: str = "") -> dict:
    """Return the confidence packet attached to every detector finding."""
    return {
        "confidence": confidence(rule, severity, snippet),
        "exploitability": exploitability(rule, severity),
        "safe_to_autofix": safe_to_autofix(rule),
    }


def enrich(finding):
    """Mutate a Finding-like object with confidence metadata and return it."""
    meta = score(
        getattr(finding, "rule", ""),
        getattr(finding, "severity", ""),
        getattr(finding, "fix", ""),
        getattr(finding, "message", ""),
        getattr(finding, "snippet", ""),
    )
    finding.confidence = meta["confidence"]
    finding.exploitability = meta["exploitability"]
    finding.safe_to_autofix = meta["safe_to_autofix"]
    return finding

def verify_consumption(value: Any) -> tuple[bool, list[str]]:
    """Verify the bounded content integrity of consumption evidence.

    Only the live registry can establish issuance and unused state.  This
    verifier deliberately does not turn copied JSON into authority.
    """
    try:
        policy.canonical_bytes(value)
    except policy.ControlPolicyError:
        return False, [
            "authorization consumption is not bounded deterministic JSON"]
    if type(value) is not dict:
        return False, ["authorization consumption is not an exact object"]
    errors: list[str] = []
    if set(value) != _CONSUMPTION_KEYS:
        errors.append("authorization consumption keys are invalid")
    if (value.get("schema") != CONSUMPTION_SCHEMA
            or value.get("version") != VERSION
            or value.get("status") != "authorized-once"):
        errors.append("authorization consumption identity is invalid")
    try:
        _exact_registry(value.get("registry_id"))
        _exact_session(value.get("session_id"))
    except ControlAuthorizationError as exc:
        errors.append(str(exc))
    profile = value.get("profile")
    try:
        expected_profile = policy.compiled_profile_document()
    except policy.ControlPolicyError:
        expected_profile = {}
    if profile != expected_profile:
        errors.append("authorization consumption profile is invalid")
    for field in (
            "policy_sha256", "plan_sha256", "capability_sha256",
            "nonce_sha256"):
        item = value.get(field)
        if type(item) is not str or policy.SHA256_RE.fullmatch(item) is None:
            errors.append(f"authorization consumption {field} is invalid")
    action = value.get("action")
    if type(action) is not str or action not in policy.ALLOWED_ACTIONS:
        errors.append("authorization consumption action is invalid")
    elif value.get("authorization_kind") != _kind_for(action):
        errors.append("authorization consumption kind is invalid")
    if type(value.get("consumed_at_unix")) is not int or value.get(
            "consumed_at_unix", -1) < 0:
        errors.append("authorization consumption time is invalid")
    if (value.get("permission_retained") is not False
            or value.get("mutation_authorized") is not False):
        errors.append("authorization consumption safety flags are invalid")
    claimed = value.get("audit_sha256")
    if type(claimed) is not str or policy.SHA256_RE.fullmatch(claimed) is None:
        errors.append("authorization consumption digest is invalid")
    else:
        body = {
            key: item for key, item in value.items()
            if key != "audit_sha256"
        }
        try:
            actual = policy.digest_json(body)
        except policy.ControlPolicyError:
            errors.append("authorization consumption body is invalid")
        else:
            if not hmac.compare_digest(claimed, actual):
                errors.append("authorization consumption digest does not match")
    return not errors, errors

def execute_observation(plan: Mapping[str, Any]) -> dict[str, Any]:
    """Execute one already-authorized observation plan.

    Capability issuance and consumption intentionally live in
    :mod:`owner_control42`; this function never accepts a boolean permission.
    """
    try:
        exact = policy.require_plan(plan)
    except policy.ControlPolicyError as exc:
        raise ControlInventoryError("observation plan is invalid") from exc
    action = exact["action"]
    if action not in policy.OBSERVATION_ACTIONS:
        raise ControlInventoryError(
            "plan-only mutation evidence is not executable")
    request = exact["request"]
    if action == policy.SYSTEM_INVENTORY:
        return system_inventory(request)
    if action == policy.FIND_FILES:
        return find_files(request)
    if action == policy.COMPUTER_PROJECT_SCAN:
        return computer_project_scan(request)
    raise ControlInventoryError("observation action is unavailable")

def _child_env(temp_dir: str = "") -> dict:
    """Minimal environment for generated code; no keys, proxies, or user paths."""
    env = {key: value for key, value in os.environ.items() if key in _SAFE_ENV_KEYS}
    env.update({
        "PYTHONDONTWRITEBYTECODE": "1",
        "PYTHONHASHSEED": "0",
        "PYTHONIOENCODING": "utf-8",
        "PYTHONUTF8": "1",
    })
    if temp_dir:
        env["TEMP"] = temp_dir
        env["TMP"] = temp_dir
        env["TMPDIR"] = temp_dir
    return env

class _OutputCapture:
    """Drain both pipes while retaining at most one shared byte budget."""

    def __init__(self, limit: int):
        self.limit = limit
        self.total = 0
        self.parts = {"stdout": [], "stderr": []}
        self.exceeded = threading.Event()
        self.lock = threading.Lock()

    def drain(self, name: str, stream):
        try:
            while True:
                chunk = stream.read(8_192)
                if not chunk:
                    return
                with self.lock:
                    remaining = max(0, self.limit - self.total)
                    kept = chunk[:remaining]
                    if kept:
                        self.parts[name].append(kept)
                        self.total += len(kept)
                    if len(chunk) > remaining:
                        self.exceeded.set()
                        return
        except (OSError, ValueError):
            return

    def text(self, name: str) -> str:
        return b"".join(self.parts[name]).decode("utf-8", "replace")

def _directory_size(path: str, stop_after: int | None = None) -> int:
    """Best-effort non-symlink-following size used to stop disk-filling code."""
    total = 0
    try:
        for root, _dirs, files in os.walk(path, followlinks=False):
            for name in files:
                try:
                    total += os.stat(os.path.join(root, name), follow_symlinks=False).st_size
                except OSError:
                    continue
                if stop_after is not None and total > stop_after:
                    return total
    except OSError:
        return total
    return total

def imports(source: str, timeout: int = DEFAULT_TIMEOUT,
            max_output: int = DEFAULT_MAX_OUTPUT) -> Verdict:
    """Explicitly execute an isolated import of ``source``."""
    return _with_module(source, "import candidate\n", timeout, max_output)

def smoke(source: str, snippet: str, timeout: int = DEFAULT_TIMEOUT,
          max_output: int = DEFAULT_MAX_OUTPUT) -> Verdict:
    """Explicitly execute a smoke-test snippet against ``source``."""
    return _with_module(source, "from candidate import *\n" + snippet, timeout, max_output)

def run_main(source: str, timeout: int = DEFAULT_TIMEOUT,
             max_output: int = DEFAULT_MAX_OUTPUT) -> Verdict:
    """Explicitly execute the candidate module's ``__main__`` path."""
    code = "import runpy\nrunpy.run_path('candidate.py', run_name='__main__')\n"
    return _with_module(source, code, timeout, max_output)

def verify(source: str, snippet: str = "", timeout: int = DEFAULT_TIMEOUT,
           max_output: int = DEFAULT_MAX_OUTPUT) -> Verdict:
    """Explicitly run the full restricted dynamic gate."""
    loaded = imports(source, timeout, max_output)
    if not loaded:
        return Verdict(False, "does not import: " + loaded.detail, loaded.stdout, loaded.stderr,
                       loaded.status, loaded.sandbox)
    if snippet:
        checked = smoke(source, snippet, timeout, max_output)
        if not checked:
            return Verdict(False, "smoke test failed: " + checked.detail,
                           checked.stdout, checked.stderr, checked.status, checked.sandbox)
    return Verdict(True, "imports and runs under " + loaded.sandbox["profile"],
                   status="passed", sandbox=loaded.sandbox)

def run_trusted_command(argv: list[str], cwd: str, *, trusted: bool = False,
                        timeout: int = DEFAULT_TIMEOUT,
                        max_output: int = DEFAULT_MAX_OUTPUT) -> Verdict:
    """Run a caller-supplied regression command after an explicit trust opt-in.

    The process is still bounded and secret-free, but arbitrary commands do not
    receive Python's audit-hook restrictions. This distinction is exposed in the
    returned sandbox profile.
    """
    if not trusted:
        return Verdict(False,
                       "trusted command execution disabled; pass trusted=True explicitly",
                       status="disabled", sandbox=sandbox_status(trusted_command=True))
    if not argv or not all(isinstance(part, str) and part for part in argv):
        return Verdict(False, "regression command is empty", status="launch-failed",
                       sandbox=sandbox_status(trusted_command=True))
    return _execute(list(argv), cwd, timeout, max_output, trusted_command=True)

def _remote_windows_path(value: str | os.PathLike[str]) -> bool:
    """Reject UNC and mapped remote drives before opening the supplied path."""
    raw = os.fspath(value)
    if raw.startswith(("\\\\", "//")):
        return True
    if os.name != "nt":
        return False
    drive = Path(raw).drive
    if not drive:
        return False
    root = drive + "\\"
    try:
        import ctypes
        drive_type = ctypes.windll.kernel32.GetDriveTypeW(root)
    except (AttributeError, OSError, TypeError):
        # A drive we cannot classify is not safe enough for a claim of local
        # operation.  DRIVE_UNKNOWN is also denied.
        return True
    return drive_type in {0, 4}  # DRIVE_UNKNOWN or DRIVE_REMOTE

def inspect_sql_file(
    value: str | os.PathLike[str],
    *,
    expected_sha256: str,
) -> dict[str, Any]:
    """Statically understand a SQL schema/migration; never execute it."""
    path = _regular_file(value, MAX_SQL_BYTES)
    data, digest, stable_snapshot = _read_bound_bytes(
        path, expected_sha256, MAX_SQL_BYTES)
    try:
        text = data.decode("utf-8", "strict")
    except UnicodeError as exc:
        raise DatabaseIntelligenceError(
            "SQL artifact must be bounded UTF-8 text") from exc
    scrubbed = _strip_literals_and_comments(text)
    statements = _statement_rows(text, scrubbed)
    comment_free = _strip_comments_preserve_literals(text)
    privileged = [
        marker for marker, pattern in _PRIVILEGED_PATTERNS
        if pattern.search(
            comment_free if marker == "credential-literal" else scrubbed)
    ]
    depth = 0
    ordered = True
    saw_transaction = False
    for row in statements:
        keyword = row["effective_keyword"]
        if keyword in {"BEGIN", "START"}:
            depth += 1
            saw_transaction = True
        elif keyword in {"COMMIT", "ROLLBACK"}:
            if depth <= 0:
                ordered = False
            else:
                depth -= 1
    transaction_balanced = saw_transaction and ordered and depth == 0
    if _snapshot(path) != stable_snapshot or _sha_file(path, MAX_SQL_BYTES) != digest:
        raise DatabaseIntelligenceError(
            "SQL artifact changed during static inspection")
    return {
        "schema": SCHEMA,
        "version": VERSION,
        "kind": "sql-file",
        "status": "lexically-classified",
        "artifact": {
            "path": str(path),
            "sha256": digest,
            "bytes": stable_snapshot[0],
        },
        "migration": {
            "statements": statements,
            "summary": {
                "statement_count": len(statements),
                "write_statement_count": sum(
                    row["writes_data_or_schema"] for row in statements),
                "destructive_statement_count": sum(
                    row["destructive"] for row in statements),
                "transaction_ordered_and_balanced": transaction_balanced,
            },
            "privileged_risk_markers": privileged,
            "analysis_contract": {
                "kind": "bounded-generic-lexical-classification",
                "dialect_parser_used": False,
                "known_limitations": [
                    "dialect-specific batch separators are not parsed",
                    "procedural or trigger bodies containing semicolons may split",
                    "nested CTE write tokens are conservative lexical risk signals",
                    "classification is not database validation",
                ],
            },
        },
        "boundaries": {
            "database_writes": False,
            "database_server_connected": False,
            "row_values_in_report": False,
            "source_sql_in_report": False,
            "supplied_sql_executed": False,
        },
    }

def understand(
    value: str | os.PathLike[str],
    *,
    expected_sha256: str,
) -> dict[str, Any]:
    """Dispatch one exact local artifact to a read-only understanding adapter."""
    path = _regular_file(value, MAX_DATABASE_BYTES)
    try:
        with path.open("rb") as handle:
            magic = handle.read(len(SQLITE_MAGIC))
    except OSError as exc:
        raise DatabaseIntelligenceError(
            "database artifact could not be classified") from exc
    if magic == SQLITE_MAGIC or path.suffix.casefold() in _SQLITE_SUFFIXES:
        return inspect_sqlite(path, expected_sha256=expected_sha256)
    if path.suffix.casefold() in _SQL_SUFFIXES:
        return inspect_sql_file(path, expected_sha256=expected_sha256)
    raise DatabaseIntelligenceError(
        "supported database artifacts are SQLite snapshots and SQL text files")

def _top_level_defs(tree) -> list:
    """(name, line, kind, decorated) for each module-level function/class."""
    out = []
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            out.append((node.name, node.lineno, "function", bool(node.decorator_list)))
        elif isinstance(node, ast.ClassDef):
            out.append((node.name, node.lineno, "class", bool(node.decorator_list)))
    return out

def _references(tree) -> tuple:
    """(used_names, exported_names): every name used anywhere, and __all__ entries."""
    used = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
            used.add(node.id)
        elif isinstance(node, ast.Attribute):
            used.add(node.attr)
        elif isinstance(node, ast.Constant) and isinstance(node.value, str) \
                and node.value.isidentifier():
            used.add(node.value)
    return used, _dunder_all(tree)

#!/usr/bin/env python3
"""
deadcode.py -- find module-level functions and classes nothing references.

Per-file tools miss code that is dead across the whole project: a function still
defined, still tested-adjacent, but never called from anywhere. This reads every
file, gathers every name that is USED anywhere (called, attribute-accessed, named
in a string for dynamic dispatch, or listed in __all__), and reports the top-level
defs whose name appears in none of them.

It is deliberately conservative -- Attestor would rather stay silent than delete
something that matters. It never flags: dunders, main, test*/setUp/tearDown,
decorated defs (they are often registered by the decorator), or anything a string
literal mentions. Private names (leading underscore) are the high-confidence
finds; public names are flagged too but noted, since a library's public API is
"unused" here only because its callers live outside the tree you scanned.

    deadcode.py src/                 # unreferenced defs across a project
    deadcode.py app.py --private     # only the high-confidence private ones
    deadcode.py src/ --json          # machine-readable
"""
from __future__ import annotations

import argparse
import ast
import json
import os
import sys
from dataclasses import asdict, dataclass

SKIP_DIRS = {".git", ".hg", ".svn", "__pycache__", "build", "dist", "node_modules"}
_EXEMPT = {"main", "setUp", "tearDown", "setUpClass", "tearDownClass",
           "setUpModule", "tearDownModule"}


@dataclass
class Dead:
    path: str
    line: int
    name: str
    kind: str
    private: bool


def _read(path: str) -> str:
    try:
        with open(path, encoding="utf-8", errors="replace") as fh:
            return fh.read()
    except OSError:
        return ""


def _parse(src: str):
    try:
        return ast.parse(src)
    except SyntaxError:
        return None


def _is_exempt(name: str) -> bool:
    return (name in _EXEMPT or name.startswith("test")
            or (name.startswith("__") and name.endswith("__")))


def _top_level_defs(tree) -> list:
    """(name, line, kind, decorated) for each module-level function/class."""
    out = []
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            out.append((node.name, node.lineno, "function", bool(node.decorator_list)))
        elif isinstance(node, ast.ClassDef):
            out.append((node.name, node.lineno, "class", bool(node.decorator_list)))
    return out


def _dunder_all(tree) -> set:
    names = set()
    for node in tree.body:
        targets = node.targets if isinstance(node, ast.Assign) else []
        if any(isinstance(t, ast.Name) and t.id == "__all__" for t in targets):
            for element in getattr(node.value, "elts", []):
                if isinstance(element, ast.Constant) and isinstance(element.value, str):
                    names.add(element.value)
    return names


def _references(tree) -> tuple:
    """(used_names, exported_names): every name used anywhere, and __all__ entries."""
    used = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
            used.add(node.id)
        elif isinstance(node, ast.Attribute):
            used.add(node.attr)
        elif isinstance(node, ast.Constant) and isinstance(node.value, str) \
                and node.value.isidentifier():
            used.add(node.value)
    return used, _dunder_all(tree)


def _load_trees(paths) -> dict:
    trees = {}
    for path in collect_paths(paths):
        tree = _parse(_read(path))
        if tree is not None:
            trees[path] = tree
    return trees


def _gather_references(trees: dict) -> tuple:
    used = set()
    exported = set()
    for tree in trees.values():
        file_used, file_exports = _references(tree)
        used |= file_used
        exported |= file_exports
    return used, exported


def _dead_in_file(path: str, tree, used: set, exported: set, private_only: bool) -> list:
    out = []
    for name, line, kind, decorated in _top_level_defs(tree):
        if decorated or _is_exempt(name) or name in exported or name in used:
            continue
        private = name.startswith("_")
        if not (private_only and not private):
            out.append(Dead(path, line, name, kind, private))
    return out


def find_dead(paths, private_only: bool = False) -> list:
    trees = _load_trees(paths)
    used, exported = _gather_references(trees)
    dead = []
    for path, tree in trees.items():
        dead += _dead_in_file(path, tree, used, exported, private_only)
    dead.sort(key=lambda d: (not d.private, d.path, d.line))
    return dead


def collect_paths(paths) -> list:
    out = []
    for raw in paths:
        if os.path.isdir(raw):
            for root, dirs, files in os.walk(raw):
                dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
                out += [os.path.join(root, f) for f in sorted(files) if f.endswith(".py")]
        elif raw.endswith(".py") or os.path.isfile(raw):
            out.append(raw)
    return out


def render(dead: list) -> str:
    if not dead:
        return "no unreferenced top-level defs found. clean."
    private = sum(1 for d in dead if d.private)
    lines = ["%d unreferenced def(s): %d private (high confidence), %d public "
             "(may be external API)" % (len(dead), private, len(dead) - private),
             "=" * 64]
    for d in dead:
        tag = "private" if d.private else "public"
        lines.append("%s:%d  %s %s  [%s]" % (d.path, d.line, d.kind, d.name, tag))
    return "\n".join(lines)


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("paths", nargs="+", help="Python files or directories")
    ap.add_argument("--private", action="store_true",
                    help="report only leading-underscore names (the high-confidence dead code)")
    ap.add_argument("--json", action="store_true", help="machine-readable output")
    args = ap.parse_args(argv)

    dead = find_dead(args.paths, private_only=args.private)
    if args.json:
        print(json.dumps([asdict(d) for d in dead], indent=2))
    else:
        print(render(dead))
    return min(len(dead), 250)


if __name__ == "__main__":
    sys.exit(main())

def _walk_scope(root):
    """Walk one executable scope without leaking into nested defs/classes."""
    stack = list(reversed(list(ast.iter_child_nodes(root))))
    while stack:
        node = stack.pop()
        if isinstance(node, _SCOPE_NODES):
            continue
        yield node
        stack.extend(reversed(list(ast.iter_child_nodes(node))))

def _string_literals(node):
    """Every literal string fragment reachable in a string-building expression."""
    for child in ast.walk(node):
        if isinstance(child, ast.Constant) and isinstance(child.value, str):
            yield child.value

def _is_interpolated_string(node) -> bool:
    """True when a string value is assembled from a non-literal part."""
    if isinstance(node, ast.JoinedStr):
        return any(isinstance(part, ast.FormattedValue) for part in node.values)
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Mod)):
        sides = (node.left, node.right)
        literal = any(isinstance(side, ast.Constant)
                      and isinstance(side.value, str) for side in sides)
        dynamic = any(not isinstance(side, ast.Constant) for side in sides)
        return literal and dynamic
    if (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
            and node.func.attr == "format"
            and isinstance(node.func.value, ast.Constant)
            and isinstance(node.func.value.value, str)):
        return bool(node.args or node.keywords)
    return False

def _unsafe_option_dict(node):
    """A dict literal that turns off a protection, as (rule, severity, what)."""
    if not isinstance(node, ast.Dict):
        return None
    for key, value in zip(node.keys, node.values):
        if not (isinstance(key, ast.Constant) and isinstance(key.value, str)
                and isinstance(value, ast.Constant)):
            continue
        if key.value == "verify" and value.value is False:
            return ("tls-verify-disabled", "HIGH", "verify=False")
        if key.value == "shell" and value.value is True:
            return ("py-subprocess-shell", "MEDIUM", "shell=True")
    return None

def _bound_names(target):
    """Every name a binding target writes, including through tuple unpacking."""
    for node in ast.walk(target):
        if isinstance(node, ast.Name):
            yield node.id

def _single_assignments(scope):
    """name -> (value_node, lineno) for names this scope assigns exactly once.

    Every binding form has to be counted, not just `name = value`.  A name
    bound in one branch by `a, b = pair` and in another by `a = 'md5'` is not a
    constant, and treating it as one asserts a certainty the code does not
    have.  Anything bound more than once, or bound in a form whose value cannot
    be read off statically, is dropped.
    """
    counts, values = {}, {}

    def bump(name, amount=1):
        counts[name] = counts.get(name, 0) + amount

    for node in _scope_nodes(scope):
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and len(node.targets) == 1:
                    bump(target.id)
                    values[target.id] = (node.value, node.lineno)
                else:
                    # Unpacking or chained assignment: bound, but the value of
                    # any single name is not readable here.
                    for name in _bound_names(target):
                        bump(name, 2)
        elif isinstance(node, ast.AnnAssign) and node.value is not None \
                and isinstance(node.target, ast.Name):
            bump(node.target.id)
            values[node.target.id] = (node.value, node.lineno)
        elif isinstance(node, (ast.AugAssign, ast.AnnAssign)):
            for name in _bound_names(node.target):
                bump(name, 2)
        elif isinstance(node, (ast.For, ast.AsyncFor)):
            for name in _bound_names(node.target):
                bump(name, 2)
        elif isinstance(node, ast.NamedExpr):
            for name in _bound_names(node.target):
                bump(name, 2)
        elif isinstance(node, ast.comprehension):
            for name in _bound_names(node.target):
                bump(name, 2)
        elif isinstance(node, (ast.withitem,)):
            if node.optional_vars is not None:
                for name in _bound_names(node.optional_vars):
                    bump(name, 2)
        elif isinstance(node, ast.ExceptHandler) and node.name:
            bump(node.name, 2)
        elif isinstance(node, (ast.Global, ast.Nonlocal)):
            for name in node.names:
                bump(name, 2)
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef,
                               ast.ClassDef)):
            bump(node.name, 2)
        elif isinstance(node, (ast.Import, ast.ImportFrom)):
            for alias in node.names:
                bump((alias.asname or alias.name).split(".")[0], 2)
    return {name: values[name] for name, count in counts.items()
            if count == 1 and name in values}

def _class_constants(tree):
    """method node -> {attribute: literal} for its own class body constants.

    Covers `class C: VERIFY = False` reached later as `self.VERIFY`, which no
    line rule can see because neither statement contains the other's half.
    """
    owned = {}
    for node in ast.walk(tree):
        if not isinstance(node, ast.ClassDef):
            continue
        constants = {}
        for statement in node.body:
            if isinstance(statement, ast.Assign) and len(statement.targets) == 1 \
                    and isinstance(statement.targets[0], ast.Name) \
                    and isinstance(statement.value, ast.Constant):
                constants[statement.targets[0].id] = statement.value.value
        if not constants:
            continue
        for statement in node.body:
            if isinstance(statement, (ast.FunctionDef, ast.AsyncFunctionDef)):
                owned[statement] = constants
    return owned

def _loads_name(node, name):
    """True if `name` is loaded as a free variable in `node`. A nested
    `except ... as name:` handler rebinds `name` locally, so uses inside it are
    that fresh binding, not a leak of the outer one -- those subtrees are skipped
    (otherwise two adjacent try/excepts that reuse the same name false-positive)."""
    if isinstance(node, ast.Name):
        return isinstance(node.ctx, ast.Load) and node.id == name
    if isinstance(node, ast.ExceptHandler) and node.name == name:
        return False
    return any(_loads_name(child, name) for child in ast.iter_child_nodes(node))

class _BindingCollector(ast.NodeVisitor):
    """Bindings for exactly one Python lexical scope (nested scopes are opaque)."""

    def __init__(self, parameters=()):
        self.bound = set(parameters)
        self.globals = set()
        self.nonlocals = set()

    def visit_Name(self, node):
        if isinstance(node.ctx, ast.Store):
            self.bound.add(node.id)

    def visit_Import(self, node):
        for alias in node.names:
            self.bound.add(alias.asname or alias.name.split(".")[0])

    def visit_ImportFrom(self, node):
        for alias in node.names:
            if alias.name == "*":
                continue
            self.bound.add(alias.asname or alias.name)

    def visit_Global(self, node):
        self.globals.update(node.names)

    def visit_Nonlocal(self, node):
        self.nonlocals.update(node.names)

    def visit_ExceptHandler(self, node):
        if node.name:
            self.bound.add(node.name)
        self.generic_visit(node)

    def visit_MatchAs(self, node):
        if node.name:
            self.bound.add(node.name)
        self.generic_visit(node)

    def visit_MatchStar(self, node):
        if node.name:
            self.bound.add(node.name)

    def visit_FunctionDef(self, node):
        self.bound.add(node.name)

    visit_AsyncFunctionDef = visit_FunctionDef

    def visit_ClassDef(self, node):
        self.bound.add(node.name)

    def visit_Lambda(self, node):
        return

    def visit_ListComp(self, node):
        return

    visit_SetComp = visit_ListComp
    visit_DictComp = visit_ListComp
    visit_GeneratorExp = visit_ListComp

def _sig(fn: ast.AST) -> str:
    """Render a def's parameter list roughly the way it reads in source."""
    a = fn.args
    parts = []
    pos = list(a.posonlyargs) + list(a.args)
    ndef = len(a.defaults)
    first_def = len(pos) - ndef
    for i, arg in enumerate(pos):
        s = arg.arg
        if i >= first_def:
            s += "=" + _unparse(a.defaults[i - first_def])
        parts.append(s)
        if a.posonlyargs and i == len(a.posonlyargs) - 1:
            parts.append("/")
    if a.vararg:
        parts.append("*" + a.vararg.arg)
    elif a.kwonlyargs:
        parts.append("*")
    for arg, d in zip(a.kwonlyargs, a.kw_defaults):
        s = arg.arg
        if d is not None:
            s += "=" + _unparse(d)
        parts.append(s)
    if a.kwarg:
        parts.append("**" + a.kwarg.arg)
    return ", ".join(parts)

def _defined_functions(tree):
    """Every function def in the module, keyed by name (for the call graph)."""
    names = set()
    for n in ast.walk(tree):
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)):
            names.add(n.name)
    return names

def _calls_in(fn, known):
    """Direct calls this function makes to other module-level functions."""
    out = []
    seen = set()
    for n in ast.walk(fn):
        if isinstance(n, ast.Call):
            target = None
            if isinstance(n.func, ast.Name):
                target = n.func.id
            elif isinstance(n.func, ast.Attribute):
                target = n.func.attr
            if target and target in known and target != fn.name and target not in seen:
                seen.add(target)
                out.append(target)
    return out

def explain(source: str, path: str) -> str:
    """
    A plain-language structural summary: what this module contains and how the
    pieces call each other. Not a bug report -- the "read it and understand it"
    half of the request. Pairs with analyze() for the "find the errors" half.
    """
    try:
        tree = ast.parse(source)
    except SyntaxError as e:
        return f"{path}: cannot parse ({e.msg} at line {e.lineno})."

    lines = source.split("\n")
    loc = sum(1 for ln in lines if ln.strip() and not ln.strip().startswith("#"))
    out = [f"how {os.path.basename(path)} works", "=" * 60]

    doc = ast.get_docstring(tree)
    if doc:
        first = doc.strip().split("\n", 1)[0]
        out.append(f"purpose : {first}")
    out.append(f"size    : {len(lines)} lines ({loc} of code)")

    imports = []
    for n in tree.body:
        if isinstance(n, ast.Import):
            imports += [a.asname or a.name for a in n.names]
        elif isinstance(n, ast.ImportFrom):
            mod = ("." * (n.level or 0)) + (n.module or "")
            imports += [f"{mod}.{a.name}" for a in n.names]
    if imports:
        shown = ", ".join(imports[:12]) + (" ..." if len(imports) > 12 else "")
        out.append(f"imports : {shown}")

    known = _defined_functions(tree)
    classes = [n for n in tree.body if isinstance(n, ast.ClassDef)]
    funcs = [n for n in tree.body
             if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))]

    if classes:
        out.append("")
        out.append(f"classes ({len(classes)}):")
        for c in classes:
            bases = ", ".join(_unparse(b) for b in c.bases)
            methods = [m for m in c.body
                       if isinstance(m, (ast.FunctionDef, ast.AsyncFunctionDef))]
            head = f"  class {c.name}" + (f"({bases})" if bases else "")
            out.append(f"{head}  -- {len(methods)} method(s)")
            for m in methods:
                out.append(f"      .{m.name}({_sig(m)})  [complexity {complexity(m)}]")

    if funcs:
        out.append("")
        out.append(f"top-level functions ({len(funcs)}):")
        for f in funcs:
            kw = "async def" if isinstance(f, ast.AsyncFunctionDef) else "def"
            out.append(f"  {kw} {f.name}({_sig(f)})  [complexity {complexity(f)}]")
            fdoc = ast.get_docstring(f)
            if fdoc:
                out.append(f"      \"{fdoc.strip().splitlines()[0]}\"")

    # intra-module call graph -- who calls whom
    edges = []
    for f in funcs:
        for callee in _calls_in(f, known):
            edges.append((f.name, callee))
    for c in classes:
        for m in c.body:
            if isinstance(m, (ast.FunctionDef, ast.AsyncFunctionDef)):
                for callee in _calls_in(m, known):
                    edges.append((f"{c.name}.{m.name}", callee))
    if edges:
        out.append("")
        out.append("call graph (who calls whom, within this module):")
        for caller, callee in edges:
            out.append(f"  {caller} -> {callee}")

    # the most complex function is where the risk concentrates
    ranked = sorted(
        [[f.name, complexity(f)] for f in funcs] +
        [[f"{c.name}.{m.name}", complexity(m)]
         for c in classes for m in c.body
         if isinstance(m, (ast.FunctionDef, ast.AsyncFunctionDef))],
        key=lambda x: x[1], reverse=True)
    if ranked:
        out.append("")
        top = ranked[0]
        out.append(f"hot spot : {top[0]} is the most complex path "
                   f"(cyclomatic complexity {top[1]}) -- read it first.")
    return "\n".join(out)

def version_in_range(version: str, range_spec: str) -> bool:
    """Check if version falls within a range specification.

    Supports: "< 2.0", ">= 1.0, < 2.0", "1.0 - 2.0", "< 3.0.1", "*".
    """
    if not range_spec or range_spec.strip() == "*":
        return True

    range_spec = range_spec.strip()

    if " - " in range_spec:
        lo, hi = range_spec.split(" - ", 1)
        return version_gte(version, lo.strip()) and version_lte(version, hi.strip())

    parts = [p.strip() for p in range_spec.split(",")]
    for part in parts:
        m = re.match(r"^([<>=!]+)\s*(.+)$", part)
        if not m:
            continue
        op, val = m.group(1), m.group(2)
        if op == "<" and not version_lt(version, val):
            return False
        elif op == "<=" and not version_lte(version, val):
            return False
        elif op == ">=" and not version_gte(version, val):
            return False
        elif op == ">" and not (not version_lte(version, val)):
            return False
        elif op == "!=" and parse_version(version) == parse_version(val):
            return False
    return True

class DepScanner:
    """Scans project dependencies for known CVEs."""

    def __init__(self):
        self._deps: list[Dependency] = []
        self._vulns: list[VulnMatch] = []
        self._files_scanned: list[str] = []

    def scan_file(self, path: str) -> list[Dependency]:
        basename = os.path.basename(path)
        parser = MANIFEST_PARSERS.get(basename)

        if parser is None and CSPROJ_PATTERN.search(basename):
            parser = parse_csproj

        if parser is None:
            return []

        try:
            with open(path, "r", encoding="utf-8", errors="ignore") as fh:
                content = fh.read()
        except (OSError, IOError):
            return []

        deps = parser(content, path)
        self._deps.extend(deps)
        self._files_scanned.append(path)
        return deps

    def scan_content(self, content: str, filename: str) -> list[Dependency]:
        parser = MANIFEST_PARSERS.get(filename)
        if parser is None and CSPROJ_PATTERN.search(filename):
            parser = parse_csproj
        if parser is None:
            return []
        deps = parser(content, filename)
        self._deps.extend(deps)
        self._files_scanned.append(filename)
        return deps

    def scan_project(self, root: str) -> list[VulnMatch]:
        for dirpath, _dirnames, filenames in os.walk(root):
            if "node_modules" in dirpath or ".git" in dirpath:
                continue
            for fname in filenames:
                if fname in MANIFEST_PARSERS or CSPROJ_PATTERN.search(fname):
                    self.scan_file(os.path.join(dirpath, fname))

        self._check_advisories()
        return self._vulns

    def _check_advisories(self) -> None:
        self._vulns = []
        for dep in self._deps:
            keys = [dep.key]
            if ":" in dep.name:
                artifact = dep.name.rsplit(":", 1)[-1]
                keys.append("%s:%s" % (dep.ecosystem.value, artifact.lower()))
            seen_cves: set[str] = set()
            for key in keys:
                for adv in _ADVISORY_INDEX.get(key, []):
                    if adv.cve_id in seen_cves:
                        continue
                    if dep.version == "*" or version_in_range(dep.version, adv.affected_versions):
                        seen_cves.add(adv.cve_id)
                        self._vulns.append(VulnMatch(
                            dependency=dep, advisory=adv,
                            is_fixable=bool(adv.fixed_version)))

    def check(self) -> list[VulnMatch]:
        self._check_advisories()
        return self._vulns

    @property
    def dependencies(self) -> list[Dependency]:
        return list(self._deps)

    @property
    def vulnerabilities(self) -> list[VulnMatch]:
        return list(self._vulns)

    @property
    def files_scanned(self) -> list[str]:
        return list(self._files_scanned)

    def report(self) -> str:
        lines = [
            "=== Dependency CVE Scan ===",
            "Files scanned: %d" % len(self._files_scanned),
            "Dependencies found: %d" % len(self._deps),
            "Vulnerabilities found: %d" % len(self._vulns),
        ]

        if self._vulns:
            by_sev: dict[str, int] = {}
            for v in self._vulns:
                name = v.advisory.severity.name
                by_sev[name] = by_sev.get(name, 0) + 1
            lines.append("")
            lines.append("By severity:")
            for sev in ("CRITICAL", "HIGH", "MEDIUM", "LOW"):
                if sev in by_sev:
                    lines.append("  %s: %d" % (sev, by_sev[sev]))

            lines.append("")
            lines.append("Details:")
            self._vulns.sort(key=lambda v: (-v.advisory.cvss, v.advisory.cve_id))
            for v in self._vulns:
                lines.append("  [%s] %s (CVSS %.1f)" % (
                    v.advisory.severity.name, v.advisory.cve_id, v.advisory.cvss))
                lines.append("    Package: %s@%s (%s)" % (
                    v.dependency.name, v.dependency.version,
                    v.dependency.ecosystem.value))
                lines.append("    Title: %s" % v.advisory.title)
                lines.append("    Fix: %s" % v.upgrade_action)
                lines.append("")

        return "\n".join(lines)

    def as_findings(self) -> list[dict[str, Any]]:
        results = []
        for v in self._vulns:
            results.append({
                "cve": v.advisory.cve_id,
                "cwe": v.advisory.cwe,
                "package": v.dependency.name,
                "version": v.dependency.version,
                "ecosystem": v.dependency.ecosystem.value,
                "severity": v.advisory.severity.name,
                "cvss": v.advisory.cvss,
                "title": v.advisory.title,
                "fixed_version": v.advisory.fixed_version,
                "source_file": v.dependency.source_file,
                "fixable": v.is_fixable,
            })
        return results

def language_for(path: str) -> str | None:
    """Return the scanner language, including common extensionless config files."""
    base = os.path.basename(path).lower()
    ext = os.path.splitext(base)[1].lower()
    if ext in LANG_BY_EXT:
        return LANG_BY_EXT[ext]
    if base in TEXT_BASENAMES or not ext:
        return "text"
    return None

def _shebang_language(path: str, text: str, fallback: str) -> str:
    """Refine extensionless scripts without guessing from arbitrary contents."""
    if os.path.splitext(os.path.basename(path))[1] or not text.startswith("#!"):
        return fallback
    first = text.split("\n", 1)[0].lower()
    if re.search(r"\bpython(?:\d+(?:\.\d+)*)?\b", first):
        return "python"
    if re.search(r"\b(?:node|deno|bun)\b", first):
        return "js"
    if re.search(r"\b(?:runghc|runhaskell)\b", first):
        return "haskell"
    return fallback

def _binary_sample(data: bytes) -> bool:
    """Conservative binary sniff: NUL or a large share of non-text controls."""
    if b"\x00" in data:
        return True
    if not data:
        return False
    controls = sum(byte < 32 and byte not in (8, 9, 10, 12, 13) for byte in data)
    return controls / len(data) > 0.10

def _masked_escape(text: str, index: int) -> tuple[str, int]:
    """Blank a backslash escape without ever swallowing an escaped newline."""
    if index + 1 >= len(text):
        return " ", 1
    following = text[index + 1]
    if following == "\r" and index + 2 < len(text) and text[index + 2] == "\n":
        return " \r\n", 3
    return " " + ("\n" if following == "\n" else " "), 2

def blank_js(text: str) -> list[str]:
    """Like blank_c_like, but also blanks template literals (backtick strings)."""
    out, i, n = [], 0, len(text)
    in_block = in_line = in_s = in_d = in_t = False
    cur = []
    while i < n:
        c = text[i]
        nxt = text[i + 1] if i + 1 < n else ""
        if in_line:
            cur.append(c if c == "\n" else " ")
            if c == "\n":
                in_line = False
        elif in_block:
            if c == "*" and nxt == "/":
                in_block = False; cur.append("  "); i += 2; continue
            cur.append("\n" if c == "\n" else " ")
        elif in_s:
            if c == "\\":
                masked, width = _masked_escape(text, i)
                cur.append(masked); i += width; continue
            cur.append("'" if c == "'" else ("\n" if c == "\n" else " "))
            if c == "'":
                in_s = False
        elif in_d:
            if c == "\\":
                masked, width = _masked_escape(text, i)
                cur.append(masked); i += width; continue
            cur.append('"' if c == '"' else ("\n" if c == "\n" else " "))
            if c == '"':
                in_d = False
        elif in_t:
            if c == "\\":
                masked, width = _masked_escape(text, i)
                cur.append(masked); i += width; continue
            cur.append("`" if c == "`" else ("\n" if c == "\n" else " "))
            if c == "`":
                in_t = False
        else:
            if c == "/" and nxt == "/":
                in_line = True; cur.append("  "); i += 2; continue
            if c == "/" and nxt == "*":
                in_block = True; cur.append("  "); i += 2; continue
            if c == "'":
                in_s = True; cur.append("'")
            elif c == '"':
                in_d = True; cur.append('"')
            elif c == "`":
                in_t = True; cur.append("`")
            else:
                cur.append(c)
        i += 1
    return "".join(cur).split("\n")

def _comments_asm_like(text: str, hlasm: bool = False) -> list[str]:
    """Blank only the comments in assembly, keeping quoted operands intact.

    `blank_asm`/`blank_hlasm` blank literals too, which is right for matching
    instructions but wrong for this view. A rule reading `ctx.literal` wants the
    operand text: section flags (`.section .data,"awx"`) are directive syntax
    and a payload path (`/bin/sh`) is data the rule is specifically looking for.
    Both survive here; only the trailing comment is removed.
    """
    out: list[str] = []
    in_block = False
    for line in text.split("\n"):
        if hlasm:
            if line[:1] == "*" or line[:2] == ".*":
                out.append(" " * len(line))
                continue
            body, tail = line[:71], " " * max(0, len(line) - 71)
            chars = list(body)
            index, quote, field = 0, None, 0
            while index < len(chars):
                char = chars[index]
                if quote:
                    if char == "'":
                        quote = None
                elif char == "'":
                    quote = char
                elif char == " ":
                    while index < len(chars) and chars[index] == " ":
                        index += 1
                    field += 1
                    if field >= 3:
                        for blank_at in range(index, len(chars)):
                            chars[blank_at] = " "
                        break
                    continue
                index += 1
            out.append("".join(chars) + tail)
            continue
        chars = list(line)
        index, quote = 0, None
        while index < len(chars):
            char = chars[index]
            nxt = chars[index + 1] if index + 1 < len(chars) else ""
            if in_block:
                if char == "*" and nxt == "/":
                    chars[index] = chars[index + 1] = " "
                    in_block = False
                    index += 2
                    continue
                chars[index] = " "
            elif quote:
                if char == "\\":
                    index += 2
                    continue
                if char == quote:
                    quote = None
            elif char in "\"'":
                quote = char
            elif char == "/" and nxt == "*":
                chars[index] = chars[index + 1] = " "
                in_block = True
                index += 2
                continue
            elif char in ";#" or (char == "/" and nxt == "/"):
                for blank_at in range(index, len(chars)):
                    chars[blank_at] = " "
                break
            index += 1
        out.append("".join(chars))
    return out

def _comments_c_like(text: str, javascript: bool = False) -> list[str]:
    """Blank comments while preserving literals for rules that inspect values."""
    cur, i, n = [], 0, len(text)
    in_block = in_line = False
    quote = None
    while i < n:
        c = text[i]
        nxt = text[i + 1] if i + 1 < n else ""
        if in_line:
            cur.append("\n" if c == "\n" else " ")
            if c == "\n":
                in_line = False
            i += 1
            continue
        if in_block:
            if c == "*" and nxt == "/":
                cur.append("  "); i += 2; in_block = False; continue
            cur.append("\n" if c == "\n" else " "); i += 1; continue
        if quote:
            cur.append(c)
            if c == "\\" and i + 1 < n:
                cur.append(text[i + 1]); i += 2; continue
            if c == quote:
                quote = None
            i += 1
            continue
        if c == "/" and nxt == "/":
            cur.append("  "); i += 2; in_line = True; continue
        if c == "/" and nxt == "*":
            cur.append("  "); i += 2; in_block = True; continue
        if c in ("'", '"') or javascript and c == "`":
            quote = c
        cur.append(c); i += 1
    return "".join(cur).split("\n")

def _comments_python(text: str) -> list[str]:
    """Comments replaced by spaces; string contents kept as they are.

    The three-character slice is taken only at a quote, for the reason given
    in `blank_python`, and guarded by the same equivalence test.
    """
    cur, i, n = [], 0, len(text)
    in_line = False
    triple = single = None
    while i < n:
        c = text[i]
        if in_line:
            cur.append("\n" if c == "\n" else " ")
            if c == "\n":
                in_line = False
            i += 1; continue
        if triple:
            if c == triple[0] and text[i:i + 3] == triple:
                cur.append(triple); i += 3; triple = None; continue
            cur.append(c)
            if c == "\\" and i + 1 < n:
                cur.append(text[i + 1]); i += 2; continue
            i += 1; continue
        if single:
            cur.append(c)
            if c == "\\" and i + 1 < n:
                cur.append(text[i + 1]); i += 2; continue
            if c == single:
                single = None
            i += 1; continue
        if c == "#":
            cur.append(" "); i += 1; in_line = True; continue
        if c == "'" or c == '"':
            three = text[i:i + 3]
            if three == '"""' or three == "'''":
                triple = three; cur.append(three); i += 3; continue
            single = c
        cur.append(c); i += 1
    return "".join(cur).split("\n")

def blank_comments(text: str, lang: str) -> list[str]:
    """Preserve code and literals but erase comments, retaining exact line mapping."""
    if lang == "asm" or lang == "hlasm":
        return _comments_asm_like(text, hlasm=(lang == "hlasm"))
    if lang == "python":
        return _comments_python(text)
    if lang == "js":
        return _comments_c_like(text, javascript=True)
    if lang == "haskell":
        return _comments_haskell(text)
    if lang in ("c", "cpp", "java", "go", "rust", "csharp"):
        return _comments_c_like(text)
    if lang in ("asm", "hlasm"):
        return _comments_asm_like(text, hlasm=(lang == "hlasm"))
    return text.split("\n")

def _python_symbols(ctx: Ctx, joined: str) -> None:
    """Names through which a Python file can reach hashlib or a boolean flag."""
    for match in PY_HASHLIB_IMPORT.finditer(joined):
        ctx.hash_module_aliases.add(match.group(1) or "hashlib")
    for match in PY_HASHLIB_FROM.finditer(joined):
        for piece in match.group(1).split(","):
            parts = piece.replace("(", " ").replace(")", " ").split()
            if not parts:
                continue
            imported = parts[0]
            bound = parts[2] if len(parts) >= 3 and parts[1] == "as" else imported
            if imported in WEAK_HASH_NAMES:
                ctx.weak_hash_names.add(bound)
            elif imported == "new":
                ctx.hash_module_aliases.add("")   # bare new(...) is ambiguous
    # Only column-zero assignments count: a module constant, not a local whose
    # value we would have to scope-track to know.
    for match in PY_MODULE_FLAG.finditer(joined):
        target = ctx.true_flags if match.group(2) == "True" else ctx.false_flags
        target.add(match.group(1))

def _polymorphic_classes(code: list[str]) -> set:
    """Names of class/struct types whose body mentions virtual/override."""
    result, current, depth_at_open = set(), None, None
    depth = 0
    for line in code:
        if current is None:
            m = CLASS_HEAD.search(line)
            if m and "{" in line.split(m.group(0), 1)[-1] or (m and "{" in line):
                current = m.group(1)
                depth = line.count("{") - line.count("}")
                if re.search(r"\b(virtual|override)\b", line):
                    result.add(current)
                if depth <= 0:
                    current = None
            elif m:
                current = m.group(1)   # body opens on a later line
                depth = 0
        else:
            depth += line.count("{") - line.count("}")
            if re.search(r"\b(virtual|override)\b", line):
                result.add(current)
            if depth <= 0:
                current = None
    return result

def _block_lines(code: list[str], start_idx: int) -> Iterable[tuple[int, str]]:
    """Yield (idx, line) for the brace-delimited block starting at/after start_idx."""
    depth, started = 0, False
    for idx in range(start_idx, len(code)):
        line = code[idx]
        depth += line.count("{") - line.count("}")
        if "{" in line:
            started = True
        if started:
            yield idx, line
        if started and depth <= 0:
            return

def covered_cwes(rule_id: str) -> tuple[str, ...]:
    """Every weakness class a rule legitimately detects, primary first."""
    primary = RULE_CWE.get(rule_id, "")
    extra = RULE_CWE_ALSO.get(rule_id, ())
    return ((primary,) if primary else ()) + tuple(extra)

def _unsigned_here(ctx, index, name):
    """Is `name` unsigned in the scope that line `index` belongs to?

    A local declaration decides it, either way -- that is what makes this
    different from the file-wide set, and it is the whole point.
    """
    for start, end, unsigned, signed in ctx.unsigned_scopes:
        if start <= index <= end:
            if name in signed:
                return False              # declared signed right here
            if name in unsigned:
                return True
            break                        # in a function, not declared here
    return name in ctx.unsigned_vars

def _expand(text, macros, rounds=3):
    """Substitute object-like macros, bounded so a cycle cannot hang a scan."""
    for _ in range(rounds):
        grown = re.sub(r"\b(\w+)\b",
                       lambda m: macros.get(m.group(1), m.group(0)), text)
        if grown == text:
            break
        text = grown
    return text

def _buffer_names(text):
    """Identifiers in an argument list that could name a buffer.

    Deliberately liberal about position: the tainted buffer arrives as
    `(char *)(data + dataLen)` as often as it arrives as `data`, so anything
    that only matches a bare comma-delimited name misses the common case.
    Type keywords and library helpers are filtered instead.
    """
    return {name for name in re.findall(r"\b([A-Za-z_]\w*)\b", text)
            if name not in _NOT_A_BUFFER}

def _parameter_releasers(code):
    """{function: which parameter it releases} for functions in this file.

    A summary, and the cheapest one that buys anything. Juliet's `_41` family
    moves the second release into a helper::

        static void badSink(twoIntsStruct *data) { free(data); }
        ...
        free(data);
        badSink(data);          /* the second free, invisible locally */

    The corrected variant drops the direct `free` and keeps only the call, so
    the two differ by exactly the thing a local walk cannot see. Restricted to
    callees defined in the same file: a summary of a function whose body is
    not here would be a guess, and guessing a `free` invents double-frees.
    """
    releasers: dict[str, int] = {}
    for name, parameters, start, end in _c_function_defs(code):
        if not parameters:
            continue
        for index in range(start, end + 1):
            match = _RELEASE.search(code[index])
            if not match:
                continue
            released = match.group(1) or match.group(2)
            if released in parameters:
                releasers[name] = parameters.index(released)
                break
    return releasers

def _c_block_span(code, index):
    """Line range of the body controlled by the statement on `index`."""
    opener = None
    for probe in range(index, min(index + 3, len(code))):
        if "{" in code[probe]:
            opener = probe
            break
        if probe > index and code[probe].strip():
            return (probe, probe)             # single statement, no braces
    if opener is None:
        return (index, index)
    depth = 0
    for probe in range(opener, len(code)):
        depth += code[probe].count("{") - code[probe].count("}")
        if depth <= 0:
            return (opener, probe)
    return (opener, len(code) - 1)

def _capacity(text):
    """(element count, element type) for a size expression, or (None, None)."""
    match = _SIZEOF_PRODUCT.match(text.strip())
    if match:
        count = _const_value(match.group(1))
        return (count, match.group(2)) if count is not None else (None, None)
    count = _const_value(text)
    return (count, "char") if count is not None else (None, None)

def _c_function_defs(code):
    """[(name, [parameter names], start, end)] for each function body."""
    defs = []
    for start, end in _c_function_spans(code):
        for probe in (start, start - 1, start - 2):
            if probe < 0 or not code[probe].strip():
                continue
            match = C_FUNCTION_HEADER.match(code[probe])
            if not match:
                continue
            params = []
            for piece in match.group(2).split(","):
                piece = piece.strip()
                if not piece or piece == "void":
                    continue
                found = C_PARAM_NAME.search(piece)
                params.append(found.group(1) if found else "")
            defs.append((match.group(1), params, start, end))
            break
    return defs

def _string_macros(code):
    """{macro: character count} for string-valued #defines."""
    out = {}
    for line in code:
        match = C_STRING_DEFINE.match(line)
        if match:
            out[match.group(1)] = len(match.group(2).replace("\\\\", "\\"))
    return out

def _parameter_capacities(ctx):
    """{(function, parameter index): (count, kind, storage)} from call sites.

    One pass to learn what each function's local buffers hold, recording every
    call that passes one of them onward; the callee's parameter then inherits
    that capacity.  It is deliberately one level deep and only accepts a
    capacity when every call site agrees -- a parameter reached with two
    different sizes is left unknown rather than guessed, because an
    over-confident size here invents overflows in correct code.
    """
    defs = _c_function_defs(ctx.code)
    if not defs:
        return {}
    known = {name for name, _, _, _ in defs}
    inherited: dict[tuple, tuple] = {}

    # One pass only learns what a caller hands its *immediate* callee, which
    # is enough for a two-file split and useless for the chained shapes: in
    # Juliet's 52/53/54 families the buffer is handed a->b->c->d->e and every
    # link but the first is a function forwarding a parameter it was given.
    # Re-running with each round's conclusions seeded back in lets the size
    # travel the whole chain. It converges quickly -- the longest chain here
    # is five -- and the round cap is what guarantees it stops at all.
    for _ in range(MAX_PROPAGATION_ROUNDS):
        observed: dict[tuple, set] = {}
        for name, params, start, end in defs:
            seed = {}
            for position, parameter in enumerate(params):
                held = inherited.get((name, position))
                if parameter and held is not None:
                    seed[parameter] = held
            sizes = _local_capacities(ctx.code, start, end, seed=seed)
            for index in range(start, end + 1):
                call = C_CALL.search(ctx.code[index])
                if not call or call.group(1) not in known:
                    continue
                for position, argument in enumerate(call.group(2).split(",")):
                    held = sizes.get(argument.strip())
                    if held is not None:
                        observed.setdefault((call.group(1), position),
                                            set()).add(held)
        # A parameter reached with two different sizes stays unknown: guessing
        # the smaller one invents overflows in code that is correct.
        settled = {key: next(iter(values)) for key, values in observed.items()
                   if len(values) == 1}
        if settled == inherited:
            break
        inherited = settled
    return inherited

def _py_route_handlers(code):
    """(path, name, params, start, end, decorators) for each web route."""
    handlers = []
    for index, line in enumerate(code):
        match = PY_ROUTE_DECORATOR.match(line)
        if not match:
            continue
        decorators, probe = [line], index
        while probe + 1 < len(code):
            probe += 1
            text = code[probe]
            if not text.strip():
                continue
            if text.lstrip().startswith("@"):
                decorators.append(text)
                continue
            break
        definition = PY_DEF.match(code[probe]) if probe < len(code) else None
        if not definition:
            continue
        indent = len(definition.group(1))
        end = probe
        for tail in range(probe + 1, len(code)):
            text = code[tail]
            if text.strip() and (len(text) - len(text.lstrip())) <= indent:
                break
            end = tail
        params = [piece.split(":")[0].split("=")[0].strip()
                  for piece in definition.group(3).split(",")
                  if piece.strip() and piece.split(":")[0].strip()
                  not in ("self", "cls", "request")]
        handlers.append((match.group(2), definition.group(2), params,
                         probe, end, decorators))
    return handlers

def _note_allocation(kinds, line):
    """Record how `line` allocated something, if it did."""
    declared = BUFFER_DECL.match(line)
    if declared:
        kinds[declared.group(2)] = "stack"
        return
    match = C_ALLOC_KIND.match(line)
    if match:
        for group in ("newarr", "new", "stack", "heap"):
            if match.group(group):
                kinds[match.group(1)] = "stack" if group == "stack" else group
                return
        return
    alias = BUFFER_ALIAS.match(line)
    if alias and alias.group(2) in kinds:
        kinds[alias.group(1)] = kinds[alias.group(2)]

def _releases(line):
    """(routine, name) for a release on this line, or None."""
    match = C_RELEASE.search(line)
    if not match:
        return None
    for group, offset in (("free", 2), ("delarr", 4), ("del", 6)):
        if match.group(group):
            return group, match.group(offset)
    return None

def _logical_call(lines, start_idx, open_col):
    """Join a possibly multi-line call from its '(' at lines[start_idx][open_col]
    until the parens balance, so a rule can see kwargs (like timeout=) passed on a
    continuation line. `lines` is blanked code, so parens inside strings/comments
    are already spaces and never miscount."""
    depth = 0
    buf = []
    for i in range(start_idx, len(lines)):
        segment = lines[i][open_col:] if i == start_idx else lines[i]
        for ch in segment:
            buf.append(ch)
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    return "".join(buf)
        buf.append("\n")
    return "".join(buf)

def _format_arguments(line):
    """Yield (sink, name) where a bare identifier is used as the format."""
    for match in FORMAT_CALL.finditer(line):
        position = FORMAT_SINKS[match.group(1)]
        arguments = _split_arguments(line[match.end():])
        if len(arguments) <= position:
            continue
        candidate = arguments[position]
        # A literal format is the correct spelling, not the defect.
        if _BARE_NAME.match(candidate):
            yield match.group(1), candidate

def r_format(ctx):
    """Fires unless the format argument is provably a literal.

    Scoped per function rather than per file: a name bound to a literal in one
    function says nothing about the same name in the next, and a file-wide set
    would let one corrected function suppress a defect in another.
    """
    for start, end in _c_function_spans(ctx.code):
        for index, line, literal in _literal_format(ctx.code, start, end):
            for _sink, name in _format_arguments(line):
                if name in literal:
                    continue
                yield _f(ctx, index, "format-string", "HIGH",
                         "passing a variable as the format string lets input smuggle in %n/%s and "
                         "read or corrupt memory.", r_format.fix)
                break

def _bound_value(text):
    """A loop bound that is pure arithmetic on literals, or None.

    Deliberately not `eval`. The inputs here are strings out of the file under
    analysis, and a static analyser that evaluates its own input is a worse
    bug than anything it could report -- the character-class guard that would
    make `eval` safe is most of the work of just doing the arithmetic.
    """
    text = text.strip()
    while text.startswith("(") and text.endswith(")"):
        text = text[1:-1].strip()
    if text.isdigit():
        return int(text)
    match = re.fullmatch(r"(\d+)\s*([*/+-])\s*(\d+)", text)
    if not match:
        return None
    left, operator, right = int(match.group(1)), match.group(2), int(match.group(3))
    if operator == "/":
        return left // right if right else None
    return {"*": left * right, "+": left + right, "-": left - right}[operator]

def r_signed_size(ctx):
    """Sign extension into a size parameter.

    The defect model is Juliet's CWE-194 and a real one::

        short data;
        data = -1;                     /* or read from input */
        if (data < 100)                /* bounds it above, not below */
            memmove(dest, source, data);

    `data` converts to `size_t` as roughly 2^64, so the copy runs off the end
    of everything. The corrected variants are instructive about what the
    discriminator has to be: one fixes the *source* (`data = 100-1`) and the
    other keeps the negative source and adds `if (data > 0)`. So neither the
    assignment alone nor the call alone separates them -- only "can be
    negative, and nothing has ruled that out by the time it is used".

    An upper bound is not a guard here, and treating `data < 100` as one would
    silence the flawed variant along with the fixed one.
    """
    for start, end in _c_function_spans(ctx.code):
        signed: set[str] = set()
        risky: dict[str, int] = {}
        for index in range(start, end + 1):
            line = ctx.code[index]

            declared = SIGNED_DECL.match(line)
            if declared:
                signed.add(declared.group(1))

            guard = NONNEGATIVE_GUARD.search(line)
            if guard:
                risky.pop(guard.group(1) or guard.group(2), None)

            negative = NEGATIVE_ASSIGN.match(line)
            if negative and negative.group(1) in signed:
                risky[negative.group(1)] = index
            else:
                source = COMMAND_TAINT_SOURCE.search(line)
                if source:
                    # `fscanf(stdin, "%hd", &data)` fills a signed variable
                    # with whatever was typed, which includes negatives.
                    for name in re.findall(r"&\s*(\w+)", line):
                        if name in signed:
                            risky[name] = index
                target = _ASSIGN_TARGET.match(line)
                if target and target.group(1) in signed and not negative:
                    # Reassigned from something that is not a negative
                    # literal; no longer known to be negative.
                    if not source:
                        risky.pop(target.group(1), None)

            if not risky:
                continue
            call = SIZE_CALL.search(line)
            if not call:
                continue
            position = SIZE_SINKS[call.group(1)]
            arguments = _split_arguments(line[call.end():])
            if len(arguments) <= position:
                continue
            candidate = arguments[position].strip()
            if candidate in risky:
                yield _f(ctx, index, "c-signed-size", "HIGH",
                         "'%s' is signed and may be negative here; passing it "
                         "as the size argument of %s converts it to an "
                         "enormous unsigned value."
                         % (candidate, call.group(1)), r_signed_size.fix)
                risky.pop(candidate, None)

def _java_param_names(declaration):
    """`String data, int count` -> {"data", "count"}."""
    names = set()
    for part in declaration.split(","):
        found = re.search(r"(\w+)\s*(?:\[\s*\])?\s*\Z", part.strip())
        if found:
            names.add(found.group(1))
    return names

def _java_step_container_taint(tainted, line):
    """Taint a container that a tainted value was just placed into."""
    for pattern in (JAVA_ELEMENT_ASSIGN, JAVA_MEMBER_ASSIGN):
        holder = pattern.match(line)
        if holder:
            right = line[holder.end():]
            if any(re.search(r"\b%s\b" % re.escape(name), right)
                   for name in tainted):
                tainted.add(holder.group(1))
            return
    for holder in JAVA_CONTAINER_ADD.finditer(line):
        if any(re.search(r"\b%s\b" % re.escape(name), holder.group(2))
               for name in tainted):
            tainted.add(holder.group(1))

def r_java_numeric_truncation(ctx):
    """A cast that discards bits of a value the caller chose.

    The cast is identical in both halves of every one of Juliet's 726 cases
    -- `(byte) data` on both sides -- so what separates them is only where
    `data` came from. That makes this a taint rule, not a pattern rule.

    Whether a cast truncates depends on the *declared width of the operand*,
    which is why the declarations are tracked: `(int) longValue` loses bits
    and `(int) shortValue` cannot. A rule that fired on the cast alone would
    report every widening conversion in the codebase.
    """
    declared: dict[str, str] = {}
    unbounded: set[str] = set()
    for index, line, tainted in _java_taint(
            ctx.code, unbounded, external=ctx.cross_file_taint):
        for kind, name in JAVA_PRIMITIVE_DECL.findall(line):
            declared[name] = kind
        for target, name in JAVA_NARROWING_CAST.findall(line):
            source = declared.get(name)
            if source is None:
                continue
            if JAVA_PRIMITIVE_WIDTH[target] >= JAVA_PRIMITIVE_WIDTH[source]:
                continue          # widening, or same width: nothing is lost
            if name in tainted:
                why = "comes from outside"
            elif name in unbounded:
                why = "has no upper bound"
            else:
                continue
            yield _f(ctx, index, "java-numeric-truncation", "MEDIUM",
                     "'%s' %s and is cast from %s to %s, which silently "
                     "discards the bits that do not fit."
                     % (name, why, source, target),
                     r_java_numeric_truncation.fix)

def r_rust_command_injection(ctx):
    """`multilang.rust-command-shell` covers `Command::new("sh")`; this covers
    a formatted argument to any program, shell or not."""
    for idx, line in enumerate(ctx.code):
        if (re.search(r"\bCommand::new\s*\(|\.arg\s*\(", line)
                and re.search(r"\bformat!\s*\(", line)):
            yield _f(ctx, idx, "rust-command-injection", "HIGH",
                     "a command argument is built with format!, so a value reaching it "
                     "becomes part of the command line.", r_rust_command_injection.fix)

def attack_technique(rule_id: str) -> str:
    """The MITRE ATT&CK technique a rule maps to, or "" if it is not end-stage."""
    return RULE_ATTACK.get(rule_id, "")

def collect_paths(paths: list[str], errors: list[str] | None = None) -> list[str]:
    """Collect safe, supported inputs. Explicit bad inputs are always reported."""
    files: list[str] = []
    own_errors = errors if errors is not None else []
    for p in paths:
        if os.path.isdir(p):
            for root, dirs, names in os.walk(
                    p, onerror=lambda exc: own_errors.append(
                        "%s: cannot traverse: %s" % (getattr(exc, "filename", p), exc))):
                dirs[:] = [name for name in dirs if name not in SKIP_DIRS]
                for nm in sorted(names):
                    candidate = os.path.join(root, nm)
                    if language_for(candidate) is None:
                        continue
                    problem = _input_problem(candidate)
                    if problem is None:
                        files.append(candidate)
                    elif problem.startswith("cannot read"):
                        own_errors.append("%s: %s" % (candidate, problem))
        elif os.path.isfile(p):
            if language_for(p) is None:
                own_errors.append("%s: unsupported input type" % p)
                continue
            problem = _input_problem(p)
            if problem:
                own_errors.append("%s: %s" % (p, problem))
            else:
                files.append(p)
        else:
            own_errors.append("%s: path does not exist" % p)
    if errors is None:
        for message in own_errors:
            print("scan error: " + message, file=sys.stderr)
    return files

def to_sarif(findings: list[Finding]) -> dict:
    """Render findings as SARIF 2.1.0 -- ingestible by GitHub code scanning / CI."""
    used = {}
    for fn in RULES:
        used[fn.rid] = {
            "id": fn.rid,
            "name": fn.rid.replace("-", "_"),
            "shortDescription": {"text": fn.title},
            "defaultConfiguration": {"level": SARIF_LEVEL[fn.severity]},
            "properties": {"languages": list(fn.langs)},
        }
    results = []
    for f in findings:
        results.append({
            "ruleId": f.rule,
            "level": SARIF_LEVEL[f.severity],
            "message": {"text": f"{f.message} Fix: {f.fix}"},
            "locations": [{
                "physicalLocation": {
                    "artifactLocation": {"uri": os.path.relpath(f.path)},
                    "region": {"startLine": f.line, "snippet": {"text": f.snippet}},
                }
            }],
            "properties": {
                "confidence": f.confidence,
                "exploitability": f.exploitability,
                "safe_to_autofix": f.safe_to_autofix,
            },
        })
    return {
        "$schema": "https://json.schemastore.org/sarif-2.1.0.json",
        "version": "2.1.0",
        "runs": [{
            "tool": {"driver": {
                "name": "AttestorVonLuneberg",
                "informationUri": TOOL_URI,
                "version": "3.0.0",
                "rules": list(used.values()),
            }},
            "results": results,
        }],
    }

def settle():
            """Close the current function: anything still owned has leaked."""
            for held, (line_number, _) in owned.items():
                found.append((line_number, held))
            owned.clear()

class AuditChain:
    """Append-only, hash-chained record. Any later edit breaks `verify`."""

    def __init__(self) -> None:
        self._entries: list[dict[str, Any]] = []

    def append(self, *, event: str, actor: str, detail: Mapping[str, Any],
               at: float) -> dict[str, Any]:
        previous = self._entries[-1]["entry_sha256"] if self._entries else GENESIS
        body = {
            "schema": AUDIT_SCHEMA,
            "index": len(self._entries),
            "event": str(event),
            "actor": str(actor),
            "detail": json.loads(canonical_json(detail)),
            "at": round(float(at), 3),
            "prev_sha256": previous,
        }
        entry = dict(body)
        entry["entry_sha256"] = _sha(canonical_json(body) + "|" + previous)
        self._entries.append(entry)
        return entry

    def entries(self) -> tuple[dict[str, Any], ...]:
        return tuple(self._entries)

    def verify(self) -> tuple[bool, list[str]]:
        problems: list[str] = []
        previous = GENESIS
        for position, entry in enumerate(self._entries):
            if entry.get("index") != position:
                problems.append("entry %d has wrong index" % position)
            if entry.get("prev_sha256") != previous:
                problems.append("entry %d does not chain" % position)
            body = {k: v for k, v in entry.items() if k != "entry_sha256"}
            if entry.get("entry_sha256") != _sha(
                    canonical_json(body) + "|" + entry.get("prev_sha256", "")):
                problems.append("entry %d digest does not match" % position)
            previous = entry.get("entry_sha256", "")
        return (not problems), problems

class Asset:
    """One piece of infrastructure the organization has authorized us to defend.

    `scopes` are opaque prefix tokens (a hostname, a CIDR string, a segment id).
    A target matches this asset only if it begins with one of them. `max_tier`
    caps how strong a response this specific asset permits; `collateral_tolerance`
    caps the modelled blast radius. `is_synthetic` marks lab infrastructure and
    is the only thing the aggressive tier may ever touch.
    """
    asset_id: str
    owner: str
    scopes: tuple[str, ...]
    max_tier: int = 2
    collateral_tolerance: int = 40
    is_synthetic: bool = False

    def __post_init__(self) -> None:
        if not _ID_RE.fullmatch(self.asset_id):
            raise EmergencyError("asset_id is not a valid identifier")
        if not self.owner.strip():
            raise EmergencyError("asset owner is required")
        if not self.scopes:
            raise EmergencyError("an asset must declare at least one scope")
        for scope in self.scopes:
            if scope in ("", "*") or not _SCOPE_RE.fullmatch(scope):
                raise EmergencyError("scope %r is not a bounded, explicit token" % scope)
        if not 0 <= self.max_tier <= 4:
            raise EmergencyError("max_tier out of range")
        if self.is_synthetic and self.owner != SYNTHETIC_OWNER:
            raise EmergencyError("synthetic assets must be owned by %r" % SYNTHETIC_OWNER)
        if not self.is_synthetic and self.max_tier > MAX_REAL_TIER:
            raise EmergencyError("a real asset may not authorize the simulation-only tier")

    def covers(self, target: str) -> bool:
        return any(target == s or target.startswith(s) for s in self.scopes)

class Registry:
    """The set of authorized assets. A target outside every scope is refused."""

    def __init__(self, assets: Sequence[Asset]) -> None:
        seen: dict[str, Asset] = {}
        for asset in assets:
            if asset.asset_id in seen:
                raise EmergencyError("duplicate asset_id %r" % asset.asset_id)
            seen[asset.asset_id] = asset
        self._assets = seen

    def resolve(self, target: str) -> Asset | None:
        if not isinstance(target, str) or not _SCOPE_RE.fullmatch(target or ""):
            return None
        matches = [a for a in self._assets.values() if a.covers(target)]
        # An ambiguous target (covered by two assets) is a misidentification
        # risk, so it is treated as unresolved rather than guessed.
        return matches[0] if len(matches) == 1 else None

    def digest(self) -> str:
        return digest_json([
            {"id": a.asset_id, "owner": a.owner, "scopes": list(a.scopes),
             "max_tier": a.max_tier, "synthetic": a.is_synthetic}
            for a in sorted(self._assets.values(), key=lambda x: x.asset_id)])

def _refresh_expiry(self) -> None:
        """Fail closed on time: an authorization past its limit is not in force."""
        if self._state == AUTHORIZED and self._auth is not None:
            if self._clock() >= self._auth.expires_at:
                self._state = EXPIRED
                self._audit.append(event="expire", actor="system",
                                   detail={"reason": "authorization time limit reached"},
                                   at=self._clock())
        elif self._state == ARMED:
            if self._clock() >= self._declared_at + self._arming_window:
                self._state = ABORTED
                self._audit.append(event="abort", actor="system",
                                   detail={"reason": "arming window lapsed without authorization"},
                                   at=self._clock())

def deterministic_json(value: Mapping[str, Any], *, pretty: bool = False) -> str:
    """Return canonical JSON suitable for report persistence or hashing."""
    if pretty:
        return json.dumps(value, sort_keys=True, indent=2, ensure_ascii=False,
                          allow_nan=False) + "\n"
    return _canonical(value).decode("utf-8")

def verify_report(report: Mapping[str, Any]) -> tuple[bool, list[str]]:
    """Verify schema and deterministic digest; this is integrity, not authenticity."""
    errors: list[str] = []
    if type(report) is not dict:
        return False, ["report is not a JSON object"]
    if report.get("schema") != SCHEMA or report.get("version") != VERSION:
        errors.append("unsupported engineering schema or version")
    digest = report.get("report_sha256")
    body = {key: value for key, value in report.items() if key != "report_sha256"}
    try:
        expected = _sha(body)
    except EngineeringError:
        errors.append("report contains non-JSON evidence")
    else:
        if digest != expected:
            errors.append("report digest mismatch")
    return not errors, errors

def _function_nodes(node: ast.AST) -> Iterable[ast.AST]:
    """Walk one function while excluding nested function and class bodies."""
    stack = list(reversed(getattr(node, "body", [])))
    while stack:
        current = stack.pop()
        yield current
        if isinstance(current, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda,
                                ast.ClassDef)):
            continue
        stack.extend(reversed(list(ast.iter_child_nodes(current))))

def _parse(text: str) -> dict[str, str]:
    """Parse an env file, dropping malformed and non-allowlisted entries."""
    out: dict[str, str] = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if line.lower().startswith("export "):
            line = line[len("export "):].lstrip()
        if "=" not in line:
            continue
        key, _, value = line.partition("=")
        key = key.strip()
        value = value.strip()
        if not _KEY_RE.fullmatch(key) or key not in ALLOWED_KEYS:
            continue
        if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
            value = value[1:-1]
        # Environment values cannot contain NUL. Newlines would also allow a
        # confusing value to masquerade as another setting in diagnostics.
        if "\x00" in value or "\r" in value or "\n" in value:
            continue
        out[key] = value
    return out

def run(
        selection: str = ALL_SCENARIOS,
        *,
        simulation_confirmed: bool = False,
) -> dict[str, Any]:
    """Run only the compiled abstract policy simulation."""
    if type(simulation_confirmed) is not bool:
        raise EscapeLabError("simulation confirmation must be a literal boolean")
    if type(selection) is not str:
        raise EscapeLabError("escape-lab scenario selection must be exact text")
    profile_sha256, language = _profile_metadata()
    base = {
        "schema": SCHEMA,
        "version": VERSION,
        "profile": PROFILE_SLUG,
        "profile_sha256": profile_sha256,
        "response_language": language,
        "selection": selection,
        "mode": "private-in-memory-policy-graph",
        "objective": (
            "Find paths to a synthetic outside state and explain the planted "
            "policy defects without attempting a real escape."),
        "controls": dict(_CONTROLS),
        "limits": {
            "max_graph_nodes": MAX_GRAPH_NODES,
            "max_graph_edges": MAX_GRAPH_EDGES,
            "max_path_steps": MAX_PATH_STEPS,
            "max_report_bytes": MAX_REPORT_BYTES,
        },
    }
    if not simulation_confirmed:
        body = {
            **base,
            "status": "simulation-confirmation-required",
            "simulation_confirmed": False,
            "scenario_results": [],
            "summary": {
                "scenarios": 0,
                "simulated_escapes": 0,
                "contained": 0,
            },
        }
        return {**body, "report_sha256": _sha(body)}
    results = [_solve(item) for item in _selected(selection)]
    escapes = sum(row["escaped_simulation"] is True for row in results)
    body = {
        **base,
        "status": "simulated-escape-demonstrated" if escapes else "contained",
        "simulation_confirmed": True,
        "scenario_results": results,
        "summary": {
            "scenarios": len(results),
            "simulated_escapes": escapes,
            "contained": len(results) - escapes,
        },
    }
    return {**body, "report_sha256": _sha(body)}

def _root_identity(value: Any) -> str:
    """Return one deterministic, non-resolving identity for a report root."""
    raw = _text(value, 8_000)
    normalized = os.path.normcase(os.path.normpath(raw)) if raw else ""
    return _sha({"normalized_report_root": normalized.replace("\\", "/")})

def _verified_for_export(report: Mapping[str, Any]) -> None:
        """Fail closed through the verifier that owns the report schema."""
        if report.get("schema") == "attestor-research/4.1":
            try:
                import research_engine41
                valid, _errors = research_engine41.verify_report(report)
            except (ImportError, OSError, RuntimeError, TypeError, ValueError) as exc:
                raise EvidenceStoreError("research report verification could not run") from exc
            if valid is not True:
                raise EvidenceStoreError("canonical export refused: research evidence is invalid")
            return
        try:
            import truth_guard41
            result = truth_guard41.verify_guarded(report, require_fresh=True)
        except (ImportError, OSError, RuntimeError, TypeError, ValueError) as exc:
            raise EvidenceStoreError("canonical report verification could not run") from exc
        if not isinstance(result, Mapping) or result.get("ok") is not True \
                or result.get("fresh") is not True:
            raise EvidenceStoreError("canonical export refused: report evidence is not fresh and verified")

class SignedTranscript:
    """Append-only HMAC-authenticated SHA-256 event chain."""

    def __init__(self, signing_key: bytes, clock_ns: Callable[[], int] = time.time_ns):
        if not isinstance(signing_key, bytes) or len(signing_key) < 32:
            raise FabricError("transcript signing key must contain at least 32 bytes")
        self._key = signing_key
        self._clock_ns = clock_ns
        self._entries: list[dict[str, Any]] = []

    def append(self, event: str, payload: Mapping[str, Any]) -> dict[str, Any]:
        if not re.fullmatch(r"[a-z][a-z0-9_.-]{1,63}", event):
            raise FabricError("invalid transcript event")
        body = {
            "schema": SCHEMA,
            "sequence": len(self._entries),
            "timestamp_ns": int(self._clock_ns()),
            "event": event,
            "payload": _redact_tree(dict(payload)),
            "previous_hash": self._entries[-1]["event_hash"] if self._entries else ZERO_HASH,
        }
        event_hash = _sha(_canonical(body))
        entry = {
            **body,
            "event_hash": event_hash,
            "signature": hmac.new(self._key, event_hash.encode("ascii"),
                                  hashlib.sha256).hexdigest(),
        }
        self._entries.append(entry)
        return dict(entry)

    def export(self) -> tuple[dict[str, Any], ...]:
        return tuple(json.loads(json.dumps(item)) for item in self._entries)

    @staticmethod
    def verify(entries: Sequence[Mapping[str, Any]], signing_key: bytes) -> bool:
        previous = ZERO_HASH
        for sequence, raw in enumerate(entries):
            try:
                body = {
                    "schema": raw["schema"], "sequence": raw["sequence"],
                    "timestamp_ns": raw["timestamp_ns"], "event": raw["event"],
                    "payload": raw["payload"], "previous_hash": raw["previous_hash"],
                }
                if body["schema"] != SCHEMA or body["sequence"] != sequence:
                    return False
                if body["previous_hash"] != previous:
                    return False
                digest = _sha(_canonical(body))
                if not hmac.compare_digest(str(raw["event_hash"]), digest):
                    return False
                expected = hmac.new(signing_key, digest.encode("ascii"),
                                    hashlib.sha256).hexdigest()
                if not hmac.compare_digest(str(raw["signature"]), expected):
                    return False
                previous = digest
            except (KeyError, TypeError, ValueError):
                return False
        return True

def transcript_verification_key(self) -> bytes:
        """Return a copy for the caller's evidence store; it is never serialized."""
        return bytes(self._signing_key)

def run(self, request: ExecutionRequest,
            authorization: ExecutionAuthorization | None = None) -> ExecutionResult:
        """Run against a read-only bind mount; the caller's workspace cannot be mutated."""
        return self._run(request, authorization, writable_workspace=False)

class ChainBuilder:
    """Builds exploit chains from findings."""

    def __init__(self, max_chain_length: int = 6,
                 max_chains: int = 50):
        self._findings: list[ChainFinding] = []
        self._max_chain_length = max_chain_length
        self._max_chains = max_chains

    def add_finding(self, cwe: int, rule: str, file_path: str,
                    line: int, **kwargs) -> ChainFinding:
        f = ChainFinding(cwe=cwe, rule=rule, file_path=file_path,
                         line=line, **kwargs)
        self._findings.append(f)
        return f

    def add_findings(self, findings: list[dict[str, Any]]) -> int:
        count = 0
        for f in findings:
            cwe = f.get("cwe", 0)
            if isinstance(cwe, str):
                import re
                m = re.search(r"(\d+)", cwe)
                cwe = int(m.group(1)) if m else 0
            if cwe <= 0:
                continue
            self.add_finding(
                cwe=cwe,
                rule=f.get("rule", "unknown"),
                file_path=f.get("file_path", f.get("path", "")),
                line=f.get("line", 0),
                severity=f.get("severity", "HIGH"),
                message=f.get("message", ""),
                snippet=f.get("snippet", ""),
                language=f.get("language", "unknown"),
            )
            count += 1
        return count

    def add_from_detect(self, findings: list) -> int:
        count = 0
        for f in findings:
            cwe_str = getattr(f, "cwe", "") or ""
            import re
            m = re.search(r"(\d+)", str(cwe_str))
            if not m:
                continue
            self.add_finding(
                cwe=int(m.group(1)),
                rule=getattr(f, "rule", "unknown"),
                file_path=getattr(f, "path", ""),
                line=getattr(f, "line", 0),
                severity=getattr(f, "severity", "HIGH"),
                message=getattr(f, "message", ""),
                snippet=getattr(f, "snippet", ""),
            )
            count += 1
        return count

    def build(self) -> list[KillChain]:
        if not self._findings:
            return []

        impact_map: dict[Impact, list[ChainFinding]] = {}
        for f in self._findings:
            for impact in f.impacts:
                impact_map.setdefault(impact, []).append(f)

        chains: list[KillChain] = []
        seen_chain_ids: set[str] = set()

        for finding in self._findings:
            if finding.stage != ChainStage.INITIAL_ACCESS:
                continue

            for impact in finding.impacts:
                initial_step = ChainStep(
                    finding=finding,
                    stage=finding.stage,
                    impact_achieved=impact,
                )
                self._extend_chain(
                    [initial_step], impact, impact_map,
                    chains, seen_chain_ids, {finding.finding_id})

        chains.sort(key=lambda c: (-c.cvss_estimate, -c.length))
        return chains[:self._max_chains]

    def _extend_chain(self, current_steps: list[ChainStep],
                      current_impact: Impact,
                      impact_map: dict[Impact, list[ChainFinding]],
                      chains: list[KillChain],
                      seen: set[str],
                      used_findings: set[str]) -> None:
        if len(current_steps) >= self._max_chain_length:
            chain = KillChain(steps=list(current_steps))
            if chain.chain_id not in seen:
                seen.add(chain.chain_id)
                chains.append(chain)
            return

        if len(chains) >= self._max_chains:
            return

        next_impacts = CHAIN_EDGES.get(current_impact, [])
        extended = False

        for next_impact in next_impacts:
            for candidate in self._findings:
                if candidate.finding_id in used_findings:
                    continue
                if next_impact not in candidate.impacts:
                    continue

                step = ChainStep(
                    finding=candidate,
                    stage=candidate.stage,
                    impact_achieved=next_impact,
                )
                current_steps.append(step)
                used_findings.add(candidate.finding_id)

                self._extend_chain(
                    current_steps, next_impact, impact_map,
                    chains, seen, used_findings)

                current_steps.pop()
                used_findings.discard(candidate.finding_id)
                extended = True

        if not extended and len(current_steps) >= 2:
            chain = KillChain(steps=list(current_steps))
            if chain.chain_id not in seen:
                seen.add(chain.chain_id)
                chains.append(chain)

    @property
    def finding_count(self) -> int:
        return len(self._findings)

    def findings_by_impact(self) -> dict[str, int]:
        counts: dict[str, int] = {}
        for f in self._findings:
            for impact in f.impacts:
                name = impact.name
                counts[name] = counts.get(name, 0) + 1
        return counts

    def findings_by_stage(self) -> dict[str, int]:
        counts: dict[str, int] = {}
        for f in self._findings:
            name = f.stage.value
            counts[name] = counts.get(name, 0) + 1
        return counts

class ChainReport:
    """Summary of all discovered chains."""
    chains: list[KillChain]
    total_findings: int = 0

    def summary(self) -> str:
        lines = [
            "=== Exploit Chain Analysis ===",
            "Findings analyzed: %d" % self.total_findings,
            "Chains discovered: %d" % len(self.chains),
        ]

        if self.chains:
            max_cvss = max(c.cvss_estimate for c in self.chains)
            max_len = max(c.length for c in self.chains)
            lines.append("Highest CVSS: %.1f" % max_cvss)
            lines.append("Longest chain: %d steps" % max_len)

            impact_counts: dict[str, int] = {}
            for c in self.chains:
                name = c.final_impact.name
                impact_counts[name] = impact_counts.get(name, 0) + 1
            lines.append("")
            lines.append("Final impacts:")
            for name, count in sorted(impact_counts.items(), key=lambda x: -x[1]):
                lines.append("  %s: %d chains" % (name, count))

            lines.append("")
            lines.append("Top 5 chains:")
            for i, chain in enumerate(self.chains[:5], 1):
                cwes = " -> ".join("CWE-%d" % c for c in chain.cwes)
                lines.append("  %d. [CVSS %.1f] %s -> %s" % (
                    i, chain.cvss_estimate, cwes, chain.final_impact.name))

        return "\n".join(lines)

    def critical_chains(self) -> list[KillChain]:
        return [c for c in self.chains if c.cvss_estimate >= 9.0]

    def rce_chains(self) -> list[KillChain]:
        return [c for c in self.chains
                if c.final_impact in (Impact.REMOTE_CODE_EXECUTION,
                                      Impact.FULL_COMPROMISE)]

def _rules(source: str, target: str) -> list[str]:
    """Rule names Attestor reports for a source, using the module's own scanner."""
    return list(vr._scan_source(source, target))

def _python_surface(source: str) -> dict[tuple[str, str], str]:
    """Return the module-level callable surface that a repair must preserve."""
    tree = ast.parse(source)
    surface = {}
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            kind = "async-function" if isinstance(node, ast.AsyncFunctionDef) else "function"
            signature = ast.dump(node.args, annotate_fields=True,
                                 include_attributes=False)
            surface[(kind, node.name)] = signature
        elif isinstance(node, ast.ClassDef):
            bases = ast.dump(ast.Tuple(elts=node.bases, ctx=ast.Load()),
                             annotate_fields=True, include_attributes=False)
            surface[("class", node.name)] = bases
    return surface

def _bounded_int(value: Any, low: int, high: int) -> int:
    """Accept only an exact integer; a float score is not trusted to be stable."""
    if type(value) is not int or isinstance(value, bool):
        return low
    return low if value < low else (high if value > high else value)

def _calibrated_score(finding: Mapping[str, Any]) -> int | None:
    """Empirical probability in fixed point, or None when calibration abstained."""
    evidence = finding.get("confidence_calibration")
    if type(evidence) is not dict or evidence.get("state") != "calibrated":
        return None
    probability = evidence.get("calibrated_probability")
    if type(probability) not in (int, float) or isinstance(probability, bool):
        return None
    if not 0.0 <= float(probability) <= 1.0:
        return None
    # Cross the float boundary exactly once, then stay in integers.
    return int(round(float(probability) * SCALE))

def _identity(finding: Mapping[str, Any], position: int) -> tuple[str, str, int, int]:
    """Stable tie-break: identical scores must order identically everywhere."""
    return (_text(finding.get("fingerprint"), 64),
            _text(finding.get("path"), 320),
            _bounded_int(finding.get("line"), 0, 2_000_000_000),
            position)

def verify_descriptor(value: Any) -> tuple[bool, list[str]]:
    """Recompute a ranking descriptor's identity and internal consistency."""
    errors: list[str] = []
    if not isinstance(value, Mapping):
        return False, ["descriptor is not a mapping"]
    if value.get("schema") != SCHEMA:
        errors.append("unexpected schema")
    if value.get("policy_sha256") != POLICY_SHA256:
        errors.append("ranking policy identity does not match this build")
    rows = value.get("rows")
    order = value.get("order")
    if type(rows) is not list or type(order) is not list:
        return False, errors + ["rows and order must both be lists"]
    if len(order) != len(rows) or sorted(order) != list(range(len(rows))):
        errors.append("order is not a permutation of rows")
    else:
        previous: int | None = None
        for index in order:
            row = rows[index]
            if type(row) is not dict or type(row.get("score")) is not int:
                errors.append("row score is missing or not an integer")
                break
            if previous is not None and row["score"] > previous:
                errors.append("order is not sorted by descending score")
                break
            previous = row["score"]
    recomputed = _sha({key: item for key, item in value.items()
                       if key != "descriptor_sha256"})
    if value.get("descriptor_sha256") != recomputed:
        errors.append("descriptor digest does not match its content")
    return not errors, errors

#!/usr/bin/env python3
"""
fixmemory.py -- durable memory for repeated safe repair patterns.

When evolve.py sees the same mechanical fix across harvested code, Attestor can
record it as a known repair pattern with counts and examples. This is not model
training; it is a plain, inspectable JSON memory.
"""
from __future__ import annotations

import argparse
import json
import os
import time

DEFAULT_MEMORY = os.path.join(os.path.dirname(os.path.abspath(__file__)), "attestor_fix_memory.json")


def load(path: str = DEFAULT_MEMORY) -> dict:
    if not os.path.exists(path):
        return {"version": 1, "patterns": {}}
    with open(path, encoding="utf-8") as fh:
        return json.load(fh)


def save(memory: dict, path: str = DEFAULT_MEMORY) -> str:
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(memory, fh, indent=2, sort_keys=True)
        fh.write("\n")
    return path


def learn(memory: dict, rid: str, note: str, count: int, source: dict | None = None) -> dict:
    key = note or rid
    patterns = memory.setdefault("patterns", {})
    rec = patterns.setdefault(key, {
        "rule": rid,
        "note": note,
        "count": 0,
        "sources": [],
        "first_seen": time.strftime("%Y-%m-%d"),
        "last_seen": "",
        "promoted": False,
    })
    rec["count"] += int(count)
    rec["last_seen"] = time.strftime("%Y-%m-%d")
    if source:
        example = {
            "repo": source.get("repo") or "unknown",
            "path": source.get("path") or "unknown",
            "url": source.get("url") or "",
        }
        if example not in rec["sources"]:
            rec["sources"].append(example)
        rec["sources"] = rec["sources"][-10:]
    if rec["count"] >= 3:
        rec["promoted"] = True
    return rec


def learn_from_evolve_run(run: dict, path: str = DEFAULT_MEMORY) -> dict:
    memory = load(path)
    for result in run.get("results", []):
        source = result.get("source", {})
        for rid, count, note in result.get("applied", []):
            learn(memory, rid, note, count, source)
    save(memory, path)
    return memory


def render(memory: dict) -> str:
    patterns = memory.get("patterns", {})
    out = ["Fix Memory", "=" * 10]
    if not patterns:
        out.append("No repair patterns recorded yet.")
        return "\n".join(out)
    for key, rec in sorted(patterns.items(), key=lambda item: (-item[1].get("count", 0), item[0])):
        badge = "known repair" if rec.get("promoted") else "observed"
        out.append("  %s x%d [%s] %s" % (
            rec.get("rule") or "unknown", rec.get("count", 0), badge, key))
    return "\n".join(out)


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--memory", default=DEFAULT_MEMORY)
    args = ap.parse_args(argv)
    print(render(load(args.memory)))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

def _review(code: str) -> list:
    """Attestor's verdict: both engines (regex + AST) on the code."""
    return harvest.scan_content(code, ".py")

def _candidate(answer) -> str:
    """Return one actual code candidate, never a provider failure sentinel."""
    values = answer.values() if isinstance(answer, dict) else (answer,)
    for value in values:
        if not isinstance(value, str) or value.startswith("[failed:"):
            continue
        code = brain.strip_fences(value)
        if code.strip():
            return code
    return ""

class FuzzerGen:
    """Generates fuzz test harnesses from findings."""

    def __init__(self):
        self._harnesses: list[FuzzHarness] = []

    def from_finding(self, finding: dict[str, Any]) -> FuzzHarness | None:
        finding = dict(finding)
        cwe = finding.get("cwe", 0)
        if isinstance(cwe, str):
            m = re.search(r"(\d+)", cwe)
            cwe = int(m.group(1)) if m else 0
        finding["cwe"] = cwe

        language = finding.get("language", "python").lower()
        target_type = CWE_FUZZ_TARGET.get(cwe, FuzzTarget.FUNCTION_CALL)
        strategy = CWE_STRATEGY.get(cwe, FuzzStrategy.MUTATION)
        dictionary = CWE_DICTIONARY.get(cwe, [])

        param_name = finding.get("param", finding.get("parameter", "input"))
        inputs = [FuzzInput(
            name=param_name,
            input_type="string",
            dictionary=dictionary,
        )]

        if language in ("python", "py"):
            has_endpoint = finding.get("endpoint") or target_type in (
                FuzzTarget.HTTP_ENDPOINT, FuzzTarget.AUTH_HANDLER)
            if has_endpoint:
                code = _python_http_harness(finding, inputs, dictionary)
            else:
                code = _python_func_harness(finding, inputs, dictionary)
        elif language in ("javascript", "js", "typescript", "ts"):
            code = _js_http_harness(finding, inputs, dictionary)
        elif language in ("java",):
            code = _java_harness(finding, inputs, dictionary)
        else:
            code = _generic_http_harness(finding, inputs, dictionary)

        harness = FuzzHarness(
            name="fuzz_cwe_%d_%s_%d" % (
                cwe, re.sub(r"[^a-z0-9]", "_",
                            finding.get("file_path", "unknown").lower()),
                finding.get("line", 0)),
            target_file=finding.get("file_path", "unknown"),
            target_line=finding.get("line", 0),
            cwe=cwe,
            language=language,
            target_type=target_type,
            strategy=strategy,
            inputs=inputs,
            code=code,
        )
        self._harnesses.append(harness)
        return harness

    def from_findings(self, findings: list[dict[str, Any]]) -> list[FuzzHarness]:
        results = []
        for f in findings:
            h = self.from_finding(f)
            if h:
                results.append(h)
        return results

    @property
    def harnesses(self) -> list[FuzzHarness]:
        return list(self._harnesses)

    def summary(self) -> str:
        lines = [
            "=== Fuzzer Harness Generation ===",
            "Harnesses generated: %d" % len(self._harnesses),
        ]
        if self._harnesses:
            by_lang: dict[str, int] = {}
            by_cwe: dict[int, int] = {}
            for h in self._harnesses:
                by_lang[h.language] = by_lang.get(h.language, 0) + 1
                by_cwe[h.cwe] = by_cwe.get(h.cwe, 0) + 1

            lines.append("")
            lines.append("By language:")
            for lang, count in sorted(by_lang.items()):
                lines.append("  %s: %d" % (lang, count))

            lines.append("")
            lines.append("By CWE:")
            for cwe, count in sorted(by_cwe.items()):
                lines.append("  CWE-%d: %d" % (cwe, count))

        return "\n".join(lines)

def advise(status: int, message: str) -> str:
    """Map an HTTP status (+ Google's error message) to a concrete fix."""
    msg = (message or "").lower()
    if status == 200:
        return "OK."
    if status == 400 and "api key not valid" in msg:
        return ("Your key is wrong or malformed. Generate a fresh one at "
                "aistudio.google.com/app/apikey and re-export GEMINI_API_KEY "
                "(watch for stray spaces/quotes).")
    if status == 400:
        return ("Bad request: %s. Usually a malformed body or a bad model name."
                % (message or "?"))
    if status == 401:
        return "Unauthorized -- the key is missing or rejected. Re-check GEMINI_API_KEY."
    if status == 403:
        return ("The key reached Google but was refused. Either the 'Generative "
                "Language API' is not enabled on the key's project, or the key has "
                "HTTP-referrer / IP restrictions. Enable the API (or loosen the key "
                "restrictions) in the Google Cloud / AI Studio console.")
    if status == 404:
        return ("Model not found for your key. Use an EXACT name from the model list "
                "above, and keep the /v1beta/ path -- old names like 'gemini-pro' 404.")
    if status == 429:
        return ("Rate / quota limit. The free tier caps requests-per-minute and "
                "per-day: use a *flash* model (not pro), respect the retryDelay in the "
                "error, and remember the daily quota resets around midnight Pacific.")
    if status >= 500:
        return "Google-side error (%d). Transient -- retry with backoff." % status
    return "Unexpected status %d: %s" % (status, message or "?")

def _request(url: str, payload=None):
    """Return (status, parsed_body). status 0 means the host was unreachable."""
    data = json.dumps(payload).encode("utf-8") if payload is not None else None
    req = urllib.request.Request(url, data=data,
                                 method="POST" if payload is not None else "GET")
    if payload is not None:
        req.add_header("Content-Type", "application/json")
    context = ssl.create_default_context(cafile=_CA) if _CA else None
    try:
        with urllib.request.urlopen(req, timeout=20, context=context) as resp:
            return resp.status, json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", "replace")
        try:
            return exc.code, json.loads(body)
        except json.JSONDecodeError:
            return exc.code, {"error": {"message": body[:200]}}
    except Exception as exc:                     # noqa: BLE001 -- network/TLS failure
        return 0, {"error": {"message": "%s: %s" % (type(exc).__name__, exc)}}

def _retry_delay(body: dict):
    """Seconds to wait, from a 429 error's RetryInfo; None if absent."""
    for detail in _details(body):
        if isinstance(detail, dict) and detail.get("@type", "").endswith("RetryInfo"):
            m = re.match(r"(\d+(?:\.\d+)?)s", detail.get("retryDelay", ""))
            if m:
                return float(m.group(1))
    return None

def _quota_metric(body: dict) -> str:
    """The name of the exhausted quota (tells per-minute vs per-day)."""
    for detail in _details(body):
        if isinstance(detail, dict) and detail.get("@type", "").endswith("QuotaFailure"):
            violations = detail.get("violations", [])
            if violations:
                v = violations[0]
                return v.get("quotaMetric", "") or v.get("quotaId", "")
    return ""

def _generatable(models_body: dict):
    """Names of models that support generateContent, flash first."""
    out = []
    for m in models_body.get("models", []):
        methods = m.get("supportedGenerationMethods", [])
        if "generateContent" in methods:
            out.append(m.get("name", "").replace("models/", ""))
    out.sort(key=lambda n: (0 if "flash" in n else 1, n))
    return out

class RepoEntry:
    """A repository in the ingestion queue."""
    url: str
    owner: str = ""
    name: str = ""
    status: RepoStatus = RepoStatus.QUEUED
    fetch_method: FetchMethod = FetchMethod.GIT_CLONE
    local_path: str = ""
    files_scanned: int = 0
    findings_count: int = 0
    languages: set[str] = field(default_factory=set)
    error: str = ""
    elapsed: float = 0.0
    sha: str = ""
    stars: int = 0
    size_kb: int = 0
    default_branch: str = "main"

    def __post_init__(self):
        if not self.owner or not self.name:
            self.owner, self.name = parse_github_url(self.url)

    @property
    def full_name(self) -> str:
        return "%s/%s" % (self.owner, self.name)

    @property
    def repo_id(self) -> str:
        return hashlib.sha256(self.full_name.lower().encode()).hexdigest()[:12]

def normalize_github_url(url: str) -> str:
    """Normalize a GitHub URL to https://github.com/owner/repo."""
    owner, name = parse_github_url(url)
    if owner and name:
        return "https://github.com/%s/%s" % (owner, name)
    return url

class GitHubAPI:
    """Minimal GitHub API client. Uses gh CLI or direct HTTP."""

    def __init__(self, token: str | None = None):
        self._token = token or os.environ.get("GITHUB_TOKEN", "")
        self._has_gh = shutil.which("gh") is not None
        self._rate_remaining = 5000
        self._rate_reset = 0.0

    def _headers(self) -> dict[str, str]:
        h = {"Accept": "application/vnd.github.v3+json",
             "User-Agent": "Owen-Attestor/4.2"}
        if self._token:
            h["Authorization"] = "token %s" % self._token
        return h

    def _gh_api(self, endpoint: str) -> dict | list | None:
        """Call GitHub API via gh CLI."""
        if not self._has_gh:
            return None
        try:
            result = subprocess.run(
                ["gh", "api", endpoint, "--paginate"],
                capture_output=True, text=True, timeout=30)
            if result.returncode == 0 and result.stdout.strip():
                return json.loads(result.stdout)
        except (subprocess.TimeoutExpired, json.JSONDecodeError, OSError):
            pass
        return None

    def _http_get(self, url: str) -> dict | list | None:
        """Call GitHub API via urllib (no external deps)."""
        try:
            import urllib.request
            req = urllib.request.Request(url, headers=self._headers())
            with urllib.request.urlopen(req, timeout=15) as resp:
                remaining = resp.headers.get("X-RateLimit-Remaining", "")
                if remaining:
                    self._rate_remaining = int(remaining)
                return json.loads(resp.read().decode())
        except Exception:
            return None

    def get(self, endpoint: str) -> dict | list | None:
        """GET a GitHub API endpoint. Tries gh CLI first, falls back to HTTP."""
        result = self._gh_api(endpoint)
        if result is not None:
            return result
        url = GITHUB_API + endpoint if endpoint.startswith("/") else endpoint
        return self._http_get(url)

    def repo_info(self, owner: str, name: str) -> dict | None:
        data = self.get("/repos/%s/%s" % (owner, name))
        return data if isinstance(data, dict) else None

    def org_repos(self, org: str, max_repos: int = 500) -> list[dict]:
        """List all public repos for an organization."""
        repos = []
        page = 1
        while len(repos) < max_repos:
            data = self.get(
                "/orgs/%s/repos?type=public&per_page=100&page=%d" % (org, page))
            if not data or not isinstance(data, list) or len(data) == 0:
                break
            repos.extend(data)
            if len(data) < 100:
                break
            page += 1
        return repos[:max_repos]

    def user_repos(self, user: str, max_repos: int = 500) -> list[dict]:
        """List all public repos for a user."""
        repos = []
        page = 1
        while len(repos) < max_repos:
            data = self.get(
                "/users/%s/repos?type=public&per_page=100&page=%d" % (user, page))
            if not data or not isinstance(data, list) or len(data) == 0:
                break
            repos.extend(data)
            if len(data) < 100:
                break
            page += 1
        return repos[:max_repos]

    def search_repos(self, query: str, max_results: int = 100) -> list[dict]:
        """Search GitHub repositories."""
        repos = []
        page = 1
        while len(repos) < max_results:
            data = self.get(
                "/search/repositories?q=%s&per_page=100&page=%d" %
                (query.replace(" ", "+"), page))
            if not data or not isinstance(data, dict):
                break
            items = data.get("items", [])
            if not items:
                break
            repos.extend(items)
            if len(items) < 100:
                break
            page += 1
        return repos[:max_results]

    @property
    def rate_remaining(self) -> int:
        return self._rate_remaining

    @property
    def authenticated(self) -> bool:
        return bool(self._token) or self._has_gh

class RepoFetcher:
    """Clones or downloads repository contents to a local directory."""

    def __init__(self, work_dir: str | None = None):
        self._work_dir = work_dir or tempfile.mkdtemp(prefix="owen_ingest_")
        self._has_git = shutil.which("git") is not None

    @property
    def work_dir(self) -> str:
        return self._work_dir

    def fetch(self, entry: RepoEntry) -> str:
        """Fetch repository contents. Returns local path."""
        dest = os.path.join(self._work_dir, entry.repo_id)
        if os.path.exists(dest):
            return dest

        if self._has_git and entry.fetch_method == FetchMethod.GIT_CLONE:
            return self._git_clone(entry, dest)
        return self._api_download(entry, dest)

    def _git_clone(self, entry: RepoEntry, dest: str) -> str:
        clone_url = "https://github.com/%s/%s.git" % (entry.owner, entry.name)
        try:
            subprocess.run(
                ["git", "clone", "--depth", "1", "--single-branch",
                 "--no-tags", clone_url, dest],
                capture_output=True, text=True, timeout=120,
                env={**os.environ, "GIT_TERMINAL_PROMPT": "0"})
        except subprocess.TimeoutExpired:
            raise RuntimeError("git clone timed out for %s" % entry.full_name)

        if not os.path.isdir(dest):
            raise RuntimeError("git clone failed for %s" % entry.full_name)

        git_dir = os.path.join(dest, ".git")
        if os.path.isdir(git_dir):
            shutil.rmtree(git_dir, ignore_errors=True)

        return dest

    def _api_download(self, entry: RepoEntry, dest: str) -> str:
        """Download via GitHub API tarball."""
        import urllib.request
        url = "https://api.github.com/repos/%s/%s/tarball" % (
            entry.owner, entry.name)
        headers = {"User-Agent": "Owen-Attestor/4.2"}
        token = os.environ.get("GITHUB_TOKEN", "")
        if token:
            headers["Authorization"] = "token %s" % token

        tarball = dest + ".tar.gz"
        try:
            req = urllib.request.Request(url, headers=headers)
            with urllib.request.urlopen(req, timeout=60) as resp:
                with open(tarball, "wb") as f:
                    while True:
                        chunk = resp.read(65536)
                        if not chunk:
                            break
                        f.write(chunk)
        except Exception as e:
            raise RuntimeError("API download failed for %s: %s" %
                               (entry.full_name, e))

        os.makedirs(dest, exist_ok=True)
        try:
            import tarfile
            with tarfile.open(tarball, "r:gz") as tf:
                tf.extractall(dest, filter="data")
        except Exception as e:
            raise RuntimeError("tarball extraction failed: %s" % e)
        finally:
            try:
                os.unlink(tarball)
            except OSError:
                pass

        return dest

    def cleanup(self, entry: RepoEntry) -> None:
        dest = os.path.join(self._work_dir, entry.repo_id)
        if os.path.isdir(dest):
            shutil.rmtree(dest, ignore_errors=True)

    def cleanup_all(self) -> None:
        if os.path.isdir(self._work_dir):
            shutil.rmtree(self._work_dir, ignore_errors=True)

def walk_source_files(root: str,
                      max_files: int = MAX_REPO_FILES,
                      ) -> Iterator[tuple[str, str]]:
    """Walk a directory yielding (file_path, language) for scannable files."""
    count = 0
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS]

        for fname in filenames:
            if count >= max_files:
                return

            ext = os.path.splitext(fname)[1].lower()
            if ext not in SCANNABLE_EXTENSIONS:
                continue

            fpath = os.path.join(dirpath, fname)

            try:
                size = os.path.getsize(fpath)
            except OSError:
                continue
            if size > MAX_FILE_SIZE or size == 0:
                continue

            lang = LANG_MAP.get(ext, "unknown")
            count += 1
            yield fpath, lang

def detect_languages(root: str) -> set[str]:
    """Detect programming languages present in a directory."""
    langs = set()
    for _, lang in walk_source_files(root, max_files=500):
        langs.add(lang)
    return langs

def scan_file(file_path: str, language: str,
              repo_root: str = "") -> list[dict[str, Any]]:
    """Scan a single file using detect.py and return findings as dicts."""
    try:
        from detect import scan as detect_scan, Finding, RULE_CWE
    except ImportError:
        try:
            import importlib
            detect = importlib.import_module("detect")
            detect_scan = detect.scan
            Finding = detect.Finding
            RULE_CWE = detect.RULE_CWE
        except ImportError:
            return _fallback_scan(file_path, language)

    try:
        findings = detect_scan(file_path)
    except Exception:
        return []

    results = []
    for f in findings:
        rel_path = f.path
        if repo_root:
            try:
                rel_path = os.path.relpath(f.path, repo_root)
            except ValueError:
                pass

        cwe = RULE_CWE.get(f.rule, "")
        results.append({
            "rule": f.rule,
            "cwe": cwe,
            "path": rel_path,
            "file_path": rel_path,
            "line": f.line,
            "severity": f.severity,
            "message": f.message,
            "fix": f.fix,
            "snippet": f.snippet,
            "language": language,
            "confidence": getattr(f, "confidence", 0.0),
        })

    return results

class RepoScanner:
    """Scans all source files in a fetched repository."""

    def __init__(self, max_files: int = MAX_REPO_FILES):
        self._max_files = max_files

    def scan(self, entry: RepoEntry) -> ScanResult:
        start = time.time()
        all_findings: list[dict[str, Any]] = []
        languages: set[str] = set()
        errors: list[str] = []
        file_count = 0

        root = entry.local_path
        if not os.path.isdir(root):
            return ScanResult(
                repo=entry, findings=[], files_scanned=0,
                languages_found=set(), scan_time=0,
                errors=["local path does not exist: %s" % root])

        for fpath, lang in walk_source_files(root, self._max_files):
            file_count += 1
            languages.add(lang)
            try:
                findings = scan_file(fpath, lang, root)
                for f in findings:
                    f["repo"] = entry.full_name
                    f["repo_url"] = entry.url
                all_findings.extend(findings)
            except Exception as e:
                errors.append("error scanning %s: %s" % (fpath, e))

        return ScanResult(
            repo=entry,
            findings=all_findings,
            files_scanned=file_count,
            languages_found=languages,
            scan_time=time.time() - start,
            errors=errors,
        )

class RepoQueue:
    """Manages the queue of repositories to ingest."""

    def __init__(self):
        self._entries: dict[str, RepoEntry] = {}
        self._order: list[str] = []

    def add(self, url: str, **kwargs) -> RepoEntry:
        url = normalize_github_url(url)
        owner, name = parse_github_url(url)
        entry = RepoEntry(url=url, owner=owner, name=name, **kwargs)
        key = entry.full_name.lower()
        if key not in self._entries:
            self._entries[key] = entry
            self._order.append(key)
        return self._entries[key]

    def add_many(self, urls: list[str]) -> int:
        count = 0
        for url in urls:
            url = url.strip()
            if url and not url.startswith("#"):
                self.add(url)
                count += 1
        return count

    def get(self, full_name: str) -> RepoEntry | None:
        return self._entries.get(full_name.lower())

    def queued(self) -> list[RepoEntry]:
        return [self._entries[k] for k in self._order
                if self._entries[k].status == RepoStatus.QUEUED]

    def all_entries(self) -> list[RepoEntry]:
        return [self._entries[k] for k in self._order]

    def __len__(self) -> int:
        return len(self._entries)

    def __contains__(self, url: str) -> bool:
        owner, name = parse_github_url(url)
        return ("%s/%s" % (owner, name)).lower() in self._entries

def _gh_api(self, endpoint: str) -> dict | list | None:
