def _execute_argv(argv: Sequence[str], cwd: Path, timeout: float,
                  max_output: int) -> CommandResult:
    """Execute a fixed argv while monitoring output files and wall-clock time.

    Temporary files keep child output out of process memory.  The child is
    killed as soon as either output boundary is observed.
    """
    if not isinstance(argv, (list, tuple)) or not argv or not all(
            isinstance(item, str) for item in argv):
        raise GitIntelligenceError("Git argv must be a non-empty text sequence")
    if not isinstance(timeout, (int, float)) or timeout <= 0:
        raise GitIntelligenceError("Git timeout must be positive")
    env = os.environ.copy()
    env.update({
        "GIT_TERMINAL_PROMPT": "0", "GIT_OPTIONAL_LOCKS": "0",
        "GIT_PAGER": "cat", "PAGER": "cat", "GIT_CONFIG_NOSYSTEM": "1",
        "LC_ALL": "C", "LANG": "C",
    })
    env.pop("GIT_EXTERNAL_DIFF", None)
    with tempfile.TemporaryFile() as stdout_file, tempfile.TemporaryFile() as stderr_file:
        try:
            process = subprocess.Popen(
                list(argv), cwd=str(cwd), stdin=subprocess.DEVNULL,
                stdout=stdout_file, stderr=stderr_file, shell=False,
                close_fds=True, env=env,
            )
        except OSError as exc:
            raise GitIntelligenceError("Git could not be started: " + str(exc)[:240]) from exc
        deadline = time.monotonic() + float(timeout)
        reason = ""
        while process.poll() is None:
            if time.monotonic() >= deadline:
                reason = "timeout"
                break
            try:
                if os.fstat(stdout_file.fileno()).st_size > max_output or \
                        os.fstat(stderr_file.fileno()).st_size > MAX_GIT_STDERR:
                    reason = "output"
                    break
            except OSError:
                reason = "output"
                break
            time.sleep(0.01)
        if reason:
            process.kill()
        try:
            process.wait(timeout=2)
        except subprocess.TimeoutExpired:
            process.kill()
            process.wait()
        stdout_size = os.fstat(stdout_file.fileno()).st_size
        stderr_size = os.fstat(stderr_file.fileno()).st_size
        if reason == "timeout":
            raise GitTimeoutError("Git command exceeded its wall-clock timeout")
        if reason == "output" or stdout_size > max_output or stderr_size > MAX_GIT_STDERR:
            raise GitOutputLimitError("Git command exceeded its output boundary")
        stdout_file.seek(0)
        stderr_file.seek(0)
        return CommandResult(process.returncode, stdout_file.read(max_output + 1),
                             stderr_file.read(MAX_GIT_STDERR + 1))

def applied_paths(result: Mapping[str, Any]) -> list[str]:
    """The files a plan result says it actually changed."""
    out = []
    for row in result.get("outcomes", []):
        if isinstance(row, Mapping) and row.get("status") == "applied":
            path = row.get("path")
            if isinstance(path, str) and path.strip():
                out.append(path.strip())
    return sorted(set(out))

def digit(position: int) -> str:
    """The decimal digit of googolplex at `position` (0 = most significant)."""
    if position < 0 or position >= TOTAL_DIGITS:
        raise ValueError("position must be in [0, 10**100]")
    return "1" if position == 0 else "0"

def stream(start: int, count: int):
    """Yield up to `count` digit characters (in chunks) starting at `start`."""
    if start < 0 or count < 0:
        raise ValueError("start and count must be non-negative")
    end = min(start + count, TOTAL_DIGITS)
    position = start
    while position < end:
        if position == 0:
            yield "1"
            position += 1
        else:
            width = min(_CHUNK, end - position)
            yield "0" * width
            position += width

def _detect_findings(path: str) -> list:
    """Regex-engine findings for a real file. Grading a bare snippet passes a
    placeholder path with no file behind it, so the regex engine is skipped and
    only the AST engine runs -- an explicit skip, not a swallowed error."""
    try:
        return detect.scan_file(path)
    except OSError:
        return []

def _static_findings(src: str, path: str) -> list:
    """detect + deepscan + rarebugs findings, deduped by (line, rule)."""
    seen = set()
    unique = []
    for finding in _detect_findings(path) + deepscan.analyze(src, path) + rarebugs.analyze(src, path):
        key = (finding.line, finding.rule)
        if key not in seen:
            seen.add(key)
            unique.append(finding)
    return unique

def _physical_memory_bytes() -> int | None:
    """Total RAM, or None when the platform will not say without a dependency."""
    # POSIX: the arithmetic is exact and needs nothing installed.
    if hasattr(os, "sysconf"):
        try:
            pages = os.sysconf("SC_PHYS_PAGES")
            page_size = os.sysconf("SC_PAGE_SIZE")
            if pages > 0 and page_size > 0:
                return pages * page_size
        except (OSError, ValueError):
            pass
    if sys.platform == "win32":
        try:
            import ctypes

            class _Status(ctypes.Structure):
                _fields_ = [("dwLength", ctypes.c_ulong),
                            ("dwMemoryLoad", ctypes.c_ulong),
                            ("ullTotalPhys", ctypes.c_ulonglong),
                            ("ullAvailPhys", ctypes.c_ulonglong),
                            ("ullTotalPageFile", ctypes.c_ulonglong),
                            ("ullAvailPageFile", ctypes.c_ulonglong),
                            ("ullTotalVirtual", ctypes.c_ulonglong),
                            ("ullAvailVirtual", ctypes.c_ulonglong),
                            ("ullAvailExtendedVirtual", ctypes.c_ulonglong)]

            status = _Status()
            status.dwLength = ctypes.sizeof(_Status)
            if ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(status)):
                return int(status.ullTotalPhys)
        except Exception:                                    # noqa: BLE001
            pass
    return None

def _discrete_gpu() -> bool:
    """True when a discrete accelerator is present.

    Only asks tools that are already installed and reports nothing about which
    card it is. `nvidia-smi` existing at all is close enough -- it ships with
    the driver, and the driver ships with the card.
    """
    if shutil.which("nvidia-smi"):
        try:
            done = subprocess.run(
                ["nvidia-smi", "--query-gpu=count", "--format=csv,noheader"],
                capture_output=True, text=True, timeout=8, check=False)
            if done.returncode == 0 and done.stdout.strip():
                return True
        except (OSError, subprocess.SubprocessError):
            pass
    if shutil.which("rocm-smi"):
        return True
    return False

def _accelerator_memory_bytes() -> int | None:
    """Total accelerator memory across all devices, or None if it cannot be read.

    Asks the same already-installed tools `_discrete_gpu` uses and keeps the
    same discipline: the total is a number this process holds, and what leaves
    `classify` is a boolean. A VRAM figure is far closer to a fingerprint than
    "high" or "standard" is -- 81,559 MiB names a specific card -- so it stays
    local, exactly like the core count and the RAM size already do.

    None means "could not be read", which is not the same as zero and must not
    be rounded into it. A machine that cannot answer has not been shown to be
    below the floor any more than it has been shown to be above it.
    """
    if shutil.which("nvidia-smi"):
        try:
            done = subprocess.run(
                ["nvidia-smi", "--query-gpu=memory.total",
                 "--format=csv,noheader,nounits"],
                capture_output=True, text=True, timeout=8, check=False)
            if done.returncode == 0 and done.stdout.strip():
                total_mib = 0
                for line in done.stdout.splitlines():
                    entry = line.strip()
                    if not entry:
                        continue
                    if not entry.isdigit():
                        # One unparseable row makes the total wrong rather than
                        # merely incomplete, so the whole reading is discarded.
                        return None
                    total_mib += int(entry)
                if total_mib > 0:
                    return total_mib * 1024 * 1024
        except (OSError, ValueError, subprocess.SubprocessError):
            pass
    if shutil.which("rocm-smi"):
        try:
            done = subprocess.run(
                ["rocm-smi", "--showmeminfo", "vram", "--csv"],
                capture_output=True, text=True, timeout=8, check=False)
            if done.returncode == 0 and done.stdout.strip():
                total = 0
                for line in done.stdout.splitlines():
                    for field in line.split(","):
                        value = field.strip()
                        # rocm-smi reports VRAM in bytes; take the widest
                        # plausible integer on each row and ignore the rest.
                        if value.isdigit() and int(value) > 1024 ** 3:
                            total = max(total, int(value))
                if total > 0:
                    return total
        except (OSError, ValueError, subprocess.SubprocessError):
            pass
    return None

def fetch_url(repo: str, ref: str, path: str):
    """Fetch one exact file by repo/ref/path via the contents API."""
    meta = online.github_json(
        f"/repos/{repo}/contents/{urllib.parse.quote(path)}?ref={urllib.parse.quote(ref)}")
    content = base64.b64decode(meta.get("content", "")).decode("utf-8", "replace")
    lic = None
    if isinstance(meta.get("license"), dict):
        lic = meta["license"].get("spdx_id")
    return content, repo, path, meta.get("html_url"), lic or _repo_license(repo)

def improve(content: str):
    """Apply the safe mechanical fixes. Returns (new_content, [(rule, count, note)])."""
    out = content
    applied = []
    for rid, rx, repl, note in SAFE_FIXES:
        out, n = rx.subn(repl, out)
        if n:
            applied.append((rid, n, note))
    return out, applied

def hyperop(n: int, a: int, b: int, _guard: int = 10 ** 6) -> int:
    """
    The nth hyperoperation on non-negative integers:
        n=1 add, n=2 multiply, n=3 power, n=4 tetration, n=5 pentation.
    Only sane for tiny inputs -- anything past a toy example is astronomically
    large, so we cap the magnitude and refuse rather than eat all your memory.
    """
    if n == 1:
        return a + b
    if n == 2:
        return a * b
    if n == 3:
        result = a ** b
        if result > _guard:
            raise OverflowError(f"{a}^{b} = {result} exceeds the demo guard")
        return result
    if b == 0:
        return 1
    # n >= 4: fold the (n-1)th operation b times
    acc = a
    for _ in range(b - 1):
        acc = hyperop(n - 1, a, acc, _guard)
    return acc

def dinosaurs_return() -> bool:
    """The clause is gated on a physically impossible antecedent. It is False."""
    return False

class _Collector(ast.NodeVisitor):
    """Functions, their parameters, their calls, and each call's arguments."""

    def __init__(self) -> None:
        self.functions: dict[str, dict[str, Any]] = {}
        self.calls: list[dict[str, Any]] = []
        self.scope: list[str] = []

    def _owner(self) -> str:
        return ".".join(self.scope)

    def _function(self, node) -> None:
        name = ".".join(self.scope + [node.name])
        if len(self.functions) < MAX_FUNCTIONS:
            arguments = node.args
            positional = [item.arg for item in
                          list(getattr(arguments, "posonlyargs", []))
                          + list(arguments.args)]
            self.functions[name] = {
                "name": name, "line": node.lineno,
                "parameters": positional,
                "keyword_parameters": [item.arg for item in arguments.kwonlyargs],
            }
        self.scope.append(node.name)
        self.generic_visit(node)
        self.scope.pop()

    visit_FunctionDef = _function
    visit_AsyncFunctionDef = _function

    def visit_ClassDef(self, node: ast.ClassDef) -> None:
        self.scope.append(node.name)
        self.generic_visit(node)
        self.scope.pop()

    def visit_Call(self, node: ast.Call) -> None:
        if len(self.calls) < MAX_CALLS:
            self.calls.append({
                "owner": self._owner(),
                "callee": _dotted(node.func),
                "line": node.lineno,
                "arguments": [
                    {"index": index,
                     "names": sorted(_names(argument)),
                     "source": _has_source(argument),
                     "sanitised": _sanitised(argument)}
                    for index, argument in enumerate(node.args)],
                "keywords": [
                    {"name": keyword.arg,
                     "names": sorted(_names(keyword.value)),
                     "source": _has_source(keyword.value),
                     "sanitised": _sanitised(keyword.value)}
                    for keyword in node.keywords if keyword.arg],
            })
        self.generic_visit(node)

def _resolve(callee: str, owner: str, functions: dict[str, Any]) -> str:
    """Resolve a call to a function defined in this module, or "" if external."""
    if callee in functions:
        return callee
    parts = owner.split(".") if owner else []
    while parts:
        candidate = ".".join(parts + [callee])
        if candidate in functions:
            return candidate
        parts.pop()
    tail = callee.rsplit(".", 1)[-1]
    return tail if tail in functions else ""

def split_variants(source: str) -> tuple[str, str] | None:
    """(flawed, fixed) for a paired test case, or None when it is not one."""
    kinds = {match.group(1) for match in _BLOCK.finditer(source)}
    if not {"OMITBAD", "OMITGOOD"} <= kinds:
        return None
    flawed = _BLOCK.sub(
        lambda m: "" if m.group(1) == "OMITGOOD" else m.group(2), source)
    fixed = _BLOCK.sub(
        lambda m: "" if m.group(1) == "OMITBAD" else m.group(2), source)
    return flawed, fixed

def split_variants_java(source: str) -> tuple[str, str] | None:
    """(flawed, fixed) for a Java test case, or None when it is not a pair.

    The flawed variant keeps `bad`/`badSink` and drops every `good*` method; the
    fixed variant does the reverse. Both sides must be present, or the file is
    not a differential pair and is skipped rather than scored as a miss.
    """
    try:
        masked = "\n".join(detect.blank(source, "java"))
    except Exception:                            # noqa: BLE001
        return None
    if len(masked) != len(source):               # offsets must line up exactly
        return None

    bad_spans: list[tuple[int, int]] = []
    good_spans: list[tuple[int, int]] = []
    for match in _JAVA_METHOD.finditer(masked):
        name = match.group(1)
        end = _java_body_end(masked, match.end() - 1)
        if end is None:
            continue
        span = (match.start(), end)
        if _JAVA_BAD.match(name):
            bad_spans.append(span)
        elif _JAVA_GOOD.match(name):
            good_spans.append(span)
    if not bad_spans or not good_spans:
        return None

    def without(spans: list[tuple[int, int]]) -> str:
        kept: list[str] = []
        cursor = 0
        for start, end in sorted(spans):
            if start < cursor:                   # overlapping match, bail out
                return source
            kept.append(source[cursor:start])
            cursor = end
        kept.append(source[cursor:])
        return "".join(kept)

    flawed, fixed = without(good_spans), without(bad_spans)
    if flawed == source or fixed == source:
        return None
    return flawed, fixed

def _split_for(source: str, suffix: str) -> tuple[str, str] | None:
    """Dispatch to the splitter the language actually uses."""
    return (split_variants_java(source) if suffix == ".java"
            else split_variants(source))

def _multifile_cases(archive: zipfile.ZipFile) -> dict[str, list[list[str]]]:
    """{cwe: [[part, part, ...], ...]} for cases split across files."""
    holding: dict[str, dict[str, list[str]]] = collections.defaultdict(
        lambda: collections.defaultdict(list))
    for name in archive.namelist():
        if "/testcases/" not in name or not name.endswith((".c", ".cpp")):
            continue
        cwe = _CASE.search(name)
        part = _MULTIFILE_PART.match(name)
        if not cwe or not part:
            continue
        holding["CWE-" + cwe.group(1)][part.group(1)].append(name)
    return {cwe: [sorted(parts) for _, parts in sorted(cases.items())]
            for cwe, cases in holding.items()}

def verify_report(report: Any) -> tuple[bool, list[str]]:
    """Recompute a benchmark report's identity and internal consistency."""
    errors: list[str] = []
    if not isinstance(report, dict):
        return False, ["report is not a mapping"]
    if report.get("schema") != SCHEMA:
        errors.append("unexpected schema")
    rows = report.get("by_cwe")
    if not isinstance(rows, dict):
        return False, errors + ["by_cwe must be a mapping"]
    if sum(row.get("pairs", 0) for row in rows.values()) != \
            report.get("paired_cases"):
        errors.append("paired_cases disagrees with the per-class rows")
    silent = sorted(cwe for cwe, row in rows.items()
                    if row.get("detection_percent") == 0.0)
    if silent != list(report.get("silent_classes", [])):
        errors.append("silent_classes disagrees with the per-class rows")
    recomputed = _sha({key: value for key, value in report.items()
                       if key != "report_sha256"})
    if report.get("report_sha256") != recomputed:
        errors.append("report digest does not match its content")
    return not errors, errors

def strip_comments(source: str) -> str:
    """Remove C/C++ comments without being fooled by comment-like literals.

    A regex cannot do this correctly: `printLine("/* not a comment */")` would
    lose half the string, and `"\\""` would end it early.  So this walks the
    source once, tracking whether it is inside a string, a character literal or
    a comment, which is short enough to be obviously right.
    """
    out: list[str] = []
    index, length = 0, len(source)
    while index < length:
        char = source[index]
        pair = source[index:index + 2]
        if pair == "/*":
            end = source.find("*/", index + 2)
            index = length if end < 0 else end + 2
            out.append(" ")
        elif pair == "//":
            end = source.find("\n", index)
            index = length if end < 0 else end
            out.append(" ")
        elif char in "\"'":
            quote, start = char, index
            index += 1
            while index < length:
                if source[index] == "\\":
                    index += 2
                    continue
                if source[index] == quote:
                    index += 1
                    break
                if source[index] == "\n" and quote == "\"":
                    break            # unterminated; do not run off the file
                index += 1
            out.append(source[start:index])
        else:
            out.append(char)
            index += 1
    return "".join(out)

def neutralise_names(source: str) -> str:
    """Rewrite identifiers that state the label to a single neutral token."""
    return _IDENTIFIER.sub(
        lambda m: _NEUTRAL if _LEAKY_NAME.match(m.group(0)) else m.group(0),
        source)

def declassify(source: str) -> str:
    """Strip every textual leak and normalise whitespace."""
    cleaned = _STORAGE.sub("", neutralise_names(strip_comments(source)))
    return "\n".join(" ".join(line.split())
                     for line in cleaned.splitlines() if line.strip())

def split_variants(source: str) -> tuple[str, str] | None:
    """(flawed, fixed) for a testcase that carries both, else None."""
    kinds = {match.group(1) for match in _BLOCK.finditer(source)}
    if not {"OMITBAD", "OMITGOOD"} <= kinds:
        return None
    flawed = _BLOCK.sub(
        lambda m: "" if m.group(1) == "OMITGOOD" else m.group(2), source)
    fixed = _BLOCK.sub(
        lambda m: "" if m.group(1) == "OMITBAD" else m.group(2), source)
    return flawed, fixed

def windows(source: str, size: int = DEFAULT_WINDOW_LINES) -> list[str]:
    """Every contiguous `size`-line window of already-declassified source."""
    if not isinstance(size, int) or isinstance(size, bool) or \
            not 1 <= size <= MAX_WINDOW_LINES:
        raise CorpusError("window size must be an int in 1..%d" % MAX_WINDOW_LINES)
    lines = source.splitlines()
    if len(lines) < size:
        return ["\n".join(lines)] if lines else []
    return ["\n".join(lines[start:start + size])
            for start in range(len(lines) - size + 1)]

def measure(archive_path: str, want_cwe: str, rule: str) -> dict:
    """Detection on seen families against detection on unseen ones."""
    seen = {"detected": 0, "pairs": 0, "families": set()}
    unseen = {"detected": 0, "pairs": 0, "families": set()}
    per_family: collections.Counter = collections.Counter()

    with zipfile.ZipFile(archive_path) as archive:
        names = sorted(n for n in archive.namelist()
                       if "/testcases/" in n and n.endswith((".c", ".cpp"))
                       and not _MULTIFILE.search(n))
        for name in names:
            parsed = family_of(name)
            if not parsed or parsed[0] != want_cwe:
                continue
            _, family = parsed
            if per_family[family] >= MAX_PAIRS_PER_FAMILY:
                continue
            try:
                raw = archive.read(name)
            except KeyError:
                continue
            if len(raw) > MAX_FILE_BYTES:
                continue
            variants = juliet_corpus.split_variants(
                raw.decode("utf-8", "replace"))
            if not variants:
                continue
            flawed, fixed = variants
            language = "cpp" if name.endswith(".cpp") else "c"

            def fires(source: str) -> bool:
                try:
                    found = detect.scan_source(source, name, language,
                                               deep=True)
                except Exception:                        # noqa: BLE001
                    return False
                return any(getattr(f, "rule", "") == rule for f in found)

            per_family[family] += 1
            bucket = unseen if is_holdout_family(family) else seen
            bucket["pairs"] += 1
            bucket["families"].add(family)
            # The same differential criterion the rest of this project uses:
            # a finding the fixed variant also produces says nothing.
            if fires(flawed) and not fires(fixed):
                bucket["detected"] += 1

    def summarise(bucket: dict) -> dict:
        return {"families": len(bucket["families"]),
                "pairs": bucket["pairs"],
                "detected": bucket["detected"],
                "detection_percent": round(
                    100.0 * bucket["detected"] / bucket["pairs"], 1)
                if bucket["pairs"] else 0.0}

    seen_out, unseen_out = summarise(seen), summarise(unseen)
    return {
        "schema": SCHEMA, "version": VERSION, "cwe": want_cwe, "rule": rule,
        "seen_families": seen_out, "unseen_families": unseen_out,
        "gap_points": round(seen_out["detection_percent"]
                            - unseen_out["detection_percent"], 1),
        # Stated rather than left to the reader: a handful of held-out
        # families cannot support a conclusion either way.
        "unseen_is_thin": unseen_out["families"] < 4,
    }

def summarise(archive_path: str) -> dict:
    """Counts, for a caller deciding whether the labels are worth using."""
    by_cwe: dict[str, int] = {}
    files = set()
    total = 0
    for flaw in iter_flaws(archive_path):
        total += 1
        files.add(flaw.path)
        by_cwe[flaw.cwe] = by_cwe.get(flaw.cwe, 0) + 1
    return {"schema": SCHEMA, "version": VERSION,
            "flaws": total, "files_with_flaws": len(files),
            "cwe_classes": len(by_cwe),
            "largest": sorted(by_cwe.items(), key=lambda kv: -kv[1])[:10]}

def rule_counts() -> dict[str, int]:
    """Language -> number of rules written specifically for it."""
    counts: dict[str, int] = {}
    for rule in detect.RULES:
        for language in getattr(rule, "langs", ()) or ():
            if language != WILDCARD:
                counts[language] = counts.get(language, 0) + 1
    return counts

def _verify_service(index: int, resources: int) -> dict:
    """Generate one service and grade every .py file. Top-level & picklable so the
    process pool can run it. A file counts as clean only at grade A with no
    high/medium findings."""
    files = codegen.generate(codegen.big_spec(resources))
    lines = 0
    py_files = 0
    clean = 0
    defects = []
    for name, content in files.items():
        lines += content.count("\n") + 1
        if not name.endswith(".py"):
            continue
        py_files += 1
        fg = grade.grade_source(content, "svc%d/%s" % (index, name), metrics.DEFAULT_LIMITS)[0]
        if fg.grade == "A" and fg.findings_high == 0 and fg.findings_medium == 0:
            clean += 1
        else:
            defects.append("svc%d/%s: %s (%dH %dM)"
                           % (index, name, fg.grade, fg.findings_high, fg.findings_medium))
    return {"files": len(files), "py_files": py_files, "lines": lines,
            "clean": clean, "defects": defects}

def _child_blocks(stmt) -> list:
    """The nested statement-blocks a compound statement opens. if/elif/else and
    the arms of try/except/finally are returned flat -- they share one level."""
    if isinstance(stmt, ast.If):
        return _if_blocks(stmt)
    if isinstance(stmt, ast.Match):
        return [case.body for case in stmt.cases]
    blocks = [getattr(stmt, f, None) for f in ("body", "orelse", "finalbody")]
    blocks += [h.body for h in getattr(stmt, "handlers", [])]
    return [b for b in blocks if b]

def _block_depth(stmts, depth: int = 1) -> int:
    """Deepest block level in a list of statements; a nested compound statement
    adds one level. Nested defs/classes are their own scope and are skipped."""
    best = depth
    for stmt in stmts:
        if isinstance(stmt, _DEF + (ast.ClassDef,)):
            continue
        for block in _child_blocks(stmt):
            best = max(best, _block_depth(block, depth + 1))
    return best

class _Cognitive:
    """SonarSource cognitive-complexity walker (see _cognitive). Each control-flow
    break scores +1; one nested inside others also adds the current nesting level,
    so deep code costs more than flat code with the same branch count. elif/else,
    boolean chains, and loop-else score a flat +1. Nested defs are their own scope.
    A per-node-type dispatch table keeps each handler small."""

    def __init__(self):
        self.total = 0

    def run(self, fn) -> int:
        self._block(fn.body, 0)
        return self.total

    def _block(self, stmts, nesting) -> None:
        for stmt in stmts:
            self._visit(stmt, nesting)

    def _visit(self, node, nesting) -> None:
        handler = self._HANDLERS.get(type(node))
        if handler is not None:
            handler(self, node, nesting)
        else:
            for child in ast.iter_child_nodes(node):
                self._visit(child, nesting)

    def _if(self, node, nesting) -> None:
        self.total += 1 + nesting
        self._visit(node.test, nesting)
        self._block(node.body, nesting + 1)
        orelse = node.orelse
        while orelse:
            if len(orelse) == 1 and isinstance(orelse[0], ast.If):
                branch = orelse[0]                       # elif: +1 flat, same depth
                self.total += 1
                self._visit(branch.test, nesting)
                self._block(branch.body, nesting + 1)
                orelse = branch.orelse
            else:
                self.total += 1                          # else: +1 flat
                self._block(orelse, nesting + 1)
                orelse = []

    def _loop(self, node, nesting) -> None:
        self.total += 1 + nesting
        self._visit(node.test if isinstance(node, ast.While) else node.iter, nesting)
        self._block(node.body, nesting + 1)
        if node.orelse:
            self.total += 1                              # loop-else: +1 flat
            self._block(node.orelse, nesting + 1)

    def _try(self, node, nesting) -> None:
        self._block(node.body, nesting)                  # try itself does not break flow
        for handler in node.handlers:
            self.total += 1 + nesting
            self._block(handler.body, nesting + 1)
        self._block(node.orelse, nesting)
        self._block(node.finalbody, nesting)

    def _with(self, node, nesting) -> None:
        self._block(node.body, nesting)                  # with does not break flow

    def _match(self, node, nesting) -> None:
        self.total += 1 + nesting
        for case in node.cases:
            self._block(case.body, nesting + 1)

    def _ternary(self, node, nesting) -> None:           # a if cond else b
        self.total += 1 + nesting
        self._visit(node.test, nesting)
        self._visit(node.body, nesting + 1)
        self._visit(node.orelse, nesting + 1)

    def _boolop(self, node, nesting) -> None:            # and/or sequence: flat +1
        self.total += 1
        for value in node.values:
            self._visit(value, nesting)

    def _skip(self, node, nesting) -> None:
        return                                           # nested def/lambda: own scope

    _HANDLERS = {
        ast.If: _if,
        ast.For: _loop, ast.AsyncFor: _loop, ast.While: _loop,
        ast.Try: _try,
        ast.With: _with, ast.AsyncWith: _with,
        ast.Match: _match,
        ast.IfExp: _ternary,
        ast.BoolOp: _boolop,
        ast.FunctionDef: _skip, ast.AsyncFunctionDef: _skip, ast.Lambda: _skip,
    }

def analyze_source(src: str, path: str = "<string>") -> list[FuncMetric]:
    """Every function/method in `src`, each with its own metrics. Empty list on
    a syntax error (a file that won't parse has no functions to measure)."""
    try:
        tree = ast.parse(src)
    except SyntaxError:
        return []
    out: list[FuncMetric] = []
    _collect(tree, "", path, out)
    return out

def exceeded(self, limits: dict) -> list[str]:
        """Which limits this function blows past, worst-first-ish for reporting."""
        over = []
        if self.complexity > limits["complexity"]:
            over.append("complexity")
        if self.cognitive > limits["cognitive"]:
            over.append("cognitive")
        if self.length > limits["length"]:
            over.append("length")
        if self.nesting > limits["nesting"]:
            over.append("nesting")
        if self.args > limits["args"]:
            over.append("args")
        return over

class MigrationEngine:
    """Scans files and applies migration rules."""

    def __init__(self, languages: list[Language] | None = None,
                 min_confidence: Confidence = Confidence.LOW,
                 include_breaking: bool = False):
        self._languages = languages
        self._min_confidence = min_confidence
        self._include_breaking = include_breaking

    def scan_line(self, line: str, language: Language,
                  file_path: str = "", line_num: int = 0,
                  context_above: str = "",
                  context_below: str = "") -> list[MigrationMatch]:
        matches = []
        rules = rules_for_language(language)

        conf_order = {Confidence.HIGH: 0, Confidence.MEDIUM: 1, Confidence.LOW: 2}
        min_ord = conf_order.get(self._min_confidence, 2)

        for rule in rules:
            if not self._include_breaking and rule.breaking:
                continue
            if conf_order.get(rule.confidence, 2) > min_ord:
                continue

            result = rule.detector(
                line,
                file_path=file_path,
                line_num=line_num,
                context_above=context_above,
                context_below=context_below,
            )
            if result:
                matches.append(result)

        return matches

    def scan_source(self, source: str, language: Language,
                    file_path: str = "") -> list[MigrationMatch]:
        lines = source.splitlines()
        all_matches = []

        for i, line in enumerate(lines):
            above = "\n".join(lines[max(0, i - 5):i])
            below = "\n".join(lines[i + 1:min(len(lines), i + 5)])
            matches = self.scan_line(
                line, language, file_path=file_path,
                line_num=i + 1, context_above=above,
                context_below=below)
            all_matches.extend(matches)

        return all_matches

    def scan_file(self, path: str) -> list[MigrationMatch]:
        ext = os.path.splitext(path)[1].lower()
        language = LANG_EXT_MAP.get(ext)
        if not language:
            return []

        if self._languages and language not in self._languages:
            return []

        try:
            with open(path, "r", encoding="utf-8", errors="ignore") as f:
                source = f.read()
        except OSError:
            return []

        return self.scan_source(source, language, file_path=path)

    def scan_project(self, root: str) -> dict[str, MigrationReport]:
        reports: dict[str, MigrationReport] = {}
        skip_dirs = {
            ".git", "node_modules", "__pycache__", ".tox",
            "venv", ".venv", "dist", "build", "vendor",
        }

        for dirpath, dirnames, filenames in os.walk(root):
            dirnames[:] = [d for d in dirnames if d not in skip_dirs]
            for fname in filenames:
                fpath = os.path.join(dirpath, fname)
                ext = os.path.splitext(fname)[1].lower()
                if ext not in LANG_EXT_MAP:
                    continue

                matches = self.scan_file(fpath)
                if matches:
                    rel = os.path.relpath(fpath, root)
                    reports[rel] = MigrationReport(
                        file_path=rel, matches=matches)

        return reports

    def apply(self, source: str, language: Language) -> str:
        matches = self.scan_source(source, language)
        lines = source.splitlines()

        replacements: dict[int, str] = {}
        for m in matches:
            if m.confidence == Confidence.HIGH and m.line > 0:
                replacements[m.line - 1] = m.replacement

        result = []
        for i, line in enumerate(lines):
            if i in replacements:
                result.append(replacements[i])
            else:
                result.append(line)

        return "\n".join(result)

    def summary(self, reports: dict[str, MigrationReport]) -> str:
        total_files = len(reports)
        total_matches = sum(r.total_migrations for r in reports.values())

        lines = [
            "=== Migration Analysis ===",
            "Files with migrations: %d" % total_files,
            "Total opportunities: %d" % total_matches,
        ]

        by_rule: dict[str, int] = {}
        by_cat: dict[str, int] = {}
        for r in reports.values():
            for m in r.matches:
                by_rule[m.rule.name] = by_rule.get(m.rule.name, 0) + 1
                by_cat[m.rule.category.name] = by_cat.get(m.rule.category.name, 0) + 1

        if by_cat:
            lines.append("")
            lines.append("By category:")
            for cat, count in sorted(by_cat.items(), key=lambda x: -x[1]):
                lines.append("  %s: %d" % (cat, count))

        if by_rule:
            lines.append("")
            lines.append("By rule:")
            for name, count in sorted(by_rule.items(), key=lambda x: -x[1]):
                lines.append("  %s: %d" % (name, count))

        return "\n".join(lines)

def classify(response: str) -> str:
    """Did the model accept the finding, reject it, or fail to commit?

    `unclear` is a real outcome, not a parsing gap.  A model that will not say
    which way it lands cannot be relied on to say so when it matters, and the
    caller treats it as a failure rather than retrying until it reads well.
    """
    if not isinstance(response, str):
        raise AuditError("response must be text")
    head = response.strip()[:40].upper()
    if head.startswith("CONFIRMED"):
        return ACCEPTED
    if head.startswith("REJECTED"):
        return REJECTED
    if _HEDGE.search(response):
        return UNCLEAR
    rejected = bool(_REJECT.search(response))
    accepted = bool(_ACCEPT.search(response))
    if rejected and not accepted:
        return REJECTED
    if accepted and not rejected:
        return ACCEPTED
    return UNCLEAR

def battery_sha256() -> str:
    """Identity of the probe set a verdict was reached against."""
    return _sha([{k: v for k, v in probe.items()} for probe in PROBES])

def may_speak(report: Mapping[str, Any],
              role: str = ROLE_ADJUDICATE) -> tuple[bool, str]:
    """Fail closed: anything but an intact, passing audit for `role` refuses.

    The role matters.  A model cleared to explain a finding has not thereby
    been cleared to decide whether one is real -- that is the failure this
    whole module exists to prevent, and letting one audit stand in for the
    other would reintroduce it through the back door.
    """
    if role not in (ROLE_ADJUDICATE, ROLE_PHRASE):
        return False, "unknown role %r" % role
    if not isinstance(report, Mapping):
        return False, "no audit report"
    if report.get("schema") != SCHEMA:
        return False, "unrecognised audit schema"
    body = {k: v for k, v in report.items() if k != "report_sha256"}
    if report.get("report_sha256") != _sha(body):
        return False, "audit report does not match its contents"
    if report.get("role", ROLE_ADJUDICATE) != role:
        return False, "audit was for the %r role, not %r" % (
            report.get("role", ROLE_ADJUDICATE), role)
    wanted = phrase_battery_sha256() if role == ROLE_PHRASE else battery_sha256()
    if report.get("battery_sha256") != wanted:
        return False, "audit was run against a different battery"
    if not report.get("trusted"):
        return False, "model failed its audit (%d of %d correct%s)" % (
            report.get("correct", 0), report.get("probes", 0),
            ", gave one answer to everything"
            if report.get("always_one_answer") else "")
    return True, "audit passed"

def standing(ledger: Mapping[str, Any] | None, model_id: str) -> dict[str, Any]:
    """How many times this model has been caught, and whether it may continue."""
    entries = [item for item in (ledger or {}).get("violations", [])
               if item.get("model_id") == model_id]
    return {
        "model_id": model_id,
        "violations": len(entries),
        "allowed": len(entries) < MAX_VIOLATIONS,
        "remaining": max(0, MAX_VIOLATIONS - len(entries)),
    }

def corpus_sha256(self) -> str:
        """Identity over example rows, independent of insertion order."""
        digests = [str(row["example_id"]) for row in self._db.execute(
            "SELECT example_id FROM examples ORDER BY example_id")]
        return _sha_value({"schema": SCHEMA, "examples": digests})

def _is_live_code(source: str, blanked: str, offset: int) -> bool:
    """False when this offset sits inside a string literal or a comment."""
    if not blanked or offset >= len(blanked):
        return True
    return not (blanked[offset] == " " and source[offset] != " ")

def _norm(finding) -> tuple:
    """(line, rule, severity, message) from either scanner's Finding shape."""
    message = getattr(finding, "message", None) or getattr(finding, "detail", "")
    return (finding.line, finding.rule, finding.severity, message)

def _grade_pair(path: str, top: int = 6) -> tuple:
    """Top-level (picklable) worker for the process pool: path -> (FileGrade, tips)."""
    fg, findings, funcs = grade_file(path)
    return fg, improvements(findings, funcs, top)

def _header_name(header: str):
    """The callable a '{'-opening header names, or None if it isn't a function."""
    match = _FUNC_HEADER.search(header)
    if match and match.group(1) not in _CONTROL_SET:
        return match.group(1)
    return None

def _c_bodies(blanked: str):
    """(name, start_line, end_line, body_text) per function/method body. Brace
    matching on blanked code; a body is a '{...}' whose header names a callable."""
    stack = []
    bodies = []
    line = 1
    seg_start = 0
    for i, ch in enumerate(blanked):
        if ch == "\n":
            line += 1
        elif ch == "{":
            stack.append((i, line, _header_name(blanked[seg_start:i])))
            seg_start = i + 1
        elif ch == "}":
            _pop_body(stack, bodies, i, line, blanked)
            seg_start = i + 1
        elif ch == ";":
            seg_start = i + 1
    return bodies

def _depth_at(body: str) -> list:
    """Brace depth in front of each character (function body top level = 0)."""
    depths = []
    depth = -1                      # the body's own opening brace lifts us to 0
    for ch in body:
        if ch == "{":
            depths.append(max(depth, 0))
            depth += 1
        elif ch == "}":
            depth -= 1
            depths.append(max(depth, 0))
        else:
            depths.append(max(depth, 0))
    return depths

def resolve(jobs) -> int:
    """Turn a --jobs value into a worker count: 0 (or None) means 'all cores'."""
    if not jobs:
        return default_jobs()
    return max(1, int(jobs))

def pmap(func, items, jobs) -> list:
    """Map func over items, in parallel when it pays off. func must be a top-level
    (picklable) function. Order of results matches order of items."""
    items = list(items)
    workers = resolve(jobs)
    if workers <= 1 or len(items) <= 1:
        return [func(item) for item in items]
    with multiprocessing.Pool(processes=workers) as pool:
        return pool.map(func, items)

#!/usr/bin/env python3
"""
nativepool.py -- run a per-file scan across all your cores.

Every native engine here processes one file independently, so scanning a tree is
embarrassingly parallel. This is the shared helper: pmap(func, items, jobs) fans
the work out over a process pool (stdlib multiprocessing, zero dependencies) and
falls back to a plain serial map for jobs<=1 or a single item. Nothing else about
the engines changes -- they just finish sooner on a big codebase.
"""
from __future__ import annotations

import multiprocessing
import os


def default_jobs() -> int:
    return os.cpu_count() or 1


def resolve(jobs) -> int:
    """Turn a --jobs value into a worker count: 0 (or None) means 'all cores'."""
    if not jobs:
        return default_jobs()
    return max(1, int(jobs))


def pmap(func, items, jobs) -> list:
    """Map func over items, in parallel when it pays off. func must be a top-level
    (picklable) function. Order of results matches order of items."""
    items = list(items)
    workers = resolve(jobs)
    if workers <= 1 or len(items) <= 1:
        return [func(item) for item in items]
    with multiprocessing.Pool(processes=workers) as pool:
        return pool.map(func, items)

def _diff(old: list, new: list) -> tuple:
    """(introduced, fixed): findings only in new, and findings only in old,
    compared as a multiset keyed on (rule, source-line-text)."""
    old_keys = Counter((rule, text) for rule, _s, _l, text, _m in old)
    introduced = []
    for item in new:
        key = (item[0], item[3])
        if old_keys[key] > 0:
            old_keys[key] -= 1
        else:
            introduced.append(item)
    new_keys = Counter((rule, text) for rule, _s, _l, text, _m in new)
    fixed = []
    for item in old:
        key = (item[0], item[3])
        if new_keys[key] > 0:
            new_keys[key] -= 1
        else:
            fixed.append(item)
    return introduced, fixed

#!/usr/bin/env python3
"""
nativereview.py -- review a C/C++/Assembly *change*, not the whole file.

Point it at the old and new versions of a file and it reports only what the change
INTRODUCED -- the findings that are in the new version but were not in the old --
plus what it FIXED, and the grade delta. Pre-existing noise is ignored, so the
review is about your diff and nothing else. Findings are matched by (rule + the
exact source line text), so moving code up or down never looks like a new bug.

Exit code = number of introduced findings, so CI can fail a change that adds bugs:

    nativereview.py old/parser.c new/parser.c
    # from git:  git show HEAD:parser.c > /tmp/old.c && nativereview.py /tmp/old.c parser.c
"""
from __future__ import annotations

import argparse
import sys
from collections import Counter

import nativegrade


def _lines(path: str) -> list:
    try:
        with open(path, encoding="utf-8", errors="replace") as fh:
            return fh.read().splitlines()
    except OSError:
        return []


def _findings_with_text(path: str) -> list:
    """(rule, severity, line, text, message) for every finding, text = the source
    line stripped -- the anchor that survives line-number shifts."""
    lines = _lines(path)
    out = []
    for line, rule, severity, message in nativegrade._findings(path):
        text = lines[line - 1].strip() if 0 < line <= len(lines) else ""
        out.append((rule, severity, line, text, message))
    return out


def _diff(old: list, new: list) -> tuple:
    """(introduced, fixed): findings only in new, and findings only in old,
    compared as a multiset keyed on (rule, source-line-text)."""
    old_keys = Counter((rule, text) for rule, _s, _l, text, _m in old)
    introduced = []
    for item in new:
        key = (item[0], item[3])
        if old_keys[key] > 0:
            old_keys[key] -= 1
        else:
            introduced.append(item)
    new_keys = Counter((rule, text) for rule, _s, _l, text, _m in new)
    fixed = []
    for item in old:
        key = (item[0], item[3])
        if new_keys[key] > 0:
            new_keys[key] -= 1
        else:
            fixed.append(item)
    return introduced, fixed


def review(old_path: str, new_path: str) -> dict:
    introduced, fixed = _diff(_findings_with_text(old_path), _findings_with_text(new_path))
    before = nativegrade.grade_file(old_path)[0]
    after = nativegrade.grade_file(new_path)[0]
    order = {"CRITICAL": 0, "HIGH": 1, "MEDIUM": 2, "LOW": 3, "INFO": 4}
    introduced.sort(key=lambda f: order.get(f[1], 5))
    return {"introduced": introduced, "fixed": fixed,
            "before": before, "after": after}


def render(result: dict, new_path: str) -> str:
    before, after = result["before"], result["after"]
    introduced, fixed = result["introduced"], result["fixed"]
    arrow = "%s (%d) -> %s (%d)" % (before.grade, before.score, after.grade, after.score)
    lines = ["native review: %s" % new_path,
             "  grade %s   |   +%d introduced, -%d fixed"
             % (arrow, len(introduced), len(fixed))]
    if introduced:
        lines.append("  introduced by this change:")
        for rule, severity, line, _text, message in introduced:
            lines.append("    [%s] %s at line %d -- %s" % (severity, rule, line, message))
    else:
        lines.append("  no new findings -- this change adds no detectable bugs.")
    if fixed:
        lines.append("  fixed by this change: " + ", ".join(sorted({f[0] for f in fixed})))
    return "\n".join(lines)


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("old", help="the previous version of the file")
    ap.add_argument("new", help="the changed version of the file")
    ap.add_argument("--json", action="store_true", help="machine-readable output")
    args = ap.parse_args(argv)

    result = review(args.old, args.new)
    if args.json:
        import json
        payload = {
            "before": {"grade": result["before"].grade, "score": result["before"].score},
            "after": {"grade": result["after"].grade, "score": result["after"].score},
            "introduced": [{"rule": r, "severity": s, "line": l, "message": m}
                           for r, s, l, _t, m in result["introduced"]],
            "fixed": sorted({f[0] for f in result["fixed"]}),
        }
        print(json.dumps(payload, indent=2))
    else:
        print(render(result, args.new))
    return min(len(result["introduced"]), 250)


if __name__ == "__main__":
    sys.exit(main())

def _call_arguments(text: str, open_index: int) -> list[str]:
    """Split a C call's top-level arguments, preserving string literal text."""
    args, current = [], []
    depth = 1
    quote = None
    i = open_index + 1
    while i < len(text) and depth:
        char = text[i]
        if quote:
            current.append(char)
            if char == "\\" and i + 1 < len(text):
                current.append(text[i + 1]); i += 2; continue
            if char == quote:
                quote = None
        elif char in ('"', "'"):
            quote = char; current.append(char)
        elif char == "(":
            depth += 1; current.append(char)
        elif char == ")":
            depth -= 1
            if depth:
                current.append(char)
        elif char == "," and depth == 1:
            args.append("".join(current).strip()); current = []
        else:
            current.append(char)
        i += 1
    if current or args:
        args.append("".join(current).strip())
    return args if depth == 0 else []

def _asm_code_lines(text: str):
    """(line number, code) with comments stripped and blank lines dropped."""
    for index, raw in enumerate(text.splitlines(), start=1):
        code = re.split(r"[;#]|//", raw, maxsplit=1)[0].rstrip()
        if code.strip():
            yield index, code

def _split_params(params: str) -> list:
    """Top-level comma split (respects <> and () nesting)."""
    parts = []
    depth = 0
    current = []
    for ch in params:
        if ch in "<(":
            depth += 1
        elif ch in ">)":
            depth = max(0, depth - 1)
        if ch == "," and depth == 0:
            parts.append("".join(current))
            current = []
        else:
            current.append(ch)
    if current:
        parts.append("".join(current))
    return [p.strip() for p in parts if p.strip() and p.strip() != "void"]

def _result_type(ret: str) -> str:
    """Drop function-only specifiers that are illegal on a local result variable."""
    return re.sub(
        r"^(?:(?:static|inline|constexpr|consteval|constinit|extern|virtual|friend)\s+)+",
        "", ret.strip())

def _fnv1a(text: str) -> int:
    """Deterministic 32-bit hash. `hash()` is randomised and unusable here."""
    value = _FNV_OFFSET
    for byte in text.encode("utf-8", "replace"):
        value = ((value ^ byte) * _FNV_PRIME) & _MASK32
    return value

def tokenize(source: str) -> list[str]:
    """Cheap language-agnostic lexing: identifiers, numbers, and operators."""
    tokens: list[str] = []
    index, length = 0, len(source)
    while index < length:
        char = source[index]
        if char in " \t\r\n":
            index += 1
        elif char in _IDENT:
            start = index
            while index < length and source[index] in _IDENT:
                index += 1
            tokens.append(source[start:index])
        else:
            tokens.append(char)
            index += 1
    return tokens

def _counted(source: str, dim: int) -> tuple[dict[int, int], int]:
    """{bucket: count} and the token total, touching only occupied buckets."""
    tokens = tokenize(source[:MAX_SOURCE_BYTES])
    counts: dict[int, int] = {}
    last = len(tokens) - 1
    for position, token in enumerate(tokens):
        key = _hashed(token) % dim
        counts[key] = counts.get(key, 0) + 1
        if position < last:
            key = _hashed("\x00".join(tokens[position:position + 2])) % dim
            counts[key] = counts.get(key, 0) + 1
        if position + 1 < last:
            key = _hashed("\x01".join(tokens[position:position + 3])) % dim
            counts[key] = counts.get(key, 0) + 1
    return counts, max(1, len(tokens))

def load_model(model: Mapping[str, Any]) -> dict[str, Any]:
    """Validate a model artifact and bind its identity."""
    cached = _RESOLVED.get(id(model))
    if cached is not None and cached[0] is model:
        return cached[1]
    _validate(model)
    body = {key: value for key, value in model.items()
            if key != "model_sha256"}
    resolved = dict(body)
    resolved["model_sha256"] = _sha(body)
    if "model_sha256" in model and model["model_sha256"] != resolved["model_sha256"]:
        raise NeuralGateError("model digest does not match its weights")
    if len(_RESOLVED) >= _RESOLVED_LIMIT:
        _RESOLVED.clear()
    _RESOLVED[id(model)] = (model, resolved)
    return resolved

def _by_feature(resolved: Mapping[str, Any]) -> tuple[tuple[int, ...], ...]:
    """Rows indexed by feature. Cached against the digest already verified."""
    digest = resolved["model_sha256"]
    cached = _TRANSPOSED.get(digest)
    if cached is None:
        rows = resolved["hidden_weights"]
        width = resolved.get("feature_dim", FEATURE_DIM)
        cached = tuple(tuple(row[index] for row in rows)
                       for index in range(width))
        if len(_TRANSPOSED) >= _RESOLVED_LIMIT:
            _TRANSPOSED.clear()
        _TRANSPOSED[digest] = cached
    return cached

def interpret(text: str) -> dict:
    """Map an English request to an intent. Scaffold is tried first (most
    specific), then review, then the snippet library, else 'unknown'."""
    spec = parse_spec(text)
    if spec:
        return {"intent": "scaffold", "spec": spec}
    m = REVIEW_RE.search(text)
    if m:
        return {"intent": "review", "path": m.group(1)}
    snip = match_snippet(text)
    if snip:
        return {"intent": "snippet", "code": snip[0], "desc": snip[1]}
    return {"intent": "unknown"}

def _get(url: str, accept: str = "text/html", timeout: int = _TIMEOUT, max_bytes: int = 20000):
    """GET a URL via the env proxy. Returns (status, body_text). Raises on failure.

    max_bytes caps the read (keeps snippet fetches cheap); pass 0 for the full body
    (needed for JSON APIs where a truncated response won't parse).
    """
    headers = {"User-Agent": "AttestorVonLuneberg/2.0", "Accept": accept}
    if "api.github.com" in url and _TOKEN:
        headers["Authorization"] = f"Bearer {_TOKEN}"
    req = urllib.request.Request(url, headers=headers)
    with urllib.request.urlopen(req, timeout=timeout, context=_ctx()) as r:
        raw = r.read() if not max_bytes else r.read(max_bytes)
        return r.status, raw.decode("utf-8", "replace")

def google_search(query: str):
    """Real Google search via the official Custom Search JSON API.

    Returns {"available": bool, ...}. Needs GOOGLE_API_KEY + GOOGLE_CX (a Custom
    Search Engine id) in the environment -- the ToS-compliant way to query Google
    programmatically. The googleapis.com host is reachable through the egress
    proxy, so this genuinely works once those are set; without them (or if the
    host is blocked) Attestor says so plainly instead of pretending.
    """
    global _fetch_budget
    if query in _google_cache:
        return _google_cache[query]
    if not _GOOGLE_KEY or not _GOOGLE_CX:
        res = {"available": False, "note": "set GOOGLE_API_KEY + GOOGLE_CX to enable Google search"}
        _google_cache[query] = res
        return res
    if _fetch_budget <= 0:
        return {"available": False, "note": "fetch budget exhausted"}
    _fetch_budget -= 1
    try:
        from urllib.parse import urlencode
        params = urlencode({"key": _GOOGLE_KEY, "cx": _GOOGLE_CX, "q": query, "num": 1})
        status, body = _get(f"https://www.googleapis.com/customsearch/v1?{params}",
                            accept="application/json", timeout=8)
        data = json.loads(body)
        total = data.get("searchInformation", {}).get("totalResults")
        items = data.get("items") or []
        top = items[0].get("link") if items else None
        res = {"available": True, "total": total, "top": top}
    except urllib.error.HTTPError as e:
        res = {"available": False, "note": f"Google API said {e.code} (key/cx/quota?)"}
    except urllib.error.URLError as e:
        reason = str(getattr(e, "reason", e))
        res = {"available": False,
               "note": "blocked by egress policy" if "403" in reason else f"unreachable ({reason[:40]})"}
    except Exception as e:                    # noqa: BLE001
        res = {"available": False, "note": f"google error ({type(e).__name__})"}
    _google_cache[query] = res
    return res

def github_json(path: str, timeout: int = 15):
    """GET an api.github.com path and parse JSON (auth + proxy + CA handled by _get)."""
    status, body = _get("https://api.github.com" + path,
                        accept="application/vnd.github+json", timeout=timeout, max_bytes=0)
    return json.loads(body)

def google_status() -> str:
    """One-line summary of whether Google search is usable right now."""
    if not _GOOGLE_KEY or not _GOOGLE_CX:
        return "Google search: not configured (set GOOGLE_API_KEY + GOOGLE_CX to switch it on)"
    g = google_search("attestor connectivity probe")
    if g.get("available"):
        return "Google search: live via the official Custom Search API"
    return f"Google search: {g.get('note', 'unavailable')}"

class Event:
    """An event on the kernel event bus."""
    __slots__ = ("kind", "source", "data", "timestamp")

    def __init__(self, kind: str, source: str, data: Any = None):
        self.kind = kind
        self.source = source
        self.data = data
        self.timestamp = time.time()

    def __repr__(self) -> str:
        return "Event(%s, %s)" % (self.kind, self.source)

class EventBus:
    """Pub/sub for inter-module communication."""

    def __init__(self):
        self._subscribers: dict[str, list[Callable[[Event], None]]] = defaultdict(list)
        self._log: list[Event] = []

    def subscribe(self, event_kind: str, callback: Callable[[Event], None]) -> None:
        self._subscribers[event_kind].append(callback)

    def publish(self, event: Event) -> None:
        self._log.append(event)
        for cb in self._subscribers.get(event.kind, []):
            cb(event)
        for cb in self._subscribers.get("*", []):
            cb(event)

    def history(self, kind: str | None = None, limit: int = 100) -> list[Event]:
        if kind is None:
            return self._log[-limit:]
        return [e for e in self._log if e.kind == kind][-limit:]

class Kernel:
    """Process scheduler and lifecycle manager."""

    def __init__(self):
        self.bus = EventBus()
        self._processes: dict[int, Process] = {}
        self._next_pid = 1
        self._generation = 0
        self.boot_time = time.time()

    @property
    def generation(self) -> int:
        return self._generation

    def advance_generation(self) -> int:
        self._generation += 1
        self.bus.publish(Event("generation.advance", "kernel",
                               {"generation": self._generation}))
        return self._generation

    def spawn(self, name: str, kind: str,
              priority: Priority = Priority.NORMAL,
              parent: int | None = None,
              metadata: dict | None = None) -> Process:
        pid = self._next_pid
        self._next_pid += 1
        proc = Process(pid=pid, name=name, kind=kind,
                       priority=priority, parent_pid=parent,
                       metadata=metadata or {})
        self._processes[pid] = proc
        self.bus.publish(Event("process.spawn", "kernel",
                               {"pid": pid, "name": name, "kind": kind}))
        return proc

    def start(self, pid: int) -> None:
        proc = self._processes[pid]
        proc.state = ProcessState.RUNNING
        proc.started_at = time.time()
        self.bus.publish(Event("process.start", "kernel", {"pid": pid}))

    def complete(self, pid: int, result: Any = None) -> None:
        proc = self._processes[pid]
        proc.state = ProcessState.COMPLETED
        proc.finished_at = time.time()
        proc.result = result
        self.bus.publish(Event("process.complete", "kernel",
                               {"pid": pid, "result_type": type(result).__name__}))

    def fail(self, pid: int, error: str) -> None:
        proc = self._processes[pid]
        proc.state = ProcessState.FAILED
        proc.finished_at = time.time()
        proc.error = error
        self.bus.publish(Event("process.fail", "kernel",
                               {"pid": pid, "error": error}))

    def get(self, pid: int) -> Process | None:
        return self._processes.get(pid)

    def ps(self, state: ProcessState | None = None,
           kind: str | None = None) -> list[Process]:
        procs = list(self._processes.values())
        if state:
            procs = [p for p in procs if p.state == state]
        if kind:
            procs = [p for p in procs if p.kind == kind]
        return sorted(procs, key=lambda p: (p.priority.value, p.created_at))

    def run_queue(self) -> list[Process]:
        return self.ps(state=ProcessState.QUEUED)

    def uptime(self) -> float:
        return time.time() - self.boot_time

    def stats(self) -> dict[str, int]:
        counts: dict[str, int] = defaultdict(int)
        for p in self._processes.values():
            counts[p.state.name] += 1
        counts["total"] = len(self._processes)
        counts["generation"] = self._generation
        return dict(counts)

class DetectionPattern:
    """A pattern Owen learned or mined from its own results."""
    pattern_id: str
    cwe: str
    language: str
    regex: str
    description: str
    source: str  # "builtin", "mined", "generated"
    hit_count: int = 0
    false_positive_count: int = 0
    generation_added: int = 0

    @property
    def precision(self) -> float:
        total = self.hit_count + self.false_positive_count
        if total == 0:
            return 1.0
        return self.hit_count / total

    @property
    def is_reliable(self) -> bool:
        return self.hit_count >= 3 and self.precision >= 0.7

class CoverageEntry:
    """Coverage status for a single CWE."""
    cwe: str
    cwe_num: int
    has_detection: bool = False
    has_poc: bool = False
    has_patch: bool = False
    has_regression: bool = False
    detection_rules: list[str] = field(default_factory=list)
    finding_count: int = 0
    verified_count: int = 0
    false_positive_count: int = 0

    @property
    def completeness(self) -> float:
        score = 0
        if self.has_detection:
            score += 0.25
        if self.has_poc:
            score += 0.25
        if self.has_patch:
            score += 0.25
        if self.has_regression:
            score += 0.25
        return score

    @property
    def is_complete(self) -> bool:
        return self.completeness == 1.0

class ModuleRegistry:
    """Dynamic registry of all Attestor components."""

    def __init__(self):
        self._modules: dict[str, RegisteredModule] = {}

    def register(self, name: str, kind: ModuleKind, module: Any,
                 version: str = "", description: str = "",
                 generation: int = 0) -> RegisteredModule:
        cwes: tuple[int, ...] = ()
        if hasattr(module, "supported_cwes"):
            cwes = module.supported_cwes()

        entry = RegisteredModule(
            name=name, kind=kind, module=module,
            version=version, supported_cwes=cwes,
            description=description, generation_added=generation,
        )
        self._modules[name] = entry
        return entry

    def get(self, name: str) -> RegisteredModule | None:
        return self._modules.get(name)

    def by_kind(self, kind: ModuleKind) -> list[RegisteredModule]:
        return [m for m in self._modules.values() if m.kind == kind]

    def all_modules(self) -> list[RegisteredModule]:
        return list(self._modules.values())

    def all_supported_cwes(self) -> dict[str, set[int]]:
        result: dict[str, set[int]] = defaultdict(set)
        for m in self._modules.values():
            result[m.kind.value].update(m.supported_cwes)
        return dict(result)

    def cwe_coverage_matrix(self) -> dict[int, dict[str, bool]]:
        all_cwes: set[int] = set()
        for m in self._modules.values():
            all_cwes.update(m.supported_cwes)

        matrix: dict[int, dict[str, bool]] = {}
        for cwe in sorted(all_cwes):
            matrix[cwe] = {}
            for m in self._modules.values():
                matrix[cwe][m.kind.value] = cwe in m.supported_cwes
        return matrix

class Gap:
    """A gap in Attestor's coverage that the improvement engine can fill."""
    cwe: int
    gap_type: str  # "no_detection", "no_poc", "no_patch", "no_regression", "low_precision"
    priority: Priority
    description: str
    suggested_action: str
    metadata: dict[str, Any] = field(default_factory=dict)

    @property
    def gap_id(self) -> str:
        return "gap-%d-%s" % (self.cwe, self.gap_type)

class PatternMiner:
    """Extracts new detection patterns from verified findings.

    When Owen confirms a finding via PoC, the finding's snippet and context
    contain the vulnerable code pattern. The miner extracts a generalized
    regex from confirmed patterns and proposes it as a new detection rule.
    """

    def __init__(self, knowledge: KnowledgeStore):
        self._knowledge = knowledge

    def mine_from_findings(self, cwe: str,
                           min_samples: int = 3) -> list[DetectionPattern]:
        confirmed = self._knowledge.findings(cwe=cwe, verified_only=True)
        if len(confirmed) < min_samples:
            return []

        snippets = [f.snippet for f in confirmed if f.snippet]
        if not snippets:
            return []

        patterns = []

        common_tokens = self._extract_common_tokens(snippets)
        if common_tokens:
            regex = self._tokens_to_regex(common_tokens)
            if regex and self._is_valid_regex(regex):
                cwe_num = int(re.search(r"\d+", cwe).group()) if re.search(r"\d+", cwe) else 0
                lang = confirmed[0].language if confirmed else "unknown"
                pid = "mined-%s-%s-%s" % (
                    cwe.lower().replace("-", ""),
                    lang,
                    hashlib.sha256(regex.encode()).hexdigest()[:8],
                )
                patterns.append(DetectionPattern(
                    pattern_id=pid,
                    cwe=cwe,
                    language=lang,
                    regex=regex,
                    description="Mined from %d verified findings" % len(confirmed),
                    source="mined",
                ))

        sink_patterns = self._extract_sink_patterns(confirmed)
        for sp in sink_patterns:
            if self._is_valid_regex(sp["regex"]):
                pid = "mined-sink-%s-%s" % (
                    cwe.lower().replace("-", ""),
                    hashlib.sha256(sp["regex"].encode()).hexdigest()[:8],
                )
                patterns.append(DetectionPattern(
                    pattern_id=pid,
                    cwe=cwe,
                    language=sp.get("language", "unknown"),
                    regex=sp["regex"],
                    description="Sink pattern: %s" % sp.get("description", ""),
                    source="mined",
                ))

        return patterns

    def _extract_common_tokens(self, snippets: list[str]) -> list[str]:
        if not snippets:
            return []
        token_sets = []
        for s in snippets:
            tokens = set(re.findall(r"[a-zA-Z_]\w*", s))
            token_sets.append(tokens)

        common = token_sets[0]
        for ts in token_sets[1:]:
            common = common & ts

        noise = {"self", "return", "if", "else", "for", "while", "def",
                 "class", "import", "from", "try", "except", "finally",
                 "with", "as", "in", "not", "and", "or", "is", "None",
                 "True", "False", "public", "private", "static", "void",
                 "int", "String", "boolean", "new", "this", "var", "let",
                 "const", "function"}
        return sorted(common - noise)

    def _tokens_to_regex(self, tokens: list[str]) -> str:
        if not tokens:
            return ""
        if len(tokens) == 1:
            return r"\b" + re.escape(tokens[0]) + r"\b"
        escaped = [re.escape(t) for t in tokens[:5]]
        parts = [r"\b" + e + r"\b" for e in escaped]
        return "(?=.*" + ")(?=.*".join(parts) + ")"

    def _extract_sink_patterns(self,
                               findings: list[StoredFinding],
                               ) -> list[dict[str, str]]:
        results = []
        sink_groups: dict[str, list[str]] = defaultdict(list)

        for f in findings:
            if not f.snippet:
                continue
            calls = re.findall(r"(\w+)\s*\(", f.snippet)
            for call in calls:
                sink_groups[call].append(f.snippet)

        for call_name, snippets in sink_groups.items():
            if len(snippets) >= 2:
                results.append({
                    "regex": r"\b" + re.escape(call_name) + r"\s*\(",
                    "description": "call to %s() seen in %d findings" %
                                   (call_name, len(snippets)),
                    "language": findings[0].language,
                })

        return results

    def _is_valid_regex(self, pattern: str) -> bool:
        try:
            re.compile(pattern)
            return True
        except re.error:
            return False

class SelfTestEngine:
    """Validates generated artifacts before they're integrated.

    Every improvement Owen makes to itself must pass the self-test
    before it goes live. This prevents regressions and ensures
    generated code actually works.
    """

    def __init__(self, knowledge: KnowledgeStore):
        self._knowledge = knowledge
        self._test_history: list[TestOutcome] = []

    def test_detection_pattern(self, pattern: DetectionPattern,
                               known_vulnerable: list[str] | None = None,
                               known_safe: list[str] | None = None,
                               ) -> TestOutcome:
        start = time.time()
        try:
            compiled = re.compile(pattern.regex)
        except re.error as e:
            return TestOutcome("pattern-compile", SelfTestResult.FAIL,
                               "Invalid regex: %s" % e)

        tp = fp = tn = fn = 0

        if known_vulnerable:
            for sample in known_vulnerable:
                if compiled.search(sample):
                    tp += 1
                else:
                    fn += 1

        if known_safe:
            for sample in known_safe:
                if compiled.search(sample):
                    fp += 1
                else:
                    tn += 1

        total_tested = tp + fp + tn + fn
        if total_tested == 0:
            return TestOutcome("pattern-validate", SelfTestResult.SKIP,
                               "No test samples provided",
                               time.time() - start)

        precision = tp / (tp + fp) if (tp + fp) > 0 else 0
        recall = tp / (tp + fn) if (tp + fn) > 0 else 0
        f1 = (2 * precision * recall / (precision + recall)
               if (precision + recall) > 0 else 0)

        outcome = TestOutcome(
            name="pattern-accuracy",
            result=SelfTestResult.PASS if f1 >= 0.6 else SelfTestResult.FAIL,
            details="P=%.2f R=%.2f F1=%.2f (TP=%d FP=%d TN=%d FN=%d)" %
                    (precision, recall, f1, tp, fp, tn, fn),
            elapsed=time.time() - start,
        )
        self._test_history.append(outcome)
        return outcome

    def test_generated_code(self, code: str, label: str = "generated") -> TestOutcome:
        start = time.time()
        try:
            ast.parse(code)
        except SyntaxError as e:
            outcome = TestOutcome(
                name="%s-syntax" % label,
                result=SelfTestResult.FAIL,
                details="SyntaxError at line %d: %s" % (e.lineno or 0, e.msg),
                elapsed=time.time() - start,
            )
            self._test_history.append(outcome)
            return outcome

        unfilled = re.findall(r"%%[A-Z_]+%%", code)
        if unfilled:
            outcome = TestOutcome(
                name="%s-placeholders" % label,
                result=SelfTestResult.FAIL,
                details="Unfilled placeholders: %s" % unfilled,
                elapsed=time.time() - start,
            )
            self._test_history.append(outcome)
            return outcome

        has_main = "__name__" in code and "__main__" in code
        has_exit = "sys.exit" in code

        issues = []
        if not has_main:
            issues.append("missing __main__ guard")
        if not has_exit:
            issues.append("missing sys.exit")

        if issues:
            outcome = TestOutcome(
                name="%s-structure" % label,
                result=SelfTestResult.FAIL,
                details="; ".join(issues),
                elapsed=time.time() - start,
            )
        else:
            outcome = TestOutcome(
                name="%s-validate" % label,
                result=SelfTestResult.PASS,
                details="valid Python, has __main__ and sys.exit",
                elapsed=time.time() - start,
            )

        self._test_history.append(outcome)
        return outcome

    def test_history(self, last_n: int = 20) -> list[TestOutcome]:
        return self._test_history[-last_n:]

    def pass_rate(self) -> float:
        if not self._test_history:
            return 0.0
        passed = sum(1 for t in self._test_history
                     if t.result == SelfTestResult.PASS)
        return passed / len(self._test_history)

class EvolutionTracker:
    """Tracks Owen's evolution across generations."""

    def __init__(self, knowledge: KnowledgeStore, registry: ModuleRegistry):
        self._knowledge = knowledge
        self._registry = registry
        self._snapshots: list[GenerationSnapshot] = []

    def snapshot(self, generation: int) -> GenerationSnapshot:
        matrix = self._registry.cwe_coverage_matrix()
        all_cwes = set(matrix.keys())

        det_cwes = {c for c, m in matrix.items() if m.get("scanner")}
        poc_cwes = {c for c, m in matrix.items() if m.get("poc_generator")}
        pat_cwes = {c for c, m in matrix.items() if m.get("patch_generator")}
        reg_cwes = {c for c, m in matrix.items() if m.get("regression_generator")}

        snap = GenerationSnapshot(
            generation=generation,
            timestamp=time.time(),
            total_cwes_covered=len(all_cwes),
            detection_cwes=len(det_cwes),
            poc_cwes=len(poc_cwes),
            patch_cwes=len(pat_cwes),
            regression_cwes=len(reg_cwes),
            total_findings=self._knowledge.finding_count(),
            verified_findings=self._knowledge.verified_count(),
            false_positive_rate=self._knowledge.false_positive_rate(),
            patterns_mined=len(self._knowledge.patterns(reliable_only=False)),
            improvements_made=len([m for m in self._knowledge.get_metrics(
                "improvements_made")]),
            coverage_score=self._knowledge.coverage_score(),
            self_test_pass_rate=0.0,
        )
        self._snapshots.append(snap)
        return snap

    def history(self) -> list[GenerationSnapshot]:
        return list(self._snapshots)

    def delta(self, gen_a: int, gen_b: int) -> dict[str, float]:
        snaps = {s.generation: s for s in self._snapshots}
        a = snaps.get(gen_a)
        b = snaps.get(gen_b)
        if not a or not b:
            return {}
        return {
            "cwes_covered": b.total_cwes_covered - a.total_cwes_covered,
            "detection_cwes": b.detection_cwes - a.detection_cwes,
            "poc_cwes": b.poc_cwes - a.poc_cwes,
            "patch_cwes": b.patch_cwes - a.patch_cwes,
            "regression_cwes": b.regression_cwes - a.regression_cwes,
            "findings": b.total_findings - a.total_findings,
            "verified": b.verified_findings - a.verified_findings,
            "fp_rate_change": b.false_positive_rate - a.false_positive_rate,
            "coverage_score_change": b.coverage_score - a.coverage_score,
        }

    def is_improving(self) -> bool:
        if len(self._snapshots) < 2:
            return True  # benefit of the doubt
        recent = self._snapshots[-2:]
        return recent[-1].coverage_score >= recent[-2].coverage_score

def denied_report() -> dict[str, Any]:
    """Return denial without reading a plan or probing any computer state."""
    body = {
        "schema": SCHEMA,
        "version": VERSION,
        "status": "authorization-required",
        "profile": policy.compiled_profile_document(),
        "action": "none",
        "policy_sha256": policy.POLICY_SHA256,
        "plan_sha256": "",
        "authorization": _denied_authorization(),
        "result": {},
        "coverage": {
            "complete": False,
            "gaps": [
                "owner-control permission was not granted for this invocation"],
        },
        "execution": {
            **_EXECUTION_BASE,
            "computer_probed": False,
            "plan_loaded": False,
        },
        "authority_boundaries": dict(_AUTHORITY_BOUNDARIES),
    }
    return {**body, "report_sha256": policy.digest_json(body)}

def unified_diff(original: str, candidate: str, target: str) -> str:
    """Return a complete, deterministic unified diff for a replacement file."""
    name = Path(target).as_posix()
    return "".join(difflib.unified_diff(
        original.splitlines(keepends=True), candidate.splitlines(keepends=True),
        fromfile="a/" + name, tofile="b/" + name,
    ))

def _multiset_delta(left: Iterable[scanengine.Issue], left_root: Path,
                    right: Iterable[scanengine.Issue], right_root: Path,
                    report_root: Path) -> tuple[scanengine.Issue, ...]:
    """Return items present in ``left`` more often than in ``right``."""
    remaining = collections.Counter(_issue_key(item, right_root) for item in right)
    delta = []
    for item in left:
        key = _issue_key(item, left_root)
        if remaining[key]:
            remaining[key] -= 1
        else:
            delta.append(_rebase_issue(item, left_root, report_root))
    return tuple(delta)

def rank_candidates(project_root: str | os.PathLike[str],
                    target: str | os.PathLike[str],
                    candidates: Mapping[str, str], **verify_options) -> list[CandidateReport]:
    """Verify and rank named candidates; accepted, safer, smaller patches win."""
    if not candidates:
        return []
    reports = [
        verify_candidate(project_root, target, source, name=name, **verify_options)
        for name, source in candidates.items()
    ]
    return sorted(reports, key=lambda item: (-item.score, item.name.lower()))

def apply_candidate(report: CandidateReport, candidate_source: str, *,
                    authorized: bool = False,
                    backup_root: str | os.PathLike[str] | None = None,
                    require_verified: bool = True) -> ApplyResult:
    """Atomically apply an accepted, non-stale report after explicit consent."""
    if not authorized:
        raise PermissionError("applying a candidate requires authorized=True/--apply")
    if not report.accepted:
        raise ValueError("a rejected candidate cannot be applied")
    root, relative, target = _project_and_target(report.project_root, report.target)
    if str(root) != str(Path(report.project_root).resolve()):
        raise ValueError("report project root no longer matches")
    candidate_bytes = candidate_source.encode("utf-8")
    if _sha(candidate_bytes) != report.candidate_sha256:
        raise ValueError("candidate content does not match the verified report")
    original_bytes = target.read_bytes()
    if _sha(original_bytes) != report.original_sha256:
        raise RuntimeError("target changed after verification; refusing stale apply")
    if report.verification_scope == "exact-file":
        current_scope_sha = _exact_file_manifest(root, relative, target)
    elif report.verification_scope == "project":
        current_scope_sha = _project_manifest(root)
    else:
        raise ValueError("report verification scope is unsupported")
    if current_scope_sha != report.project_sha256:
        raise RuntimeError(
            "verified scope changed after verification; refusing stale apply")

    backup_base = (Path(backup_root).expanduser().resolve() if backup_root
                   else _default_backup_root(root))
    backup_dir = backup_base / relative.parent
    stamp = time.strftime("%Y%m%d-%H%M%S", time.gmtime())
    backup = backup_dir / (relative.name + ".%s.%s.bak" % (
        stamp, report.original_sha256[:12]))
    suffix = 1
    while backup.exists():
        backup = backup_dir / (relative.name + ".%s.%s.%d.bak" % (
            stamp, report.original_sha256[:12], suffix))
        suffix += 1
    mode = target.stat().st_mode
    _atomic_write(backup, original_bytes, mode)
    replaced = False
    try:
        _atomic_write(target, candidate_bytes, mode)
        replaced = True
        ok, detail = _post_apply_check(target, require_verified=require_verified)
        if not ok:
            _atomic_write(target, original_bytes, mode)
            return ApplyResult(
                str(target), str(backup), False, True, report.original_sha256,
                report.candidate_sha256, detail + "; restored backup",
            )
    except Exception:
        if replaced:
            _atomic_write(target, original_bytes, mode)
        raise
    return ApplyResult(
        str(target), str(backup), True, False, report.original_sha256,
        report.candidate_sha256, "applied atomically; post-apply scan passed",
    )

def rollback_apply(result: ApplyResult, *, authorized: bool = False) -> ApplyResult:
    """Restore a PatchGuard backup, refusing to overwrite later user changes."""
    if not authorized:
        raise PermissionError("rollback requires authorized=True")
    if not result.applied or result.rolled_back:
        raise ValueError("this result does not represent an active applied patch")
    target = Path(result.target)
    backup = Path(result.backup)
    if not backup.is_file() or _is_link(backup):
        raise ValueError("backup is missing or unsafe")
    if not target.is_file() or _is_link(target):
        raise ValueError("target is missing or unsafe")
    if _sha(target.read_bytes()) != result.candidate_sha256:
        raise RuntimeError("target changed after apply; refusing destructive rollback")
    original = backup.read_bytes()
    if _sha(original) != result.original_sha256:
        raise RuntimeError("backup integrity check failed")
    _atomic_write(target, original, target.stat().st_mode)
    return ApplyResult(
        str(target), str(backup), False, True, result.original_sha256,
        result.candidate_sha256, "backup restored atomically",
    )

def verify_plan(report: Mapping[str, Any]) -> tuple[bool, list[str]]:
    """Recompute a plan's identity. Fails closed on anything unexpected."""
    problems: list[str] = []
    if not isinstance(report, Mapping) or report.get("schema") != SCHEMA:
        return False, ["not a plan produced by this module"]
    body = {k: v for k, v in report.items() if k != "plan_sha256"}
    if report.get("plan_sha256") != _sha(body):
        problems.append("plan digest does not match its contents")
    steps = report.get("steps")
    if not isinstance(steps, list):
        return False, problems + ["plan has no steps"]
    for position, step in enumerate(steps):
        if not isinstance(step, Mapping):
            problems.append("step %d is not a mapping" % position)
            continue
        if step.get("index") != position:
            problems.append("step %d is out of order" % position)
        if step.get("action") != VERIFY_THEN_APPLY:
            problems.append("step %d has an unknown action" % position)
    return not problems, problems

def verify_result(result: Mapping[str, Any],
                  report: Mapping[str, Any]) -> tuple[bool, list[str]]:
    """Check a result is intact and belongs to the plan it claims."""
    problems: list[str] = []
    if not isinstance(result, Mapping) or result.get("schema") != RESULT_SCHEMA:
        return False, ["not a plan result produced by this module"]
    body = {k: v for k, v in result.items() if k != "result_sha256"}
    if result.get("result_sha256") != _sha(body):
        problems.append("result digest does not match its contents")
    if result.get("plan_sha256") != report.get("plan_sha256"):
        problems.append("result does not belong to this plan")
    if not result.get("authorized") and result.get("applied"):
        problems.append("an unauthorised run reports applied changes")
    return not problems, problems

def scan_tree(root: str, *, extensions: Sequence[str] = (".py", ".c", ".cpp",
                                                         ".h", ".js", ".hs"),
              max_files: int = 2_000) -> list[dict[str, Any]]:
    """Findings across a tree, in the shape `plan()` expects.

    Imported lazily so this module stays importable -- and testable -- without
    dragging the whole detector in behind it.
    """
    import detect

    findings: list[dict[str, Any]] = []
    seen = 0
    for base, directories, files in os.walk(root):
        directories[:] = [d for d in directories
                          if d not in ("__pycache__", ".git", "node_modules",
                                       ".venv", "venv")]
        for name in sorted(files):
            if not name.endswith(tuple(extensions)):
                continue
            seen += 1
            if seen > max_files:
                return findings
            path = os.path.join(base, name)
            try:
                for item in detect.scan_file(path, deep=True):
                    findings.append({
                        "path": os.path.relpath(path, root).replace("\\", "/"),
                        "rule": item.rule,
                        "line": int(getattr(item, "line", 0) or 0),
                        "message": getattr(item, "message", ""),
                    })
            except Exception:                            # noqa: BLE001
                continue                                 # one bad file is not
    return findings                                      # a failed run

def _live_actions(root: str, *, test_command: Sequence[str] | None,
                  authorize_tests: bool):
    """Bind the planner to the real remediation engine."""
    import detect
    import verified_remediation as remediation

    def verify(project_root, path, findings):
        return remediation.verify_remediation(
            project_root, path, findings,
            test_command=list(test_command) if test_command else None,
            authorize_tests=authorize_tests, runtime_policy=None, jobs=1,
            deep=True, require_verified=True, exact_file_scope=True,
            seed=0, fuzz_cases=64)

    def apply_fix(verification):
        return remediation.apply_remediation(
            verification, authorized=True, backup_root=None,
            require_verified=True)

    def rescan(path):
        return [{"rule": item.rule}
                for item in detect.scan_file(os.path.join(root, path),
                                             deep=True)]

    def rollback(result):
        return remediation.rollback_remediation(result, authorized=True)

    return verify, apply_fix, rescan, rollback

def poc(cwe: int):
    """Register a PoC generator for a CWE."""
    def decorator(fn: Callable[[PocFinding], list[ProofOfConcept]]):
        _REGISTRY[cwe] = fn
        return fn
    return decorator

def supported_cwes() -> tuple[int, ...]:
    """CWE numbers this module can generate PoCs for."""
    return tuple(sorted(_REGISTRY))

def validate_poc(p: ProofOfConcept) -> tuple[bool, str]:
    """Check that a generated PoC is syntactically valid Python."""
    try:
        ast.parse(p.code)
        return True, "valid"
    except SyntaxError as e:
        return False, "syntax error at line %d: %s" % (e.lineno or 0, e.msg)

def from_detect_finding(finding: Any, cwe_map: dict[str, str] | None = None) -> PocFinding:
    """Adapt a detect.py Finding into a PocFinding."""
    cwe_str = ""
    if cwe_map:
        cwe_str = cwe_map.get(finding.rule, "")
    if not cwe_str and hasattr(finding, "cwe"):
        cwe_str = getattr(finding, "cwe", "")
    cwe_num = 0
    if cwe_str:
        m = re.search(r"(\d+)", str(cwe_str))
        if m:
            cwe_num = int(m.group(1))
    return PocFinding(
        cwe=cwe_num,
        rule=finding.rule,
        file_path=finding.path,
        line=finding.line,
        snippet=getattr(finding, "snippet", ""),
        message=getattr(finding, "message", ""),
    )

def _fill(template: str, **kw: Any) -> str:
    """Replace %%KEY%% placeholders in a code template."""
    for key, value in kw.items():
        template = template.replace("%%" + key + "%%", str(value))
    return template

def _header(cwe: int, title: str, f: PocFinding) -> str:
    """Standard PoC script header."""
    return (
        '#!/usr/bin/env python3\n'
        '"""%s PoC -- CWE-%d\n'
        'Found by: Attestor rule %s at %s:%d\n'
        '"""\n'
    ) % (title, cwe, f.rule, f.file_path, f.line)

def deterministic_json(value: Any, *, pretty: bool = False) -> str:
    """Serialize an IR or cache input deterministically."""
    if pretty:
        return json.dumps(value, sort_keys=True, indent=2, ensure_ascii=False) + "\n"
    return json.dumps(value, sort_keys=True, separators=(",", ":"),
                      ensure_ascii=False)

def _strip_comments(text: str, language: str) -> str:
    """Replace comments with spaces while preserving strings and line offsets."""
    out = list(text)
    size = len(text)
    i = 0
    quote = ""
    escaped = False
    block_depth = 0
    while i < size:
        char = text[i]
        nxt = text[i + 1] if i + 1 < size else ""
        if block_depth:
            if language == "rust" and char == "/" and nxt == "*":
                out[i] = out[i + 1] = " "
                block_depth += 1
                i += 2
                continue
            if char == "*" and nxt == "/":
                out[i] = out[i + 1] = " "
                block_depth -= 1
                i += 2
                continue
            if char != "\n":
                out[i] = " "
            i += 1
            continue
        if quote:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = ""
            i += 1
            continue
        if char in {"'", '"', "`"}:
            quote = char
            i += 1
            continue
        if char == "/" and nxt == "*":
            out[i] = out[i + 1] = " "
            block_depth = 1
            i += 2
            continue
        if char == "/" and nxt == "/":
            while i < size and text[i] != "\n":
                out[i] = " "
                i += 1
            continue
        if language == "php" and char == "#" and nxt != "[":
            while i < size and text[i] != "\n":
                out[i] = " "
                i += 1
            continue
        i += 1
    return "".join(out)

def _mask_literals(text: str) -> str:
    """Mask quoted content without changing offsets or newlines."""
    out = list(text)
    quote = ""
    escaped = False
    for i, char in enumerate(text):
        if quote:
            if char != "\n":
                out[i] = " "
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = ""
            continue
        if char in {"'", '"', "`"}:
            out[i] = " "
            quote = char
    return "".join(out)

def _manifest(path: str, kind: str, raw: bytes, text: str) -> dict[str, Any]:
    """Return names and structure only; never retain manifest values or scripts."""
    result: dict[str, Any] = {"path": path, "kind": kind, "sha256": _sha(raw),
                              "bytes": len(raw), "keys": [], "dependencies": [],
                              "parse_gap": ""}
    if kind in {"npm", "npm-lock", "typescript-config", "javascript-config",
                "composer", "composer-lock", "cmake-presets"}:
        try:
            value = json.loads(text)
        except (json.JSONDecodeError, UnicodeError):
            result["parse_gap"] = "invalid JSON; manifest names were not extracted"
            return result
        if isinstance(value, dict):
            result["keys"] = sorted(str(key)[:256] for key in value)[:2_000]
            for section in ("dependencies", "devDependencies", "peerDependencies",
                            "optionalDependencies", "require", "require-dev", "packages"):
                members = value.get(section)
                if isinstance(members, dict):
                    result["dependencies"].extend(str(key)[:512] for key in members
                                                  if key and key != "")
            if kind in {"typescript-config", "javascript-config"}:
                options = value.get("compilerOptions")
                if isinstance(options, dict):
                    result["keys"].extend("compilerOptions." + str(key)[:220]
                                          for key in options)
    elif kind in {"cargo", "cargo-lock"}:
        sections = re.findall(r"(?m)^\s*\[([^\]\r\n]{1,256})\]", text)
        result["keys"] = sorted(set(sections))[:2_000]
        in_dependencies = False
        for line in text.splitlines():
            section = re.match(r"\s*\[([^\]]+)\]", line)
            if section:
                in_dependencies = section.group(1).lower().endswith("dependencies")
                continue
            if in_dependencies:
                dependency = re.match(r"\s*([A-Za-z0-9_.-]+)\s*=", line)
                if dependency:
                    result["dependencies"].append(dependency.group(1))
    elif kind == "go-mod":
        for match in re.finditer(r"(?m)^\s*(?:require\s+)?([A-Za-z0-9._~/-]+)\s+v\d", text):
            result["dependencies"].append(match.group(1))
        result["keys"] = sorted(set(re.findall(r"(?m)^\s*(module|go|toolchain|require|replace|exclude|retract)\b", text)))
    elif kind in {"maven", "dotnet-project", "nuget"}:
        result["keys"] = sorted(set(re.findall(r"<([A-Za-z_][A-Za-z0-9_.:-]*)\b", text)))[:2_000]
        result["dependencies"] = sorted(set(re.findall(
            r"<(?:PackageReference|dependency|artifactId)\b[^>]*(?:Include\s*=\s*['\"]([^'\"]+)['\"]|>\s*([^<\s]+))",
            text, flags=re.IGNORECASE)))[:2_000]
        result["dependencies"] = [next((part for part in item if part), "")
                                  for item in result["dependencies"]]
    result["keys"] = sorted(set(result["keys"]))[:2_000]
    result["dependencies"] = sorted(set(filter(None, result["dependencies"])))[:5_000]
    return result

def content_fingerprint(report: dict[str, Any]) -> str:
    """Hash the portable IR content, excluding the machine-specific root."""
    portable = {key: value for key, value in report.items() if key != "root"}
    return _sha(deterministic_json(portable))

def _literal_pattern(value: str) -> str:
    """Escape a signature template while allowing ordinary whitespace drift."""
    return re.escape(value).replace(r"\ ", r"\s*").replace(r"\	", r"\s*")

def _sink_pattern(template: str) -> str:
    """Compile a readable sink template into one bounded capture pattern."""
    if template.count("{value}") != 1:
        raise ValueError("sink template must contain exactly one {value}")
    parts = re.split(r"(\{value\}|\{any\})", template)
    compiled: list[str] = []
    for part in parts:
        if part == "{value}":
            quantifier = "{1,500}" if template.endswith("{value}") else "{1,500}?"
            compiled.append(r"(?P<value>[^\r\n;]" + quantifier + ")")
        elif part == "{any}":
            compiled.append(r"(?:[^,\r\n;]{1,240}?)")
        else:
            compiled.append(_literal_pattern(part))
    pattern = "".join(compiled)
    if template[0].isalnum() or template[0] in "_$":
        pattern = r"(?<![\w.$])" + pattern
    return pattern

class LazyRuleCatalog(Sequence[FlowRule]):
    """Sequence facade that makes count queries cheap and listing deterministic."""

    def __len__(self) -> int:
        return RULE_COUNT

    def __getitem__(self, index):
        return _materialize_rules()[index]

    def __iter__(self) -> Iterator[FlowRule]:
        return iter(_materialize_rules())

def _mask_comments(text: str, language: str) -> str:
    """Mask comments while retaining offsets and string arguments used by APIs."""
    chars = list(text)
    quote = ""
    escaped = False
    block = False
    index = 0
    allow_hash = language in {"python", "php"}
    while index < len(chars):
        char = chars[index]
        nxt = chars[index + 1] if index + 1 < len(chars) else ""
        if block:
            if char == "*" and nxt == "/":
                chars[index] = chars[index + 1] = " "
                block = False
                index += 2
                continue
            if char not in "\r\n":
                chars[index] = " "
            index += 1
            continue
        if quote:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = ""
            index += 1
            continue
        if char in "'\"`":
            quote = char
            index += 1
            continue
        if char == "/" and nxt == "*":
            chars[index] = chars[index + 1] = " "
            block = True
            index += 2
            continue
        if char == "/" and nxt == "/":
            while index < len(chars) and chars[index] not in "\r\n":
                chars[index] = " "
                index += 1
            continue
        if allow_hash and char == "#":
            while index < len(chars) and chars[index] not in "\r\n":
                chars[index] = " "
                index += 1
            continue
        index += 1
    return "".join(chars)

def behavior_check(request: str) -> tuple[str, str]:
    """Return (label, smoke-test snippet) for a request, or ("", "")."""
    low = request.lower()
    for label, words, snippet in _CASES:
        if all(word in low for word in words):
            return label, snippet
    return "", ""

def run_test_command(root: str | Path, command: list[str] | tuple[str, ...],
                     timeout: int = 120,
                     output_bytes: int = DEFAULT_OUTPUT_BYTES) -> dict[str, Any]:
    """Run an explicitly supplied argv list without a shell and return bounded output."""
    argv = _validate_command(command)
    timeout = max(1, min(int(timeout), MAX_TEST_TIMEOUT))
    base = Path(root).expanduser().resolve()
    capture = _BoundedCapture(output_bytes)
    popen_args: dict[str, Any] = {
        "cwd": str(base), "env": _safe_env(), "stdin": subprocess.DEVNULL,
        "stdout": subprocess.PIPE, "stderr": subprocess.STDOUT, "shell": False,
    }
    if os.name == "nt":
        popen_args["creationflags"] = getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
    else:
        popen_args["start_new_session"] = True
    try:
        proc = subprocess.Popen(argv, **popen_args)
    except OSError as exc:
        return {"status": "error", "command": argv, "exit_code": None,
                "timeout_seconds": timeout, "output": "", "truncated": False,
                "detail": "%s: %s" % (type(exc).__name__, exc)}
    reader = threading.Thread(target=capture.drain, args=(proc.stdout,), daemon=True)
    reader.start()
    timed_out = False
    try:
        proc.wait(timeout=timeout)
    except subprocess.TimeoutExpired:
        timed_out = True
        _terminate_tree(proc)
        try:
            proc.wait(timeout=5)
        except subprocess.TimeoutExpired:
            proc.kill()
            proc.wait()
    reader.join(timeout=5)
    output, truncated = capture.text()
    if timed_out:
        status, detail = "timeout", "test command exceeded %d seconds" % timeout
    elif proc.returncode == 0:
        status, detail = "passed", ""
    else:
        status, detail = "failed", "test command exited with code %d" % proc.returncode
    return {"status": status, "command": argv, "exit_code": proc.returncode,
            "timeout_seconds": timeout, "output": output, "truncated": truncated,
            "detail": detail}

def inventory_dependencies(root: str | Path) -> DependencyInventory:
    """Read supported local manifests.  This never contacts a registry or installs."""
    base = Path(root).expanduser().resolve()
    inventory = DependencyInventory()
    if not base.is_dir():
        inventory.errors.append("workspace is not a directory: %s" % base)
        return inventory
    rows: list[tuple[str, str, str, str, str]] = []
    for path in _manifest_paths(base):
        manifest = _relative(base, path)
        inventory.manifests.append(manifest)
        try:
            text = _read_manifest(path)
            lower = path.name.lower()
            if lower.startswith("requirements") and lower.endswith(".txt"):
                _parse_requirements(text, manifest, rows)
            elif lower == "pyproject.toml":
                _parse_pyproject(text, manifest, rows)
            elif lower == "pipfile.lock":
                _parse_pipfile_lock(text, manifest, rows)
            elif lower == "package.json":
                _parse_package_json(text, manifest, rows)
            elif lower in {"package-lock.json", "npm-shrinkwrap.json"}:
                _parse_package_lock(text, manifest, rows)
            elif lower in {"cargo.toml", "cargo.lock"}:
                _parse_cargo(text, manifest, rows, lower == "cargo.lock")
            elif lower == "go.mod":
                _parse_go_mod(text, manifest, rows)
            elif lower == "pom.xml":
                _parse_pom(text, manifest, rows)
            elif lower.endswith(".csproj"):
                _parse_csproj(text, manifest, rows)
            elif lower == "packages.lock.json":
                _parse_packages_lock(text, manifest, rows)
        except (OSError, UnicodeError, ValueError, TypeError, ET.ParseError) as exc:
            inventory.errors.append("%s: %s: %s" % (manifest, type(exc).__name__, exc))
    merged: dict[tuple[str, str, str, str], set[str]] = {}
    display_names: dict[tuple[str, str, str, str], str] = {}
    for ecosystem, name, version, scope, manifest in rows:
        key = (ecosystem, name.lower(), version, scope)
        merged.setdefault(key, set()).add(manifest)
        display_names.setdefault(key, name)
    inventory.dependencies = [
        Dependency(ecosystem, display_names[key], version, scope,
                   tuple(sorted(manifests)), _purl(ecosystem, display_names[key], version))
        for key, manifests in sorted(merged.items())
        for ecosystem, _normalized, version, scope in [key]
    ]
    inventory.manifests.sort()
    inventory.errors.sort()
    return inventory

def _native_grades(paths: list[str]) -> tuple[list[dict[str, Any]], list[str]]:
    """Use nativegrade's scanners/metrics without invoking its compiler adapter."""
    rows, errors = [], []
    for path in sorted(paths, key=str.lower):
        try:
            findings = nativegrade._findings(path)
            funcs = nativegrade.nativemetrics.analyze_file(path)
            score = nativegrade._score(findings, funcs, nativegrade.nativemetrics.DEFAULT_LIMITS)
            counts = {"CRITICAL": 0, "HIGH": 0, "MEDIUM": 0, "LOW": 0, "INFO": 0}
            for _line, _rule, severity, _message in findings:
                counts[severity] = counts.get(severity, 0) + 1
            over = [metric for metric in funcs if metric.exceeded(nativegrade.nativemetrics.DEFAULT_LIMITS)]
            rows.append({
                "path": path, "score": score, "grade": nativegrade.letter(score),
                "critical": counts["CRITICAL"], "high": counts["HIGH"],
                "medium": counts["MEDIUM"], "low_info": counts["LOW"] + counts["INFO"],
                "worst_cognitive": max((metric.cognitive for metric in funcs), default=0),
                "worst_cyclomatic": max((metric.cyclomatic for metric in funcs), default=0),
                "functions": len(funcs), "over_threshold": len(over),
                "engine": "nativegrade", "verification": "static-only",
                "fix_first": nativegrade.improvements(findings, funcs),
            })
        except (OSError, UnicodeError, ValueError, SyntaxError) as exc:
            errors.append("%s: %s: %s" % (path, type(exc).__name__, exc))
    return rows, sorted(errors)

def _is_container_literal(node) -> bool:
    """True when a receiver is provably a list/dict/set -- a literal, a
    comprehension, or a list()/dict()/set() call. Only then is a mutating method
    on it guaranteed to be the None-returning builtin, not a custom method."""
    if isinstance(node, (ast.List, ast.Dict, ast.Set,
                         ast.ListComp, ast.DictComp, ast.SetComp)):
        return True
    return (isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
            and node.func.id in {"list", "dict", "set"})

def collect(paths, min_severity: str = "LOW") -> list[Finding]:
    """Collect rare findings from Python files/folders."""
    threshold = SEVERITY_ORDER[min_severity]
    findings = []
    for path in _iter_py(paths):
        findings.extend(item for item in scan_path(path)
                        if SEVERITY_ORDER[item.severity] >= threshold)
    findings.sort(key=Finding.sort_key)
    return findings

def all_payloads(platform_filter: str | None = None) -> list[BypassPayload]:
    """Return all bypass payloads, optionally filtered by platform."""
    if platform_filter is None:
        return list(_ALL_PAYLOADS)
    pf = platform_filter.lower()
    return [p for p in _ALL_PAYLOADS
            if p.platform == "any" or p.platform == pf]

def payloads_by_technique(technique: str) -> list[BypassPayload]:
    """Return payloads for a specific technique prefix."""
    return [p for p in _ALL_PAYLOADS if p.technique.startswith(technique)]

def techniques() -> list[str]:
    """Return all available technique names."""
    return sorted(set(p.technique for p in _ALL_PAYLOADS))

def detect_platform() -> str:
    """Detect the current platform for payload filtering."""
    system = platform.system().lower()
    if system == "windows":
        return "windows"
    elif system == "darwin":
        return "macos"
    elif system == "linux":
        return "linux"
    return "unknown"

def _imported_name(line: str):
    """The single name a lone `import`/`from ... import` binds, else None."""
    try:
        node = ast.parse(line.strip()).body[0]
    except (SyntaxError, IndexError):
        return None
    if isinstance(node, (ast.Import, ast.ImportFrom)) and len(node.names) == 1:
        alias = node.names[0]
        return alias.asname or alias.name.split(".")[0]
    return None

def _fix_eq_none(src: str, finding) -> list:
    """`x == None` -> `x is None`, `x != None` -> `x is not None`. None is a
    singleton, so identity is both correct and the documented style."""
    def repl(match):
        return "is None" if match.group(1) == "==" else "is not None"
    return _one_line_fix(src, finding, r"(==|!=)\s*None\b", repl,
                         "compared to None with 'is' (line %d)")

def _best_fix(src: str, findings: list, path: str, baseline: int):
    """First candidate that parses and strictly lowers the finding count."""
    for finding in findings:
        for candidate, note in _candidates(src, finding):
            if _parses(candidate) and len(_scan_all(candidate, path)) < baseline:
                return candidate, note
    return None

def _cls(rule: str) -> str:
    """Turn a rule name into a CamelCase test class name."""
    return "".join(w.capitalize() for w in rule.replace("-", "_").split("_"))

def _forbidden_sensitive_file(name: str) -> bool:
    """Reject runtime credentials, signing keys, state stores, and bearer caches."""
    folded = name.casefold()
    if folded in FORBIDDEN_FILES:
        return True
    if Path(folded).suffix in FORBIDDEN_SENSITIVE_SUFFIXES:
        return True
    if re.fullmatch(r".+\.(?:db|sqlite|sqlite3)-(?:wal|shm|journal)", folded):
        return True
    return re.fullmatch(
        r"(?:client[_-]secret|service[_-]account).*\.json", folded
    ) is not None

def _unsafe_entry_reason(name: Any) -> str:
    """Return why an archive-style relative path is unsafe on supported hosts."""
    if not isinstance(name, str) or not name:
        return "empty or non-text path"
    if name.startswith("/") or "\\" in name:
        return "absolute or backslash path"
    parts = name.split("/")
    if any(part in {"", ".", ".."} for part in parts):
        return "empty or traversal path component"
    for part in parts:
        if any(ord(character) < 32 or ord(character) == 127 for character in part):
            return "control character"
        if any(character in WINDOWS_FORBIDDEN_CHARACTERS for character in part):
            return "Windows-forbidden character"
        if part.endswith((" ", ".")):
            return "trailing space or period"
        device_stem = part.split(".", 1)[0].rstrip(" .").upper()
        if device_stem in WINDOWS_RESERVED_NAMES:
            return "Windows-reserved device name"
    return ""

def _read_baseline(path: Path) -> bytes:
    """Reject oversized baselines by metadata, then retain a race-safe read cap."""
    try:
        info = path.stat()
        if not stat.S_ISREG(info.st_mode) or info.st_size > MAX_FILE_BYTES:
            raise RepairDirectorError("baseline file exceeds the size boundary")
        with path.open("rb") as stream:
            raw = stream.read(MAX_FILE_BYTES + 1)
    except RepairDirectorError:
        raise
    except OSError as exc:
        raise RepairDirectorError("baseline file is unavailable") from exc
    if len(raw) > MAX_FILE_BYTES:
        raise RepairDirectorError("baseline file exceeds the size boundary")
    return raw

def _read_provider_file(path: Path) -> bytes:
    """Read one provider JSON file without crossing its declared byte boundary."""
    try:
        info = path.stat()
        if not stat.S_ISREG(info.st_mode) or info.st_size > MAX_PROVIDER_BYTES:
            raise RepairDirectorError("candidate file exceeds the size boundary")
        with path.open("rb") as stream:
            raw = stream.read(MAX_PROVIDER_BYTES + 1)
    except RepairDirectorError:
        raise
    except OSError as exc:
        raise RepairDirectorError("candidate file is unavailable") from exc
    if len(raw) > MAX_PROVIDER_BYTES:
        raise RepairDirectorError("candidate file exceeds the size boundary")
    return raw

def candidate_from_document(document: Mapping[str, Any], root: str | os.PathLike[str]) -> RepairCandidate:
    """Parse one complete candidate and bind it to the current workspace."""
    if type(document) is not dict or document.get("schema") != CANDIDATE_SCHEMA:
        raise RepairDirectorError("candidate schema is unsupported")
    base = _workspace(root)
    raw_changes = document.get("changes")
    if type(raw_changes) is not list or not 1 <= len(raw_changes) <= MAX_CHANGED_FILES:
        raise RepairDirectorError("candidate changes must be a bounded array")
    changes: list[CandidateChange] = []
    for raw in raw_changes:
        if type(raw) is not dict:
            raise RepairDirectorError("candidate change must be an object")
        relative = _relative(raw.get("path"))
        before = raw.get("before_sha256")
        if before is not None and not isinstance(before, str):
            raise RepairDirectorError("before_sha256 has an invalid type")
        content = _decode_content(raw)
        target = _target(base, relative, missing=before is None)
        if before is None:
            if target.exists():
                raise RepairDirectorError("add candidate targets an existing path")
        else:
            if _sha(_read_baseline(target)) != before:
                raise RepairDirectorError("candidate is stale for " + relative)
        changes.append(CandidateChange(relative, before, content))
    rules = document.get("target_rules", [])
    fingerprints = document.get("target_fingerprints", [])
    if type(rules) is not list or type(fingerprints) is not list:
        raise RepairDirectorError("candidate target identities must be arrays")
    return RepairCandidate(
        str(document.get("candidate_id", "")), str(document.get("producer", "")),
        tuple(changes), tuple(str(item) for item in rules),
        tuple(str(item) for item in fingerprints),
        str(document.get("rationale", "")),
        document.get("producer_evidence", {}) if type(document.get("producer_evidence", {})) is dict else {},
    )

def candidate_from_provider_text(text: str, root: str | os.PathLike[str]) -> RepairCandidate:
    """Accept exactly one JSON candidate; markdown/code-fence extraction is forbidden."""
    if not isinstance(text, str) or not 1 <= len(text.encode("utf-8")) <= MAX_PROVIDER_BYTES:
        raise RepairDirectorError("provider candidate response is empty or oversized")
    def strict_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise RepairDirectorError("provider candidate contains a duplicate JSON key")
            result[key] = value
        return result
    try:
        document = json.loads(text, object_pairs_hook=strict_object)
    except (json.JSONDecodeError, RecursionError) as exc:
        raise RepairDirectorError("provider response is not exactly one JSON document") from exc
    return candidate_from_document(document, root)

def mechanical_candidates(root: str | os.PathLike[str], findings: Iterable[Any], *,
                          maximum: int = 8) -> list[RepairCandidate]:
    """Generate bounded, deterministic complete-source candidates for supported Python rules."""
    if not 0 <= int(maximum) <= MAX_CANDIDATES:
        raise RepairDirectorError("mechanical candidate limit is invalid")
    base = _workspace(root)
    grouped: dict[str, list[dict[str, Any]]] = {}
    for raw in findings:
        row = _finding_row(raw)
        try:
            relative = _finding_relative(base, row.get("path"))
        except RepairDirectorError:
            continue
        if _RULE_RE.fullmatch(str(row.get("rule", ""))):
            grouped.setdefault(relative, []).append(row)
    candidates: list[RepairCandidate] = []
    for relative in sorted(grouped, key=str.casefold):
        if len(candidates) >= maximum:
            break
        target = _target(base, relative)
        if target.suffix.lower() not in {".py", ".pyi"}:
            continue
        try:
            raw_source = _read_baseline(target)
            source = raw_source.decode("utf-8", "strict")
            proposal = verified_remediation.propose_fixes(source, relative, grouped[relative])
        except (RepairDirectorError, OSError, UnicodeError, ValueError, SyntaxError):
            continue
        if not proposal.changed or not proposal.improved_source:
            continue
        resolved_rules = sorted(set(edit.rule for edit in proposal.edits
                                    if edit.rule != "import"))
        bound = [row for row in grouped[relative]
                 if str(row.get("rule", "")) in set(resolved_rules)]
        rules = tuple(sorted(set(str(row.get("rule")) for row in bound)))
        fingerprints = tuple(sorted(set(str(row.get("fingerprint")) for row in bound
                                        if _SHA_RE.fullmatch(str(row.get("fingerprint", ""))))))
        if not rules and not fingerprints:
            continue
        content = proposal.improved_source.encode("utf-8")
        before = _sha(raw_source)
        identifier = "mechanical-%02d-%s" % (len(candidates) + 1, _sha([relative, rules, before])[:16])
        candidates.append(RepairCandidate(
            identifier, "attestor-deterministic-remediation/4.1",
            (CandidateChange(relative, before, content),), rules, fingerprints,
            "Apply deterministic source transformations for supported findings.",
            {"proposal_sha256": _sha({"target": proposal.target,
                                      "before": proposal.original_sha256,
                                      "after": proposal.candidate_sha256,
                                      "rules": resolved_rules}),
             "resolved_rules": resolved_rules,
             "refusal_count": len(proposal.refusals)},
        ))
    return candidates

def snapshot_target(root: str | os.PathLike[str], findings: Iterable[Any] = ()) -> dict[str, Any]:
    """Snapshot exactly a selected file, or delegate to repository snapshotting.

    A file analysis must not silently widen repository-memory scope to every
    sibling in its parent directory.  The file snapshot stores only its relative
    name, size, digest, finding identities, and an explicitly unavailable
    architecture summary.
    """
    supplied = Path(root).expanduser()
    if supplied.is_symlink():
        raise MemoryError("memory target is not a regular file")
    target = supplied.resolve()
    if target.is_dir():
        return snapshot(target, findings)
    if not target.is_file():
        raise MemoryError("memory target is not a regular file")
    try:
        size = target.stat().st_size
        if size > MAX_TOTAL_BYTES:
            raise MemoryError("memory target exceeds the byte boundary")
        digest = _sha(target.read_bytes())
    except OSError as exc:
        raise MemoryError("memory target cannot be read") from exc
    base = target.parent
    finding_keys = sorted(set(filter(None, (_finding_key(base, item) for item in findings))))
    content = {
        "schema": SCHEMA, "repository": target.name,
        "repository_id": _sha(str(target).casefold()),
        "files": [{"path": target.name, "sha256": digest, "bytes": size}],
        "skipped": [],
        "architecture": {
            "modules": 0, "definitions": 0, "resolved_call_edges": 0,
            "entrypoints": [], "import_cycles": [], "config_keys_used": [],
            "state": "not-derived-for-single-file-scope",
        },
        "finding_keys": finding_keys,
        "scope": {"kind": "file", "siblings_read": False},
        "privacy": {
            "source_code_stored": False, "finding_messages_stored": False,
            "secret_values_stored": False, "absolute_paths_stored": False,
        },
    }
    content["snapshot_id"] = _sha(_canonical(content))
    return content

def minimize(source: str, ext: str, rule: str) -> str:
    """Greedy line minimizer that preserves the target rule."""
    if not _has_rule(source, ext, rule):
        return source
    lines = source.splitlines()
    changed = True
    while changed and len(lines) > 1:
        changed = False
        for i in range(len(lines)):
            trial = lines[:i] + lines[i + 1:]
            text = "\n".join(trial) + "\n"
            if text.strip() and _has_rule(text, ext, rule):
                lines = trial
                changed = True
                break
    text = "\n".join(lines)
    return text + ("\n" if text else "")

def _public_data(value: Any) -> Any:
    """Recursively remove terminal controls from caller-visible string values."""
    if isinstance(value, str):
        return _text(value, len(value))
    if isinstance(value, list):
        return [_public_data(item) for item in value]
    if isinstance(value, tuple):
        return [_public_data(item) for item in value]
    if isinstance(value, Mapping):
        clean: dict[Any, Any] = {}
        for key, item in value.items():
            public_key = _text(key, len(key)) if isinstance(key, str) else key
            if public_key == "" or public_key in clean:
                continue
            clean[public_key] = _public_data(item)
        return clean
    return value

def plan_queries(question: str, *, maximum: int = 6) -> list[dict[str, Any]]:
    """Create deterministic research facets; a plan is not a search result."""
    if not isinstance(question, str) or not question.strip() or len(question.encode("utf-8")) > MAX_QUESTION_BYTES:
        raise ResearchError("question must be non-empty text no larger than 16 KiB")
    if not 1 <= int(maximum) <= MAX_QUERIES:
        raise ResearchError("query count is outside the bounded policy")
    base = _bounded_query(question)
    profile = classify_question(question)
    candidates: list[tuple[str, str]] = [("direct", base)]
    candidates.extend([
        ("primary", _bounded_query(base + " official primary source")),
        ("evidence", _bounded_query(base + " evidence research")),
        ("limitations", _bounded_query(base + " limitations criticism")),
    ])
    if profile["time_sensitive"]:
        candidates.append(("freshness", _bounded_query(base + " latest update date")))
    if "academic" in profile["categories"] or "medical" in profile["categories"]:
        candidates.append(("scholarly", _bounded_query(base + " systematic review research paper")))
    if "legal" in profile["categories"]:
        candidates.append(("authority", _bounded_query(base + " government court official text")))
    if "product" in profile["categories"] or "travel" in profile["categories"]:
        candidates.append(("independent", _bounded_query(base + " independent comparison drawbacks")))
    seen: set[str] = set()
    result = []
    for purpose, query in candidates:
        key = query.casefold()
        if key in seen:
            continue
        seen.add(key)
        result.append({"purpose": purpose, "query": query, "query_sha256": _sha(query)})
        if len(result) >= maximum:
            break
    return result

def _robots_can_fetch(text: str, url: str, agent: str) -> bool:
    """Bounded longest-match robots evaluator for User-agent/Allow/Disallow."""
    if len(text.encode("utf-8", "replace")) > MAX_ROBOTS_BYTES:
        return False
    groups: list[tuple[list[str], list[tuple[bool, str]]]] = []
    agents: list[str] = []
    rules: list[tuple[bool, str]] = []
    saw_rule = False
    for raw in text.splitlines()[:20_000]:
        line = raw.split("#", 1)[0].strip()
        if not line or ":" not in line:
            continue
        name, value = (item.strip() for item in line.split(":", 1))
        lower = name.casefold()
        if lower == "user-agent":
            if saw_rule and agents:
                groups.append((agents, rules)); agents, rules, saw_rule = [], [], False
            product = value.casefold()
            if product == "*" or re.fullmatch(r"[a-z_-]+", product):
                agents.append(product)
        elif lower in {"allow", "disallow"} and agents:
            saw_rule = True
            if value or lower == "allow":
                rules.append((lower == "allow", value))
    if agents:
        groups.append((agents, rules))
    token = agent.casefold()
    if not re.fullmatch(r"[a-z_-]+", token):
        return False
    exact = [rules for names, rules in groups if token in names]
    selected = exact if exact else [rules for names, rules in groups if "*" in names]
    combined = [rule for group in selected for rule in group]
    parsed_url = urlsplit(url)
    path = _robots_octet_spelling((parsed_url.path or "/") + (
        "?" + parsed_url.query if parsed_url.query else "")
    )
    if path == "/robots.txt":
        return True
    matches: list[tuple[int, bool]] = []
    for allow, pattern in combined:
        if not pattern:
            continue
        anchored = pattern.endswith("$")
        value = _robots_octet_spelling(pattern[:-1] if anchored else pattern)
        expression = "^" + re.escape(value).replace(r"\*", ".*") + ("$" if anchored else "")
        try:
            if re.search(expression, path):
                matches.append((_robots_specificity(value), allow))
        except re.error:
            continue
    if not matches:
        return True
    longest = max(length for length, _allow in matches)
    # Equivalent Allow and Disallow matches resolve to Allow.
    return any(allow for length, allow in matches if length == longest)

def _robots_specificity(pattern: str) -> int:
    """Count path octets, excluding wildcard syntax, for longest-match ties."""
    count = index = 0
    while index < len(pattern):
        if pattern[index] == "*":
            index += 1
        elif pattern[index] == "%" and index + 2 < len(pattern) and re.fullmatch(
                r"[0-9A-F]{2}", pattern[index + 1:index + 3]):
            count += 1
            index += 3
        else:
            count += len(pattern[index].encode("utf-8"))
            index += 1
    return count

def _text(value: Any, maximum: int = 1_000) -> str:
    """Return bounded single-line text that cannot steer a terminal display."""
    safe: list[str] = []
    for character in str(value or ""):
        codepoint = ord(character)
        if character in _BIDI_CONTROLS or codepoint < 32 or 0x7F <= codepoint <= 0x9F:
            if character in "\t\r\n":
                safe.append(" ")
            elif codepoint <= 0xFF:
                safe.append("\\x%02x" % codepoint)
            else:
                safe.append("\\u%04x" % codepoint)
        else:
            safe.append(character)
        if len(safe) >= maximum:
            break
    return "".join(safe)

def _trusted_counts(evidence: Mapping | None) -> dict[str, int]:
    """Read measurements only from an explicitly validated envelope."""
    if not isinstance(evidence, Mapping) or evidence.get("validated") is not True:
        return {}
    values = evidence.get("counts", {})
    if not isinstance(values, Mapping):
        return {}
    out = {}
    for key, value in values.items():
        if (isinstance(key, str) and isinstance(value, int)
                and not isinstance(value, bool) and 0 <= value <= 10_000_000):
            out[key.upper()] = value
    return out

def _proved_improvement(row) -> tuple[bool, list[str]]:
    """Require the complete deterministic proof bundle before saying VERIFIED."""
    reasons = []
    if not isinstance(row, Mapping):
        return False, ["improvement is not an object"]
    if row.get("accepted") is not True:
        reasons.append("accepted must be the boolean true")
    verification = row.get("verification")
    if not isinstance(verification, Mapping) or verification.get("accepted") is not True:
        reasons.append("verification bundle is missing or refused")
        verification = {}
    if verification.get("compiler_or_parser") != "verified":
        reasons.append("parser/compiler verification is missing")
    if verification.get("new_findings"):
        reasons.append("verification reports new findings")
    if verification.get("new_failures"):
        reasons.append("verification reports new failures")
    probes = row.get("probes")
    if not isinstance(probes, list) or not probes or any(
            not isinstance(probe, Mapping) or probe.get("status") != "passed" for probe in probes):
        reasons.append("required assurance probes are missing or failed")
    selected = row.get("selected_tests", {})
    if isinstance(selected, Mapping) and selected.get("status") in {"failed", "timed-out"}:
        reasons.append("selected tests failed")
    source = row.get("improved_source")
    if not isinstance(source, str) or not source:
        reasons.append("improved source is absent")
    elif secret_guard.scan_text(source, str(row.get("target", "improved-source"))):
        reasons.append("improved source contains credential-like material")
    try:
        resolved = int(row.get("resolved_count", -1))
        remaining = int(row.get("remaining_count", -1))
    except (TypeError, ValueError):
        reasons.append("repair counts are invalid")
    else:
        if resolved != len(verification.get("resolved_findings", [])):
            reasons.append("resolved count contradicts verification evidence")
        if remaining != verification.get("findings_after"):
            reasons.append("remaining count contradicts verification evidence")
    if row.get("reasons"):
        reasons.append("improvement contains refusal reasons")
    return not reasons, reasons

def _git_show(ref: str, path: str) -> str:
    """The contents of `path` at git `ref` (e.g. HEAD), or '' if unavailable."""
    try:
        proc = subprocess.run(["git", "show", "%s:%s" % (ref, path)],
                              capture_output=True, text=True, timeout=30)
    except (OSError, subprocess.SubprocessError):
        return ""
    return proc.stdout if proc.returncode == 0 else ""

def _diff(old: list, new: list) -> tuple:
    """(introduced, fixed) as multisets keyed on (rule, source-line-text), so the
    same finding relocated is neither introduced nor fixed."""
    old_keys = Counter((rule, text) for rule, _s, _l, text, _m in old)
    introduced = []
    for item in new:
        key = (item[0], item[3])
        if old_keys[key] > 0:
            old_keys[key] -= 1
        else:
            introduced.append(item)
    new_keys = Counter((rule, text) for rule, _s, _l, text, _m in new)
    fixed = []
    for item in old:
        key = (item[0], item[3])
        if new_keys[key] > 0:
            new_keys[key] -= 1
        else:
            fixed.append(item)
    return introduced, fixed

#!/usr/bin/env python3
"""
review.py -- review a Python *change*, not the whole file.

grade.py judges a file as it stands; this judges what a change did to it. Give it
the old and new versions and it reports only what the diff INTRODUCED -- the
findings present in the new version but not the old -- plus what it FIXED, and the
A-F grade delta. Pre-existing noise is ignored, so the review is about your diff
and nothing else.

Findings are matched by (rule + the exact source line text), so moving code up or
down never looks like a new bug -- only genuinely new problems count. It fuses
every Python engine grade.py uses (detect + deepscan + rarebugs), so a change that
introduces a rare bug, a security smell, or a complexity blow-up all show up.

Exit code = number of introduced findings, so CI can fail a change that adds bugs:

    review.py old/app.py new/app.py          # compare two files
    review.py app.py --git                    # compare app.py against its git HEAD
    review.py app.py --git --ref v1.2.0       # ...against a tag/branch/commit
    review.py old.py new.py --json            # machine-readable
"""
from __future__ import annotations

import argparse
import subprocess
import sys
from collections import Counter

import grade
import metrics

_SEV_ORDER = {"HIGH": 0, "MEDIUM": 1, "LOW": 2, "INFO": 3}


def _read(path: str) -> str:
    try:
        with open(path, encoding="utf-8", errors="replace") as fh:
            return fh.read()
    except OSError:
        return ""


def _git_show(ref: str, path: str) -> str:
    """The contents of `path` at git `ref` (e.g. HEAD), or '' if unavailable."""
    try:
        proc = subprocess.run(["git", "show", "%s:%s" % (ref, path)],
                              capture_output=True, text=True, timeout=30)
    except (OSError, subprocess.SubprocessError):
        return ""
    return proc.stdout if proc.returncode == 0 else ""


def _findings_of(src: str, path: str) -> list:
    """(rule, severity, line, text, message) for every Python finding in `src`.
    text is the stripped source line -- the anchor that survives line shifts."""
    if not src.strip():
        return []
    lines = src.splitlines()
    _fg, findings, _funcs = grade.grade_source(src, path, metrics.DEFAULT_LIMITS)
    out = []
    for finding in findings:
        text = lines[finding.line - 1].strip() if 0 < finding.line <= len(lines) else ""
        message = getattr(finding, "message", "")
        out.append((finding.rule, finding.severity, finding.line, text, message))
    return out


def _diff(old: list, new: list) -> tuple:
    """(introduced, fixed) as multisets keyed on (rule, source-line-text), so the
    same finding relocated is neither introduced nor fixed."""
    old_keys = Counter((rule, text) for rule, _s, _l, text, _m in old)
    introduced = []
    for item in new:
        key = (item[0], item[3])
        if old_keys[key] > 0:
            old_keys[key] -= 1
        else:
            introduced.append(item)
    new_keys = Counter((rule, text) for rule, _s, _l, text, _m in new)
    fixed = []
    for item in old:
        key = (item[0], item[3])
        if new_keys[key] > 0:
            new_keys[key] -= 1
        else:
            fixed.append(item)
    return introduced, fixed


def review(old_src: str, new_src: str, old_path: str, new_path: str) -> dict:
    limits = metrics.DEFAULT_LIMITS
    introduced, fixed = _diff(_findings_of(old_src, old_path), _findings_of(new_src, new_path))
    introduced.sort(key=lambda f: _SEV_ORDER.get(f[1], 4))
    before = grade.grade_source(old_src, old_path, limits)[0] if old_src.strip() else None
    after = grade.grade_source(new_src, new_path, limits)[0]
    return {"introduced": introduced, "fixed": fixed, "before": before, "after": after}


def review_files(old_path: str, new_path: str) -> dict:
    return review(_read(old_path), _read(new_path), old_path, new_path)


def review_git(path: str, ref: str = "HEAD") -> dict:
    return review(_git_show(ref, path), _read(path), path, path)


def _grade_arrow(before, after) -> str:
    if before is None:
        return "%s (%d)" % (after.grade, after.score)
    return "%s (%d) -> %s (%d)" % (before.grade, before.score, after.grade, after.score)


def render(result: dict, label: str) -> str:
    introduced, fixed = result["introduced"], result["fixed"]
    lines = ["review: %s" % label,
             "  grade %s   |   +%d introduced, -%d fixed"
             % (_grade_arrow(result["before"], result["after"]), len(introduced), len(fixed))]
    if introduced:
        lines.append("  introduced by this change:")
        for rule, severity, line, _text, message in introduced:
            detail = (" -- " + message) if message else ""
            lines.append("    [%s] %s at line %d%s" % (severity, rule, line, detail))
    else:
        lines.append("  no new findings -- this change adds no detectable problems.")
    if fixed:
        lines.append("  fixed by this change: " + ", ".join(sorted({f[0] for f in fixed})))
    return "\n".join(lines)


def _as_json(result: dict) -> str:
    import json
    before, after = result["before"], result["after"]
    payload = {
        "before": {"grade": before.grade, "score": before.score} if before else None,
        "after": {"grade": after.grade, "score": after.score},
        "introduced": [{"rule": r, "severity": s, "line": l, "message": m}
                       for r, s, l, _t, m in result["introduced"]],
        "fixed": sorted({f[0] for f in result["fixed"]}),
    }
    return json.dumps(payload, indent=2)


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("paths", nargs="+", help="OLD NEW, or a single file with --git")
    ap.add_argument("--git", action="store_true",
                    help="compare the single given file against its version at --ref")
    ap.add_argument("--ref", default="HEAD", help="git ref to compare against (default HEAD)")
    ap.add_argument("--json", action="store_true", help="machine-readable output")
    args = ap.parse_args(argv)

    if args.git:
        if len(args.paths) != 1:
            ap.error("--git takes exactly one file to compare against its git history")
        result = review_git(args.paths[0], args.ref)
        label = "%s (working tree vs %s)" % (args.paths[0], args.ref)
    else:
        if len(args.paths) != 2:
            ap.error("give OLD and NEW file paths, or one file with --git")
        result = review_files(args.paths[0], args.paths[1])
        label = args.paths[1]

    print(_as_json(result) if args.json else render(result, label))
    return min(len(result["introduced"]), 250)


if __name__ == "__main__":
    sys.exit(main())

class RuntimePolicy:
    """Explicit execution policy.  Every execution capability defaults off."""

    allow_execution: bool = False
    allow_target_execution: bool = False
    allow_network: bool = False
    allow_child_processes: bool = False
    allow_unisolated_non_python: bool = False
    timeout_seconds: float = DEFAULT_TIMEOUT
    cpu_seconds: int = 10
    memory_bytes: int = 512 * 1024 * 1024
    max_output_bytes: int = DEFAULT_MAX_OUTPUT
    max_processes: int = 1
    deterministic_seed: int = 13_371
    allowed_executables: tuple[str, ...] = field(
        default_factory=lambda: (str(Path(sys.executable).resolve()),))

    @classmethod
    def selected_tests(cls, **overrides) -> "RuntimePolicy":
        """Return a network-denied policy after explicit test authorization."""
        values = dataclasses.asdict(cls())
        values.update(overrides)
        values["allow_execution"] = True
        values["allowed_executables"] = tuple(values["allowed_executables"])
        return cls(**values)

    def validated(self) -> "RuntimePolicy":
        if not 0.05 <= float(self.timeout_seconds) <= MAX_TIMEOUT:
            raise ValueError("timeout_seconds must be between 0.05 and 300")
        if not 1 <= int(self.cpu_seconds) <= 300:
            raise ValueError("cpu_seconds must be between 1 and 300")
        if not 16 * 1024 * 1024 <= int(self.memory_bytes) <= 16 * 1024**3:
            raise ValueError("memory_bytes must be between 16 MiB and 16 GiB")
        if not 1 <= int(self.max_output_bytes) <= MAX_OUTPUT:
            raise ValueError("max_output_bytes must be between 1 byte and 4 MiB")
        if not 1 <= int(self.max_processes) <= 128:
            raise ValueError("max_processes must be between 1 and 128")
        if not 0 <= int(self.deterministic_seed) <= 2**32 - 1:
            raise ValueError("deterministic_seed must be an unsigned 32-bit integer")
        if any(not isinstance(item, str) or not item for item in self.allowed_executables):
            raise ValueError("allowed_executables must contain non-empty paths")
        return self

def run_selected_tests(command: Sequence[str], cwd: str | os.PathLike[str], *,
                       authorized: bool = False,
                       policy: RuntimePolicy | None = None) -> RuntimeResult:
    """Convenience API that still preserves both explicit execution gates."""
    return run_command(command, cwd, policy=policy, authorized=authorized,
                       purpose="selected-tests")

def shannon_entropy(value: str) -> float:
    """Calculate Shannon entropy per character for an ephemeral candidate."""
    if not value:
        return 0.0
    counts = Counter(value)
    length = float(len(value))
    return -sum((count / length) * math.log2(count / length)
                for count in counts.values())

def scan_staged_diff(diff: str) -> list[SecretFinding]:
    """Scan only added lines from a caller-supplied staged unified diff."""
    diff = _bounded_export(diff, "staged diff")
    current = "<staged-diff>"; target_line = 0; findings: list[SecretFinding] = []
    for raw in diff.splitlines():
        if raw.startswith("+++ "):
            current = raw[4:].removeprefix("b/")[:1_024]
        elif raw.startswith("@@"):
            match = re.search(r"\+(\d+)", raw)
            target_line = int(match.group(1)) - 1 if match else target_line
        elif raw.startswith("+") and not raw.startswith("+++"):
            target_line += 1
            findings.extend(scan_text(raw[1:], source_kind="staged-diff", path=current,
                                      line_offset=target_line - 1))
        elif not raw.startswith("-"):
            target_line += 1
        if len(findings) >= MAX_FINDINGS: break
    return findings[:MAX_FINDINGS]

def scan_history_export(export: str) -> list[SecretFinding]:
    """Scan a supplied patch/history export without invoking Git."""
    export = _bounded_export(export, "history export")
    return [SecretFinding(item.rule_id, item.severity, "git-history-export", item.path,
                          item.line, item.evidence)
            for item in scan_staged_diff(export)]

def _contains_raw_secret(value: Any) -> bool:
    """Conservatively reject recognizable secret material anywhere in a report."""
    pending = [value]
    visited = 0
    while pending:
        current = pending.pop()
        visited += 1
        if visited > 250_000:
            return True
        if isinstance(current, str):
            if any(pattern.search(current) for _rule, _severity, pattern in _PATTERNS):
                return True
            for match in _ASSIGNMENT.finditer(current):
                candidate = match.group("quoted") or match.group("bare") or ""
                if (not _PLACEHOLDERS.fullmatch(candidate) and
                        len(set(candidate)) >= 5 and _entropy(candidate) >= 3.0):
                    return True
        elif type(current) is dict:
            pending.extend(current.keys()); pending.extend(current.values())
        elif type(current) in {list, tuple}:
            pending.extend(current)
    return False

def scan_hostile_file_out_of_process(path: str | os.PathLike[str], timeout: float = 10.0) -> dict[str, Any]:
    """Scan an untrusted local artifact in an isolated Python child process.

    The worker uses isolated-mode Python, a minimal environment, no shell, a
    bounded timeout/output, and only Attestor's parser code.  It never imports or
    executes the target artifact.
    """
    supplied = Path(path).expanduser()
    if supplied.is_symlink():
        raise SecretLifecycleError("out-of-process scanner refuses linked artifacts")
    target = supplied.resolve(strict=True)
    if not target.is_file() or target.stat().st_size > MAX_FILE_BYTES:
        raise SecretLifecycleError("out-of-process artifact exceeds the file boundary")
    environment = {key: value for key, value in os.environ.items()
                   if key in {"SystemRoot", "WINDIR", "TEMP", "TMP", "PATH", "PATHEXT"}}
    try:
        result = subprocess.run([sys.executable, "-I", str(Path(__file__).resolve()),
                                 "--worker", str(target)], stdin=subprocess.DEVNULL,
                                capture_output=True, text=True, shell=False,
                                timeout=max(0.1, min(float(timeout), 30.0)),
                                env=environment, check=False)
    except (OSError, subprocess.SubprocessError) as exc:
        raise SecretLifecycleError("out-of-process scanner failed") from exc
    if result.returncode != 0 or len(result.stdout) > 8 * 1024 * 1024:
        raise SecretLifecycleError("out-of-process scanner rejected the artifact")
    try:
        report = json.loads(result.stdout)
    except json.JSONDecodeError as exc:
        raise SecretLifecycleError("out-of-process scanner returned invalid evidence") from exc
    if not verify_report(report):
        raise SecretLifecycleError("out-of-process scanner returned invalid evidence")
    return report

class _CappedRows(list[dict[str, Any]]):
    """List-shaped scanner sink that refuses resource-amplified output."""

    def __init__(self, limit: int) -> None:
        super().__init__()
        self.limit = max(1, int(limit))
        self.truncated = False

    def append(self, row: dict[str, Any]) -> None:
        if len(self) < self.limit:
            super().append(row)
        else:
            self.truncated = True

def _linklike(path: Path) -> bool:
    """Recognize POSIX links and Windows reparse points without following them."""
    if path.is_symlink():
        return True
    metadata = path.lstat()
    attributes = int(getattr(metadata, "st_file_attributes", 0))
    reparse = int(getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400))
    return bool(attributes & reparse)

def retain(rows: Iterable[dict[str, Any]], engine: str) -> None:
        """Retain a bounded global top-K instead of the first K observations."""
        nonlocal raw_seen, raw_truncated
        for scanner_index, row in enumerate(rows):
            if scanner_index >= MAX_ROWS_PER_SCANNER:
                raw_truncated = True
                return
            if type(row) is not dict:
                continue
            normalized = _normalize(row, snapshot_map, route_files)
            if normalized is None:
                continue
            raw_seen += 1
            priority = (
                float(SEVERITY_WEIGHT.get(
                    str(normalized.get("severity", "MEDIUM")), 0)),
                float(normalized.get("risk_score", 0)),
                float(normalized.get("confidence", 0)),
                str(normalized.get("fingerprint", "")),
            )
            entry = (priority, raw_seen, engine, normalized)
            if len(ranked_findings) < raw_limit:
                heapq.heappush(ranked_findings, entry)
            elif priority > ranked_findings[0][0]:
                heapq.heapreplace(ranked_findings, entry)
            if raw_seen > raw_limit:
                raw_truncated = True

def enrich_findings(findings: Iterable[dict[str, Any]], context: dict[str, Any],
                    repo_report: dict[str, Any]) -> list[dict[str, Any]]:
    """Attach uniform taxonomy, evidence, reachability, and risk metadata."""
    components = context.get("attack_surface", {}).get("components", [])
    route_files = {row["path"] for row in components
                   if row.get("kind") == "web-or-api-route"}
    rows = []
    for original in findings:
        row = security_taxonomy.enrich_taxonomy(dict(original))
        row.setdefault("precision", "high" if row.get("confidence", 0) >= 0.85 else "medium")
        row.setdefault("evidence", [{
            "kind": "static-detector", "path": row.get("path", ""),
            "line": max(1, int(row.get("line", 1))),
            "description": row.get("message", "static security evidence"),
        }])
        if not isinstance(row.get("reachability"), dict) or "risk_score" not in row:
            row = _enrich_risk(row, route_files, repo_report)
        rows.append(row)
    return rows

def workspace_scope_sha256(workspace: str | os.PathLike[str]) -> str:
    """Content-address the bounded, link-free local workspace without executing it."""
    try:
        return security_validation413.tree_manifest(workspace)["report_sha256"]
    except security_validation413.ValidationError as exc:
        raise SecurityLabError(str(exc)) from exc

def _command(experiment: str, target: str, duration: int) -> tuple[str, ...]:
    """Build the only command shape the lab is permitted to submit."""
    return ("attestor-security-lab", experiment, "--target", target,
            "--duration", str(duration), "--artifacts", "/tmp/attestor-artifacts")

def execute(self, plan: LabPlan,
                authorization: LabAuthorization | None = None) -> dict[str, Any]:
        """Run one fixed experiment; omission of authorization always refuses."""
        if not self.verify_plan(plan):
            return self._refused(plan, "plan integrity verification failed")
        if plan.status != "ready" or not _IMAGE.fullmatch(plan.image):
            return self._refused(plan, plan.gap or "experiment adapter is unavailable")
        try: current_digest = workspace_scope_sha256(plan.workspace)
        except (OSError, SecurityLabError):
            return self._refused(plan, "workspace could not be re-attested")
        try:
            base = Path(plan.workspace).resolve(strict=True)
            target = (base / Path(plan.target)).resolve(strict=True)
            relative = target.relative_to(base)
            if (relative.as_posix() != plan.target or
                    not _is_test_target(relative, plan.experiment)):
                return self._refused(plan, "test target failed execution-time scope validation")
        except (OSError, ValueError):
            return self._refused(plan, "test target could not be re-attested")
        if not hmac.compare_digest(current_digest, plan.workspace_sha256):
            return self._refused(plan, "workspace changed after plan creation")
        if not isinstance(authorization, LabAuthorization) or not authorization.valid_for(
                plan.experiment, current_digest, plan.plan_sha256):
            return self._refused(plan, "explicit plan-bound lab authorization is required")
        if not self.fabric.capabilities.eligible:
            return self._refused(plan, "no eligible local rootless execution fabric is available")
        fabric_auth = execution_fabric35.ExecutionAuthorization(
            True, authorization.purpose, authorization.actor)
        request = execution_fabric35.ExecutionRequest(
            image=plan.image, command=plan.command, workspace=plan.workspace,
            label="lab-" + plan.experiment.replace("-", ""))
        result = self.fabric.run_disposable(request, fabric_auth)
        return {"schema": SCHEMA, "version": VERSION, "status": result.status,
                "experiment": plan.experiment, "plan_sha256": plan.plan_sha256,
                "returncode": result.returncode, "timed_out": result.timed_out,
                "truncated": result.truncated, "runtime": result.runtime,
                "transcript": result.transcript, "reason": result.reason,
                "controls": {"host_execution": False, "network": False,
                             "workspace": "disposable-copy", "image_pull": False}}

def finding_fingerprint(row: dict[str, Any]) -> str:
    """Return a value-independent, deterministic finding identity."""
    payload = json.dumps([
        "attestor-finding/v1", str(row.get("rule", "")),
        str(row.get("path", "")).replace("\\", "/").lower(),
        max(1, int(row.get("line", 1))), str(row.get("cwe", "")),
    ], ensure_ascii=True, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()

def baseline_document(report: dict[str, Any]) -> dict[str, Any]:
    """Build a baseline document suitable for a future ``--baseline`` scan."""
    return {
        "schema": BASELINE_SCHEMA,
        "fingerprints": sorted({row["fingerprint"] for row in report.get("findings", [])}),
        "note": "Fingerprints contain rule/location metadata only; no matched secret material.",
    }

def _safe_text(value: Any, maximum: int = 1_024, *, redact_secrets: bool = True) -> str:
    """Return bounded text that is safe for terminals and security reports."""
    raw = str(value if value is not None else "")
    if redact_secrets and _looks_like_secret(raw):
        return "[redacted]"
    output: list[str] = []
    size = 0
    for character in unicodedata.normalize("NFC", raw):
        codepoint = ord(character)
        if character in "\t\r\n":
            rendered = " "
        elif codepoint < 32 or 0x7F <= codepoint <= 0x9F:
            rendered = "\\x%02x" % codepoint
        elif 0xD800 <= codepoint <= 0xDFFF:
            rendered = "\\u%04x" % codepoint
        elif codepoint in _BIDI:
            rendered = "\\u%04x" % codepoint
        else:
            rendered = character
        if size + len(rendered) > maximum:
            break
        output.append(rendered)
        size += len(rendered)
    return "".join(output)

def _is_regex_pattern_declaration(line: str) -> bool:
    """Distinguish a detector regex literal from executable behavior text."""
    return _REGEX_PATTERN_DECLARATION.match(line) is not None

def _is_reparse_metadata(metadata: os.stat_result) -> bool:
    """Recognize POSIX links and every Windows reparse-point class."""
    attributes = int(getattr(metadata, "st_file_attributes", 0))
    reparse = int(getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400))
    return stat.S_ISLNK(metadata.st_mode) or bool(attributes & reparse)

def _is_linklike(path: Path) -> bool:
    """Treat symbolic links, junctions, and opaque reparse points as links."""
    try:
        return _is_reparse_metadata(os.lstat(path))
    except OSError:
        return True

def _resolved_without_link(base: Path, candidate: Path) -> bool:
    """Require canonical containment and refuse a reparse in any child spelling."""
    try:
        resolved = candidate.resolve(strict=True)
        resolved.relative_to(base)
    except (OSError, ValueError):
        return False
    return os.path.normcase(str(resolved)) == os.path.normcase(
        str(candidate.absolute()))

def _read_verified_regular_file(
    path: Path, initial: os.stat_result, base_device: int, limit: int,
) -> tuple[bytes | None, str]:
    """Read twice through one descriptor and verify identity/content stability."""
    flags = os.O_RDONLY | int(getattr(os, "O_BINARY", 0))
    flags |= int(getattr(os, "O_NOFOLLOW", 0))
    flags |= int(getattr(os, "O_NOINHERIT", 0))
    try:
        descriptor = os.open(path, flags)
        try:
            opened = os.fstat(descriptor)
            if (
                _is_reparse_metadata(opened)
                or not stat.S_ISREG(opened.st_mode)
                or int(opened.st_dev) != base_device
                or not all(_identity(initial))
                or _identity(opened) != _identity(initial)
            ):
                return None, (
                    "opened file crossed a link, device, identity, or "
                    "regular-file boundary")
            if _metadata_token(
                    opened, include_content_fields=True) != _metadata_token(
                        initial, include_content_fields=True):
                return None, "file metadata changed before content verification"
            if opened.st_size > limit:
                return None, "file exceeded the applicable byte boundary"

            first = _read_fd_pass(descriptor, limit)
            middle = os.fstat(descriptor)
            second = _read_fd_pass(descriptor, limit)
            final = os.fstat(descriptor)
            if len(first) > limit or len(second) > limit:
                return None, "file grew beyond the read boundary"
            stable = _metadata_token(opened, include_content_fields=True)
            if (
                _metadata_token(middle, include_content_fields=True) != stable
                or _metadata_token(final, include_content_fields=True) != stable
                or len(first) != int(opened.st_size)
            ):
                return None, "file metadata changed while content was read"
            if not hmac.compare_digest(first, second):
                return None, "file content changed between verification reads"
            path_after = os.lstat(path)
            if (
                _is_reparse_metadata(path_after)
                or _metadata_token(
                    path_after, include_content_fields=True) != stable
            ):
                return None, (
                    "file path or metadata changed after content verification")
            return first, ""
        finally:
            # A close failure is part of the same fail-closed read operation;
            # the outer handler converts it into unavailable evidence.
            os.close(descriptor)
    except (OSError, OverflowError):
        return None, "file metadata or content became unavailable"

class _CollectionGapSink:
    """Deterministic bounded gaps with a reserved overflow disclosure."""

    def __init__(self) -> None:
        self._rows: dict[tuple[str, str], dict[str, str]] = {}
        self._withheld = 0

    def add(self, reason: str, path: str = "") -> None:
        row = {
            "capability": "workspace-collection",
            "reason": _safe_text(reason, 512),
            "path": _safe_text(path, 1_024),
        }
        key = (row["reason"], row["path"])
        if key in self._rows:
            return
        capacity = max(0, MAX_GAPS - 1)
        if len(self._rows) < capacity:
            self._rows[key] = row
        else:
            self._withheld += 1

    def rows(self) -> list[dict[str, str]]:
        rows = sorted(
            self._rows.values(),
            key=lambda row: (row["path"].casefold(), row["path"], row["reason"]),
        )
        if self._withheld and MAX_GAPS > 0:
            rows.append({
                "capability": "workspace-collection",
                "reason": _safe_text(
                    f"{self._withheld} additional distinct collection gaps were "
                    "withheld by the gap output boundary",
                    512,
                ),
                "path": "",
            })
        return rows[:MAX_GAPS]

def analyze(
    root: str | os.PathLike[str], *, staged_diff: str = "",
    history_export: str = "",
) -> dict[str, Any]:
    """Compatibility entry point for Attestor's 4.1.3 security orchestration.

    The optional staged diff is scanned as caller-supplied text and is never
    applied. ``history_export`` must be a JSON array of the metadata-only
    records accepted by :func:`scan_security_posture`; unstructured history
    containing source lines or secret values is intentionally rejected.
    """
    if not isinstance(staged_diff, str) or not isinstance(history_export, str):
        raise SecurityPostureError("staged diff and history export must be text")
    if len(staged_diff.encode("utf-8")) > MAX_FILE_BYTES:
        raise SecurityPostureError("staged diff exceeds byte boundary")
    if len(history_export.encode("utf-8")) > MAX_METADATA_BYTES:
        raise SecurityPostureError("history export exceeds metadata byte boundary")
    artifacts, gaps = collect_workspace_artifacts(root)
    if staged_diff:
        artifacts.append(Artifact(
            "__attestor_supplied__/staged.diff", staged_diff, False, "text/x-diff",
        ))
    history: Iterable[Mapping[str, Any]] = ()
    if history_export:
        parsed = _load_json(history_export, "history export")
        if type(parsed) is dict and set(parsed) == {"events"}:
            parsed = parsed["events"]
        if type(parsed) is not list:
            raise SecurityPostureError("history export must be a metadata event array")
        history = parsed
    return scan_security_posture(
        artifacts, history_evidence=history, collection_gaps=gaps,
    )

def cwe_rank(cwe: str) -> int | None:
    """Return the official CWE Top 25:2025 rank when mapped exactly."""
    return CWE_TOP25_2025_RANK.get((cwe or "").upper())

def cwe_priority_factor(cwe: str) -> float:
    """Return a conservative 1.00..1.25 risk multiplier for Top-25 CWEs."""
    rank = cwe_rank(cwe)
    return 1.0 if rank is None else round(1.0 + ((26 - rank) / 25.0) * 0.25, 3)

def primary_owasp(*, cwe: str = "", category: str = "", rule: str = "",
                  legacy: str = "") -> str:
    """Map a finding to OWASP Top 10:2025 without overstating weak evidence."""
    text = " ".join((category, rule)).lower()
    # Prefer an exact weakness mapping.  Broad terms such as "secret" and
    # "supply" are only fallbacks for findings without a mapped CWE.
    code = CWE_TO_OWASP_2025.get((cwe or "").upper())
    if code:
        return OWASP_2025[code]
    if any(word in text for word in ("supply", "dependency", "lockfile", "package",
                                      "github-action", "build-pipeline", "install-hook")):
        return OWASP_2025["A03"]
    if any(word in text for word in ("crypto", "cipher", "tls", "certificate", "secret")):
        return OWASP_2025["A04"]
    if any(word in text for word in ("exception", "error-handling", "fail-open")):
        return OWASP_2025["A10"]
    if any(word in text for word in ("logging", "alerting", "audit-log")):
        return OWASP_2025["A09"]
    match = OWASP_CODE_RX.search(legacy or "")
    if match:
        old_code, year = match.group(1).upper(), match.group(2)
        if year == "2025":
            return OWASP_2025.get(old_code, legacy)
        return OWASP_2025.get(LEGACY_TO_2025.get(old_code, ""), "")
    return ""

def stride_for(category: str, rule: str = "") -> list[str]:
    """Return applicable STRIDE threat classes, ordered and deduplicated."""
    text = " ".join((category, rule)).lower()
    values: list[str] = []
    if any(word in text for word in ("auth", "identity", "credential", "token")):
        values += ["Spoofing", "Elevation of Privilege"]
    if any(word in text for word in ("access", "authorization", "privilege", "admin")):
        values += ["Elevation of Privilege"]
    if any(word in text for word in ("injection", "integrity", "supply", "dependency",
                                      "workflow", "ci", "iac", "cloud")):
        values += ["Tampering"]
    if any(word in text for word in ("secret", "data", "exposure", "leak", "cors", "cookie")):
        values += ["Information Disclosure"]
    if any(word in text for word in ("logging", "audit")):
        values += ["Repudiation"]
    if any(word in text for word in ("availability", "resource", "dos", "limit")):
        values += ["Denial of Service"]
    return list(dict.fromkeys(values or ["Tampering"]))

def _preflight_json(value: Any) -> None:
    """Reject oversized/deep JSON shapes before ``json.dumps`` allocates them."""
    pending: list[tuple[Any, int]] = [(value, 0)]
    nodes = 0
    estimated = 0
    while pending:
        current, depth = pending.pop()
        nodes += 1
        if nodes > 300_000 or depth > 128:
            raise ValidationError("value exceeds the JSON structure boundary")
        if isinstance(current, str):
            if len(current) > MAX_JSON_BYTES:
                raise ValidationError("value exceeds the JSON boundary")
            estimated += len(current.encode("utf-8"))
        elif current is None or type(current) is bool:
            estimated += 5
        elif type(current) is int:
            estimated += max(
                1, (abs(current).bit_length() * 30_103) // 100_000 + 2)
        elif type(current) is float:
            if not math.isfinite(current):
                raise ValidationError("value contains a non-finite number")
            estimated += 32
        elif type(current) in {list, tuple}:
            if len(current) > MAX_ENTRIES:
                raise ValidationError("value exceeds the JSON collection boundary")
            estimated += len(current) + 2
            pending.extend((item, depth + 1) for item in current)
        elif type(current) is dict:
            if len(current) > MAX_ENTRIES:
                raise ValidationError("value exceeds the JSON collection boundary")
            estimated += len(current) + 2
            for key, item in current.items():
                if not isinstance(key, str):
                    raise ValidationError("JSON object keys must be text")
                if len(key) > MAX_JSON_BYTES:
                    raise ValidationError("JSON object key exceeds the boundary")
                estimated += len(key.encode("utf-8")) + 3
                pending.append((item, depth + 1))
        else:
            raise ValidationError("value contains a non-JSON type")
        if estimated > MAX_JSON_BYTES:
            raise ValidationError("value exceeds the JSON boundary")

def safe_text(value: Any, maximum: int = 1_000) -> str:
    """Return display-safe bounded text without raw terminal/bidi controls."""
    if type(maximum) is not int or maximum < 0:
        raise ValidationError("text boundary is invalid")
    output: list[str] = []
    used = 0
    for character in str(value or ""):
        code = ord(character)
        token = (f"\\u{code:04x}" if
                 code < 0x20 or 0x7F <= code <= 0x9F or character in _BIDI
                 else character)
        encoded = len(token.encode("utf-8"))
        if used + encoded > maximum:
            break
        output.append(token)
        used += encoded
    return "".join(output)

def generate_test_plans(
        entry_points: Iterable[Mapping[str, Any]],
        findings: Iterable[Mapping[str, Any]], *, maximum: int = 128) -> dict[str, Any]:
    """Generate bounded, non-payload fuzz/property/differential test plans."""
    if type(maximum) is not int or not 1 <= maximum <= MAX_FUZZ_PLANS:
        raise ValidationError("test-plan count boundary is invalid")
    entries = _bounded_values(entry_points, 4_000, "test-plan entry points")
    issues = _bounded_values(findings, MAX_FINDINGS, "test-plan findings")
    rows: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    truncated = False
    for entry in entries:
        if not isinstance(entry, Mapping):
            continue
        entry_id = safe_text(entry.get("id") or entry.get("name"), 200)
        path = safe_text(entry.get("path"), 500)
        if not entry_id:
            continue
        for mode, oracle in (
                ("property", "declared invariants remain true"),
                ("boundary-fuzz", "no crash, timeout, or invariant violation"),
                ("differential", "old and candidate behavior differ only where declared"),
        ):
            key = (entry_id, mode)
            if key in seen:
                continue
            seen.add(key)
            rows.append({
                "plan_id": _sha({"entry": entry_id, "path": path, "mode": mode})[:24],
                "entry_point": entry_id,
                "path": path,
                "mode": mode,
                "generator": {
                    "kind": "typed-boundary-values",
                    "classes": ["empty", "minimum", "maximum", "unicode",
                                "duplicate-structure", "truncated-structure"],
                    "offensive_payloads": False,
                },
                "oracle": oracle,
                "execution": "requires separately authorized sandbox",
                "evidence_state": "inferred",
            })
            if len(rows) > maximum:
                truncated = True
                break
        if truncated:
            break
    rules = sorted({
        safe_text(row.get("rule") or row.get("rule_id"), 200)
        for row in issues if isinstance(row, Mapping)
        and (row.get("rule") or row.get("rule_id"))
    })
    body = {
        "schema": "attestor-security-test-plans/4.1",
        "version": VERSION,
        "status": "planned-not-executed",
        "plans": rows[:maximum],
        "plan_count": min(len(rows), maximum),
        "rules_considered": rules[:1_000],
        "coverage": {
            "complete": not truncated,
            "gaps": (["test plans were truncated by the count boundary"]
                     if truncated else []),
        },
        "execution": {
            "target_executed": False,
            "network_accessed": False,
            "files_written": False,
        },
    }
    return _report(body)

