def _dotted(node: ast.AST | None) -> str:
    """Return a conservative dotted name without evaluating an expression."""
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        left = _dotted(node.value)
        return (left + "." if left else "") + node.attr
    if isinstance(node, ast.Call):
        return _dotted(node.func)
    return ""

def build_frontend_command(path: str | os.PathLike[str], language: str,
                           executable: str | None = None,
                           output_dir: str | os.PathLike[str] | None = None) -> list[str] | None:
    """Return a parser/no-execution command as an argv list.

    No command is returned for languages where the engine cannot guarantee a
    parser-only mode.  Callers must still use ``shell=False`` and a timeout.
    """
    source = str(Path(path).resolve())
    tool = executable or (FRONTEND_TOOLS.get(language, (None,))[0])
    if not tool:
        return None
    out = str(Path(output_dir).resolve()) if output_dir else str(Path(tempfile.gettempdir()).resolve())
    if language == "javascript":
        return [tool, "--check", "--", source]
    if language == "typescript":
        return [tool, "--pretty", "false", "--noEmit", "--noResolve", "--skipLibCheck", source]
    if language == "c":
        return [tool, "-fsyntax-only", "-fno-diagnostics-color", "-x", "c", source]
    if language == "cpp":
        return [tool, "-fsyntax-only", "-fno-diagnostics-color", "-x", "c++", source]
    if language == "java":
        return [tool, "-proc:none", "-implicit:none", "-d", out, source]
    if language == "csharp":
        return [tool, "/noconfig", "/nologo", "/target:library", "/out:" + str(Path(out) / "check.dll"), source]
    if language == "go":
        return [tool, "-e", "-d", source]
    if language == "rust":
        return [tool, "--check", "--edition", "2021", source]
    if language == "ruby":
        return [tool, "--disable-gems", "-c", source]
    if language == "php":
        return [tool, "-n", "-l", source]
    if language == "swift":
        return [tool, "-parse", source]
    if language == "shell":
        return [tool, "--noprofile", "--norc", "-n", source]
    if language == "powershell":
        parser = ("$tokens=$null;$errors=$null;"
                  "[System.Management.Automation.Language.Parser]::ParseFile($args[0],[ref]$tokens,[ref]$errors)>$null;"
                  "if($errors.Count){$errors|ForEach-Object{$_.Message};exit 1}")
        return [tool, "-NoLogo", "-NoProfile", "-NonInteractive", "-Command", parser, source]
    return None

def solve(self) -> tuple[int, bool]:
        """Solve summaries with a deterministic dependency worklist.

        A caller is revisited only when one of its resolved callees changes.
        This preserves fixed-point behavior while avoiding whole-repository
        rescans for every layer of an interprocedural chain.
        """
        queue = collections.deque(sorted(self.functions))
        queued = set(queue)
        dependencies: dict[str, set[str]] = {name: set() for name in self.functions}
        reverse: dict[str, set[str]] = collections.defaultdict(set)
        maximum = max(1_000, len(self.functions) * (MAX_EVIDENCE_CALLS + 4))
        operations = 0

        while queue and operations < maximum:
            qname = queue.popleft(); queued.remove(qname)
            operations += 1
            self.call_sites[qname] = {}
            analyzer = _FunctionAnalyzer(self, self.functions[qname], self.summaries)
            summary = analyzer.run()

            new_dependencies = {
                row["target"] for row in self.call_sites[qname].values() if row["target"]
            }
            for target in dependencies[qname] - new_dependencies:
                reverse[target].discard(qname)
            for target in new_dependencies - dependencies[qname]:
                reverse[target].add(qname)
            dependencies[qname] = new_dependencies

            if summary != self.summaries[qname]:
                self.summaries[qname] = summary
                for caller in sorted(reverse.get(qname, ())):
                    if caller not in queued:
                        queue.append(caller); queued.add(caller)

        self.function_evaluations = operations
        equivalent_rounds = (operations + max(1, len(self.functions)) - 1) // max(1, len(self.functions))
        return equivalent_rounds, not bool(queue)

def _absolute_import(module: str, current_module: str, path: str) -> str:
    """Resolve Python's leading-dot import spelling without importing code."""
    if not module.startswith("."):
        return module
    level = len(module) - len(module.lstrip("."))
    suffix = module[level:]
    package = current_module if PurePosixPath(path).name == "__init__.py" \
        else current_module.rpartition(".")[0]
    parts = [part for part in package.split(".") if part]
    if level - 1 > len(parts):
        return ""
    prefix = parts[:len(parts) - (level - 1)] if level > 1 else parts
    return ".".join([*prefix, *([suffix] if suffix else [])])

class AdapterRegistry:
    """Closed parser registry; registration is explicit and duplicate-safe."""
    def __init__(self) -> None:
        self._by_language: dict[str, Adapter] = {}

    def register(self, adapter: Adapter) -> None:
        if not adapter.name or not adapter.languages:
            raise SemanticGraphError("adapter name and languages are required")
        if adapter.available and not callable(adapter.extractor):
            raise SemanticGraphError("available adapter requires a callable extractor")
        if (not isinstance(adapter.cache_token, str) or not adapter.cache_token or
                len(adapter.cache_token) > 256):
            raise SemanticGraphError("adapter cache token is invalid")
        if adapter.starts_process and not adapter.invokes_compiler:
            raise SemanticGraphError("process-starting adapter must declare compiler invocation")
        if adapter.level.startswith("compiler-derived") and not adapter.compiler_evidence:
            raise SemanticGraphError("compiler-derived adapters require compiler evidence")
        if adapter.compiler_evidence is not None:
            _canonical(adapter.compiler_evidence)
        for language in adapter.languages:
            if language in self._by_language:
                raise SemanticGraphError(f"adapter already registered for {language}")
            self._by_language[language] = adapter

    def get(self, language: str) -> Adapter | None:
        return self._by_language.get(language)

    def report(self) -> list[dict[str, Any]]:
        unique = {adapter.name: adapter for adapter in self._by_language.values()}
        rows = []
        for item in sorted(unique.values(), key=lambda value: value.name):
            row = {"name": item.name, "languages": list(item.languages),
                   "analysis_level": item.level, "available": item.available,
                   "cache_token_sha256": _sha(item.cache_token),
                   "compiler_invoked": item.invokes_compiler,
                   "process_started": item.starts_process}
            if item.compiler_evidence is not None:
                row["compiler_evidence"] = json.loads(
                    _canonical(item.compiler_evidence).decode("utf-8"))
            rows.append(row)
        return rows

class SemanticCache:
    """In-memory content cache.  It stores JSON facts, never AST objects or source."""
    def __init__(self) -> None:
        self._entries: dict[str, tuple[str, str, dict[str, Any], list[dict[str, Any]]]] = {}

    def synchronize(self, paths: set[str]) -> list[str]:
        removed = sorted(set(self._entries) - paths)
        for path in removed:
            del self._entries[path]
        return removed

    def lookup(self, path: str, sha256: str, adapter_key: str) -> tuple[dict[str, Any], list[dict[str, Any]]] | None:
        row = self._entries.get(path)
        if row and row[0] == sha256 and row[1] == adapter_key:
            return json.loads(json.dumps(row[2])), json.loads(json.dumps(row[3]))
        return None

    def store(self, path: str, sha256: str, adapter_key: str, facts: dict[str, Any],
              gaps: list[dict[str, Any]]) -> bool:
        invalidated = (path in self._entries and
                       self._entries[path][:2] != (sha256, adapter_key))
        self._entries[path] = (sha256, adapter_key, json.loads(json.dumps(facts)),
                               json.loads(json.dumps(gaps)))
        return invalidated

def _terminal_text(value: Any, maximum: int = 2_000) -> str:
    """Preserve ordinary Unicode while visibly escaping display controls."""
    result: list[str] = []
    rendered_size = 0
    for character in str(value if value is not None else ""):
        codepoint = ord(character)
        if character in "\t\r\n":
            rendered = " "
        elif codepoint < 32 or 0x7F <= codepoint <= 0x9F:
            rendered = "\\x%02x" % codepoint
        elif codepoint in _BIDI_CONTROLS:
            rendered = "\\u%04x" % codepoint
        else:
            rendered = character
        if rendered_size + len(rendered) > maximum:
            break
        result.append(rendered)
        rendered_size += len(rendered)
    return "".join(result)

def load_pack_json(payload: bytes | str, *, maximum_bytes: int = 8 * 1024 * 1024) -> dict[str, Any]:
    """Decode one bounded strict-JSON pack without duplicate-key collapse."""
    if type(maximum_bytes) is not int or not 1 <= maximum_bytes <= 64 * 1024 * 1024:
        raise RulePackError("rule-pack JSON byte boundary is invalid")
    if isinstance(payload, bytes):
        raw = payload
        try:
            text = raw.decode("utf-8")
        except UnicodeError as exc:
            raise RulePackError("rule-pack JSON is not valid UTF-8") from exc
    elif isinstance(payload, str):
        text = payload
        raw = text.encode("utf-8")
    else:
        raise RulePackError("rule-pack JSON must be bytes or text")
    if len(raw) > maximum_bytes:
        raise RulePackError("rule-pack JSON exceeds the byte boundary")
    try:
        value = json.loads(text, object_pairs_hook=_reject_duplicate_pairs)
    except RulePackError:
        raise
    except (json.JSONDecodeError, UnicodeError, RecursionError) as exc:
        raise RulePackError("rule-pack JSON cannot be parsed") from exc
    if type(value) is not dict:
        raise RulePackError("rule-pack JSON root must be an object")
    _canonical(value)
    return value

def _local_flow(tree: ast.AST) -> list[tuple[int, str, str]]:
    """Conservative same-scope source/assignment/sink witnesses for fixtures."""
    sources = graph41._SOURCE_CALLS
    sinks = graph41._SINKS
    result: list[tuple[int, str, str]] = []
    for scope in [tree, *[node for node in ast.walk(tree)
                           if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))]]:
        env: set[str] = set()
        body = _statement_sequence(getattr(scope, "body", []))
        for statement in body:
            if isinstance(statement, (ast.Assign, ast.AnnAssign)):
                value = statement.value
                tainted = any(isinstance(node, ast.Call) and _dotted(node.func) in sources
                              for node in ast.walk(value))
                names = {node.id for node in ast.walk(value) if isinstance(node, ast.Name)}
                tainted = tainted or bool(names & env)
                targets = statement.targets if isinstance(statement, ast.Assign) else [statement.target]
                for target in targets:
                    if isinstance(target, ast.Name):
                        if tainted:
                            env.add(target.id)
                        else:
                            env.discard(target.id)
            for expression in _statement_expressions(statement):
                for node in ast.walk(expression):
                    if not isinstance(node, ast.Call) or _dotted(node.func) not in sinks:
                        continue
                    argument = node.args[0] if node.args else next(
                        (keyword.value for keyword in node.keywords if keyword.arg is not None), None)
                    outer = _dotted(argument.func) if isinstance(argument, ast.Call) else ""
                    context = sinks[_dotted(node.func)][1]
                    if (outer in graph41._SANITIZERS or
                            outer in graph41._SINK_SANITIZERS.get(context, ())):
                        continue
                    direct = argument is not None and any(
                        isinstance(part, ast.Call) and _dotted(part.func) in sources
                        for part in ast.walk(argument))
                    names = ({part.id for part in ast.walk(argument) if isinstance(part, ast.Name)}
                             if argument is not None else set())
                    if direct or names & env:
                        result.append((node.lineno, _dotted(node.func),
                                       sinks[_dotted(node.func)][0]))
    return result

def merkle_root(leaves: Sequence[str]) -> str:
    """Root over ordered leaf digests.

    Odd nodes are promoted rather than duplicated: duplicating the last leaf is
    the classic malleability bug that lets two different leaf sets share a root.
    """
    if not leaves:
        return _sha_value({"schema": SCHEMA, "leaves": 0})
    level = list(leaves)
    while len(level) > 1:
        nxt: list[str] = []
        for index in range(0, len(level) - 1, 2):
            nxt.append(_sha_text(level[index] + level[index + 1]))
        if len(level) % 2:
            nxt.append(level[-1])
        level = nxt
    return level[0]

def _default_cost(path: str) -> int:
    """File size, or 1 when it cannot be read.

    Bytes are a crude proxy for analysis cost but a far better one than file
    count: parsing and walking an AST scales with the source, not with how many
    files it was split into.
    """
    try:
        return max(1, os.path.getsize(path))
    except OSError:
        return 1

def shard_result(shard: int, plan_report: dict[str, Any],
                 findings: Sequence[Any]) -> dict[str, Any]:
    """Package one worker's output so compose() can check it belongs."""
    for row in plan_report.get("assignments", []):
        if row.get("shard") == shard:
            return {"schema": RESULT_SCHEMA, "shard": shard,
                    "assignment_sha256": row["assignment_sha256"],
                    "findings": list(findings)}
    raise ShardError("shard %r is not part of this plan" % (shard,))

class Verification:
    """The outcome of checking an attestation, and why."""
    valid: bool          # signature verified against a trusted key
    authentic: bool      # same as valid; named for the forensic reader
    state: str           # fresh | stale | future-dated | expiry-unknown | invalid
    key_id: str
    generated_at: str
    expires_at: str
    errors: tuple[str, ...] = ()

    @property
    def trustworthy(self) -> bool:
        """Signed by a trusted key and currently within its validity window."""
        return self.valid and self.state in {"fresh", "expiry-unknown"}

def _require_verifiable_report(report: Mapping[str, Any]) -> None:
    """The report must be a snapshot report that self-verifies before we sign it.

    Signing a malformed or already-inconsistent report would attach authority
    to evidence Attestor would otherwise reject, so the gate is the snapshot
    module's own verifier, unchanged.
    """
    if not isinstance(report, Mapping):
        raise AttestationError("snapshot report must be an object")
    if report.get("schema") != snapshot41.SCHEMA:
        raise AttestationError("attestation only signs a source-snapshot report")
    ok, errors = snapshot41.verify_report(report)
    if not ok:
        raise AttestationError(
            "snapshot report did not self-verify: " + ", ".join(errors[:3]))
    if not DIGEST_PATTERN.fullmatch(str(report.get("snapshot_sha256", ""))):
        raise AttestationError("snapshot report has no valid content identity")

def trustworthy(self) -> bool:
        """Signed by a trusted key and currently within its validity window."""
        return self.valid and self.state in {"fresh", "expiry-unknown"}

def canonical_json(value: Any) -> bytes:
    """Return the byte representation used for IDs and HMAC authentication."""
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False,
                      allow_nan=False).encode("utf-8")

def make_purl(ecosystem: str, name: str, version: str = "") -> str:
    """Create a normalized package URL for a supported package ecosystem."""
    ecosystem = ecosystem.strip().lower()
    if not _SAFE_ECOSYSTEM.fullmatch(ecosystem):
        raise SupplyChainError("invalid ecosystem")
    name = _normal_name(ecosystem, name)
    if not _SAFE_NAME.fullmatch(name) or name.startswith(("/", ".")) or ".." in name.split("/"):
        raise SupplyChainError("invalid package name")
    namespace = ""
    package = name
    if ecosystem == "maven" and ":" in name:
        namespace, package = name.rsplit(":", 1)
    elif ecosystem in {"npm", "composer"} and "/" in name:
        namespace, package = name.rsplit("/", 1)
    elif ecosystem == "golang" and "/" in name:
        namespace, package = name.rsplit("/", 1)
    safe = ".-_~"
    encoded = quote(package, safe=safe)
    if namespace:
        encoded = "/".join(quote(part, safe=safe) for part in namespace.split("/")) + "/" + encoded
    exact = _exact_version(version)
    return "pkg:%s/%s%s" % (ecosystem, encoded, ("@" + quote(exact, safe=safe + "+")) if exact else "")

def _decoded_integrity(values: Iterable[str]) -> list[tuple[str, str]]:
    """Normalize hexadecimal and SRI base64 hashes without weakening semantics."""
    expected = {"sha1": 20, "sha256": 32, "sha384": 48, "sha512": 64}
    result: set[tuple[str, str]] = set()
    for value in values:
        for token in value.split():
            algorithm = payload = ""
            if ":" in token:
                algorithm, payload = token.split(":", 1)
            elif "-" in token:
                algorithm, payload = token.split("-", 1)
            algorithm = algorithm.lower().replace("-", "")
            size = expected.get(algorithm)
            if not size or not payload:
                continue
            if len(payload) == size * 2 and re.fullmatch(r"[0-9a-fA-F]+", payload):
                result.add((algorithm, payload.lower()))
                continue
            try:
                padding = "=" * (-len(payload) % 4)
                decoded = base64.b64decode(payload + padding, validate=True)
            except (binascii.Error, ValueError):
                continue
            if len(decoded) == size:
                result.add((algorithm, decoded.hex()))
    return sorted(result)

def _license_kind(value: str) -> tuple[str, str]:
    """Classify local license text conservatively without claiming full SPDX validation."""
    clean = value.strip()
    if clean in _SPDX_LICENSE_IDS:
        return "id", clean
    expression = re.fullmatch(r"[A-Za-z0-9.+() -]+", clean)
    tokens = re.findall(r"[A-Za-z0-9][A-Za-z0-9.+-]*", clean)
    license_tokens = [token for token in tokens if token not in {"AND", "OR", "WITH"}]
    if (expression and any(token in {"AND", "OR", "WITH"} for token in tokens)
            and license_tokens and all(token in _SPDX_LICENSE_IDS for token in license_tokens)):
        return "expression", clean
    return "name", _bounded(clean, 256)

def build_spdx(inventory: Inventory, *, source_date_epoch: int | None = None) -> dict[str, Any]:
    """Build Attestor's primary SPDX export (SPDX 3.0.1 JSON-LD)."""
    return build_spdx_3_0_1(inventory, source_date_epoch=source_date_epoch)

def sign_advisory_snapshot(snapshot: Mapping[str, Any], key: bytes, key_id: str) -> dict[str, Any]:
    """Authenticate a deterministic snapshot using a caller-managed HMAC key."""
    if not isinstance(key, bytes) or len(key) < 32:
        raise SupplyChainError("HMAC key must contain at least 32 bytes")
    if not re.fullmatch(r"[A-Za-z0-9_.-]{1,128}", key_id or ""):
        raise SupplyChainError("invalid key ID")
    unsigned = _without_signature(dict(snapshot))
    if unsigned.get("schema") != SNAPSHOT_SCHEMA:
        raise SupplyChainError("unsupported advisory snapshot schema")
    _validate_snapshot_structure(unsigned)
    digest = hmac.new(key, canonical_json(unsigned), hashlib.sha256).hexdigest()
    return {**unsigned, "signature": {"algorithm": "hmac-sha256", "key_id": key_id, "digest": digest}}

def assess_advisories(inventory: Inventory, snapshot: Mapping[str, Any] | None = None,
                      trusted_keys: Mapping[str, bytes] | None = None,
                      *, now: _datetime.datetime | None = None,
                      reachability: Mapping[str, Any] | None = None) -> dict[str, Any]:
    """Match authenticated local advisory data; never fetches or claims live status."""
    reach = normalize_reachability(inventory, reachability or {})
    if snapshot is None:
        return {
            "state": "unavailable", "live_status": False,
            "message": "No advisory snapshot was provided; vulnerability status is unknown.",
            "verification": {"valid": False, "authenticated": False, "state": "not-provided"},
            "dependencies": [{"purl": dep.purl, "status": "unknown", "advisories": [],
                              "reachability": reach[dep.purl]} for dep in inventory.dependencies],
        }
    verification = verify_advisory_snapshot(snapshot, trusted_keys or {}, now=now)
    if not verification.valid:
        return {
            "state": "invalid", "live_status": False,
            "message": "Advisory snapshot could not be authenticated; results are unknown.",
            "verification": verification.to_dict(),
            "dependencies": [{"purl": dep.purl, "status": "unknown", "advisories": [],
                              "reachability": reach[dep.purl]} for dep in inventory.dependencies],
        }
    advisories = snapshot.get("advisories", [])
    results: list[dict[str, Any]] = []
    for dep in inventory.dependencies:
        matches: list[dict[str, Any]] = []
        indeterminate_range = False
        base_purl = make_purl(dep.ecosystem, dep.name)
        for advisory in advisories:
            package = advisory["package"]
            if make_purl(str(package["ecosystem"]), str(package["name"])) != base_purl:
                continue
            exact_versions = advisory.get("versions", [])
            range_result = _range_match(dep.version, advisory.get("ranges", []))
            if advisory.get("ranges") and range_result is None:
                indeterminate_range = True
            affected = bool(advisory.get("all_versions", False)) or bool(dep.version and dep.version in exact_versions) or range_result is True
            if affected:
                matches.append({
                    "id": advisory["id"], "summary": _bounded(advisory.get("summary", ""), 512),
                    "severity": str(advisory.get("severity", "unknown")).lower(),
                    "aliases": sorted(str(item) for item in advisory.get("aliases", []) if isinstance(item, str)),
                    "fixed_versions": sorted(str(item) for item in advisory.get("fixed_versions", []) if isinstance(item, str)),
                })
        matches.sort(key=lambda item: item["id"])
        results.append({
            "purl": dep.purl,
            "status": ("affected" if matches else "range_evaluation_unknown" if indeterminate_range
                       else "unknown_version" if not dep.version else "no_match_in_snapshot"),
            "advisories": matches,
            "reachability": reach[dep.purl],
            "caveat": "No match is not proof of safety; this is an authenticated offline snapshot, not a live feed." if not matches else "",
        })
    return {
        "state": verification.state, "live_status": False,
        "message": "Authenticated offline snapshot assessed; this is not live registry/advisory status.",
        "source": {str(key): _redact_evidence(value, 1024)
                   for key, value in sorted(snapshot.get("source", {}).items())},
        "verification": verification.to_dict(), "dependencies": results,
        "affected": sum(item["status"] == "affected" for item in results),
    }

def run_reachability_hook(inventory: Inventory, hook: Callable[[Dependency], Any]) -> dict[str, dict[str, Any]]:
    """Run an explicitly supplied analysis hook.  Attestor never supplies target imports here."""
    evidence: dict[str, Any] = {}
    for dep in inventory.dependencies:
        try:
            evidence[dep.purl] = hook(dep)
        except Exception as exc:  # Hooks are untrusted extension points; preserve unknown state.
            evidence[dep.purl] = {"status": "unknown", "source": "hook-error",
                                  "reason": "%s: %s" % (type(exc).__name__, _bounded(exc, 256))}
    return normalize_reachability(inventory, evidence)

def _terminal_text(value: Any, maximum: int = 4_096) -> str:
    """Preserve ordinary Unicode while visibly escaping display controls."""
    result: list[str] = []
    rendered_size = 0
    for character in str(value if value is not None else ""):
        codepoint = ord(character)
        if character in "\t\r\n":
            rendered = " "
        elif codepoint < 32 or 0x7F <= codepoint <= 0x9F:
            rendered = "\\x%02x" % codepoint
        elif codepoint in _BIDI_CONTROLS:
            rendered = "\\u%04x" % codepoint
        else:
            rendered = character
        if rendered_size + len(rendered) > maximum:
            break
        result.append(rendered)
        rendered_size += len(rendered)
    return "".join(result)

def _terminal_json(value: Any, depth: int = 0) -> Any:
    """Return JSON-shaped advisory data with terminal-safe keys and strings."""
    if depth > 128:
        raise SupplyChainTrustError("advisory nesting exceeds boundary")
    if isinstance(value, str):
        return _terminal_text(value, max(1, len(value) * 6))
    if isinstance(value, (list, tuple)):
        return [_terminal_json(item, depth + 1) for item in value]
    if type(value) is dict:
        result: dict[str, Any] = {}
        for key, item in value.items():
            if not isinstance(key, str):
                raise SupplyChainTrustError("advisory object key is not text")
            safe_key = _terminal_text(key, max(1, len(key) * 6))
            if safe_key in result:
                raise SupplyChainTrustError("advisory keys collide after control escaping")
            result[safe_key] = _terminal_json(item, depth + 1)
        return result
    return value

def _literal(value: object) -> str:
    """Typed, sortable encoding for bounded scalar constants."""
    if value is None:
        return "none:"
    if isinstance(value, bool):
        return "bool:" + ("true" if value else "false")
    if isinstance(value, str):
        return "str:" + value
    if isinstance(value, int):
        return "int:" + str(value)
    if isinstance(value, float):
        return "float:" + repr(value)
    if isinstance(value, bytes):
        return "bytes:" + value.hex()
    return ""

def _static_value(self, module: Module, node: ast.AST,
                      env: Mapping[str, Value], heap: dict[str, AbstractObject]) -> tuple[Value, bool]:
        """Extract literal global data without evaluating target expressions."""
        if isinstance(node, ast.Constant):
            literal = _literal(node.value)
            return self.value(constants=(literal,) if literal else ()), bool(literal)
        if isinstance(node, ast.Name) and node.id in env:
            return env[node.id], True
        if isinstance(node, (ast.List, ast.Tuple, ast.Set)):
            values: list[Value] = []
            fields: list[tuple[str, Value]] = []
            for index, child in enumerate(node.elts):
                value, supported = self._static_value(module, child, env, heap)
                if not supported:
                    return EMPTY, False
                values.append(value)
                fields.append(("index:%d" % index, value))
            if len(fields) > self.limits.max_object_fields:
                self.limit_hits.add("max_object_fields")
                fields = fields[:self.limits.max_object_fields]
            obj_id = "global:%s:%d:%d" % (
                module.path, getattr(node, "lineno", 1), getattr(node, "col_offset", 0))
            heap[obj_id] = AbstractObject(tuple(fields))
            constants = [constant for value in values for constant in value.constants]
            return self.value(objects=(obj_id,), constants=constants), True
        if isinstance(node, ast.Dict):
            fields: list[tuple[str, Value]] = []
            for key_node, value_node in zip(node.keys, node.values):
                literal = _literal_node(key_node)
                if not literal:
                    return EMPTY, False
                value, supported = self._static_value(module, value_node, env, heap)
                if not supported:
                    return EMPTY, False
                fields.append(("key:" + literal, value))
            if len(fields) > self.limits.max_object_fields:
                self.limit_hits.add("max_object_fields")
                fields = fields[:self.limits.max_object_fields]
            obj_id = "global:%s:%d:%d" % (
                module.path, getattr(node, "lineno", 1), getattr(node, "col_offset", 0))
            heap[obj_id] = AbstractObject(tuple(sorted(fields)))
            return self.value(objects=(obj_id,),
                              constants=(key[len("key:"):] for key, _ in fields)), True
        return EMPTY, False

def _predicate_expression(node: ast.AST) -> str:
        """Render useful branch structure without copying source literals."""
        if isinstance(node, ast.Name):
            return node.id
        if isinstance(node, ast.Attribute):
            return _dotted(node) or "attribute"
        if isinstance(node, ast.Constant):
            return "<%s-literal>" % type(node.value).__name__.lower()
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
            return "not (%s)" % FunctionAnalyzer._predicate_expression(node.operand)
        if isinstance(node, ast.BoolOp):
            operator = " and " if isinstance(node.op, ast.And) else " or "
            return operator.join(FunctionAnalyzer._predicate_expression(item)
                                 for item in node.values)
        if isinstance(node, ast.Compare):
            operators = {
                ast.Eq: "==", ast.NotEq: "!=", ast.In: "in", ast.NotIn: "not in",
                ast.Lt: "<", ast.LtE: "<=", ast.Gt: ">", ast.GtE: ">=",
                ast.Is: "is", ast.IsNot: "is not",
            }
            parts = [FunctionAnalyzer._predicate_expression(node.left)]
            for operator, comparator in zip(node.ops, node.comparators):
                parts.append(operators.get(type(operator), type(operator).__name__))
                if isinstance(comparator, (ast.Set, ast.List, ast.Tuple)):
                    parts.append("<literal-allowlist:%d>" % len(comparator.elts))
                else:
                    parts.append(FunctionAnalyzer._predicate_expression(comparator))
            return " ".join(parts)
        if isinstance(node, ast.Call):
            return (_dotted(node.func) or "dynamic-call") + "(...)"
        return "<%s-predicate>" % type(node).__name__

def payload_exec_marker(_opts):
    """The only payload type in msf-lite: a marker string proving a
    parameter reached command execution. Shells are refused by design."""
    return {
        "module": "payload.exec_marker",
        "marker": ";cfmark42;",
        "interpretation": ("marker appearing verbatim in a response "
                           "indicates command execution"),
        "refused_alternatives": list(REFUSAL_LIST),
    }

def _solve_byte_map(op_name, examples):
    """Intersect per-position constraints to solve the constant."""
    factory, space = ANALYTIC_OPS[op_name]
    candidates = None
    for src, dst in examples:
        if len(src) != len(dst):
            continue
        allowed = set(space)
        for i in range(len(src)):
            valid = {k for k in allowed
                     if factory(k)(bytes([src[i]])) == bytes([dst[i]])}
            candidates = valid if candidates is None \
                else (candidates & valid)
            if not candidates:
                break
        if candidates is not None and not candidates:
            continue
    if not candidates:
        return []
    return sorted(candidates)[:4]

def analytic_candidates(examples):
    """Ops solved directly from constraints, strongest evidence first."""
    found = []
    for op_name in ANALYTIC_OPS:
        for constant in _solve_byte_map(op_name, examples):
            pipeline = [(op_name, constant)]
            if all(apply_pipeline(pipeline, src) == dst
                   for src, dst in examples):
                found.append(pipeline)
    for name, fn in SIMPLE_OPS.items():
        if all(fn(src) == dst for src, dst in examples):
            found.append([(name, None)])
    return found

def map_findings_to_threats(model: Mapping[str, Any],
                            findings: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
    """Bind measured analyzer findings to the threats that were modelled.

    A finding is linked to a category when its rule contains one of that
    category's hint tokens. The link is evidence (`basis: measured`); it does not
    by itself mean the threat is realised, only that there is something to weigh.
    """
    if not isinstance(model, Mapping) or model.get("schema") != MODEL_SCHEMA:
        raise ThreatModelError("expected a threat model")
    categories = {t.get("category") for t in (model.get("threats") or [])}
    links = []
    for f in findings:
        rule = str(f.get("rule", "")).lower()
        for category in STRIDE:
            if category not in categories:
                continue
            for hint in CATEGORY_HINTS[category]:
                if hint in rule:
                    links.append({
                        "category": category,
                        "basis": "measured",
                        "finding_rule": str(f.get("rule", "")),
                        "finding_line": f.get("line"),
                        "severity": f.get("severity"),
                    })
                    break
    return links

def severity_for_category(links: Sequence[Mapping[str, Any]],
                          severities: Mapping[str, int]) -> dict[str, int]:
    """Aggregate a worst-seen severity per STRIDE category from measured links."""
    ranking = dict(severities)
    out = {c: 0 for c in STRIDE}
    for link in links:
        cat = link.get("category")
        sev = str(link.get("severity", "")).lower()
        if cat in out and sev in ranking:
            out[cat] = max(out[cat], ranking[sev])
    return out

def looks_like_a_workstation(record: dict) -> bool:
    """Usage consistent with a machine bought to do a lot of this."""
    return record.get("bytes_this_period", 0) >= WORKSTATION_PATTERN_BYTES

def normalize_relative_path(value: str) -> str:
    """Return one portable NFC path or reject ambiguity/escape syntax."""
    if not isinstance(value, str):
        raise RepairError("change path must be text")
    value = value.replace("\\", "/")
    if unicodedata.normalize("NFC", value) != value:
        raise RepairError("change path must use canonical NFC spelling")
    if not value or len(value) > 512:
        raise RepairError("change path is empty, too long, or contains reserved syntax")
    if value.startswith("/") or value.startswith("//"):
        raise RepairError("change path must be workspace-relative")
    raw_parts = value.split("/")
    if any(part in {"", ".", ".."} for part in raw_parts):
        raise RepairError("change path contains an empty, dot, or parent segment")
    for part in raw_parts:
        stem = part.split(".", 1)[0].rstrip(" .").upper()
        if any(character in _FORBIDDEN_PATH_CHARS or
               unicodedata.category(character) in {"Cc", "Cf", "Cs"}
               for character in part):
            raise RepairError("change path contains a non-portable segment")
        utf8_bytes = len(part.encode("utf-8", "strict"))
        utf16_units = len(part.encode("utf-16-le", "strict")) // 2
        if (len(part) > 255 or utf8_bytes > 255 or utf16_units > 255 or
                part.rstrip(" .") != part or stem in _WINDOWS_RESERVED_NAMES):
            raise RepairError("change path contains a non-portable segment")
    path = PurePosixPath(*raw_parts)
    if path.is_absolute() or path.as_posix().casefold() == LOCK_NAME.casefold():
        raise RepairError("change path is reserved or absolute")
    return path.as_posix()

class FileChange:
    """Add (hash=None), update, or delete (content=None) one regular file."""

    path: str
    before_sha256: str | None
    new_content: bytes | str | None

    def __post_init__(self) -> None:
        object.__setattr__(self, "path", normalize_relative_path(self.path))
        if self.before_sha256 is not None:
            digest = str(self.before_sha256).lower()
            if not _SHA_RE.fullmatch(digest):
                raise RepairError("before_sha256 must be a lowercase SHA-256 digest")
            object.__setattr__(self, "before_sha256", digest)
        if isinstance(self.new_content, str):
            object.__setattr__(self, "new_content",
                               self.new_content.encode("utf-8", "strict"))
        elif self.new_content is not None and not isinstance(self.new_content, bytes):
            raise RepairError("new_content must be bytes, text, or None")
        if self.before_sha256 is None and self.new_content is None:
            raise RepairError("an absent file cannot be deleted")

    @property
    def operation(self) -> str:
        if self.before_sha256 is None:
            return "add"
        if self.new_content is None:
            return "delete"
        return "update"

    @property
    def after_sha256(self) -> str | None:
        return _sha(self.new_content) if self.new_content is not None else None

def _signature_ok(document: Mapping[str, Any], trusted_keys: Mapping[str, bytes]) -> str:
    """Return the trusted key_id if the signature verifies, else raise."""
    signature = document.get("signature")
    if not isinstance(signature, Mapping):
        raise TrustedAccessError("document is not signed")
    if signature.get("algorithm") != ALGORITHM:
        raise TrustedAccessError("unsupported signature algorithm")
    key_id = str(signature.get("key_id", ""))
    if not KEY_ID_PATTERN.fullmatch(key_id):
        raise TrustedAccessError("signature key_id is invalid")
    key = trusted_keys.get(key_id)
    if not isinstance(key, (bytes, bytearray)) or len(key) < MIN_KEY_BYTES:
        raise TrustedAccessError("signature key is not trusted")
    digest = signature.get("digest")
    if not isinstance(digest, str) or not DIGEST_PATTERN.fullmatch(digest):
        raise TrustedAccessError("signature digest is malformed")
    body = {key: value for key, value in document.items() if key != "signature"}
    expected = hmac.new(bytes(key), _canonical(body), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, digest):
        raise TrustedAccessError("signature verification failed")
    return key_id

def subject_fingerprint(subject_key: bytes) -> str:
    """The public fingerprint of a subject key, safe to embed in a grant."""
    if not isinstance(subject_key, (bytes, bytearray)) or len(subject_key) < MIN_KEY_BYTES:
        raise TrustedAccessError("subject key must be at least %d bytes" % MIN_KEY_BYTES)
    return hashlib.sha256(b"attestor-trusted-access-subject\x00" + bytes(subject_key)).hexdigest()

def prove_possession(subject_key: bytes, challenge: Mapping[str, Any]) -> str:
    """The subject's answer to a challenge: HMAC of the challenge under its key."""
    if not isinstance(subject_key, (bytes, bytearray)) or len(subject_key) < MIN_KEY_BYTES:
        raise TrustedAccessError("subject key must be at least %d bytes" % MIN_KEY_BYTES)
    if challenge.get("schema") != CHALLENGE_SCHEMA:
        raise TrustedAccessError("challenge schema is unsupported")
    return hmac.new(bytes(subject_key), _canonical(dict(challenge)), hashlib.sha256).hexdigest()

def _resource_covers(granted: str, requested: str) -> bool:
    """Does a granted resource pattern cover a concrete requested resource?

    Exact match, or a single trailing `/*` prefix. A bare `*` never reaches
    here -- it is refused at issue time -- so there is no way to widen a grant
    to everything.
    """
    if granted == requested:
        return True
    if granted.endswith("/*"):
        prefix = granted[:-1]                 # keep the trailing slash
        return requested.startswith(prefix) and len(requested) > len(prefix)
    return False

def issue_revocation_list(*, revoked_grant_ids: Iterable[str], authority_key: bytes,
                          authority_key_id: str, ttl_seconds: int = 24 * 60 * 60,
                          now: _datetime.datetime | None = None) -> dict[str, Any]:
    """A signed, freshness-bounded set of grant ids that must be refused."""
    ids = sorted({str(item) for item in revoked_grant_ids})
    if len(ids) > 100_000:
        raise TrustedAccessError("revocation list exceeds its bound")
    for item in ids:
        if not re.fullmatch(r"[0-9a-f]{32}", item):
            raise TrustedAccessError("a revoked grant id is malformed")
    moment = now or _utc_now()
    body = {
        "schema": REVOCATION_SCHEMA,
        "version": VERSION,
        "revoked": ids,
        "generated_at": _iso(moment),
        "expires_at": _iso(moment + _datetime.timedelta(seconds=ttl_seconds)),
    }
    return _sign(body, authority_key, authority_key_id)

def _identity_safe(value: Any, sensitive: bool = False) -> Any:
    """Remove secret material before any stable-ID hashing operation."""
    if value is None or isinstance(value, bool) or type(value) in {int, float}:
        return "<redacted>" if sensitive and value not in {None, False, 0} else value
    if isinstance(value, str):
        if sensitive or _contains_secret(value):
            return "<redacted>"
        return value[:2_000]
    if type(value) is dict:
        output = {}
        used: set[str] = set()
        redacted_key_number = 0
        for key in sorted(value):
            if not isinstance(key, str):
                raise TruthGuardError("object keys must be strings")
            secret_key = _contains_secret(key)
            if secret_key:
                redacted_key_number += 1
            safe_key = _bounded_public_key(
                key, limit=512,
                redacted_label="<redacted-key-%d>" % redacted_key_number,
                used=used)
            output[safe_key] = _identity_safe(value[key], _SENSITIVE_COMPONENT.fullmatch(key) is not None)
        return output
    if type(value) in {list, tuple}:
        return [_identity_safe(item, sensitive) for item in value[:1_024]]
    return "<unsupported>"

def guard_response(response_text: str, evidence: Mapping[str, Any],
                   claims: Sequence[Mapping[str, Any]] | None = None, *,
                   root: str | os.PathLike[str] | None = None) -> dict[str, Any]:
    """Validate explicit claims, or conservatively extract known count/assurance forms."""
    if not isinstance(response_text, str):
        raise TruthGuardError("response_text must be text")
    selected = list(claims) if claims is not None else _auto_claims(response_text)
    if not selected:
        selected = [{"kind": "statement", "text": response_text or "empty response"}]
    return validate_claims(selected, evidence, root=root, response_text=response_text)

def redact_tree(value: Any, *, _pointer_value: str = "",
                _validated: bool = False) -> Any:
    """Return a recursively bounded, credential-redacted JSON-shaped copy."""
    if not _validated:
        _assert_json_tree(value)
    if value is None or isinstance(value, bool):
        return value
    if type(value) in {int, float}:
        return "[REDACTED: sensitive field]" if _sensitive_pointer(_pointer_value) else value
    if isinstance(value, str):
        safe, _, _ = _safe_text(
            value, sensitive=_sensitive_pointer(_pointer_value),
            limit=MAX_SAFE_RESPONSE_CHARS)
        return safe
    if type(value) in {list, tuple}:
        return [redact_tree(item, _pointer_value=_pointer_value + "/" + str(index),
                            _validated=True)
                for index, item in enumerate(value)]
    if type(value) is dict:
        output: dict[str, Any] = {}
        used: set[str] = set()
        redacted_key_number = 0
        for key in sorted(value):
            secret_key = _contains_secret(key)
            if secret_key:
                redacted_key_number += 1
            public_key = _bounded_public_key(
                key, limit=1_024,
                redacted_label="[REDACTED-KEY-%d]" % redacted_key_number,
                used=used)
            child_pointer = _pointer_value + "/" + _pointer_escape(key)
            output[public_key] = redact_tree(
                value[key], _pointer_value=child_pointer, _validated=True)
        return output
    raise TruthGuardError("value is not JSON-shaped")

def deterministic_json(report: Mapping[str, Any], *, indent: int | None = 2) -> str:
    """Serialize any JSON report deterministically with recursive redaction."""
    if type(report) is not dict:
        raise TruthGuardError("report must be a JSON object")
    _assert_json_tree(report)
    safe = redact_tree(report, _validated=True)
    return json.dumps(safe, sort_keys=True, indent=indent, ensure_ascii=False, allow_nan=False)

def _project_finding(row: Any) -> dict[str, Any] | None:
    """Retain exactly the scalar finding fields Truth Guard 1 consumes."""
    if type(row) is not dict:
        return None
    projected: dict[str, Any] = {}
    for key in ("rule", "rule_id", "ruleId", "path", "line",
                "severity", "fingerprint"):
        value = row.get(key)
        if value is None or isinstance(value, (str, bool, int, float)):
            if key in row:
                projected[key] = value
    return projected

def _project_refused_improvement(row: Any) -> dict[str, Any] | None:
    """Retain refusals; accepted repairs require their complete proof objects."""
    if type(row) is not dict or row.get("accepted") is True:
        return None
    projected: dict[str, Any] = {}
    for key in ("target", "path", "status", "accepted", "complete"):
        value = row.get(key)
        if value is None or isinstance(value, (str, bool, int, float)):
            if key in row:
                projected[key] = value
    return projected

def _document_root(document: Mapping[str, Any]) -> Path | None:
    """Resolve only an existing report root for independent location checks."""
    raw = document.get("root")
    if not isinstance(raw, str) or not raw or "\x00" in raw:
        return None
    try:
        path = Path(raw).expanduser().resolve()
    except (OSError, RuntimeError, ValueError):
        return None
    if path.is_file():
        # Do not widen an exact-file report into permission to inspect siblings.
        return None
    return path if path.is_dir() else None

def guard_output(mode: str, output: Any, *, evidence: Mapping[str, Any] | None = None) -> dict[str, Any]:
    """Universal mode adapter; free-form output needs a validated envelope."""
    if type(output) is dict:
        return guard_document(output)
    if type(evidence) is dict and evidence.get("validated") is True \
            and type(evidence.get("document")) is dict:
        document = dict(evidence["document"])
        document["mode"] = str(mode)[:80]
        document["response"] = str(output)[:64 * 1024]
        return guard_document(document)
    return guard_document({
        "mode": str(mode)[:80], "status": "abstained",
        "response": "I cannot substantiate free-form output without a validated evidence envelope.",
        "coverage": {"absence_proven": False,
                     "gaps": ["validated evidence envelope was not supplied"]},
    })

def _project_finding(row: Any) -> dict[str, Any] | None:
    """Keep only fields independently consumed for a finding claim."""
    if type(row) is not dict:
        return None
    projected: dict[str, Any] = {}
    for key in ("rule", "rule_id", "ruleId", "path", "line",
                "severity", "fingerprint"):
        value = row.get(key)
        if value is None or isinstance(value, (str, bool, int, float)):
            if key in row:
                projected[key] = value
    return projected

def _project_refused_improvement(row: Any) -> dict[str, Any] | None:
    """Retain only improvements whose refusal needs no omitted proof detail."""
    if type(row) is not dict or row.get("accepted") is True:
        return None
    projected: dict[str, Any] = {}
    for key in ("target", "path", "status", "accepted", "complete"):
        value = row.get(key)
        if value is None or isinstance(value, (str, bool, int, float)):
            if key in row:
                projected[key] = value
    return projected

def _document_root(document: Mapping[str, Any]) -> Path | None:
    """Resolve only an existing report root for independent location checks."""
    raw = document.get("root")
    if not isinstance(raw, str) or not raw or "\x00" in raw:
        return None
    try:
        path = Path(raw).expanduser().resolve()
    except (OSError, RuntimeError, ValueError):
        return None
    if path.is_file():
        # The legacy independent validator accepts a directory root and would
        # otherwise be able to inspect siblings of an exact-file request.
        return None
    return path if path.is_dir() else None

def guard_output(mode: str, output: Any, *, evidence: Mapping[str, Any] | None = None) -> dict[str, Any]:
    """Universal mode adapter; free-form output needs a validated envelope."""
    if type(output) is dict:
        return guard_document(output)
    if type(evidence) is dict and evidence.get("validated") is True \
            and type(evidence.get("document")) is dict:
        document = dict(evidence["document"])
        document["mode"] = str(mode)[:80]
        document["response"] = str(output)[:64 * 1024]
        return guard_document(document)
    return guard_document({
        "mode": str(mode)[:80], "status": "abstained",
        "response": "I cannot substantiate free-form output without a validated evidence envelope.",
        "coverage": {"absence_proven": False,
                     "gaps": ["validated evidence envelope was not supplied"]},
    })

def _is_link_or_reparse(path: Path) -> bool:
    """Return true for POSIX links and Windows reparse-backed paths."""
    try:
        metadata = path.lstat()
    except OSError:
        return False
    attributes = int(getattr(metadata, "st_file_attributes", 0))
    reparse_flag = int(getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400))
    return stat.S_ISLNK(metadata.st_mode) or bool(attributes & reparse_flag)

def _snapshot_file(path: Path) -> tuple[int, str]:
    """Hash one immutable regular file without retaining its full contents."""
    try:
        with path.open("rb") as stream:
            before = os.fstat(stream.fileno())
            if before.st_size > MAX_FILE_BYTES:
                raise TruthGuard41Error("source file exceeds the per-file snapshot boundary")
            digest = hashlib.sha256()
            size = 0
            while True:
                chunk = stream.read(1024 * 1024)
                if not chunk:
                    break
                size += len(chunk)
                if size > MAX_FILE_BYTES:
                    raise TruthGuard41Error("source file exceeds the per-file snapshot boundary")
                digest.update(chunk)
            after = os.fstat(stream.fileno())
    except TruthGuard41Error:
        raise
    except OSError as exc:
        raise TruthGuard41Error("selected source inventory could not be read") from exc
    identity_before = (before.st_size, before.st_mtime_ns, getattr(before, "st_ino", 0))
    identity_after = (after.st_size, after.st_mtime_ns, getattr(after, "st_ino", 0))
    if size != before.st_size or identity_before != identity_after:
        raise TruthGuard41Error("selected source changed while its inventory was hashed")
    return size, digest.hexdigest()

def _snapshot_manifest(root: Path) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Create a bounded, complete lexical inventory of the selected root.

    Directory entries and non-followed links are included so additions and
    removals change the manifest. Only regular files contribute content bytes.
    """
    entries: list[dict[str, Any]] = []
    gaps: list[dict[str, Any]] = []
    total_bytes = 0

    def add(entry: dict[str, Any]) -> None:
        if len(entries) >= MAX_MANIFEST_ENTRIES:
            raise TruthGuard41Error("selected source inventory exceeds the entry boundary")
        entries.append(entry)

    if root.is_file():
        size, digest = _snapshot_file(root)
        return [{"path": root.name, "kind": "file", "bytes": size,
                 "sha256": digest}], []

    stack: list[tuple[Path, Path]] = [(root, Path())]
    while stack:
        directory, prefix = stack.pop()
        try:
            children = sorted(os.scandir(directory), key=lambda item: item.name)
        except OSError as exc:
            raise TruthGuard41Error("selected source inventory could not be enumerated") from exc
        pending_directories: list[tuple[Path, Path]] = []
        for child in children:
            path = Path(child.path)
            relative_path = prefix / child.name
            relative = relative_path.as_posix()
            if _is_link_or_reparse(path):
                try:
                    target = os.readlink(path)
                except OSError:
                    target = "unavailable"
                add({"path": relative, "kind": "link-or-reparse",
                     "target_sha256": _sha(os.fsencode(target))})
                gaps.append({"path": relative,
                             "reason": "link or reparse entry is inventoried but not followed"})
                continue
            try:
                if child.is_dir(follow_symlinks=False):
                    add({"path": relative, "kind": "directory"})
                    pending_directories.append((path, relative_path))
                elif child.is_file(follow_symlinks=False):
                    size, digest = _snapshot_file(path)
                    total_bytes += size
                    if total_bytes > MAX_TOTAL_BYTES:
                        raise TruthGuard41Error("selected source inventory exceeds the aggregate byte boundary")
                    add({"path": relative, "kind": "file", "bytes": size,
                         "sha256": digest})
                else:
                    add({"path": relative, "kind": "unsupported"})
                    gaps.append({"path": relative,
                                 "reason": "non-regular source entry is outside snapshot coverage"})
            except OSError as exc:
                raise TruthGuard41Error("selected source inventory entry could not be classified") from exc
        stack.extend(reversed(pending_directories))
    entries.sort(key=lambda item: (str(item.get("path", "")), str(item.get("kind", ""))))
    return entries, gaps

def require_compiled_profile(value: Any) -> VariantProfile:
    """Return *value* only when it is the intact canonical release singleton."""
    if type(value) is not VariantProfile:
        raise VariantError("variant profile is not a compiled profile")
    canonical = PROFILES.get(value.slug)
    expected = _COMPILED_SPECS.get(value.slug)
    if canonical is not value or expected is None or _profile_tuple(value) != expected:
        raise VariantError("variant profile is forged or no longer canonical")
    return value

def parse_profile(value: Any) -> VariantProfile:
    """Resolve a CLI alias or revalidate a compiled profile object.

    API and UI boundaries should call :func:`profile_for_slug`; aliases are
    deliberately a CLI convenience and are not wire-level identifiers.
    """
    if type(value) is VariantProfile:
        return require_compiled_profile(value)
    normalized = _normalize_alias(value)
    slug = ALIASES.get(normalized)
    if slug is None:
        raise VariantError("unknown Attestor 4.1.4 variant")
    return require_compiled_profile(PROFILES[slug])

def profile_for_slug(value: Any) -> VariantProfile:
    """Resolve only an exact stable slug for API/UI trust boundaries."""
    if type(value) is not str or value not in PROFILES:
        raise VariantError("variant must be one exact compiled slug")
    return require_compiled_profile(PROFILES[value])

def _canonical(value: Any) -> bytes:
    """Encode small exact JSON without allowing adversarial allocation."""
    pending: list[tuple[Any, int]] = [(value, 0)]
    nodes = 0
    estimated = 0
    while pending:
        current, depth = pending.pop()
        nodes += 1
        if nodes > MAX_CANONICAL_NODES or depth > MAX_CANONICAL_DEPTH:
            raise VariantError("variant evidence exceeds the structure boundary")
        if current is None or type(current) is bool:
            estimated += 5
        elif type(current) is int:
            if not -(2 ** 63) <= current <= 2 ** 63 - 1:
                raise VariantError("variant evidence integer is outside the boundary")
            estimated += 24
        elif type(current) is str:
            size = len(current.encode("utf-8"))
            if size > MAX_STRING_BYTES:
                raise VariantError("variant evidence text is outside the boundary")
            estimated += size + 3
        elif type(current) is list:
            if len(current) > MAX_COLLECTION_ITEMS:
                raise VariantError("variant evidence collection is outside the boundary")
            estimated += len(current) + 2
            pending.extend((item, depth + 1) for item in current)
        elif type(current) is dict:
            if len(current) > MAX_COLLECTION_ITEMS:
                raise VariantError("variant evidence collection is outside the boundary")
            estimated += len(current) + 2
            for key, item in current.items():
                if type(key) is not str or len(key.encode("utf-8")) > MAX_STRING_BYTES:
                    raise VariantError("variant evidence object key is invalid")
                estimated += len(key.encode("utf-8")) + 3
                pending.append((item, depth + 1))
        else:
            raise VariantError("variant evidence contains a non-JSON value")
        if estimated > MAX_CANONICAL_BYTES:
            raise VariantError("variant evidence exceeds the byte boundary")
    try:
        raw = json.dumps(
            value, sort_keys=True, separators=(",", ":"),
            ensure_ascii=False, allow_nan=False,
        ).encode("utf-8")
    except (TypeError, ValueError, OverflowError, RecursionError) as exc:
        raise VariantError("variant evidence is not deterministic JSON") from exc
    if len(raw) > MAX_CANONICAL_BYTES:
        raise VariantError("variant evidence exceeds the byte boundary")
    return raw

def profile_identity(value: Any) -> str:
    """Return the stable SHA-256 identity of a canonical compiled profile."""
    return profile_dict(value)["profile_sha256"]

def verify_profile_dict(value: Any) -> tuple[bool, list[str]]:
    """Verify exact shape, digest, invariant policy, and compiled identity."""
    errors: list[str] = []
    try:
        _canonical(value)
    except VariantError:
        return False, ["profile dictionary is not bounded deterministic JSON"]
    if type(value) is not dict:
        return False, ["profile dictionary is not an exact object"]
    expected_keys = {
        "schema", "version", "slug", "display_name", "mode",
        "analyzer_build_sha256", "analysis",
        "enforcement_contract", "resources", "response_language",
        "security_invariants",
        "profile_sha256",
    }
    if set(value) != expected_keys:
        errors.append("profile dictionary keys are invalid")
    if value.get("schema") != PROFILE_SCHEMA or value.get("version") != VERSION:
        errors.append("profile dictionary schema or version is invalid")
    slug = value.get("slug")
    profile = PROFILES.get(slug) if type(slug) is str else None
    if profile is None:
        errors.append("profile dictionary slug is not compiled")
    claimed = value.get("profile_sha256")
    if not isinstance(claimed, str) or SHA256_RE.fullmatch(claimed) is None:
        errors.append("profile dictionary digest is invalid")
    else:
        body = {key: item for key, item in value.items()
                if key != "profile_sha256"}
        try:
            actual = _sha(body)
        except VariantError:
            errors.append("profile dictionary body is outside the boundary")
        else:
            if not hmac.compare_digest(claimed, actual):
                errors.append("profile dictionary digest does not match")
    if profile is not None:
        try:
            expected = profile_dict(profile)
        except VariantError:
            errors.append("compiled profile failed canonical validation")
        else:
            if value != expected:
                errors.append("profile dictionary is not the compiled canonical profile")
    return not errors, errors

def load_profile_dict(value: Any) -> VariantProfile:
    """Load exact serialized evidence back to its canonical singleton."""
    valid, errors = verify_profile_dict(value)
    if not valid:
        raise VariantError("; ".join(errors[:3]))
    return require_compiled_profile(PROFILES[value["slug"]])

def verify_report(value: Any) -> tuple[bool, list[str]]:
    """Verify a variant-selection report without trusting its claimed slug."""
    errors: list[str] = []
    try:
        _canonical(value)
    except VariantError:
        return False, ["variant report is not bounded deterministic JSON"]
    if type(value) is not dict:
        return False, ["variant report is not an exact object"]
    expected_keys = {
        "schema", "version", "selected_profile",
        "selected_profile_sha256", "enforcement_policy_sha256",
        "security_policy_sha256", "report_sha256",
    }
    if set(value) != expected_keys:
        errors.append("variant report keys are invalid")
    if value.get("schema") != REPORT_SCHEMA or value.get("version") != VERSION:
        errors.append("variant report schema or version is invalid")
    selected = value.get("selected_profile")
    profile_valid, profile_errors = verify_profile_dict(selected)
    if not profile_valid:
        errors.extend("selected " + error for error in profile_errors[:4])
    selected_digest = (
        selected.get("profile_sha256") if type(selected) is dict else None)
    if (value.get("selected_profile_sha256") != selected_digest or
            not isinstance(selected_digest, str) or
            SHA256_RE.fullmatch(selected_digest) is None):
        errors.append("selected profile identity binding is invalid")
    if value.get("security_policy_sha256") != SECURITY_POLICY_SHA256:
        errors.append("variant security-policy identity is invalid")
    if value.get("enforcement_policy_sha256") != ENFORCEMENT_POLICY_SHA256:
        errors.append("variant enforcement-policy identity is invalid")
    claimed = value.get("report_sha256")
    if not isinstance(claimed, str) or SHA256_RE.fullmatch(claimed) is None:
        errors.append("variant report digest is invalid")
    else:
        body = {key: item for key, item in value.items()
                if key != "report_sha256"}
        try:
            actual = _sha(body)
        except VariantError:
            errors.append("variant report body is outside the boundary")
        else:
            if not hmac.compare_digest(claimed, actual):
                errors.append("variant report digest does not match")
    return not errors, errors

def _module_state(tree: ast.Module, name: str) -> tuple[bool, bool]:
    """Return (already imported under its name, safe to add under its name)."""
    imported = False
    unsafe = False
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                bound = alias.asname or alias.name.split(".")[0]
                if alias.name == name and bound == name:
                    imported = True
                elif bound == name:
                    unsafe = True
        elif isinstance(node, ast.ImportFrom):
            for alias in node.names:
                if (alias.asname or alias.name) == name:
                    unsafe = True
        elif isinstance(node, ast.Name) and node.id == name and isinstance(node.ctx, ast.Store):
            unsafe = True
        elif isinstance(node, ast.arg) and node.arg == name:
            unsafe = True
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) and node.name == name:
            unsafe = True
    return imported, not unsafe

def apply_remediation(report: RemediationReport, *, authorized: bool = False,
                      backup_root: str | os.PathLike[str] | None = None,
                      require_verified: bool = True) -> patchguard.ApplyResult:
    """Apply only a previously accepted report, with backup and auto-rollback."""
    if not authorized:
        raise PermissionError("applying improved source requires authorized=True/--apply")
    if not report.accepted or report.validation is None:
        raise ValueError("a rejected or unverified remediation cannot be applied")
    return patchguard.apply_candidate(
        report.validation, report.proposal.improved_source, authorized=True,
        backup_root=backup_root, require_verified=require_verified)

def baseline(request: str, bus, execute: bool = True) -> dict:
    """One raw shot from the model -- no verification, no repair."""
    try:
        raw = bus.generate(forge._gen_prompt(request))
    except brain.ProviderError as exc:
        return {"error": str(exc)}
    code = brain.strip_fences(raw if isinstance(raw, str)
                              else next(iter(raw.values()), ""))
    return _measure(code, execute)

def _addresses(host: str, port: int) -> set:
    """Resolve every address for a host; an empty/failed answer is unsafe."""
    candidate = host.strip("[]")
    literal = None
    try:
        literal = ipaddress.ip_address(candidate)
    except ValueError:
        literal = None
    if literal is not None:
        return {literal}
    try:
        ascii_host = candidate.encode("idna").decode("ascii")
        results = socket.getaddrinfo(ascii_host, port, type=socket.SOCK_STREAM)
    except (UnicodeError, OSError) as exc:
        raise UnsafeURL("could not safely resolve URL host") from exc
    addresses = set()
    for _family, _kind, _proto, _canon, sockaddr in results:
        try:
            addresses.add(ipaddress.ip_address(sockaddr[0].split("%", 1)[0]))
        except ValueError:
            continue
    if not addresses:
        raise UnsafeURL("URL host resolved to no usable address")
    return addresses

def _connect_public(host: str, port: int, timeout, source_address=None):
    """Resolve, validate, and connect to the exact validated IP (DNS pinning)."""
    addresses = _addresses(host, port)
    blocked = [address for address in addresses if not _public_address(address)]
    if blocked:
        raise UnsafeURL("connection target became non-public")
    last_error = None
    for address in sorted(addresses, key=str):
        try:
            return socket.create_connection(
                (str(address), port), timeout, source_address=source_address)
        except OSError as exc:
            last_error = exc
    if last_error:
        raise last_error
    raise UnsafeURL("URL host resolved to no usable address")

class PinnedHTTPConnection(http.client.HTTPConnection):
    """HTTP connection pinned to an IP that passed public-address validation."""

    def connect(self):
        self.sock = _connect_public(
            self.host, self.port, self.timeout, self.source_address)
        if self._tunnel_host:
            self._tunnel()

class PinnedHTTPSConnection(http.client.HTTPSConnection):
    """Pinned HTTPS connection retaining the original hostname for SNI/certs."""

    def connect(self):
        self.sock = _connect_public(
            self.host, self.port, self.timeout, self.source_address)
        server_hostname = self.host
        if self._tunnel_host:
            self._tunnel()
            server_hostname = self._tunnel_host
        self.sock = self._context.wrap_socket(self.sock, server_hostname=server_hostname)

def validate_url(url: str, *, allow_http: bool = False) -> str:
    """Validate one fetch target and all of its current DNS answers.

    Validation is repeated for each redirect by :class:`SafeRedirectHandler`.
    This meaningfully reduces SSRF and DNS-rebinding exposure, though only a
    network sandbox can remove the DNS-check/connect race entirely.
    """
    if not isinstance(url, str) or any(ch in url for ch in "\x00\r\n\\"):
        raise UnsafeURL("invalid URL")
    try:
        parsed = urllib.parse.urlsplit(url)
        port = parsed.port
    except ValueError as exc:
        raise UnsafeURL("invalid URL") from exc
    scheme = parsed.scheme.lower()
    if scheme not in {_HTTP_SCHEME, _HTTPS_SCHEME}:
        raise UnsafeURL("only public HTTP(S) URLs are supported")
    if scheme == _HTTP_SCHEME and not allow_http:
        raise UnsafeURL("plaintext HTTP is disabled; use HTTPS or explicitly allow HTTP")
    if parsed.username is not None or parsed.password is not None:
        raise UnsafeURL("URLs containing credentials are not allowed")
    host = (parsed.hostname or "").rstrip(".").lower()
    if not host or "%" in host:
        raise UnsafeURL("URL must contain a valid public host")
    if host == "localhost" or host.endswith((".localhost", ".local", ".internal")):
        raise UnsafeURL("local/private URL hosts are not allowed")
    effective_port = port or (443 if scheme == _HTTPS_SCHEME else 80)
    addresses = _addresses(host, effective_port)
    blocked = sorted(str(address) for address in addresses if not _public_address(address))
    if blocked:
        raise UnsafeURL("URL resolves to a non-public address: " + ", ".join(blocked))
    return url

class SafeRedirectHandler(urllib.request.HTTPRedirectHandler):
    """Revalidate every redirect target and cap redirect chains."""

    max_redirections = 5

    def __init__(self, *, allow_http: bool = False):
        super().__init__()
        self.allow_http = bool(allow_http)

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        target = urllib.parse.urljoin(req.full_url, newurl)
        validate_url(target, allow_http=self.allow_http)
        return super().redirect_request(req, fp, code, msg, headers, target)

class PageParser(HTMLParser):
    """Pull the structure out of a page: title, scripts (inline + linked),
    stylesheets, forms, and inline on* event handlers."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.title = ""
        self.inline_scripts = []
        self.script_srcs = []
        self.stylesheets = []
        self.forms = 0
        self.inline_handlers = []
        self._in_title = False
        self._in_script = False
        self._script_buf = []

    def handle_starttag(self, tag, attrs):
        d = {k: (v or "") for k, v in attrs}
        if tag == "title":
            self._in_title = True
        elif tag == "script":
            if d.get("src"):
                self.script_srcs.append(d["src"])
            else:
                self._in_script = True
                self._script_buf = []
        elif tag == "link" and "stylesheet" in d.get("rel", "") and d.get("href"):
            self.stylesheets.append(d["href"])
        elif tag == "form":
            self.forms += 1
        for name, value in d.items():
            if name.startswith("on") and len(name) > 2:
                self.inline_handlers.append((tag, name, value))

    def handle_endtag(self, tag):
        if tag == "title":
            self._in_title = False
        elif tag == "script" and self._in_script:
            self._in_script = False
            code = "".join(self._script_buf).strip()
            if code:
                self.inline_scripts.append(code)

    def handle_data(self, data):
        if self._in_title:
            self.title += data.strip()
        elif self._in_script:
            self._script_buf.append(data)

def analyze(html: str, base_url: str, extra_scripts=None) -> dict:
    """Parse the page and review every script it carries. extra_scripts is a
    list of (label, code) for linked .js files already fetched."""
    parser = PageParser()
    parser.feed(html)

    findings = []
    for i, code in enumerate(parser.inline_scripts):
        findings += review_js(code, f"inline-script[{i}]")
    for label, code in (extra_scripts or []):
        findings += review_js(code, label)
    findings.sort(key=detect.Finding.sort_key)
    return {"parser": parser, "base_url": base_url,
            "findings": findings, "smells": html_smells(parser)}

def _biggest_buggy_script(report: dict):
    """The inline script with the most findings -- the best candidate to rewrite."""
    counts = {}
    for f in report["findings"]:
        counts[f.path] = counts.get(f.path, 0) + 1
    if not counts:
        return None, None
    label = max(counts, key=counts.get)
    p = report["parser"]
    for i, code in enumerate(p.inline_scripts):
        if f"inline-script[{i}]" == label:
            return label, code
    return None, None

def _imports(tree: ast.AST) -> dict[str, str]:
    """local name -> fully qualified target it refers to."""
    bindings: dict[str, str] = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                bindings[alias.asname or alias.name.split(".")[0]] = alias.name
        elif isinstance(node, ast.ImportFrom) and node.module and not node.level:
            for alias in node.names:
                bindings[alias.asname or alias.name] = \
                    node.module + "." + alias.name
    return bindings

def _resolve(callee: str, owner_module: str, bindings: dict[str, str],
             functions: dict[str, Any], by_tail: dict[str, list[str]]) -> str:
    """Resolve a call to a function anywhere in the program."""
    head, _, rest = callee.partition(".")
    target = bindings.get(head)
    if target:
        candidate = target + ("." + rest if rest else "")
        if candidate in functions:
            return candidate
        # `import helpers` then `helpers.handle(...)`
        if rest and (target + "." + rest) in functions:
            return target + "." + rest
    local = owner_module + "." + callee if owner_module else callee
    if local in functions:
        return local
    if callee in functions:
        return callee
    matches = by_tail.get(callee.rsplit(".", 1)[-1], ())
    # Only bind a bare name when it is unambiguous across the program;
    # guessing between same-named functions invents call edges.
    return matches[0] if len(matches) == 1 else ""

def compare_versions(left, right):
    """Return -1/0/1, or None when the pair is not confidently comparable."""
    try:
        lt = _version_tokens(left)
        rt = _version_tokens(right)
    except Exception:
        return None
    if not lt or not rt:
        return None
    # any alphabetic component makes the comparison inconclusive; guessing
    # an ordering for pre-release tags is exactly the wrong place to be clever
    if any(part[0] != 0 for part in lt + rt):
        return None
    return -1 if lt < rt else (1 if lt > rt else 0)

def dot_product_sixed(weight_vec, feature_vec):
    """Fixed-point dot product: floor(sum(w_i * x_i)) over six features."""
    acc = 0
    for weight, feat in zip(weight_vec, feature_vec):
        acc += weight * feat
    return acc

def centrality(graph, alpha_scaled=ALPHA_SCALED):
    """Power iteration on x' = a*M^T x + (1-a)*s, fixed-point 1e6."""
    nodes = graph["nodes"]
    ids = sorted(nodes)
    index = {nid: i for i, nid in enumerate(ids)}
    size = len(ids)

    outgoing = {nid: 0 for nid in ids}
    for src, dst in graph["edges"]:
        outgoing[src] += 1

    # column-normalized adjacency, row-major over targets
    m_rows = [[0] * size for _ in range(size)]
    for src, dst in graph["edges"]:
        if outgoing[src]:
            m_rows[index[dst]][index[src]] = SCALE // outgoing[src]

    seed = []
    total_sev = 0.0
    for nid in ids:
        sev = float(nodes[nid].get("severity", 0.5))
        seed.append(sev)
        total_sev += sev
    if total_sev <= 0:
        seed = [1.0 / size] * size
    else:
        seed = [s / total_sev for s in seed]
    s_scaled = [int(round(v * SCALE)) for v in seed]

    x = list(s_scaled)
    one_minus_alpha = SCALE - alpha_scaled
    residual = SCALE
    iterations = 0
    for iterations in range(1, MAX_ITER + 1):
        new_x = []
        for j in range(size):
            acc = 0
            row = m_rows[j]
            for i in range(size):
                if row[i]:
                    acc += x[i] * row[i]
            value = (alpha_scaled * acc // SCALE
                     + one_minus_alpha * s_scaled[j] // SCALE)
            new_x.append(value)
        residual = max(abs(new_x[i] - x[i]) for i in range(size))
        x = new_x
        if residual <= TOL_SCALED:
            break

    norm = sum(x) or 1
    values = {nid: round(x[index[nid]] / norm, 6) for nid in ids}
    return {
        "values": values,
        "iterations_used": iterations,
        "final_residual_scaled": residual,
        "converged": residual <= TOL_SCALED,
        "equation": "x' = 0.85*(M^T x) + 0.15*s, fixed point 1e6",
    }

def expand_targets(targets):
    """Lazy generator: hosts stream one at a time, nothing materializes,
    so even a /8 simply takes as long as it takes."""
    for raw in targets:
        text = raw.strip()
        if not text:
            continue
        try:
            network = ipaddress.ip_network(text, strict=False)
        except ValueError as exc:
            raise RnError("bad target %r: %s" % (text, exc)) from None
        for addr in network:
            if addr.version == 4:
                yield str(addr)

def build_chainforge_graph(findings):
    """Earned-ladder graph: each primitive's requirements are exactly the
    capabilities granted by everything before it, so the chain models
    escalating access rather than wishful edges."""
    nodes = {}
    edges = []
    entry = "campaign.entry"
    nodes[entry] = {"kind": "entry", "severity": 0.1, "grants": []}
    previous = entry
    ranked = sorted(findings,
                    key=lambda f: -FINDING_SEVERITY.get(f["kind"], (0.4,))[0])
    accumulated = set()
    for index, finding in enumerate(ranked[:24]):
        node_id = "finding.%d.%s" % (index, finding["kind"])
        severity, grants, _extra = FINDING_SEVERITY.get(
            finding["kind"], (0.4, [], []))
        nodes[node_id] = {
            "kind": "primitive",
            "severity": severity,
            "grants": list(grants),
            "requires": sorted(accumulated),
            "novelty": 0.5,
        }
        edges.append([previous, node_id])
        previous = node_id
        accumulated |= set(grants)
    impact = "campaign.impact"
    nodes[impact] = {"kind": "impact", "severity": 1.0,
                     "requires": sorted(accumulated)}
    if len(nodes) > 2:
        edges.append([previous, impact])
    return {"nodes": nodes, "edges": edges,
            "entries": [entry], "impacts": [impact]}

def execute_with_coverage(fn, data, allowed=(KeyboardInterrupt, SystemExit)):
    """Run fn(data) under a line tracer. Returns (covered_set, crash|None)."""
    covered = set()

    def tracer(frame, event, arg):
        if event == "line":
            covered.add((id(frame.f_code), frame.f_lineno))
        return tracer

    previous = sys.gettrace()
    sys.settrace(tracer)
    try:
        fn(bytes(data))
        crash = None
    except allowed:
        crash = None
    except Exception as exc:  # noqa: BLE001 - any fault is signal here
        import traceback
        tail = traceback.format_exc(limit=3)[-600:]
        crash = {
            "exception": "%s: %s" % (type(exc).__name__, exc),
            "traceback_tail": tail,
        }
    finally:
        sys.settrace(previous)
    return covered, crash

def mutate(rng, data):
    """Local mutation ops tuned for coverage hill-climbing."""
    buf = bytearray(data)
    if not buf:
        buf.extend(b"A")
    for _ in range(rng.randint(1, 3)):
        if not buf:
            buf.extend(b"A")
        i = rng.randrange(len(buf))
        op = rng.randrange(4)
        if op == 0:
            buf[i] = rng.randrange(256)
        elif op == 1:
            buf.insert(i, rng.choice(b"ATTACKPWN"))
        elif op == 2:
            del buf[i:i + rng.randint(1, 4)]
        else:
            chunk = bytes(buf[i:i + 2]) or b"\x00"
            buf[i:i] = chunk * 2
    if len(buf) > 256:
        del buf[256:]
    return bytes(buf)

def apply_constraint(buf, constraint, mode):
    """mode 'falsify' drives past the guard; mode 'satisfy' takes it."""
    form = constraint["form"]
    falsify = mode == "falsify"

    if form == "eq_byte":
        index = constraint["index"]
        while index >= len(buf):
            buf.extend(b"\x00")
        target = _byte_of(constraint["value"])
        # guard 'data[i] == c': satisfy => byte equals c, falsify => differs
        buf[index] = target if mode == "satisfy" else ((target ^ 1) & 0xFF)
    elif form == "neq_byte":
        index = constraint["index"]
        while index >= len(buf):
            buf.extend(b"\x00")
        target = _byte_of(constraint["value"])
        # guard 'data[i] != c': satisfy => differs, falsify => equals c
        buf[index] = ((target ^ 1) & 0xFF) if mode == "satisfy" else target
    elif form == "startswith":
        prefix = constraint["prefix"].encode("latin-1", errors="replace")
        negated = constraint.get("negated", False)
        present_needed = negated ^ (mode == "satisfy")
        if present_needed and prefix:
            buf[:len(prefix)] = prefix
        elif prefix and buf:
            buf[0] = (_byte_of(prefix[0]) ^ 1) & 0xFF
    elif form == "len_lt":
        if mode == "falsify":
            while len(buf) < constraint["n"]:
                buf.extend(b"\x00")
        else:
            del buf[max(1, constraint["n"] - 1):]
    elif form == "len_ge":
        if mode == "falsify":
            del buf[max(1, constraint["n"] - 1):]
        else:
            while len(buf) < constraint["n"]:
                buf.extend(b"\x00")

def split_credentials(request_headers):
    """Return (auth_subset, anon_rest) for header swapping."""
    auth_part = {}
    rest = {}
    for name, value in (request_headers or {}).items():
        if name.lower() in AUTH_HEADERS:
            auth_part[name] = value
        else:
            rest[name] = value
    return auth_part, rest

def build_object_graph(entries, base_url, principal_headers, principal_name,
                       timeout):
    """Baseline pass: fetch as the owning principal, learn id ownership."""
    graph = {}
    _, base_headers = split_credentials({})
    for entry in entries:
        headers = dict(base_headers)
        headers.update(principal_headers)
        headers.update({k: v for k, v in (entry.get("headers") or {}).items()
                        if k.lower() not in AUTH_HEADERS})
        body = (entry.get("body") or "").encode()
        url = base_url.rstrip("/") + entry["path"]
        status, payload = _request(entry["method"], url, headers, body,
                                   timeout)
        if status == 200:
            for obj in extract_object_ids(payload.decode("latin-1",
                                                         errors="replace")):
                key = (obj["kind"], obj["id"].lower())
                graph.setdefault(key, {
                    "id": obj["id"], "kind": obj["kind"],
                    "owner": principal_name,
                    "endpoints": set(),
                })["endpoints"].add(entry["path"])
        for obj in extract_object_ids(entry["path"]):
            key = (obj["kind"], obj["id"].lower())
            graph.setdefault(key, {
                "id": obj["id"], "kind": obj["kind"],
                "owner": principal_name,
                "endpoints": set(),
            })["endpoints"].add(entry["path"])
    return graph

def apply_rules(rules, url, headers, body):
    """Mutates headers/body/url per ordered rule list."""
    new_url = url
    new_headers = dict(headers)
    new_body = body

    for rule in rules:
        field = rule["field"]

        def sub(text):
            return rule["pattern"].sub(rule["replace"], text)

        try:
            if field in ("url", "any"):
                new_url = sub(new_url)
            if field in ("body", "any"):
                new_body = sub(new_body.decode("latin-1",
                                               errors="replace")).encode()
            if field in ("header", "any"):
                for name in list(new_headers.keys()):
                    if rule["header"] and name.lower() != rule["header"]:
                        continue
                    value = str(new_headers[name])
                    replaced = rule["pattern"].sub(rule["replace"], value)
                    if replaced != value:
                        new_headers[name] = replaced
        except re.error as exc:
            raise PxError("bad regex in rule %r: %s" % (rule["name"],
                                                        exc)) from None
    return new_url, new_headers, new_body

def _request_root(node):
                """Walk an attribute/call chain down to its base name."""
                while isinstance(node, ast.Attribute):
                    node = node.value
                if isinstance(node, ast.Name):
                    return node.id
                return ""

def run_scored(fn, data, distances, allowed):
    """Single tracer pass: collect entered function names, line coverage,
    and crash info in one execution."""
    entered = set()
    covered = set()

    def tracer(frame, event, arg):
        if event == "call":
            entered.add(frame.f_code.co_name)
            return tracer
        if event == "line":
            covered.add((id(frame.f_code), frame.f_lineno))
            return tracer
        return None

    import sys
    previous = sys.gettrace()
    sys.settrace(tracer)
    crash = None
    try:
        fn(bytes(data))
    except allowed:
        pass
    except Exception as exc:  # noqa: BLE001
        crash = {"exception": "%s: %s" % (type(exc).__name__, exc)}
    finally:
        sys.settrace(previous)

    best = INF
    for name in entered:
        best = min(best, distances.get(name, INF))
    return best, covered, crash

def classify_tier(static_evidence=None, dynamic_result=None):
    """Assign the evidence tier from what actually exists."""
    has_static = bool(static_evidence)
    has_dynamic = False
    if dynamic_result:
        has_dynamic = bool(dynamic_result.get("runtime_confirmed")
                           or dynamic_result.get("confirmed_count")
                           or dynamic_result.get("synthetic_confirmed"))
    if has_static and has_dynamic:
        return 4, TIER_NAMES[4]
    if has_dynamic:
        return 3, TIER_NAMES[3]
    if has_static:
        return 2, TIER_NAMES[2]
    return 1, TIER_NAMES[1]

def harvest_lessons(root, teacher_model, lessons_target,
                    base="http://127.0.0.1:11434", num_ctx=8192,
                    progress=False):
    """Walk the directory, feed chunks to the teacher, collect lessons."""
    lessons = []
    started = time.time()
    for path in iter_source_files(root):
        if len(lessons) >= lessons_target:
            break
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        for chunk in chunk_text(text):
            if len(lessons) >= lessons_target:
                break
            prompt = TEACH_PROMPTS[len(lessons) % len(TEACH_PROMPTS)].format(
                chunk=chunk)
            try:
                result = lb.draft(prompt, model=teacher_model,
                                  base=base)
                lesson = result.get("response", "").strip()
            except Exception as exc:  # noqa: BLE001
                if progress:
                    print("  teacher error:", str(exc)[:80], flush=True)
                continue
            if len(lesson) > 40:
                lessons.append({
                    "source": str(path),
                    "prompt_kind": len(lessons) % len(TEACH_PROMPTS),
                    "lesson": lesson,
                })
                if progress:
                    rate = len(lessons) / max(time.time() - started, 1)
                    print("  lesson %d/%d (%.2f/s) <- %s"
                          % (len(lessons), lessons_target, rate,
                             path.name), flush=True)
    return lessons

def build_mixed_corpus(root, lessons, max_code_bytes=50_000_000):
    """Bulk = your real code (the harness reads it, no teacher needed).
    Seasoning = teacher lessons. Mixed and returned as bytes."""
    bulk = []
    used = 0
    for path in iter_source_files(root):
        if used >= max_code_bytes:
            break
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        bulk.append(text)
        used += len(text)
    lesson_text = "\n\n".join(
        "# teacher lesson\n" + entry["lesson"] for entry in lessons)
    return ("\n\n".join(bulk) + "\n\n" + lesson_text).encode("utf-8")

def review_dir(root, teacher_model, max_files=8, max_chunks_per_file=1,
               base="http://127.0.0.1:11434", progress=True):
    """Send code to the teacher for review. The harness reads the disk;
    the teacher only ever sees the chunk in its prompt."""
    reviews = []
    files_seen = 0
    for path in iter_source_files(root):
        if files_seen >= max_files:
            break
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        if len(text.strip()) < 200:
            continue
        files_seen += 1
        chunks = list(chunk_text(text))[:max_chunks_per_file]
        for chunk in chunks:
            prompt = REVIEW_PROMPT.format(chunk=chunk)
            try:
                result = lb.draft(prompt, model=teacher_model, base=base)
                review = result.get("response", "").strip()
            except Exception as exc:  # noqa: BLE001
                if progress:
                    print("  review error:", str(exc)[:80], flush=True)
                continue
            if review:
                reviews.append({"file": str(path), "review": review})
                if progress:
                    print("  reviewed %s (%d chars)"
                          % (path.name, len(review)), flush=True)
    return reviews

def syntax_check(code):
    """Returns (ok, errors)."""
    try:
        ast.parse(code)
        compile(code, "<draft>", "exec")
        return True, []
    except SyntaxError as exc:
        return False, ["SyntaxError line %d: %s" % (exc.lineno, exc.msg)]
    except ValueError as exc:
        return False, ["ValueError: %s" % exc]

def security_scan(code):
    """Run Owen's source_hardening scanner. Returns list of findings."""
    try:
        import source_hardening42 as hard
        return hard.scan_text(code)
    except Exception:  # noqa: BLE001
        return []

def parse_github_url(url):
    """Parse a GitHub URL into (type, owner, repo, extra)."""
    url = url.strip().rstrip("/")
    m = re.match(r"https?://github\.com/([\w.-]+)/([\w.-]+)(?:/(pull|tree|blob)/([\w./-]+))?", url)
    if not m:
        raise ValueError("not a recognized GitHub URL: %s" % url)
    return {
        "type": m.group(3) or "repo",
        "owner": m.group(1),
        "repo": m.group(2),
        "extra": m.group(4),
        "url": url,
    }

def review_repo(repo_dir):
    """Run Owen's full review stack on a checked-out repo."""
    sys.path.insert(0, __file__.rsplit("\\", 1)[0] if "\\" in __file__ else ".")

    findings = {"reader": None, "hardening": [], "total": 0}

    # reader42 - design-level analysis
    try:
        import reader42 as rd
        report = rd.read_repo(str(repo_dir))
        findings["reader"] = {
            "files_read": report["files_read"],
            "functions": report["functions_understood"],
            "q1_unauth_sinks": report["q1_count"],
            "q2_inconsistent_validation": report["q2_count"],
            "narrative": report["narrative"],
        }
        findings["total"] += report["q1_count"] + report["q2_count"]
    except Exception as exc:  # noqa: BLE001
        findings["reader"] = {"error": str(exc)[:200]}

    # source_hardening - secrets, bidi, entropy
    try:
        import source_hardening42 as hard
        hits = []
        for py_file in Path(repo_dir).rglob("*.py"):
            if any(p in (".git", "__pycache__", ".venv") for p in py_file.parts):
                continue
            try:
                hits.extend(hard.scan_file(str(py_file)))
            except OSError:
                continue
        findings["hardening"] = hits[:100]
        findings["total"] += len(hits)
    except Exception as exc:  # noqa: BLE001
        findings["hardening"] = [{"error": str(exc)[:200]}]

    return findings

def find_package_type(repo_path):
    """Detect what kind of installable package this is."""
    p = Path(repo_path)
    checks = [
        ("setup.py", "pip install ."),
        ("pyproject.toml", "pip install ."),
        ("setup.cfg", "pip install ."),
        ("requirements.txt", "pip install -r requirements.txt"),
        ("package.json", None),  # npm -- not auto-installed
        ("Cargo.toml", None),     # cargo -- not auto-installed
        ("go.mod", None),         # go -- not auto-installed
    ]
    for filename, install_cmd in checks:
        if (p / filename).exists():
            return {"file": filename, "cmd": install_cmd,
                    "language": "python" if install_cmd else filename}
    # even bare .py repos can be imported if they're on sys.path
    py_files = list(p.rglob("*.py"))[:1]
    if py_files:
        return {"file": "*.py", "cmd": "__path__",
                "language": "python-raw"}
    return {"file": None, "cmd": None, "language": "unknown"}
